SELECT '1890ee49-c4dd-7975-b7c9-0652f82df60f', 'a4071a47-861e-78f2-996a-eb8b98f6051f', 1, 'PUBLISHED', 'Binary Search Tree', '[{"id":"90add399-b5fc-7af2-b647-f9cf8ddc2b5b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A binary search tree keeps its keys "},{"type":"text","text":"ordered","marks":[{"type":"bold"}]},{"type":"text","text":": everything in a node''s left subtree is smaller, everything in its right subtree is larger. That one invariant is what every problem here exploits — the inorder traversal is sorted, every search is a single root-to-leaf walk, and a count stored in each node turns "},{"type":"text","text":"order statistics","marks":[{"type":"italic"}]},{"type":"text","text":" into "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" queries."}]}]}},"revision":1},{"id":"da44e5ab-e810-7823-87ee-135c9df7ebc9","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary Search Tree (BST)","marks":[{"type":"bold"}]},{"type":"text","text":" — a binary tree in which, for "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" node, all keys in the left subtree are "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":" the node''s key and all keys in the right subtree are "},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":" it. The rule applies to whole subtrees, not just to the two children — this is the detail most wrong solutions miss."}]}]}},"revision":1},{"id":"56623976-f4cf-79a4-9fdd-71916fd57d46","type":"code","position":"a2","content":{"language":"text","code":"            20\n          /    \\\n         8      22\n       /   \\\n      4     12\n           /  \\\n         10    14\n\ninorder:  4  8  10  12  14  20  22      (always sorted)","filename":"Tree A — the sample tree used throughout this topic"},"revision":1},{"id":"81e07af9-26ac-718b-b50c-abbeb6977312","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"What the problems rely on"}]},"revision":1},{"id":"855a4054-1baa-7d6f-8932-7fe28e9516ab","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The reader already knows search, insert and delete. The advanced problems are built from four consequences of the BST invariant:"}]}]}},"revision":1},{"id":"dd305fc4-2be6-778e-81cf-393173bebadc","type":"callout","position":"a5","content":{"variant":"note","title":"Inorder is sorted","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Left, node, right visits keys in ascending order. Anything you can do on a sorted array (two pointers, previous-element checks, kth element) you can do on a BST without materialising the array."}]}]}},"revision":1},{"id":"57f51aff-5b16-7b51-89eb-1f34e19ba0d6","type":"callout","position":"a6","content":{"variant":"note","title":"One path answers a query","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Search, floor, ceiling, predecessor and successor each follow a single root-to-leaf path: "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" time, where "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" is the height."}]}]}},"revision":1},{"id":"998827bc-b751-7cb7-8a70-c02ca64a08a3","type":"callout","position":"a7","content":{"variant":"note","title":"Ancestors bound a node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A node must lie strictly inside the range "},{"type":"text","text":"(lower, upper)","marks":[{"type":"code"}]},{"type":"text","text":" set by all of its ancestors — not only by its parent."}]}]}},"revision":1},{"id":"d3dd908b-94b0-73c0-b41c-00c9c03a8779","type":"callout","position":"a8","content":{"variant":"note","title":"Nodes can carry extra data","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Storing the size of the left subtree (an "},{"type":"text","text":"augmented","marks":[{"type":"italic"}]},{"type":"text","text":" BST) makes “kth smallest” and “rank of x” "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" queries."}]}]}},"revision":1},{"id":"b21b9f18-16b2-7bb6-8e69-1a7572c167f4","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Note"}]],[[{"type":"text","text":"search / insert / delete"}],[{"type":"text","text":"O(h)"}],[{"type":"text","text":"h = O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" when balanced, "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" when skewed"}]],[[{"type":"text","text":"floor / ceiling / successor"}],[{"type":"text","text":"O(h)"}],[{"type":"text","text":"one path down, remember the best candidate"}]],[[{"type":"text","text":"kth smallest (plain)"}],[{"type":"text","text":"O(h + k)"}],[{"type":"text","text":"inorder traversal stopped after "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" nodes"}]],[[{"type":"text","text":"kth smallest (augmented)"}],[{"type":"text","text":"O(h)"}],[{"type":"text","text":"each node stores the size of its left subtree"}]],[[{"type":"text","text":"check if a tree is a BST"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"range method or inorder-previous method"}]],[[{"type":"text","text":"inorder traversal"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"stack holds at most "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" nodes"}]]]},"revision":1},{"id":"bb0864a7-e418-7232-bcae-87012a347795","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The library ordered containers — C++ "},{"type":"text","text":"std::set","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"std::map","marks":[{"type":"code"}]},{"type":"text","text":", Java "},{"type":"text","text":"TreeSet","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" — are self-balancing BSTs (red-black trees), so "},{"type":"text","text":"h = O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" is guaranteed. Python and JavaScript ship no ordered set; you either write a small BST, keep a sorted list with "},{"type":"text","text":"bisect","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" inserts) or use a third-party package."}]}]}},"revision":1},{"id":"7b025435-f271-7554-be0b-b84af15989ef","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Floor and ceiling of a key"}]},"revision":1},{"id":"b37a2c8d-adbc-74ca-a4de-2f7e1e1dce19","type":"callout","position":"aC","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, x = 11","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"floor 10, ceiling 12","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, x = 23","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"floor 22, ceiling -1 (none)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, x = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"floor -1 (none), ceiling 4","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"318fa673-f65b-7d58-8236-e4680c8e06e3","type":"callout","position":"aD","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk down from the root. For the "},{"type":"text","text":"floor","marks":[{"type":"bold"}]},{"type":"text","text":" (largest key "},{"type":"text","text":"<= x","marks":[{"type":"code"}]},{"type":"text","text":"): when the current key is too big go left; when it is "},{"type":"text","text":"<= x","marks":[{"type":"code"}]},{"type":"text","text":" it is a candidate — record it and go right to look for a closer one. The "},{"type":"text","text":"ceiling","marks":[{"type":"bold"}]},{"type":"text","text":" is the mirror image. The answer is the last candidate recorded on the path — no backtracking, no recursion."}]}]}},"revision":1},{"id":"d58843c8-2836-7514-8b3e-899ecc79be18","type":"code","position":"aE","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef insert(root, key):\n    if root is None:\n        return Node(key)\n    if key < root.key:\n        root.left = insert(root.left, key)\n    elif key > root.key:\n        root.right = insert(root.right, key)\n    return root\n\ndef floor_of(root, x):\n    res = -1\n    while root:\n        if root.key == x:\n            return x\n        if root.key > x:\n            root = root.left        # too big: only the left subtree can hold a floor\n        else:\n            res = root.key          # candidate; a closer one may sit to the right\n            root = root.right\n    return res\n\ndef ceil_of(root, x):\n    res = -1\n    while root:\n        if root.key == x:\n            return x\n        if root.key < x:\n            root = root.right       # too small: only the right subtree can hold a ceiling\n        else:\n            res = root.key          # candidate; a closer one may sit to the left\n            root = root.left\n    return res\n\nroot = None\nfor k in [20, 8, 22, 4, 12, 10, 14]:\n    root = insert(root, k)\nfor x in [11, 23, 3, 12]:\n    print(f\"x={x}: floor {floor_of(root, x)} ceiling {ceil_of(root, x)}\")","filename":"Python"},"revision":1},{"id":"22d9082e-b792-7721-a66e-333785e10bcb","type":"code","position":"aF","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nNode* insert(Node* root, int key) {\n    if (!root) return new Node(key);\n    if (key < root->key) root->left = insert(root->left, key);\n    else if (key > root->key) root->right = insert(root->right, key);\n    return root;\n}\n\nint floorOf(Node* root, int x) {\n    int res = -1;\n    while (root) {\n        if (root->key == x) return x;\n        if (root->key > x) root = root->left;          // too big: go left\n        else { res = root->key; root = root->right; }  // candidate, look right for a closer one\n    }\n    return res;\n}\n\nint ceilOf(Node* root, int x) {\n    int res = -1;\n    while (root) {\n        if (root->key == x) return x;\n        if (root->key < x) root = root->right;         // too small: go right\n        else { res = root->key; root = root->left; }   // candidate, look left for a closer one\n    }\n    return res;\n}\n\nint main() {\n    Node* root = nullptr;\n    for (int k : {20, 8, 22, 4, 12, 10, 14}) root = insert(root, k);\n    for (int x : {11, 23, 3, 12})\n        cout << \"x=\" << x << \": floor \" << floorOf(root, x) << \" ceiling \" << ceilOf(root, x) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"ade9b850-0176-702b-b4de-a3c676428f81","type":"code","position":"aG","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node insert(Node root, int key) {\n        if (root == null) return new Node(key);\n        if (key < root.key) root.left = insert(root.left, key);\n        else if (key > root.key) root.right = insert(root.right, key);\n        return root;\n    }\n\n    static int floorOf(Node root, int x) {\n        int res = -1;\n        while (root != null) {\n            if (root.key == x) return x;\n            if (root.key > x) root = root.left;            // too big: go left\n            else { res = root.key; root = root.right; }    // candidate, look right for a closer one\n        }\n        return res;\n    }\n\n    static int ceilOf(Node root, int x) {\n        int res = -1;\n        while (root != null) {\n            if (root.key == x) return x;\n            if (root.key < x) root = root.right;           // too small: go right\n            else { res = root.key; root = root.left; }     // candidate, look left for a closer one\n        }\n        return res;\n    }\n\n    public static void main(String[] args) {\n        Node root = null;\n        for (int k : new int[]{20, 8, 22, 4, 12, 10, 14}) root = insert(root, k);\n        for (int x : new int[]{11, 23, 3, 12})\n            System.out.println(\"x=\" + x + \": floor \" + floorOf(root, x) + \" ceiling \" + ceilOf(root, x));\n    }\n}","filename":"Java"},"revision":1},{"id":"5356a6ca-167a-74e4-a7dc-aaac589ea5c0","type":"code","position":"aH","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction insert(root, key) {\n    if (!root) return new Node(key);\n    if (key < root.key) root.left = insert(root.left, key);\n    else if (key > root.key) root.right = insert(root.right, key);\n    return root;\n}\n\nfunction floorOf(root, x) {\n    let res = -1;\n    while (root) {\n        if (root.key === x) return x;\n        if (root.key > x) root = root.left;               // too big: go left\n        else { res = root.key; root = root.right; }       // candidate, look right for a closer one\n    }\n    return res;\n}\n\nfunction ceilOf(root, x) {\n    let res = -1;\n    while (root) {\n        if (root.key === x) return x;\n        if (root.key < x) root = root.right;              // too small: go right\n        else { res = root.key; root = root.left; }        // candidate, look left for a closer one\n    }\n    return res;\n}\n\nlet root = null;\nfor (const k of [20, 8, 22, 4, 12, 10, 14]) root = insert(root, k);\nfor (const x of [11, 23, 3, 12])\n    console.log(`x=${x}: floor ${floorOf(root, x)} ceiling ${ceilOf(root, x)}`);","filename":"JavaScript"},"revision":1},{"id":"db2f4795-c801-7ebf-a96d-eef654a4b3b8","type":"code","position":"aI","content":{"language":"text","code":"x=11: floor 10 ceiling 12\nx=23: floor 22 ceiling -1\nx=3: floor -1 ceiling 4\nx=12: floor 12 ceiling 12","filename":"Output"},"revision":1},{"id":"2276423a-f559-7689-8356-cc6dfea3fda4","type":"text","position":"aJ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(h) · Space O(1)"}]}]}},"revision":1},{"id":"0bffd419-2c47-7c40-ac2b-a77ec7e42ea9","type":"callout","position":"aK","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning as soon as you see a key "},{"type":"text","text":"<= x","marks":[{"type":"code"}]},{"type":"text","text":" gives a "},{"type":"text","text":"valid","marks":[{"type":"italic"}]},{"type":"text","text":" floor but not the "},{"type":"text","text":"greatest","marks":[{"type":"italic"}]},{"type":"text","text":" one — "},{"type":"text","text":"floor(11)","marks":[{"type":"code"}]},{"type":"text","text":" would stop at "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"text","text":" instead of continuing right to "},{"type":"text","text":"10","marks":[{"type":"code"}]},{"type":"text","text":". Always keep walking and overwrite the candidate."}]}]}},"revision":1},{"id":"60601d92-4831-77f7-954c-0bd23fb6a937","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Ceiling on the left side of every element"}]},"revision":1},{"id":"3fea7dd1-171c-76d0-a1da-b07385b929f3","type":"callout","position":"aM","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [2, 8, 30, 15, 25, 12]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1 -1 -1 30 30 15","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [30, 20, 10]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1 30 20","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"9687d308-577d-7691-a54c-2fb82e85d185","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For every "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", print the smallest element among "},{"type":"text","text":"arr[0..i-1]","marks":[{"type":"code"}]},{"type":"text","text":" that is "},{"type":"text","text":">= arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" if there is none. The first element never has one."}]},{"type":"paragraph","content":[{"type":"text","text":"The obvious solution rescans the prefix for each element:"}]}]}},"revision":1},{"id":"6f1830bd-c0db-70b9-b8fb-8fc8ccddabaf","type":"code","position":"aO","content":{"language":"python","code":"def left_ceilings_naive(arr):\n    res = [-1]\n    for i in range(1, len(arr)):\n        best = -1\n        for j in range(i):                                # scan everything to the left\n            if arr[j] >= arr[i] and (best == -1 or arr[j] < best):\n                best = arr[j]\n        res.append(best)\n    return res\n\nprint(*left_ceilings_naive([2, 8, 30, 15, 25, 12]))","filename":"Python"},"revision":1},{"id":"f5b1d2a5-856e-79d7-8819-0585934c0839","type":"code","position":"aP","content":{"language":"text","code":"-1 -1 -1 30 30 15","filename":"Output"},"revision":1},{"id":"610a6abc-d046-789e-8cb9-e8337b991860","type":"text","position":"aQ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n²) · Space O(1)"}]}]}},"revision":1},{"id":"508ada99-a754-7eaa-9e85-60d87290ffcf","type":"callout","position":"aR","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep the elements seen so far in an "},{"type":"text","text":"ordered set","marks":[{"type":"bold"}]},{"type":"text","text":" (a self-balancing BST). The ceiling of "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" is then one "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" query — "},{"type":"text","text":"lower_bound","marks":[{"type":"code"}]},{"type":"text","text":" in C++, "},{"type":"text","text":"TreeSet.ceiling","marks":[{"type":"code"}]},{"type":"text","text":" in Java — and inserting "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" afterwards is another. Python uses "},{"type":"text","text":"bisect","marks":[{"type":"code"}]},{"type":"text","text":" on a sorted list (the query is "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":", the insert "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" but with a very small constant); JavaScript reuses the hand-written BST from the previous section."}]}]}},"revision":1},{"id":"8d269e4b-f7b6-7ba0-b7ac-3f27a65a7bad","type":"code","position":"aS","content":{"language":"python","code":"from bisect import bisect_left, insort\n\ndef left_ceilings(arr):\n    seen = []                              # kept sorted\n    res = []\n    for x in arr:\n        i = bisect_left(seen, x)           # index of the first element >= x\n        res.append(seen[i] if i < len(seen) else -1)\n        insort(seen, x)                    # O(n) shift, but a tight memmove\n    return res\n\nfor arr in ([2, 8, 30, 15, 25, 12], [30, 20, 10]):\n    print(*left_ceilings(arr))","filename":"Python"},"revision":1},{"id":"8471d18b-a644-73bc-8ea9-95a39175db03","type":"code","position":"aT","content":{"language":"cpp","code":"#include <iostream>\n#include <set>\n#include <vector>\nusing namespace std;\n\nvector<int> leftCeilings(const vector<int>& arr) {\n    set<int> seen;                                   // red-black tree\n    vector<int> res;\n    for (int x : arr) {\n        auto it = seen.lower_bound(x);               // first element >= x, O(log n)\n        res.push_back(it == seen.end() ? -1 : *it);\n        seen.insert(x);\n    }\n    return res;\n}\n\nint main() {\n    for (const vector<int>& arr : {vector<int>{2, 8, 30, 15, 25, 12}, vector<int>{30, 20, 10}}) {\n        vector<int> res = leftCeilings(arr);\n        for (int i = 0; i < (int)res.size(); i++) cout << (i ? \" \" : \"\") << res[i];\n        cout << \"\\n\";\n    }\n}","filename":"C++"},"revision":1},{"id":"06b63f17-4ccc-79ec-bdf3-889ffc4bfefe","type":"code","position":"aU","content":{"language":"java","code":"import java.util.TreeSet;\n\npublic class Main {\n    static String leftCeilings(int[] arr) {\n        TreeSet<Integer> seen = new TreeSet<>();      // red-black tree\n        StringBuilder sb = new StringBuilder();\n        for (int x : arr) {\n            Integer c = seen.ceiling(x);              // smallest element >= x, or null\n            sb.append(c == null ? -1 : c).append('' '');\n            seen.add(x);\n        }\n        return sb.toString().trim();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(leftCeilings(new int[]{2, 8, 30, 15, 25, 12}));\n        System.out.println(leftCeilings(new int[]{30, 20, 10}));\n    }\n}","filename":"Java"},"revision":1},{"id":"f201ca9f-bc77-7233-a588-96f00f3c0a65","type":"code","position":"aV","content":{"language":"javascript","code":"// JavaScript has no ordered set: reuse the BST insert + ceiling from above\nclass Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction insert(root, key) {\n    if (!root) return new Node(key);\n    if (key < root.key) root.left = insert(root.left, key);\n    else if (key > root.key) root.right = insert(root.right, key);\n    return root;\n}\n\nfunction ceilOf(root, x) {\n    let res = -1;\n    while (root) {\n        if (root.key === x) return x;\n        if (root.key < x) root = root.right;\n        else { res = root.key; root = root.left; }\n    }\n    return res;\n}\n\nfunction leftCeilings(arr) {\n    let seen = null;\n    const res = [];\n    for (const x of arr) {\n        res.push(ceilOf(seen, x));              // query the elements to the left\n        seen = insert(seen, x);                 // then add the current one\n    }\n    return res;\n}\n\nfor (const arr of [[2, 8, 30, 15, 25, 12], [30, 20, 10]])\n    console.log(leftCeilings(arr).join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"6cdc8251-82a0-74be-a0ab-95307da99f9e","type":"code","position":"aW","content":{"language":"text","code":"-1 -1 -1 30 30 15\n-1 30 20","filename":"Output"},"revision":1},{"id":"621baf60-a2cb-787a-b320-1680bc2af63c","type":"text","position":"aX","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log n) · Space O(n)"}]}]}},"revision":1},{"id":"9cc5e46c-e077-7596-87e8-40d27a008966","type":"callout","position":"aY","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Query "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" insert: if you insert "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" first, its own ceiling is itself and every answer becomes "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":". The same pattern (ordered set of the prefix + one query per element) solves "},{"type":"text","text":"floor on the left","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"ceiling on the right","marks":[{"type":"italic"}]},{"type":"text","text":" (scan from the end) and "},{"type":"text","text":"count of smaller elements to the left","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"108dcc70-bc98-7451-b2d3-f200d8579c9d","type":"heading","position":"aZ","content":{"level":1,"content":[{"type":"text","text":"Kth smallest element"}]},"revision":1},{"id":"eeca8206-7afe-7d9d-9b1d-a266856ad5af","type":"callout","position":"aa","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, k = 7","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"22","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, k = 8","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1 (fewer than 8 nodes)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"a32601ac-089a-7ee1-b223-9183ab4c0099","type":"callout","position":"ab","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inorder visits keys in ascending order, so the kth node visited "},{"type":"text","text":"is","marks":[{"type":"bold"}]},{"type":"text","text":" the kth smallest. Run an iterative inorder traversal with an explicit stack, count the nodes as they are popped, and stop as soon as the count reaches "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" — no need to finish the traversal."}]}]}},"revision":1},{"id":"f8546e6f-6793-7af1-bf75-9bc1dfc5d0ae","type":"code","position":"ac","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef insert(root, key):\n    if root is None:\n        return Node(key)\n    if key < root.key:\n        root.left = insert(root.left, key)\n    elif key > root.key:\n        root.right = insert(root.right, key)\n    return root\n\ndef kth_smallest(root, k):\n    stack, node = [], root\n    while stack or node:\n        while node:                  # go as far left as possible\n            stack.append(node)\n            node = node.left\n        node = stack.pop()           # the next key in sorted order\n        k -= 1\n        if k == 0:\n            return node.key\n        node = node.right\n    return -1                        # fewer than k nodes\n\nroot = None\nfor x in [20, 8, 22, 4, 12, 10, 14]:\n    root = insert(root, x)\nfor k in (3, 7, 8):\n    print(f\"k={k}: {kth_smallest(root, k)}\")","filename":"Python"},"revision":1},{"id":"6cdeea1f-7024-79c9-b187-636980786ef4","type":"code","position":"ad","content":{"language":"cpp","code":"#include <iostream>\n#include <stack>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nNode* insert(Node* root, int key) {\n    if (!root) return new Node(key);\n    if (key < root->key) root->left = insert(root->left, key);\n    else if (key > root->key) root->right = insert(root->right, key);\n    return root;\n}\n\nint kthSmallest(Node* root, int k) {\n    stack<Node*> st;\n    Node* node = root;\n    while (!st.empty() || node) {\n        while (node) { st.push(node); node = node->left; }   // go as far left as possible\n        node = st.top(); st.pop();                           // next key in sorted order\n        if (--k == 0) return node->key;\n        node = node->right;\n    }\n    return -1;                                               // fewer than k nodes\n}\n\nint main() {\n    Node* root = nullptr;\n    for (int x : {20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n    for (int k : {3, 7, 8}) cout << \"k=\" << k << \": \" << kthSmallest(root, k) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"e4204ed7-5d94-7ae2-af60-9247d9d633bb","type":"code","position":"ae","content":{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node insert(Node root, int key) {\n        if (root == null) return new Node(key);\n        if (key < root.key) root.left = insert(root.left, key);\n        else if (key > root.key) root.right = insert(root.right, key);\n        return root;\n    }\n\n    static int kthSmallest(Node root, int k) {\n        Deque<Node> stack = new ArrayDeque<>();\n        Node node = root;\n        while (!stack.isEmpty() || node != null) {\n            while (node != null) { stack.push(node); node = node.left; }   // go as far left as possible\n            node = stack.pop();                                             // next key in sorted order\n            if (--k == 0) return node.key;\n            node = node.right;\n        }\n        return -1;                                                          // fewer than k nodes\n    }\n\n    public static void main(String[] args) {\n        Node root = null;\n        for (int x : new int[]{20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n        for (int k : new int[]{3, 7, 8}) System.out.println(\"k=\" + k + \": \" + kthSmallest(root, k));\n    }\n}","filename":"Java"},"revision":1},{"id":"9d072f2c-f52c-7563-a80c-3af4369d96f6","type":"code","position":"af","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction insert(root, key) {\n    if (!root) return new Node(key);\n    if (key < root.key) root.left = insert(root.left, key);\n    else if (key > root.key) root.right = insert(root.right, key);\n    return root;\n}\n\nfunction kthSmallest(root, k) {\n    const stack = [];\n    let node = root;\n    while (stack.length || node) {\n        while (node) { stack.push(node); node = node.left; }   // go as far left as possible\n        node = stack.pop();                                     // next key in sorted order\n        if (--k === 0) return node.key;\n        node = node.right;\n    }\n    return -1;                                                  // fewer than k nodes\n}\n\nlet root = null;\nfor (const x of [20, 8, 22, 4, 12, 10, 14]) root = insert(root, x);\nfor (const k of [3, 7, 8]) console.log(`k=${k}: ${kthSmallest(root, k)}`);","filename":"JavaScript"},"revision":1},{"id":"47bcb8e8-6e63-784e-88fa-2f29cdac8286","type":"code","position":"ag","content":{"language":"text","code":"k=3: 10\nk=7: 22\nk=8: -1","filename":"Output"},"revision":1},{"id":"78411ff0-f9ce-7ad0-b9b9-feacb8963413","type":"text","position":"ah","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(h + k) · Space O(h)"}]}]}},"revision":1},{"id":"240e88d0-c68d-747d-ba1f-19d88547a740","type":"callout","position":"ai","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes used a recursive traversal with a "},{"type":"text","text":"global counter","marks":[{"type":"bold"}]},{"type":"text","text":" and a "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" after printing — but the "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" only leaves the current frame, the parent frames continue into their right subtrees, and the counter is never reset for a second query. An explicit stack (or a counter object passed down and a boolean "},{"type":"text","text":"found","marks":[{"type":"italic"}]},{"type":"text","text":" flag) avoids both bugs."}]}]}},"revision":1},{"id":"7f6689e5-17c5-7b6c-a186-c811083d7fec","type":"text","position":"aj","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the tree is queried many times, or "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" is large, pay a little memory to make every query "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":": store in each node the "},{"type":"text","text":"number of nodes in its left subtree","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"lcount","marks":[{"type":"code"}]},{"type":"text","text":"). Insert maintains it — every time the new key goes left, the node it passes gains one left descendant."}]}]}},"revision":1},{"id":"5285bd8a-8cd5-7ca0-a22a-9c91297bd4da","type":"code","position":"ak","content":{"language":"text","code":"            20 (lcount 5)\n          /    \\\n (lcount 1) 8    22 (0)\n       /   \\\n  (0) 4     12 (lcount 1)\n           /  \\\n     (0) 10    14 (0)\n\nkth(k=3) at 20: lcount+1 = 6 > 3   → go left, k stays 3\n          at 8: lcount+1 = 2 < 3   → go right, k = 3-2 = 1\n         at 12: lcount+1 = 2 > 1   → go left\n         at 10: lcount+1 = 1 == 1  → answer 10","filename":"Augmented tree A: each node knows the size of its left subtree"},"revision":1},{"id":"f7e70a38-9bf8-745c-bb4b-a661ea3dbd18","type":"code","position":"al","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n        self.lcount = 0              # number of nodes in the left subtree\n\ndef insert(root, key):\n    if root is None:\n        return Node(key)\n    if key < root.key:\n        root.left = insert(root.left, key)\n        root.lcount += 1             # one more node went into my left subtree\n    elif key > root.key:\n        root.right = insert(root.right, key)\n    return root\n\ndef kth_smallest(root, k):\n    while root:\n        rank = root.lcount + 1       # this node is the rank-th smallest of its subtree\n        if rank == k:\n            return root.key\n        if k < rank:\n            root = root.left         # answer is in the left subtree\n        else:\n            k -= rank                # skip the left subtree and this node\n            root = root.right\n    return -1\n\nroot = None\nfor x in [20, 8, 22, 4, 12, 10, 14]:\n    root = insert(root, x)\nfor k in (3, 7, 8):\n    print(f\"k={k}: {kth_smallest(root, k)}\")","filename":"Python"},"revision":1},{"id":"0664a23b-b698-7188-ab6f-f22d66f9b7e1","type":"code","position":"am","content":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    int lcount = 0;                      // number of nodes in the left subtree\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nNode* insert(Node* root, int key) {\n    if (!root) return new Node(key);\n    if (key < root->key) {\n        root->left = insert(root->left, key);\n        root->lcount++;                  // one more node went into my left subtree\n    } else if (key > root->key) {\n        root->right = insert(root->right, key);\n    }\n    return root;\n}\n\nint kthSmallest(Node* root, int k) {\n    while (root) {\n        int rank = root->lcount + 1;     // this node is the rank-th smallest of its subtree\n        if (rank == k) return root->key;\n        if (k < rank) root = root->left;             // answer is in the left subtree\n        else { k -= rank; root = root->right; }      // skip the left subtree and this node\n    }\n    return -1;\n}\n\nint main() {\n    Node* root = nullptr;\n    for (int x : {20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n    for (int k : {3, 7, 8}) cout << \"k=\" << k << \": \" << kthSmallest(root, k) << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"b15e90ef-cbed-70af-82fa-d1da44bd0be9","type":"code","position":"an","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int key, lcount;                 // lcount = number of nodes in the left subtree\n        Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node insert(Node root, int key) {\n        if (root == null) return new Node(key);\n        if (key < root.key) {\n            root.left = insert(root.left, key);\n            root.lcount++;               // one more node went into my left subtree\n        } else if (key > root.key) {\n            root.right = insert(root.right, key);\n        }\n        return root;\n    }\n\n    static int kthSmallest(Node root, int k) {\n        while (root != null) {\n            int rank = root.lcount + 1;  // this node is the rank-th smallest of its subtree\n            if (rank == k) return root.key;\n            if (k < rank) root = root.left;              // answer is in the left subtree\n            else { k -= rank; root = root.right; }       // skip the left subtree and this node\n        }\n        return -1;\n    }\n\n    public static void main(String[] args) {\n        Node root = null;\n        for (int x : new int[]{20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n        for (int k : new int[]{3, 7, 8}) System.out.println(\"k=\" + k + \": \" + kthSmallest(root, k));\n    }\n}","filename":"Java"},"revision":1},{"id":"1c0717f8-f9f1-7489-a2d8-236b97a6d3de","type":"code","position":"ao","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; this.lcount = 0; }\n}\n\nfunction insert(root, key) {\n    if (!root) return new Node(key);\n    if (key < root.key) {\n        root.left = insert(root.left, key);\n        root.lcount++;                   // one more node went into my left subtree\n    } else if (key > root.key) {\n        root.right = insert(root.right, key);\n    }\n    return root;\n}\n\nfunction kthSmallest(root, k) {\n    while (root) {\n        const rank = root.lcount + 1;    // this node is the rank-th smallest of its subtree\n        if (rank === k) return root.key;\n        if (k < rank) root = root.left;                  // answer is in the left subtree\n        else { k -= rank; root = root.right; }           // skip the left subtree and this node\n    }\n    return -1;\n}\n\nlet root = null;\nfor (const x of [20, 8, 22, 4, 12, 10, 14]) root = insert(root, x);\nfor (const k of [3, 7, 8]) console.log(`k=${k}: ${kthSmallest(root, k)}`);","filename":"JavaScript"},"revision":1},{"id":"888bf841-4b35-721e-80a1-981448ee69f2","type":"code","position":"ap","content":{"language":"text","code":"k=3: 10\nk=7: 22\nk=8: -1","filename":"Output"},"revision":1},{"id":"7e7b4b2d-3e37-7f00-a818-97761415f16f","type":"text","position":"aq","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(h) · Space O(1)"}]}]}},"revision":1},{"id":"152eb127-2f4a-7704-8579-780ee4b697d2","type":"callout","position":"ar","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The same "},{"type":"text","text":"lcount","marks":[{"type":"code"}]},{"type":"text","text":" field answers "},{"type":"text","text":"rank(x)","marks":[{"type":"bold"}]},{"type":"text","text":" (how many keys are "},{"type":"text","text":"< x","marks":[{"type":"code"}]},{"type":"text","text":") in "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"n - k + 1","marks":[{"type":"code"}]},{"type":"text","text":" turns "},{"type":"text","text":"kth smallest","marks":[{"type":"italic"}]},{"type":"text","text":" into "},{"type":"text","text":"kth largest","marks":[{"type":"italic"}]},{"type":"text","text":". If the tree also supports "},{"type":"text","text":"delete","marks":[{"type":"code"}]},{"type":"text","text":", every node on the deletion path whose left subtree shrank must have its "},{"type":"text","text":"lcount","marks":[{"type":"code"}]},{"type":"text","text":" decremented — forgetting that silently corrupts later queries."}]}]}},"revision":1},{"id":"039c136c-291b-7d04-988b-2d636d154ddc","type":"heading","position":"as","content":{"level":1,"content":[{"type":"text","text":"Check whether a binary tree is a BST"}]},"revision":1},{"id":"7fa181d6-e8b8-77f5-aa8f-540e366a3199","type":"code","position":"at","content":{"language":"text","code":"tree A (valid)             tree B (NOT a BST)\n      20                         20\n    /    \\                     /    \\\n   8      22                  8      22\n /   \\                      /   \\\n4     12                   4     25   ← 25 > 20 but sits in 20''s left subtree\n     /  \\\n   10    14","filename":"Every node of tree B passes a parent-vs-children check, yet tree B is not a BST"},"revision":1},{"id":"b583a7f0-24c9-7bb8-8e26-fba4999061ae","type":"callout","position":"au","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree B","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"e84f14b5-3640-7149-8be5-88d9d7701e6c","type":"text","position":"av","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The tempting solution compares each node with its two children only. It accepts tree B:"}]}]}},"revision":1},{"id":"a1d1dc2b-2264-76cb-b9e4-26e61e27f296","type":"code","position":"aw","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef looks_like_bst(root):                 # WRONG: only compares a node with its own children\n    if root is None:\n        return True\n    if root.left and root.left.key > root.key:\n        return False\n    if root.right and root.right.key < root.key:\n        return False\n    return looks_like_bst(root.left) and looks_like_bst(root.right)\n\nb = Node(20)\nb.left, b.right = Node(8), Node(22)\nb.left.left, b.left.right = Node(4), Node(25)      # 25 violates the rule at its grandparent 20\nprint(\"tree B:\", \"Yes\" if looks_like_bst(b) else \"No\")","filename":"Python"},"revision":1},{"id":"3deea035-a850-796c-b5ba-174f525c1fae","type":"code","position":"ax","content":{"language":"text","code":"tree B: Yes","filename":"Output"},"revision":1},{"id":"cfe7cf29-550c-7b9c-b6d6-8b8c3e03f8f6","type":"callout","position":"ay","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"8 < 20","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"4 < 8 < 25","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"20 < 22","marks":[{"type":"code"}]},{"type":"text","text":" — every local check passes, yet "},{"type":"text","text":"25","marks":[{"type":"code"}]},{"type":"text","text":" is in the left subtree of "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":". The BST rule constrains a node by "},{"type":"text","text":"all","marks":[{"type":"bold"}]},{"type":"text","text":" of its ancestors, not just its parent."}]}]}},"revision":1},{"id":"99c7bb05-56ef-7450-bf82-a6b671caa49e","type":"text","position":"az","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A correct but slow fix checks, for every node, the maximum of the whole left subtree and the minimum of the whole right subtree. Each node is scanned by each of its ancestors, which is "},{"type":"text","text":"O(n²)","marks":[{"type":"code"}]},{"type":"text","text":" on a skewed tree:"}]}]}},"revision":1},{"id":"9c274baa-c47c-7368-995c-679cff94fa46","type":"code","position":"b00","content":{"language":"python","code":"import sys\n\nclass Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef max_key(root):\n    if root is None:\n        return -sys.maxsize\n    return max(root.key, max_key(root.left), max_key(root.right))\n\ndef min_key(root):\n    if root is None:\n        return sys.maxsize\n    return min(root.key, min_key(root.left), min_key(root.right))\n\ndef is_bst_slow(root):\n    if root is None:\n        return True\n    if root.left and max_key(root.left) >= root.key:        # whole left subtree must be smaller\n        return False\n    if root.right and min_key(root.right) <= root.key:      # whole right subtree must be larger\n        return False\n    return is_bst_slow(root.left) and is_bst_slow(root.right)\n\na = Node(20)\na.left, a.right = Node(8), Node(22)\na.left.left, a.left.right = Node(4), Node(12)\na.left.right.left, a.left.right.right = Node(10), Node(14)\n\nb = Node(20)\nb.left, b.right = Node(8), Node(22)\nb.left.left, b.left.right = Node(4), Node(25)\n\nprint(\"tree A:\", \"Yes\" if is_bst_slow(a) else \"No\")\nprint(\"tree B:\", \"Yes\" if is_bst_slow(b) else \"No\")","filename":"Python"},"revision":1},{"id":"063190a3-ca39-7e15-8065-b9693ec875c4","type":"code","position":"b01","content":{"language":"text","code":"tree A: Yes\ntree B: No","filename":"Output"},"revision":1},{"id":"1ad75947-9d72-71b1-8824-28889c9924a9","type":"text","position":"b02","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n²) worst case · Space O(h)"}]}]}},"revision":1},{"id":"3156c20e-68d7-7788-911d-94092fef59dd","type":"callout","position":"b03","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Range method.","marks":[{"type":"bold"}]},{"type":"text","text":" Pass down the open interval "},{"type":"text","text":"(lo, hi)","marks":[{"type":"code"}]},{"type":"text","text":" that the ancestors allow. The root may be anything; going left tightens "},{"type":"text","text":"hi","marks":[{"type":"code"}]},{"type":"text","text":" to the current key, going right tightens "},{"type":"text","text":"lo","marks":[{"type":"code"}]},{"type":"text","text":". Each node is visited once and checked against two numbers — "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e3dbe4d6-49e8-7478-9d87-68e75bc85e52","type":"code","position":"b04","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef is_bst(root, lo=float(\"-inf\"), hi=float(\"inf\")):\n    if root is None:\n        return True\n    if not (lo < root.key < hi):             # must lie strictly inside the ancestors'' range\n        return False\n    return (is_bst(root.left, lo, root.key)   # left subtree: everything < root.key\n            and is_bst(root.right, root.key, hi))   # right subtree: everything > root.key\n\na = Node(20)\na.left, a.right = Node(8), Node(22)\na.left.left, a.left.right = Node(4), Node(12)\na.left.right.left, a.left.right.right = Node(10), Node(14)\n\nb = Node(20)\nb.left, b.right = Node(8), Node(22)\nb.left.left, b.left.right = Node(4), Node(25)\n\nprint(\"tree A:\", \"Yes\" if is_bst(a) else \"No\")\nprint(\"tree B:\", \"Yes\" if is_bst(b) else \"No\")","filename":"Python"},"revision":1},{"id":"a597bd49-5468-789e-834b-24731e467b1e","type":"code","position":"b05","content":{"language":"cpp","code":"#include <climits>\n#include <iostream>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nbool isBST(Node* root, long long lo, long long hi) {\n    if (!root) return true;\n    if (root->key <= lo || root->key >= hi) return false;     // outside the ancestors'' range\n    return isBST(root->left, lo, root->key)                  // left: everything < key\n        && isBST(root->right, root->key, hi);                // right: everything > key\n}\n\nint main() {\n    Node* a = new Node(20);\n    a->left = new Node(8); a->right = new Node(22);\n    a->left->left = new Node(4); a->left->right = new Node(12);\n    a->left->right->left = new Node(10); a->left->right->right = new Node(14);\n\n    Node* b = new Node(20);\n    b->left = new Node(8); b->right = new Node(22);\n    b->left->left = new Node(4); b->left->right = new Node(25);\n\n    cout << \"tree A: \" << (isBST(a, LLONG_MIN, LLONG_MAX) ? \"Yes\" : \"No\") << \"\\n\";\n    cout << \"tree B: \" << (isBST(b, LLONG_MIN, LLONG_MAX) ? \"Yes\" : \"No\") << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"5b2146cd-d804-7a44-b0bb-50089dcac0ef","type":"code","position":"b06","content":{"language":"java","code":"public class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static boolean isBST(Node root, long lo, long hi) {\n        if (root == null) return true;\n        if (root.key <= lo || root.key >= hi) return false;   // outside the ancestors'' range\n        return isBST(root.left, lo, root.key)                 // left: everything < key\n            && isBST(root.right, root.key, hi);               // right: everything > key\n    }\n\n    public static void main(String[] args) {\n        Node a = new Node(20);\n        a.left = new Node(8); a.right = new Node(22);\n        a.left.left = new Node(4); a.left.right = new Node(12);\n        a.left.right.left = new Node(10); a.left.right.right = new Node(14);\n\n        Node b = new Node(20);\n        b.left = new Node(8); b.right = new Node(22);\n        b.left.left = new Node(4); b.left.right = new Node(25);\n\n        System.out.println(\"tree A: \" + (isBST(a, Long.MIN_VALUE, Long.MAX_VALUE) ? \"Yes\" : \"No\"));\n        System.out.println(\"tree B: \" + (isBST(b, Long.MIN_VALUE, Long.MAX_VALUE) ? \"Yes\" : \"No\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"b360bfe4-94c4-758a-afd5-6ed22de9713a","type":"code","position":"b07","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction isBST(root, lo = -Infinity, hi = Infinity) {\n    if (!root) return true;\n    if (root.key <= lo || root.key >= hi) return false;       // outside the ancestors'' range\n    return isBST(root.left, lo, root.key)                     // left: everything < key\n        && isBST(root.right, root.key, hi);                   // right: everything > key\n}\n\nconst a = new Node(20);\na.left = new Node(8); a.right = new Node(22);\na.left.left = new Node(4); a.left.right = new Node(12);\na.left.right.left = new Node(10); a.left.right.right = new Node(14);\n\nconst b = new Node(20);\nb.left = new Node(8); b.right = new Node(22);\nb.left.left = new Node(4); b.left.right = new Node(25);\n\nconsole.log(\"tree A:\", isBST(a) ? \"Yes\" : \"No\");\nconsole.log(\"tree B:\", isBST(b) ? \"Yes\" : \"No\");","filename":"JavaScript"},"revision":1},{"id":"b475f0cd-fdc7-7ca1-8f40-e6a108779d31","type":"code","position":"b08","content":{"language":"text","code":"tree A: Yes\ntree B: No","filename":"Output"},"revision":1},{"id":"609c25c7-8e94-7417-ae4b-668cfbafc168","type":"text","position":"b09","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}},"revision":1},{"id":"8656dd35-ee0f-7a32-b06c-7208a02e9962","type":"callout","position":"b0A","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Using "},{"type":"text","text":"INT_MIN","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"INT_MAX","marks":[{"type":"code"}]},{"type":"text","text":" as the initial bounds with "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" keys rejects a tree that legitimately contains "},{"type":"text","text":"INT_MIN","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"INT_MAX","marks":[{"type":"code"}]},{"type":"text","text":" (the check is strict). Use a wider type for the bounds ("},{"type":"text","text":"long long","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":"), "},{"type":"text","text":"±Infinity","marks":[{"type":"code"}]},{"type":"text","text":" in JavaScript, or "},{"type":"text","text":"None","marks":[{"type":"code"}]},{"type":"text","text":" sentinels meaning "},{"type":"text","text":"unbounded","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"094354f6-bc47-7616-925a-3135edcc7248","type":"callout","position":"b0B","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inorder-previous method.","marks":[{"type":"bold"}]},{"type":"text","text":" Inorder of a BST is strictly increasing. Traverse inorder and remember the previous key; the moment the current key is "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" the previous one, the tree is not a BST. One pass, no bounds, and it stops at the first violation."}]}]}},"revision":1},{"id":"646b2ba7-02a9-7ef5-bb6a-3fa967cd30d3","type":"code","position":"b0C","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef is_bst(root):\n    stack, node, prev = [], root, None\n    while stack or node:\n        while node:                        # iterative inorder traversal\n            stack.append(node)\n            node = node.left\n        node = stack.pop()\n        if prev is not None and node.key <= prev:     # inorder must strictly increase\n            return False\n        prev = node.key\n        node = node.right\n    return True\n\na = Node(20)\na.left, a.right = Node(8), Node(22)\na.left.left, a.left.right = Node(4), Node(12)\na.left.right.left, a.left.right.right = Node(10), Node(14)\n\nb = Node(20)\nb.left, b.right = Node(8), Node(22)\nb.left.left, b.left.right = Node(4), Node(25)\n\nprint(\"tree A:\", \"Yes\" if is_bst(a) else \"No\")\nprint(\"tree B:\", \"Yes\" if is_bst(b) else \"No\")","filename":"Python"},"revision":1},{"id":"6cdef1fb-002e-7dc3-84bf-f4430e123c30","type":"code","position":"b0D","content":{"language":"cpp","code":"#include <iostream>\n#include <stack>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nbool isBST(Node* root) {\n    stack<Node*> st;\n    Node* node = root;\n    bool havePrev = false;\n    int prev = 0;\n    while (!st.empty() || node) {\n        while (node) { st.push(node); node = node->left; }   // iterative inorder traversal\n        node = st.top(); st.pop();\n        if (havePrev && node->key <= prev) return false;     // inorder must strictly increase\n        prev = node->key; havePrev = true;\n        node = node->right;\n    }\n    return true;\n}\n\nint main() {\n    Node* a = new Node(20);\n    a->left = new Node(8); a->right = new Node(22);\n    a->left->left = new Node(4); a->left->right = new Node(12);\n    a->left->right->left = new Node(10); a->left->right->right = new Node(14);\n\n    Node* b = new Node(20);\n    b->left = new Node(8); b->right = new Node(22);\n    b->left->left = new Node(4); b->left->right = new Node(25);\n\n    cout << \"tree A: \" << (isBST(a) ? \"Yes\" : \"No\") << \"\\n\";\n    cout << \"tree B: \" << (isBST(b) ? \"Yes\" : \"No\") << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"9d55a5e4-02b7-7921-897b-8c021eb9eaed","type":"code","position":"b0E","content":{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static boolean isBST(Node root) {\n        Deque<Node> stack = new ArrayDeque<>();\n        Node node = root;\n        Integer prev = null;\n        while (!stack.isEmpty() || node != null) {\n            while (node != null) { stack.push(node); node = node.left; }   // iterative inorder\n            node = stack.pop();\n            if (prev != null && node.key <= prev) return false;             // must strictly increase\n            prev = node.key;\n            node = node.right;\n        }\n        return true;\n    }\n\n    public static void main(String[] args) {\n        Node a = new Node(20);\n        a.left = new Node(8); a.right = new Node(22);\n        a.left.left = new Node(4); a.left.right = new Node(12);\n        a.left.right.left = new Node(10); a.left.right.right = new Node(14);\n\n        Node b = new Node(20);\n        b.left = new Node(8); b.right = new Node(22);\n        b.left.left = new Node(4); b.left.right = new Node(25);\n\n        System.out.println(\"tree A: \" + (isBST(a) ? \"Yes\" : \"No\"));\n        System.out.println(\"tree B: \" + (isBST(b) ? \"Yes\" : \"No\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"d82823ce-b375-77a6-8198-6a72cad588ee","type":"code","position":"b0F","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction isBST(root) {\n    const stack = [];\n    let node = root, prev = null;\n    while (stack.length || node) {\n        while (node) { stack.push(node); node = node.left; }   // iterative inorder traversal\n        node = stack.pop();\n        if (prev !== null && node.key <= prev) return false;    // inorder must strictly increase\n        prev = node.key;\n        node = node.right;\n    }\n    return true;\n}\n\nconst a = new Node(20);\na.left = new Node(8); a.right = new Node(22);\na.left.left = new Node(4); a.left.right = new Node(12);\na.left.right.left = new Node(10); a.left.right.right = new Node(14);\n\nconst b = new Node(20);\nb.left = new Node(8); b.right = new Node(22);\nb.left.left = new Node(4); b.left.right = new Node(25);\n\nconsole.log(\"tree A:\", isBST(a) ? \"Yes\" : \"No\");\nconsole.log(\"tree B:\", isBST(b) ? \"Yes\" : \"No\");","filename":"JavaScript"},"revision":1},{"id":"25e3107e-409c-7923-9d11-178e20d357d0","type":"code","position":"b0G","content":{"language":"text","code":"tree A: Yes\ntree B: No","filename":"Output"},"revision":1},{"id":"97500669-74a3-7612-a14b-14d742b24c3a","type":"text","position":"b0H","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}},"revision":1},{"id":"c993bd64-dbf6-751e-b8a9-e9af937e9fbf","type":"callout","position":"b0I","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both methods use a "},{"type":"text","text":"strict","marks":[{"type":"bold"}]},{"type":"text","text":" comparison, so a tree with duplicate keys is rejected. If your definition allows duplicates on one side (say "},{"type":"text","text":"left <= node","marks":[{"type":"code"}]},{"type":"text","text":"), relax exactly that one bound — and say so in the interview before you code."}]}]}},"revision":1},{"id":"bb4c8dbc-1124-7294-afa0-5a7b092327a7","type":"heading","position":"b0J","content":{"level":1,"content":[{"type":"text","text":"Fix a BST with two nodes swapped"}]},"revision":1},{"id":"1857df1f-ef38-76f0-94ae-4e5972f6bc17","type":"code","position":"b0K","content":{"language":"text","code":"    given (two keys swapped)             fixed\n            20                             20\n          /    \\                         /    \\\n        60      80        ──▶           8      80\n       /  \\    /  \\                   /  \\    /  \\\n      4   10  8   100                4   10  60   100\n\ninorder:  4  60  10  20  8  80  100   →   4  8  10  20  60  80  100\n             ^^^^^^      ^^^^^\n              dip 1       dip 2","filename":"Swapping 60 and 8 back restores the sorted inorder sequence"},"revision":1},{"id":"a45dc1e8-cfb8-7dc2-9165-1764b9909bd0","type":"callout","position":"b0L","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree above","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"inorder before: 4 60 10 20 8 80 100, after: 4 8 10 20 60 80 100","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"d5d805fa-96ce-7e90-b45a-e18ccef8bbde","type":"callout","position":"b0M","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The inorder sequence of a BST is sorted; swapping two keys creates "},{"type":"text","text":"one or two dips","marks":[{"type":"bold"}]},{"type":"text","text":" (a place where a key is smaller than its predecessor). With two dips, the swapped nodes are the "},{"type":"text","text":"larger","marks":[{"type":"italic"}]},{"type":"text","text":" element of the first dip and the "},{"type":"text","text":"smaller","marks":[{"type":"italic"}]},{"type":"text","text":" element of the second; with one dip (the two nodes are inorder-adjacent) they are the two elements of that dip. Record "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" at the first dip and overwrite "},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":" at every dip, then swap their keys."}]}]}},"revision":1},{"id":"149bee43-333c-7c17-bea4-bda381b0c9f4","type":"text","position":"b0N","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Traverse inorder, remembering ","marks":[{"type":"bold"}]},{"type":"text","text":"prev","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"At each node compare "},{"type":"text","text":"node.key","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"prev.key","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First dip (","marks":[{"type":"bold"}]},{"type":"text","text":"node.key < prev.key","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":")","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Set "},{"type":"text","text":"first = prev","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"second = node","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Second dip","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Only "},{"type":"text","text":"second = node","marks":[{"type":"code"}]},{"type":"text","text":" changes — "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" stays the larger element of the first dip."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Swap","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Exchange "},{"type":"text","text":"first.key","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"second.key","marks":[{"type":"code"}]},{"type":"text","text":". The structure of the tree is untouched."}]}]}]}]}},"revision":1},{"id":"257bbdcb-d674-777f-a221-fc03ce29bed6","type":"code","position":"b0O","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\nclass Fixer:\n    def __init__(self):\n        self.prev = self.first = self.second = None\n\n    def visit(self, node):                        # inorder, looking for dips\n        if node is None:\n            return\n        self.visit(node.left)\n        if self.prev and node.key < self.prev.key:  # a dip: smaller key after a larger one\n            if self.first is None:\n                self.first = self.prev            # first dip: remember the larger element\n            self.second = node                    # the smaller element (overwritten by a 2nd dip)\n        self.prev = node\n        self.visit(node.right)\n\ndef fix_bst(root):\n    f = Fixer()\n    f.visit(root)\n    if f.first and f.second:\n        f.first.key, f.second.key = f.second.key, f.first.key\n\ndef inorder(node, out):\n    if node:\n        inorder(node.left, out)\n        out.append(node.key)\n        inorder(node.right, out)\n\nroot = Node(20)\nroot.left, root.right = Node(60), Node(80)\nroot.left.left, root.left.right = Node(4), Node(10)\nroot.right.left, root.right.right = Node(8), Node(100)\n\nbefore = []\ninorder(root, before)\nprint(\"before:\", *before)\nfix_bst(root)\nafter = []\ninorder(root, after)\nprint(\"after:\", *after)","filename":"Python"},"revision":1},{"id":"be31846d-837e-739c-921a-8337be22eef4","type":"code","position":"b0P","content":{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nstruct Fixer {\n    Node *prev = nullptr, *first = nullptr, *second = nullptr;\n    void visit(Node* node) {                           // inorder, looking for dips\n        if (!node) return;\n        visit(node->left);\n        if (prev && node->key < prev->key) {           // a dip: smaller key after a larger one\n            if (!first) first = prev;                  // first dip: remember the larger element\n            second = node;                             // the smaller element (overwritten by a 2nd dip)\n        }\n        prev = node;\n        visit(node->right);\n    }\n};\n\nvoid fixBST(Node* root) {\n    Fixer f;\n    f.visit(root);\n    if (f.first && f.second) swap(f.first->key, f.second->key);\n}\n\nvoid inorder(Node* node, vector<int>& out) {\n    if (!node) return;\n    inorder(node->left, out);\n    out.push_back(node->key);\n    inorder(node->right, out);\n}\n\nvoid printKeys(const char* label, Node* root) {\n    vector<int> keys;\n    inorder(root, keys);\n    cout << label;\n    for (int k : keys) cout << \" \" << k;\n    cout << \"\\n\";\n}\n\nint main() {\n    Node* root = new Node(20);\n    root->left = new Node(60); root->right = new Node(80);\n    root->left->left = new Node(4); root->left->right = new Node(10);\n    root->right->left = new Node(8); root->right->right = new Node(100);\n\n    printKeys(\"before:\", root);\n    fixBST(root);\n    printKeys(\"after:\", root);\n}","filename":"C++"},"revision":1},{"id":"3547314e-bc4e-7167-aa4f-8fbd2e704c67","type":"code","position":"b0Q","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static class Fixer {\n        Node prev, first, second;\n        void visit(Node node) {                        // inorder, looking for dips\n            if (node == null) return;\n            visit(node.left);\n            if (prev != null && node.key < prev.key) { // a dip: smaller key after a larger one\n                if (first == null) first = prev;       // first dip: remember the larger element\n                second = node;                         // the smaller element (overwritten by a 2nd dip)\n            }\n            prev = node;\n            visit(node.right);\n        }\n    }\n\n    static void fixBST(Node root) {\n        Fixer f = new Fixer();\n        f.visit(root);\n        if (f.first != null && f.second != null) {\n            int t = f.first.key; f.first.key = f.second.key; f.second.key = t;\n        }\n    }\n\n    static void inorder(Node node, List<Integer> out) {\n        if (node == null) return;\n        inorder(node.left, out);\n        out.add(node.key);\n        inorder(node.right, out);\n    }\n\n    static void printKeys(String label, Node root) {\n        List<Integer> keys = new ArrayList<>();\n        inorder(root, keys);\n        StringBuilder sb = new StringBuilder(label);\n        for (int k : keys) sb.append('' '').append(k);\n        System.out.println(sb);\n    }\n\n    public static void main(String[] args) {\n        Node root = new Node(20);\n        root.left = new Node(60); root.right = new Node(80);\n        root.left.left = new Node(4); root.left.right = new Node(10);\n        root.right.left = new Node(8); root.right.right = new Node(100);\n\n        printKeys(\"before:\", root);\n        fixBST(root);\n        printKeys(\"after:\", root);\n    }\n}","filename":"Java"},"revision":1},{"id":"eac3d3de-a385-790c-a779-28313b4739e5","type":"code","position":"b0R","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nclass Fixer {\n    constructor() { this.prev = null; this.first = null; this.second = null; }\n    visit(node) {                                        // inorder, looking for dips\n        if (!node) return;\n        this.visit(node.left);\n        if (this.prev && node.key < this.prev.key) {     // a dip: smaller key after a larger one\n            if (!this.first) this.first = this.prev;     // first dip: remember the larger element\n            this.second = node;                          // the smaller element (overwritten by a 2nd dip)\n        }\n        this.prev = node;\n        this.visit(node.right);\n    }\n}\n\nfunction fixBST(root) {\n    const f = new Fixer();\n    f.visit(root);\n    if (f.first && f.second) [f.first.key, f.second.key] = [f.second.key, f.first.key];\n}\n\nfunction inorder(node, out) {\n    if (!node) return;\n    inorder(node.left, out);\n    out.push(node.key);\n    inorder(node.right, out);\n}\n\nconst root = new Node(20);\nroot.left = new Node(60); root.right = new Node(80);\nroot.left.left = new Node(4); root.left.right = new Node(10);\nroot.right.left = new Node(8); root.right.right = new Node(100);\n\nconst before = [];\ninorder(root, before);\nconsole.log(\"before:\", before.join(\" \"));\nfixBST(root);\nconst after = [];\ninorder(root, after);\nconsole.log(\"after:\", after.join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"aff1606f-236a-7818-8dd0-1839a2e0f844","type":"code","position":"b0S","content":{"language":"text","code":"before: 4 60 10 20 8 80 100\nafter: 4 8 10 20 60 80 100","filename":"Output"},"revision":1},{"id":"9ff8c02f-ce00-75f9-b8d6-0713aab217d8","type":"text","position":"b0T","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(h)"}]}]}},"revision":1},{"id":"b48ffd88-9940-7506-a6b5-1d128b2eaa65","type":"callout","position":"b0U","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setting "},{"type":"text","text":"second = prev","marks":[{"type":"code"}]},{"type":"text","text":" at the second dip (instead of "},{"type":"text","text":"second = node","marks":[{"type":"code"}]},{"type":"text","text":") picks the wrong node. Trace the adjacent case too: in "},{"type":"text","text":"8 / 20 22","marks":[{"type":"code"}]},{"type":"text","text":" (the root "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":" swapped with its child "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"text","text":") the inorder is "},{"type":"text","text":"20 8 22","marks":[{"type":"code"}]},{"type":"text","text":" — a single dip, so "},{"type":"text","text":"first = 20","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"second = 8","marks":[{"type":"code"}]},{"type":"text","text":", and the single swap is correct. The original notes kept "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":" as globals, which breaks as soon as the function is called twice; the "},{"type":"text","text":"Fixer","marks":[{"type":"code"}]},{"type":"text","text":" object above resets them per call."}]}]}},"revision":1},{"id":"b8a1a8ac-ba02-7d4f-99c4-d4b83e19d42d","type":"heading","position":"b0V","content":{"level":1,"content":[{"type":"text","text":"Pair with a given sum in a BST"}]},"revision":1},{"id":"02e0cae7-c5c2-7414-840c-f5ca9718f784","type":"callout","position":"b0W","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, sum = 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes (8 + 22, or 10 + 20)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree A, sum = 29","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"ff3fb6b0-8b49-7796-ac5b-70e6f719cd0b","type":"callout","position":"b0X","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 1 — inorder + two pointers.","marks":[{"type":"bold"}]},{"type":"text","text":" Inorder gives the keys sorted. Then the classic sorted-array trick: a pointer at each end, move the left one right when the sum is too small and the right one left when it is too large. "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time, "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" for the array."}]}]}},"revision":1},{"id":"c1f92d44-70ce-702c-a901-ad9e72192aaf","type":"code","position":"b0Y","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef insert(root, key):\n    if root is None:\n        return Node(key)\n    if key < root.key:\n        root.left = insert(root.left, key)\n    elif key > root.key:\n        root.right = insert(root.right, key)\n    return root\n\ndef inorder(node, out):\n    if node:\n        inorder(node.left, out)\n        out.append(node.key)\n        inorder(node.right, out)\n\ndef pair_sum(root, target):\n    keys = []\n    inorder(root, keys)                     # sorted keys\n    i, j = 0, len(keys) - 1\n    while i < j:                            # two pointers on a sorted array\n        s = keys[i] + keys[j]\n        if s == target:\n            return (keys[i], keys[j])\n        if s < target:\n            i += 1                          # need a bigger sum\n        else:\n            j -= 1                          # need a smaller sum\n    return None\n\nroot = None\nfor x in [20, 8, 22, 4, 12, 10, 14]:\n    root = insert(root, x)\nfor target in (30, 29):\n    res = pair_sum(root, target)\n    print(f\"sum={target}:\", f\"Yes ({res[0]} + {res[1]})\" if res else \"No\")","filename":"Python"},"revision":1},{"id":"2af291ac-a1e3-71e3-9a19-c95ce88d5f90","type":"code","position":"b0Z","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nNode* insert(Node* root, int key) {\n    if (!root) return new Node(key);\n    if (key < root->key) root->left = insert(root->left, key);\n    else if (key > root->key) root->right = insert(root->right, key);\n    return root;\n}\n\nvoid inorder(Node* node, vector<int>& out) {\n    if (!node) return;\n    inorder(node->left, out);\n    out.push_back(node->key);\n    inorder(node->right, out);\n}\n\nbool pairSum(Node* root, int target, int& a, int& b) {\n    vector<int> keys;\n    inorder(root, keys);                              // sorted keys\n    int i = 0, j = (int)keys.size() - 1;\n    while (i < j) {                                   // two pointers on a sorted array\n        int s = keys[i] + keys[j];\n        if (s == target) { a = keys[i]; b = keys[j]; return true; }\n        if (s < target) i++;                          // need a bigger sum\n        else j--;                                     // need a smaller sum\n    }\n    return false;\n}\n\nint main() {\n    Node* root = nullptr;\n    for (int x : {20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n    for (int target : {30, 29}) {\n        int a, b;\n        if (pairSum(root, target, a, b)) cout << \"sum=\" << target << \": Yes (\" << a << \" + \" << b << \")\\n\";\n        else cout << \"sum=\" << target << \": No\\n\";\n    }\n}","filename":"C++"},"revision":1},{"id":"abc841c4-f5a5-7c36-9b65-09f23e7521ab","type":"code","position":"b0a","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node insert(Node root, int key) {\n        if (root == null) return new Node(key);\n        if (key < root.key) root.left = insert(root.left, key);\n        else if (key > root.key) root.right = insert(root.right, key);\n        return root;\n    }\n\n    static void inorder(Node node, List<Integer> out) {\n        if (node == null) return;\n        inorder(node.left, out);\n        out.add(node.key);\n        inorder(node.right, out);\n    }\n\n    static int[] pairSum(Node root, int target) {\n        List<Integer> keys = new ArrayList<>();\n        inorder(root, keys);                              // sorted keys\n        int i = 0, j = keys.size() - 1;\n        while (i < j) {                                   // two pointers on a sorted array\n            int s = keys.get(i) + keys.get(j);\n            if (s == target) return new int[]{keys.get(i), keys.get(j)};\n            if (s < target) i++;                          // need a bigger sum\n            else j--;                                     // need a smaller sum\n        }\n        return null;\n    }\n\n    public static void main(String[] args) {\n        Node root = null;\n        for (int x : new int[]{20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n        for (int target : new int[]{30, 29}) {\n            int[] res = pairSum(root, target);\n            System.out.println(\"sum=\" + target + \": \" + (res == null ? \"No\" : \"Yes (\" + res[0] + \" + \" + res[1] + \")\"));\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"c4c5c2e8-9fa6-7db1-8680-a744a2c3c573","type":"code","position":"b0b","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction insert(root, key) {\n    if (!root) return new Node(key);\n    if (key < root.key) root.left = insert(root.left, key);\n    else if (key > root.key) root.right = insert(root.right, key);\n    return root;\n}\n\nfunction inorder(node, out) {\n    if (!node) return;\n    inorder(node.left, out);\n    out.push(node.key);\n    inorder(node.right, out);\n}\n\nfunction pairSum(root, target) {\n    const keys = [];\n    inorder(root, keys);                                  // sorted keys\n    let i = 0, j = keys.length - 1;\n    while (i < j) {                                       // two pointers on a sorted array\n        const s = keys[i] + keys[j];\n        if (s === target) return [keys[i], keys[j]];\n        if (s < target) i++;                              // need a bigger sum\n        else j--;                                         // need a smaller sum\n    }\n    return null;\n}\n\nlet root = null;\nfor (const x of [20, 8, 22, 4, 12, 10, 14]) root = insert(root, x);\nfor (const target of [30, 29]) {\n    const res = pairSum(root, target);\n    console.log(`sum=${target}:`, res ? `Yes (${res[0]} + ${res[1]})` : \"No\");\n}","filename":"JavaScript"},"revision":1},{"id":"ba867d98-d695-7fea-9ef9-185252fce3f4","type":"code","position":"b0c","content":{"language":"text","code":"sum=30: Yes (8 + 22)\nsum=29: No","filename":"Output"},"revision":1},{"id":"5ca01e3c-daeb-7d8b-bca7-b12d99e31f85","type":"text","position":"b0d","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n)"}]}]}},"revision":1},{"id":"edb738f2-3f59-7f26-9055-53cbe65fca90","type":"callout","position":"b0e","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 2 — hash set during the traversal.","marks":[{"type":"bold"}]},{"type":"text","text":" Visit the nodes (inorder here, but any order works) and keep the keys seen so far in a set. At each node ask whether "},{"type":"text","text":"target - key","marks":[{"type":"code"}]},{"type":"text","text":" has already been seen; if not, add "},{"type":"text","text":"key","marks":[{"type":"code"}]},{"type":"text","text":". This is exactly the array “pair sum with hashing” solution, run on the tree in place. It reports a different (equally valid) pair than the two-pointer method — "},{"type":"text","text":"10 + 20","marks":[{"type":"code"}]},{"type":"text","text":" is complete as soon as "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":" is visited, before "},{"type":"text","text":"22","marks":[{"type":"code"}]},{"type":"text","text":" is reached."}]}]}},"revision":1},{"id":"6517d11a-6bb2-7d3d-95b1-6850a4ec1340","type":"code","position":"b0f","content":{"language":"python","code":"class Node:\n    def __init__(self, key):\n        self.key = key\n        self.left = None\n        self.right = None\n\ndef insert(root, key):\n    if root is None:\n        return Node(key)\n    if key < root.key:\n        root.left = insert(root.left, key)\n    elif key > root.key:\n        root.right = insert(root.right, key)\n    return root\n\ndef pair_sum(node, target, seen):\n    if node is None:\n        return None\n    found = pair_sum(node.left, target, seen)\n    if found:\n        return found\n    if target - node.key in seen:            # the partner was visited earlier\n        return (target - node.key, node.key)\n    seen.add(node.key)\n    return pair_sum(node.right, target, seen)\n\nroot = None\nfor x in [20, 8, 22, 4, 12, 10, 14]:\n    root = insert(root, x)\nfor target in (30, 29):\n    res = pair_sum(root, target, set())      # a fresh set per query\n    print(f\"sum={target}:\", f\"Yes ({res[0]} + {res[1]})\" if res else \"No\")","filename":"Python"},"revision":1},{"id":"89479ea4-a4a1-77fe-aa04-50457e5b7a22","type":"code","position":"b0g","content":{"language":"cpp","code":"#include <iostream>\n#include <unordered_set>\nusing namespace std;\n\nstruct Node {\n    int key;\n    Node *left = nullptr, *right = nullptr;\n    Node(int k) : key(k) {}\n};\n\nNode* insert(Node* root, int key) {\n    if (!root) return new Node(key);\n    if (key < root->key) root->left = insert(root->left, key);\n    else if (key > root->key) root->right = insert(root->right, key);\n    return root;\n}\n\nbool pairSum(Node* node, int target, unordered_set<int>& seen, int& a, int& b) {\n    if (!node) return false;\n    if (pairSum(node->left, target, seen, a, b)) return true;\n    if (seen.count(target - node->key)) {               // the partner was visited earlier\n        a = target - node->key; b = node->key;\n        return true;\n    }\n    seen.insert(node->key);\n    return pairSum(node->right, target, seen, a, b);\n}\n\nint main() {\n    Node* root = nullptr;\n    for (int x : {20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n    for (int target : {30, 29}) {\n        unordered_set<int> seen;                         // a fresh set per query\n        int a, b;\n        if (pairSum(root, target, seen, a, b)) cout << \"sum=\" << target << \": Yes (\" << a << \" + \" << b << \")\\n\";\n        else cout << \"sum=\" << target << \": No\\n\";\n    }\n}","filename":"C++"},"revision":1},{"id":"d571c82d-8950-7a8f-94f0-cdd08e967ddc","type":"code","position":"b0h","content":{"language":"java","code":"import java.util.HashSet;\nimport java.util.Set;\n\npublic class Main {\n    static class Node {\n        int key; Node left, right;\n        Node(int k) { key = k; }\n    }\n\n    static Node insert(Node root, int key) {\n        if (root == null) return new Node(key);\n        if (key < root.key) root.left = insert(root.left, key);\n        else if (key > root.key) root.right = insert(root.right, key);\n        return root;\n    }\n\n    static int[] pairSum(Node node, int target, Set<Integer> seen) {\n        if (node == null) return null;\n        int[] found = pairSum(node.left, target, seen);\n        if (found != null) return found;\n        if (seen.contains(target - node.key))             // the partner was visited earlier\n            return new int[]{target - node.key, node.key};\n        seen.add(node.key);\n        return pairSum(node.right, target, seen);\n    }\n\n    public static void main(String[] args) {\n        Node root = null;\n        for (int x : new int[]{20, 8, 22, 4, 12, 10, 14}) root = insert(root, x);\n        for (int target : new int[]{30, 29}) {\n            int[] res = pairSum(root, target, new HashSet<>());   // a fresh set per query\n            System.out.println(\"sum=\" + target + \": \" + (res == null ? \"No\" : \"Yes (\" + res[0] + \" + \" + res[1] + \")\"));\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"07a04c1f-cfbe-7958-b49b-62b9d5585971","type":"code","position":"b0i","content":{"language":"javascript","code":"class Node {\n    constructor(key) { this.key = key; this.left = null; this.right = null; }\n}\n\nfunction insert(root, key) {\n    if (!root) return new Node(key);\n    if (key < root.key) root.left = insert(root.left, key);\n    else if (key > root.key) root.right = insert(root.right, key);\n    return root;\n}\n\nfunction pairSum(node, target, seen) {\n    if (!node) return null;\n    const found = pairSum(node.left, target, seen);\n    if (found) return found;\n    if (seen.has(target - node.key))                      // the partner was visited earlier\n        return [target - node.key, node.key];\n    seen.add(node.key);\n    return pairSum(node.right, target, seen);\n}\n\nlet root = null;\nfor (const x of [20, 8, 22, 4, 12, 10, 14]) root = insert(root, x);\nfor (const target of [30, 29]) {\n    const res = pairSum(root, target, new Set());        // a fresh set per query\n    console.log(`sum=${target}:`, res ? `Yes (${res[0]} + ${res[1]})` : \"No\");\n}","filename":"JavaScript"},"revision":1},{"id":"d6b07692-b18e-7bf8-9a29-e8c42d0b785a","type":"code","position":"b0j","content":{"language":"text","code":"sum=30: Yes (10 + 20)\nsum=29: No","filename":"Output"},"revision":1},{"id":"17e2f3db-c924-7a82-ba5d-00940c376b60","type":"text","position":"b0k","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n)"}]}]}},"revision":1},{"id":"c9bf34ff-37f4-7455-97d0-63ecc62b3385","type":"callout","position":"b0l","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both methods are "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time and "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" extra space. The "},{"type":"text","text":"O(h)","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" space","marks":[{"type":"bold"}]},{"type":"text","text":" version runs the two-pointer idea directly on the tree: one stack performs a forward inorder (left-node-right) and a second stack a reverse inorder (right-node-left); advance whichever side the two-pointer rule says to move. It is the same algorithm with the sorted array replaced by two lazy iterators."}]}]}},"revision":1},{"id":"c281a96c-0e75-76e2-9803-7ad87872357b","type":"callout","position":"b0m","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"target - node.key in seen","marks":[{"type":"code"}]},{"type":"text","text":" must be checked "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"seen.add(node.key)","marks":[{"type":"code"}]},{"type":"text","text":"; otherwise a node pairs with itself when "},{"type":"text","text":"target = 2 * key","marks":[{"type":"code"}]},{"type":"text","text":" (sum "},{"type":"text","text":"40","marks":[{"type":"code"}]},{"type":"text","text":" would report "},{"type":"text","text":"20 + 20","marks":[{"type":"code"}]},{"type":"text","text":" on tree A)."}]}]}},"revision":1},{"id":"e8937022-e080-729d-8835-92e7113fac00","type":"heading","position":"b0n","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"aaa483f1-5a73-73ac-885a-9dd9ad09068a","type":"question","position":"b0o","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is the inorder traversal of a BST sorted?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Inorder visits the left subtree, then the node, then the right subtree. By the BST invariant everything in the left subtree is smaller than the node and everything in the right subtree is larger, and the same holds recursively inside each subtree — so the sequence produced is ascending. Reverse inorder (right, node, left) gives descending order."}]}]}},"revision":1},{"id":"c73972f6-3d84-7ef5-b3e2-5fd15e53c0cf","type":"question","position":"b0p","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the kth smallest in O(h) when the tree changes over time?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Augment every node with the size of its left subtree. Insert and delete update that count along the single path they touch ("},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":"), and the query walks down comparing "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"lcount + 1","marks":[{"type":"code"}]},{"type":"text","text":". The plain inorder method is "},{"type":"text","text":"O(h + k)","marks":[{"type":"code"}]},{"type":"text","text":" per query and needs no extra field — fine for one-off queries, not for a stream of them."}]}]}},"revision":1},{"id":"e3d40474-804b-7f9d-b57d-521dde3d9b10","type":"question","position":"b0q","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does comparing a node with its children not prove a tree is a BST?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because the invariant constrains a node by "},{"type":"text","text":"all","marks":[{"type":"bold"}]},{"type":"text","text":" its ancestors. In tree B above, "},{"type":"text","text":"25","marks":[{"type":"code"}]},{"type":"text","text":" is a valid right child of "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"text","text":" but it lives in the left subtree of "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":", where every key must be below "},{"type":"text","text":"20","marks":[{"type":"code"}]},{"type":"text","text":". Pass down the "},{"type":"text","text":"(lo, hi)","marks":[{"type":"code"}]},{"type":"text","text":" range from the ancestors, or check that the inorder sequence strictly increases — both are "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"7ef82ed8-21e0-74ba-94d8-a2e6b60d72b7","type":"question","position":"b0r","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two nodes of a BST were swapped. How many dips can the inorder sequence have, and which nodes do you swap back?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One or two. If the swapped nodes are adjacent in inorder there is one dip and its two elements are the culprits. Otherwise there are two dips: the larger element of the first dip and the smaller element of the second. Recording "},{"type":"text","text":"first = prev","marks":[{"type":"code"}]},{"type":"text","text":" only at the first dip and "},{"type":"text","text":"second = node","marks":[{"type":"code"}]},{"type":"text","text":" at every dip handles both cases with one pass."}]}]}},"revision":1},{"id":"74cd7235-4cca-75f1-80c4-ffc48fdb712b","type":"question","position":"b0s","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are std::set, TreeMap and heapq in terms of BSTs?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"std::set","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"std::map","marks":[{"type":"code"}]},{"type":"text","text":" and Java''s "},{"type":"text","text":"TreeSet","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"TreeMap","marks":[{"type":"code"}]},{"type":"text","text":" are red-black trees — self-balancing BSTs with "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" insert, delete, "},{"type":"text","text":"lower_bound","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"ceiling","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"floor","marks":[{"type":"code"}]},{"type":"text","text":" and ordered iteration. "},{"type":"text","text":"heapq","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" a BST: a heap only exposes its minimum, so it cannot answer floor/ceiling or kth queries. Python and JavaScript have no ordered-set container in the standard library."}]}]}},"revision":1},{"id":"62569b2b-2bcb-7f85-a724-6b2d0f1c3200","type":"question","position":"b0t","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you find the lowest common ancestor of two keys in a BST?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk down from the root: if both keys are smaller go left, if both are larger go right, otherwise the current node is the split point and therefore the LCA. "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":" time, no parent pointers and no recursion needed — a general binary tree needs an "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" traversal instead."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
