SELECT '106745a5-588a-790f-b254-a14e42a0ad23', 'cb7ae394-c66b-754e-a632-58215d9ad546', 1, 'PUBLISHED', 'Disjoint Set', '[{"id":"1ef7edad-8a50-7efc-96cf-e9f08ddd2c40","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A disjoint-set (union–find) structure keeps track of a collection of elements partitioned into "},{"type":"text","text":"non-overlapping groups","marks":[{"type":"bold"}]},{"type":"text","text":", and answers two questions almost instantly: "},{"type":"text","text":"which group is x in?","marks":[{"type":"italic"}]},{"type":"text","text":" and "},{"type":"text","text":"merge the groups of x and y","marks":[{"type":"italic"}]},{"type":"text","text":". It is the engine behind Kruskal''s MST, cycle detection and dynamic connectivity."}]}]}},"revision":1},{"id":"27dfd4d3-3c96-7727-973a-d83a88d39fbe","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Disjoint set (union–find)","marks":[{"type":"bold"}]},{"type":"text","text":" — a data structure over elements "},{"type":"text","text":"0 … n-1","marks":[{"type":"code"}]},{"type":"text","text":" that maintains a partition into disjoint sets, each identified by one "},{"type":"text","text":"representative","marks":[{"type":"bold"}]},{"type":"text","text":" element, supporting "},{"type":"text","text":"find(x)","marks":[{"type":"code"}]},{"type":"text","text":" → representative of "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":"''s set, and "},{"type":"text","text":"union(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" → merge the two sets containing "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ff763bb9-6e34-77fd-a6e3-5dcc2466b7ea","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The problem: dynamic connectivity"}]},"revision":1},{"id":"fd66e465-5906-71ad-834f-9f09488d3ee3","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" people are initially strangers. Two operations arrive in any order: "},{"type":"text","text":"makeFriends(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" — now "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":" are in the same friend circle (friendship is transitive) — and "},{"type":"text","text":"areFriends(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" — are they in the same circle? Answer the queries as they come, with no knowledge of future operations."}]}]}},"revision":1},{"id":"3383ac77-4b5d-7a6c-9b2a-5ff5e6df715b","type":"callout","position":"a4","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 4; makeFriends(0, 1), makeFriends(1, 3), areFriends(0, 2), areFriends(0, 1), areFriends(0, 3)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No Yes Yes","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"8f5ddbf0-5dec-7645-9771-366fa1f537cd","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Approach"}],[{"type":"text","text":"makeFriends","marks":[{"type":"code"}]}],[{"type":"text","text":"areFriends","marks":[{"type":"code"}]}],[{"type":"text","text":"Problem"}]],[[{"type":"text","text":"Adjacency list + DFS/BFS"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n + m) — traverse the graph"}],[{"type":"text","text":"a query must explore the whole component"}]],[[{"type":"text","text":"Adjacency matrix + DFS/BFS"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n²)"}],[{"type":"text","text":"same, and n² memory"}]],[[{"type":"text","text":"Store the component id of every node"}],[{"type":"text","text":"Θ(n) — relabel one whole component"}],[{"type":"text","text":"Θ(1)"}],[{"type":"text","text":"every merge rewrites up to n labels"}]],[[{"type":"text","text":"Disjoint set","marks":[{"type":"bold"}]}],[{"type":"text","text":"≈ O(1)","marks":[{"type":"bold"}]},{"type":"text","text":" amortised"}],[{"type":"text","text":"≈ O(1)","marks":[{"type":"bold"}]},{"type":"text","text":" amortised"}],[{"type":"text","text":"—"}]]]},"revision":1},{"id":"96b7e46c-221b-7677-a186-abed68a7c3b0","type":"callout","position":"a6","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Represent every set as a "},{"type":"text","text":"tree","marks":[{"type":"bold"}]},{"type":"text","text":": each element stores its parent, the root is the set''s representative. "},{"type":"text","text":"find(x)","marks":[{"type":"code"}]},{"type":"text","text":" climbs to the root. "},{"type":"text","text":"union(x, y)","marks":[{"type":"code"}]},{"type":"text","text":" makes one root the parent of the other. Two elements are in the same set exactly when they climb to the same root."}]}]}},"revision":1},{"id":"60d26c18-7cb0-7add-9c64-116c9537f9c9","type":"code","position":"a7","content":{"language":"text","code":"initially                 makeFriends(0, 1)        makeFriends(1, 3)\nparent: 0 1 2 3           parent: 0 0 2 3          parent: 0 0 2 0\n\n(0) (1) (2) (3)            (0)   (2) (3)              (0)    (2)\n                            │                         / \\\n                           (1)                      (1) (3)\n\nareFriends(0, 2): find(0)=0, find(2)=2 → No\nareFriends(0, 3): find(0)=0, find(3)=0 → Yes","filename":"Each set is a tree stored in a parent array; a root is its own parent"},"revision":1},{"id":"a72afa3e-8d9a-7be3-adee-e88bea5429f4","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Basic implementation: parent array"}]},"revision":1},{"id":"45ca2676-fd0b-7729-be41-8ede4c5238b1","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"make_set","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"parent[i] = i","marks":[{"type":"code"}]},{"type":"text","text":" for every element — "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" singleton sets."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"find(x)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Follow "},{"type":"text","text":"parent","marks":[{"type":"code"}]},{"type":"text","text":" links until reaching an element that is its own parent; that root is the representative."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"union(x, y)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"rx = find(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"ry = find(y)","marks":[{"type":"code"}]},{"type":"text","text":"; if they differ, "},{"type":"text","text":"parent[ry] = rx","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"areFriends(x, y)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"find(x) == find(y)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"a824bef3-e915-7193-a9db-0b78041b1a55","type":"code","position":"aA","content":{"language":"python","code":"class DisjointSet:\n    def __init__(self, n):\n        self.parent = list(range(n))       # every element starts as its own set\n\n    def find(self, x):\n        while self.parent[x] != x:         # climb to the root\n            x = self.parent[x]\n        return x\n\n    def union(self, x, y):\n        rx, ry = self.find(x), self.find(y)\n        if rx != ry:\n            self.parent[ry] = rx           # hang one tree under the other root\n\n    def are_friends(self, x, y):\n        return self.find(x) == self.find(y)\n\nds = DisjointSet(4)\nds.union(0, 1)                             # makeFriends\nds.union(1, 3)\nfor x, y in [(0, 2), (0, 1), (0, 3)]:\n    print(f\"areFriends({x}, {y}):\", \"Yes\" if ds.are_friends(x, y) else \"No\")\nprint(\"parent:\", \" \".join(map(str, ds.parent)))","filename":"Python"},"revision":1},{"id":"c37cbb09-4328-72dc-81b6-e52d61cd8652","type":"code","position":"aB","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass DisjointSet {\n    vector<int> parent;\npublic:\n    DisjointSet(int n) : parent(n) {\n        for (int i = 0; i < n; i++) parent[i] = i;      // every element starts as its own set\n    }\n    int find(int x) {\n        while (parent[x] != x) x = parent[x];          // climb to the root\n        return x;\n    }\n    void unite(int x, int y) {                         // \"union\" is a C++ keyword\n        int rx = find(x), ry = find(y);\n        if (rx != ry) parent[ry] = rx;                 // hang one tree under the other root\n    }\n    bool areFriends(int x, int y) { return find(x) == find(y); }\n    const vector<int>& parents() const { return parent; }\n};\n\nint main() {\n    DisjointSet ds(4);\n    ds.unite(0, 1);                                    // makeFriends\n    ds.unite(1, 3);\n    int queries[3][2] = {{0, 2}, {0, 1}, {0, 3}};\n    for (auto& q : queries)\n        cout << \"areFriends(\" << q[0] << \", \" << q[1] << \"): \" << (ds.areFriends(q[0], q[1]) ? \"Yes\" : \"No\") << \"\\n\";\n    cout << \"parent:\";\n    for (int p : ds.parents()) cout << \" \" << p;\n    cout << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"15da2d3a-8cb4-792d-b445-1b62af11f3ca","type":"code","position":"aC","content":{"language":"java","code":"public class Main {\n    static class DisjointSet {\n        int[] parent;\n        DisjointSet(int n) {\n            parent = new int[n];\n            for (int i = 0; i < n; i++) parent[i] = i;   // every element starts as its own set\n        }\n        int find(int x) {\n            while (parent[x] != x) x = parent[x];       // climb to the root\n            return x;\n        }\n        void union(int x, int y) {\n            int rx = find(x), ry = find(y);\n            if (rx != ry) parent[ry] = rx;              // hang one tree under the other root\n        }\n        boolean areFriends(int x, int y) { return find(x) == find(y); }\n    }\n\n    public static void main(String[] args) {\n        DisjointSet ds = new DisjointSet(4);\n        ds.union(0, 1);                                 // makeFriends\n        ds.union(1, 3);\n        int[][] queries = {{0, 2}, {0, 1}, {0, 3}};\n        for (int[] q : queries)\n            System.out.println(\"areFriends(\" + q[0] + \", \" + q[1] + \"): \" + (ds.areFriends(q[0], q[1]) ? \"Yes\" : \"No\"));\n        StringBuilder sb = new StringBuilder(\"parent:\");\n        for (int p : ds.parent) sb.append('' '').append(p);\n        System.out.println(sb);\n    }\n}","filename":"Java"},"revision":1},{"id":"5a0a0da6-97ab-79b1-9192-a0db6599e660","type":"code","position":"aD","content":{"language":"javascript","code":"class DisjointSet {\n    constructor(n) { this.parent = Array.from({ length: n }, (_, i) => i); }   // every element is its own set\n    find(x) {\n        while (this.parent[x] !== x) x = this.parent[x];   // climb to the root\n        return x;\n    }\n    union(x, y) {\n        const rx = this.find(x), ry = this.find(y);\n        if (rx !== ry) this.parent[ry] = rx;               // hang one tree under the other root\n    }\n    areFriends(x, y) { return this.find(x) === this.find(y); }\n}\n\nconst ds = new DisjointSet(4);\nds.union(0, 1);                                            // makeFriends\nds.union(1, 3);\nfor (const [x, y] of [[0, 2], [0, 1], [0, 3]])\n    console.log(`areFriends(${x}, ${y}):`, ds.areFriends(x, y) ? \"Yes\" : \"No\");\nconsole.log(\"parent:\", ds.parent.join(\" \"));","filename":"JavaScript"},"revision":1},{"id":"d733c201-f39a-7989-8bcb-b954a3e3e496","type":"code","position":"aE","content":{"language":"text","code":"areFriends(0, 2): No\nareFriends(0, 1): Yes\nareFriends(0, 3): Yes\nparent: 0 0 2 0","filename":"Output"},"revision":1},{"id":"ddcf9cdf-ed9c-7061-8b89-e303e155abe6","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) worst case per operation — the tree can degenerate into a chain · Space O(n)"}]}]}},"revision":1},{"id":"27dce041-372b-7579-84a7-b4b4bd5ddab4","type":"callout","position":"aG","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive union can build a tree that is a straight line: "},{"type":"text","text":"union(1,0), union(2,1), union(3,2), …","marks":[{"type":"code"}]},{"type":"text","text":" makes "},{"type":"text","text":"find(0)","marks":[{"type":"code"}]},{"type":"text","text":" walk "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" steps. The two optimisations below exist to keep every tree shallow."}]}]}},"revision":1},{"id":"b3bdf97e-d509-7581-a82f-39563cacc309","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Union by rank (or by size)"}]},"revision":1},{"id":"08019e67-2392-7421-9b3b-dcff1147df10","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep an extra array "},{"type":"text","text":"rank","marks":[{"type":"code"}]},{"type":"text","text":" that stores an upper bound on the "},{"type":"text","text":"height","marks":[{"type":"bold"}]},{"type":"text","text":" of each root''s tree. When uniting two roots, make the root of the "},{"type":"text","text":"shorter","marks":[{"type":"bold"}]},{"type":"text","text":" tree a child of the taller one — the height does not grow. Only when both have equal rank does the merged tree get one level taller."}]}]}},"revision":1},{"id":"3eb04d02-d4b6-7470-9043-ec44345f52af","type":"code","position":"aJ","content":{"language":"text","code":"rank[rx] < rank[ry]          rank[rx] > rank[ry]          rank[rx] == rank[ry]\nparent[rx] = ry              parent[ry] = rx              parent[ry] = rx; rank[rx] += 1\n\n    (ry)                         (rx)                         (rx)  rank+1\n   /  │  \\                      /  │  \\                      /  │  \\\n ...  ... (rx)                ...  ... (ry)                 ...  ... (ry)","filename":"Attach the shallower tree under the deeper root — height grows only on a tie"},"revision":1},{"id":"1ffc3655-a014-7474-b7ef-15e95bba2194","type":"table","position":"aK","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Variant"}],[{"type":"text","text":"What is compared"}],[{"type":"text","text":"Guarantee"}]],[[{"type":"text","text":"Union by rank"}],[{"type":"text","text":"height bound of the two trees"}],[{"type":"text","text":"height ≤ "},{"type":"text","text":"log₂ n","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"find","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Union by size"}],[{"type":"text","text":"number of elements in the two trees (attach smaller under larger)"}],[{"type":"text","text":"same "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" bound; the size array is useful in its own right (component sizes)"}]]]},"revision":1},{"id":"3458dbc9-cde6-7fcc-9c74-05b07257ccd8","type":"callout","position":"aL","content":{"variant":"note","title":"Why log n","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With union by rank alone, a tree of height "},{"type":"text","text":"h","marks":[{"type":"code"}]},{"type":"text","text":" must contain at least "},{"type":"text","text":"2^h","marks":[{"type":"code"}]},{"type":"text","text":" elements (each rank increase doubles the minimum size), so no tree is deeper than "},{"type":"text","text":"log₂ n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"391de635-e119-768f-998b-2a787998205d","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Path compression"}]},"revision":1},{"id":"0ab7648b-bdd2-72a1-aa09-043c26b3162e","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"find(x)","marks":[{"type":"code"}]},{"type":"text","text":" already visits every node on the path from "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" to the root. While it is there, "},{"type":"text","text":"re-point each of them directly at the root","marks":[{"type":"bold"}]},{"type":"text","text":" — the next "},{"type":"text","text":"find","marks":[{"type":"code"}]},{"type":"text","text":" on any of them is a single step. The parent array is only ever changed in a way that keeps the same sets."}]}]}},"revision":1},{"id":"f01b4f84-f414-7699-af9e-9038af9c8508","type":"code","position":"aO","content":{"language":"text","code":"before find(6)                      after find(6)\n\n     (0)                               (0)\n     / \\                             / | \\\n   (1) (2)                         (1)(2)(4)        6 and 4 now point straight at 0;\n         │                              │   \\       5 still points at 4 (it was not on the path)\n        (4)                            (3)  (6) …\n       /   \\\n     (5)   (6)","filename":"Path compression flattens the path that find() walks"},"revision":1},{"id":"38510ba3-6cb7-7085-88af-ae996bf9e46b","type":"callout","position":"aP","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 7; union(0,1) union(2,3) union(4,5) union(1,3) union(5,6) union(3,5); then find(6)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"parent array before / after shows the compression; connected(2, 5) = Yes","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"24cd4215-f79b-7ea7-83d2-cf7dc5ae9def","type":"code","position":"aQ","content":{"language":"python","code":"class DisjointSet:\n    def __init__(self, n):\n        self.parent = list(range(n))\n        self.rank = [0] * n                    # upper bound on the height of each root''s tree\n        self.components = n\n\n    def find(self, x):\n        if self.parent[x] != x:\n            self.parent[x] = self.find(self.parent[x])   # path compression: point straight at the root\n        return self.parent[x]\n\n    def union(self, x, y):\n        rx, ry = self.find(x), self.find(y)\n        if rx == ry:\n            return False                       # already in the same set\n        if self.rank[rx] < self.rank[ry]:      # union by rank: shallower tree goes under the deeper root\n            rx, ry = ry, rx\n        self.parent[ry] = rx\n        if self.rank[rx] == self.rank[ry]:\n            self.rank[rx] += 1                 # only a tie makes the tree taller\n        self.components -= 1\n        return True\n\n    def connected(self, x, y):\n        return self.find(x) == self.find(y)\n\nds = DisjointSet(7)\nfor x, y in [(0, 1), (2, 3), (4, 5), (1, 3), (5, 6), (3, 5)]:\n    ds.union(x, y)\nprint(\"parent after unions:\", \" \".join(map(str, ds.parent)))\nprint(\"find(6) =\", ds.find(6))\nprint(\"parent after find(6):\", \" \".join(map(str, ds.parent)))\nprint(\"connected(2, 5):\", \"Yes\" if ds.connected(2, 5) else \"No\")\nprint(\"connected(3, 6):\", \"Yes\" if ds.connected(3, 6) else \"No\")\nprint(\"components:\", ds.components)","filename":"Python"},"revision":1},{"id":"8c14cd81-cdf8-73fb-ad7a-4865f801325c","type":"code","position":"aR","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass DisjointSet {\n    vector<int> parent, rnk;                      // rnk = upper bound on the height of each root''s tree\npublic:\n    int components;\n    DisjointSet(int n) : parent(n), rnk(n, 0), components(n) {\n        for (int i = 0; i < n; i++) parent[i] = i;\n    }\n    int find(int x) {\n        if (parent[x] != x) parent[x] = find(parent[x]);   // path compression: point straight at the root\n        return parent[x];\n    }\n    bool unite(int x, int y) {\n        int rx = find(x), ry = find(y);\n        if (rx == ry) return false;               // already in the same set\n        if (rnk[rx] < rnk[ry]) swap(rx, ry);      // union by rank: shallower tree goes under the deeper root\n        parent[ry] = rx;\n        if (rnk[rx] == rnk[ry]) rnk[rx]++;        // only a tie makes the tree taller\n        components--;\n        return true;\n    }\n    bool connected(int x, int y) { return find(x) == find(y); }\n    void printParents(const string& label) {\n        cout << label << \":\";\n        for (int p : parent) cout << \" \" << p;\n        cout << \"\\n\";\n    }\n};\n\nint main() {\n    DisjointSet ds(7);\n    int edges[6][2] = {{0, 1}, {2, 3}, {4, 5}, {1, 3}, {5, 6}, {3, 5}};\n    for (auto& e : edges) ds.unite(e[0], e[1]);\n    ds.printParents(\"parent after unions\");\n    cout << \"find(6) = \" << ds.find(6) << \"\\n\";\n    ds.printParents(\"parent after find(6)\");\n    cout << \"connected(2, 5): \" << (ds.connected(2, 5) ? \"Yes\" : \"No\") << \"\\n\";\n    cout << \"connected(3, 6): \" << (ds.connected(3, 6) ? \"Yes\" : \"No\") << \"\\n\";\n    cout << \"components: \" << ds.components << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"f6163a34-8e4f-7c48-9996-e3c924b0a584","type":"code","position":"aS","content":{"language":"java","code":"public class Main {\n    static class DisjointSet {\n        int[] parent, rank;                           // rank = upper bound on the height of each root''s tree\n        int components;\n        DisjointSet(int n) {\n            parent = new int[n]; rank = new int[n]; components = n;\n            for (int i = 0; i < n; i++) parent[i] = i;\n        }\n        int find(int x) {\n            if (parent[x] != x) parent[x] = find(parent[x]);   // path compression: point straight at the root\n            return parent[x];\n        }\n        boolean union(int x, int y) {\n            int rx = find(x), ry = find(y);\n            if (rx == ry) return false;               // already in the same set\n            if (rank[rx] < rank[ry]) { int t = rx; rx = ry; ry = t; }   // union by rank: shallower under deeper\n            parent[ry] = rx;\n            if (rank[rx] == rank[ry]) rank[rx]++;     // only a tie makes the tree taller\n            components--;\n            return true;\n        }\n        boolean connected(int x, int y) { return find(x) == find(y); }\n        String parents() {\n            StringBuilder sb = new StringBuilder();\n            for (int p : parent) sb.append('' '').append(p);\n            return sb.toString();\n        }\n    }\n\n    public static void main(String[] args) {\n        DisjointSet ds = new DisjointSet(7);\n        int[][] edges = {{0, 1}, {2, 3}, {4, 5}, {1, 3}, {5, 6}, {3, 5}};\n        for (int[] e : edges) ds.union(e[0], e[1]);\n        System.out.println(\"parent after unions:\" + ds.parents());\n        System.out.println(\"find(6) = \" + ds.find(6));\n        System.out.println(\"parent after find(6):\" + ds.parents());\n        System.out.println(\"connected(2, 5): \" + (ds.connected(2, 5) ? \"Yes\" : \"No\"));\n        System.out.println(\"connected(3, 6): \" + (ds.connected(3, 6) ? \"Yes\" : \"No\"));\n        System.out.println(\"components: \" + ds.components);\n    }\n}","filename":"Java"},"revision":1},{"id":"512cd232-abac-727c-a1cc-6b1eef641a59","type":"code","position":"aT","content":{"language":"javascript","code":"class DisjointSet {\n    constructor(n) {\n        this.parent = Array.from({ length: n }, (_, i) => i);\n        this.rank = new Array(n).fill(0);             // upper bound on the height of each root''s tree\n        this.components = n;\n    }\n    find(x) {\n        if (this.parent[x] !== x) this.parent[x] = this.find(this.parent[x]);   // path compression\n        return this.parent[x];\n    }\n    union(x, y) {\n        let rx = this.find(x), ry = this.find(y);\n        if (rx === ry) return false;                  // already in the same set\n        if (this.rank[rx] < this.rank[ry]) [rx, ry] = [ry, rx];   // union by rank: shallower under deeper\n        this.parent[ry] = rx;\n        if (this.rank[rx] === this.rank[ry]) this.rank[rx]++;     // only a tie makes the tree taller\n        this.components--;\n        return true;\n    }\n    connected(x, y) { return this.find(x) === this.find(y); }\n}\n\nconst ds = new DisjointSet(7);\nfor (const [x, y] of [[0, 1], [2, 3], [4, 5], [1, 3], [5, 6], [3, 5]]) ds.union(x, y);\nconsole.log(\"parent after unions:\", ds.parent.join(\" \"));\nconsole.log(\"find(6) =\", ds.find(6));\nconsole.log(\"parent after find(6):\", ds.parent.join(\" \"));\nconsole.log(\"connected(2, 5):\", ds.connected(2, 5) ? \"Yes\" : \"No\");\nconsole.log(\"connected(3, 6):\", ds.connected(3, 6) ? \"Yes\" : \"No\");\nconsole.log(\"components:\", ds.components);","filename":"JavaScript"},"revision":1},{"id":"b31e8950-9d39-7d0b-a656-803c97811b4b","type":"code","position":"aU","content":{"language":"text","code":"parent after unions: 0 0 0 0 0 4 4\nfind(6) = 0\nparent after find(6): 0 0 0 0 0 4 0\nconnected(2, 5): Yes\nconnected(3, 6): Yes\ncomponents: 1","filename":"Output"},"revision":1},{"id":"517abe56-36fc-782b-97c5-5a7357066525","type":"text","position":"aV","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(α(n)) amortised per operation — effectively constant · Space O(n)"}]}]}},"revision":1},{"id":"66dff50e-68a6-7cc5-9527-9c5d0f01cc4e","type":"table","position":"aW","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Optimisations used"}],[{"type":"text","text":"Amortised cost per operation"}]],[[{"type":"text","text":"none"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"union by rank only"}],[{"type":"text","text":"O(log n)"}]],[[{"type":"text","text":"path compression only"}],[{"type":"text","text":"O(log n)"}]],[[{"type":"text","text":"both","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(α(n))","marks":[{"type":"bold"}]},{"type":"text","text":" — the inverse Ackermann function, "},{"type":"text","text":"≤ 4","marks":[{"type":"code"}]},{"type":"text","text":" for every "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" that fits in the universe"}]]]},"revision":1},{"id":"99b45be7-c34d-7c83-8e6c-3fb56598d81c","type":"callout","position":"aX","content":{"variant":"note","title":"Rank ≠ height","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After path compression the "},{"type":"text","text":"rank","marks":[{"type":"code"}]},{"type":"text","text":" values are no longer exact heights — they are only upper bounds. That is fine: the proof of the "},{"type":"text","text":"log n","marks":[{"type":"code"}]},{"type":"text","text":" bound only needs ranks to be upper bounds, and leaving them untouched keeps "},{"type":"text","text":"find","marks":[{"type":"code"}]},{"type":"text","text":" simple."}]}]}},"revision":1},{"id":"27deb618-6da3-76a3-8dbf-7e61127b1b16","type":"callout","position":"aY","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The recursive "},{"type":"text","text":"find","marks":[{"type":"code"}]},{"type":"text","text":" compresses the path but recurses once per level. Python''s recursion limit (1000) can be hit on adversarial inputs "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" the first compression; an iterative two-pass version (first find the root, then re-point every node on the path) avoids that."}]}]}},"revision":1},{"id":"fb800056-b6a3-754f-87a2-1317b98e4223","type":"heading","position":"aZ","content":{"level":1,"content":[{"type":"text","text":"Detect a cycle in an undirected graph"}]},"revision":1},{"id":"68896b32-431d-7533-bf56-7adb32e8101e","type":"text","position":"aa","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Process the edges one by one. For edge "},{"type":"text","text":"(u, v)","marks":[{"type":"code"}]},{"type":"text","text":": if "},{"type":"text","text":"u","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"v","marks":[{"type":"code"}]},{"type":"text","text":" are already in the same set, this edge closes a "},{"type":"text","text":"cycle","marks":[{"type":"bold"}]},{"type":"text","text":"; otherwise unite them. This is also exactly the test Kruskal''s algorithm uses to decide whether an edge may join the spanning tree."}]}]}},"revision":1},{"id":"a720823f-2686-7357-a7a3-92dc1aeaab1c","type":"callout","position":"ab","content":{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 4, edges = (0,1) (1,2) (2,3) (3,1)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"cycle found at edge 3-1","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"77f705c3-f753-7c50-9a27-eb4393693581","type":"callout","position":"ac","content":{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An edge between two vertices that are already connected creates a second path between them — a cycle. Union–find answers \"already connected?\" in near-constant time, so the whole scan is "},{"type":"text","text":"O(E · α(V))","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"40c47f1b-b08d-74ef-97bf-c144b13ae9a1","type":"code","position":"ad","content":{"language":"python","code":"class DisjointSet:\n    def __init__(self, n):\n        self.parent = list(range(n))\n        self.rank = [0] * n\n\n    def find(self, x):\n        if self.parent[x] != x:\n            self.parent[x] = self.find(self.parent[x])\n        return self.parent[x]\n\n    def union(self, x, y):\n        rx, ry = self.find(x), self.find(y)\n        if rx == ry:\n            return False\n        if self.rank[rx] < self.rank[ry]:\n            rx, ry = ry, rx\n        self.parent[ry] = rx\n        if self.rank[rx] == self.rank[ry]:\n            self.rank[rx] += 1\n        return True\n\ndef has_cycle(n, edges):\n    ds = DisjointSet(n)\n    for u, v in edges:\n        if ds.find(u) == ds.find(v):                 # already connected → this edge closes a cycle\n            print(f\"edge {u}-{v}: already connected → cycle\")\n            return True\n        ds.union(u, v)\n        print(f\"edge {u}-{v}: joined\")\n    return False\n\nedges = [(0, 1), (1, 2), (2, 3), (3, 1)]\nprint(\"graph has a cycle:\", \"Yes\" if has_cycle(4, edges) else \"No\")","filename":"Python"},"revision":1},{"id":"d3ad7f9f-9e38-76ab-b409-c3bff0ae049e","type":"code","position":"ae","content":{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct DisjointSet {\n    vector<int> parent, rnk;\n    DisjointSet(int n) : parent(n), rnk(n, 0) { for (int i = 0; i < n; i++) parent[i] = i; }\n    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }\n    bool unite(int x, int y) {\n        int rx = find(x), ry = find(y);\n        if (rx == ry) return false;\n        if (rnk[rx] < rnk[ry]) swap(rx, ry);\n        parent[ry] = rx;\n        if (rnk[rx] == rnk[ry]) rnk[rx]++;\n        return true;\n    }\n};\n\nbool hasCycle(int n, const vector<pair<int,int>>& edges) {\n    DisjointSet ds(n);\n    for (auto [u, v] : edges) {\n        if (ds.find(u) == ds.find(v)) {              // already connected → this edge closes a cycle\n            cout << \"edge \" << u << \"-\" << v << \": already connected → cycle\\n\";\n            return true;\n        }\n        ds.unite(u, v);\n        cout << \"edge \" << u << \"-\" << v << \": joined\\n\";\n    }\n    return false;\n}\n\nint main() {\n    vector<pair<int,int>> edges = {{0, 1}, {1, 2}, {2, 3}, {3, 1}};\n    bool cyc = hasCycle(4, edges);\n    cout << \"graph has a cycle: \" << (cyc ? \"Yes\" : \"No\") << \"\\n\";\n}","filename":"C++"},"revision":1},{"id":"97d3e132-eece-7a58-90af-e97f81421918","type":"code","position":"af","content":{"language":"java","code":"public class Main {\n    static class DisjointSet {\n        int[] parent, rank;\n        DisjointSet(int n) { parent = new int[n]; rank = new int[n]; for (int i = 0; i < n; i++) parent[i] = i; }\n        int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }\n        boolean union(int x, int y) {\n            int rx = find(x), ry = find(y);\n            if (rx == ry) return false;\n            if (rank[rx] < rank[ry]) { int t = rx; rx = ry; ry = t; }\n            parent[ry] = rx;\n            if (rank[rx] == rank[ry]) rank[rx]++;\n            return true;\n        }\n    }\n\n    static boolean hasCycle(int n, int[][] edges) {\n        DisjointSet ds = new DisjointSet(n);\n        for (int[] e : edges) {\n            int u = e[0], v = e[1];\n            if (ds.find(u) == ds.find(v)) {              // already connected → this edge closes a cycle\n                System.out.println(\"edge \" + u + \"-\" + v + \": already connected → cycle\");\n                return true;\n            }\n            ds.union(u, v);\n            System.out.println(\"edge \" + u + \"-\" + v + \": joined\");\n        }\n        return false;\n    }\n\n    public static void main(String[] args) {\n        int[][] edges = {{0, 1}, {1, 2}, {2, 3}, {3, 1}};\n        boolean cyc = hasCycle(4, edges);\n        System.out.println(\"graph has a cycle: \" + (cyc ? \"Yes\" : \"No\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"ba6796df-a47f-759a-9ba3-8c4751b0bd60","type":"code","position":"ag","content":{"language":"javascript","code":"class DisjointSet {\n    constructor(n) { this.parent = Array.from({ length: n }, (_, i) => i); this.rank = new Array(n).fill(0); }\n    find(x) { return this.parent[x] === x ? x : (this.parent[x] = this.find(this.parent[x])); }\n    union(x, y) {\n        let rx = this.find(x), ry = this.find(y);\n        if (rx === ry) return false;\n        if (this.rank[rx] < this.rank[ry]) [rx, ry] = [ry, rx];\n        this.parent[ry] = rx;\n        if (this.rank[rx] === this.rank[ry]) this.rank[rx]++;\n        return true;\n    }\n}\n\nfunction hasCycle(n, edges) {\n    const ds = new DisjointSet(n);\n    for (const [u, v] of edges) {\n        if (ds.find(u) === ds.find(v)) {                 // already connected → this edge closes a cycle\n            console.log(`edge ${u}-${v}: already connected → cycle`);\n            return true;\n        }\n        ds.union(u, v);\n        console.log(`edge ${u}-${v}: joined`);\n    }\n    return false;\n}\n\nconst edges = [[0, 1], [1, 2], [2, 3], [3, 1]];\nconst cyc = hasCycle(4, edges);\nconsole.log(\"graph has a cycle:\", cyc ? \"Yes\" : \"No\");","filename":"JavaScript"},"revision":1},{"id":"ac2c5bb4-b660-7504-a1a9-ed9191256003","type":"code","position":"ah","content":{"language":"text","code":"edge 0-1: joined\nedge 1-2: joined\nedge 2-3: joined\nedge 3-1: already connected → cycle\ngraph has a cycle: Yes","filename":"Output"},"revision":1},{"id":"2a8068a0-d04b-70b9-a364-a5a377295000","type":"text","position":"ai","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(E · α(V)) · Space O(V)"}]}]}},"revision":1},{"id":"d850ac6f-77d5-7b50-b163-c6734c4267db","type":"callout","position":"aj","content":{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This test is for "},{"type":"text","text":"undirected","marks":[{"type":"bold"}]},{"type":"text","text":" graphs only. In a directed graph the edges "},{"type":"text","text":"a → b","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"c → b","marks":[{"type":"code"}]},{"type":"text","text":" put "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":" in one set without any cycle; directed cycle detection needs DFS with colours (see Graphs)."}]}]}},"revision":1},{"id":"87880854-eb0c-7a9c-8983-1e8667b66478","type":"heading","position":"ak","content":{"level":1,"content":[{"type":"text","text":"Where disjoint sets are used"}]},"revision":1},{"id":"dd0edcd0-2401-7121-a608-92b6559a6880","type":"callout","position":"al","content":{"variant":"note","title":"Kruskal''s MST","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sort edges by weight; add an edge iff its endpoints are in different sets."}]}]}},"revision":1},{"id":"f60f5987-584f-747e-811d-639012380139","type":"callout","position":"am","content":{"variant":"note","title":"Connected components","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Union every edge; the number of roots is the number of components — "},{"type":"text","text":"components","marks":[{"type":"code"}]},{"type":"text","text":" above."}]}]}},"revision":1},{"id":"5149ced3-c05e-7f63-8a32-f7a6114aa0f2","type":"callout","position":"an","content":{"variant":"note","title":"Cycle detection","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An edge inside one set closes a cycle (above)."}]}]}},"revision":1},{"id":"ded96c4e-d9d5-727d-895a-3dbb3112e56b","type":"callout","position":"ao","content":{"variant":"note","title":"Dynamic connectivity","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Answer \"are x and y connected?\" while edges keep arriving — the friends problem."}]}]}},"revision":1},{"id":"70d2428d-4885-70aa-a4e2-a08d8e626b88","type":"callout","position":"ap","content":{"variant":"note","title":"Image / grid regions","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flood-fill alternatives: unite neighbouring pixels of the same colour (number of islands)."}]}]}},"revision":1},{"id":"2591cbaa-98cd-7785-b99d-797a0582b0ba","type":"callout","position":"aq","content":{"variant":"note","title":"Percolation, LCA (Tarjan), equivalence classes","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any problem that merges groups and never splits them."}]}]}},"revision":1},{"id":"96e36196-91f9-7ec9-b8fb-154b9f7fb630","type":"callout","position":"ar","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Union–find supports "},{"type":"text","text":"merge only","marks":[{"type":"bold"}]},{"type":"text","text":" — there is no efficient "},{"type":"text","text":"split","marks":[{"type":"code"}]},{"type":"text","text":". If sets must be separated again, it is the wrong structure (use offline processing in reverse, or a link-cut tree)."}]}]}},"revision":1},{"id":"a4d3377e-3c8e-7953-a284-231e5aac8f2e","type":"heading","position":"as","content":{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]},"revision":1},{"id":"0651422f-536f-7c73-b81c-6bf4fbf76ed5","type":"question","position":"at","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the amortised complexity of union–find with both optimisations, and what does α(n) mean?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"O(α(n))","marks":[{"type":"code"}]},{"type":"text","text":" per operation amortised, where "},{"type":"text","text":"α","marks":[{"type":"code"}]},{"type":"text","text":" is the "},{"type":"text","text":"inverse Ackermann function","marks":[{"type":"bold"}]},{"type":"text","text":" — it grows so slowly that "},{"type":"text","text":"α(n) ≤ 4","marks":[{"type":"code"}]},{"type":"text","text":" for any "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" below "},{"type":"text","text":"2^65536","marks":[{"type":"code"}]},{"type":"text","text":". In practice every operation is constant time. Tarjan proved this bound is tight for the structure."}]}]}},"revision":1},{"id":"64c9ec6c-f8c6-7fc5-b882-06c2f802bbbe","type":"question","position":"au","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Union by rank vs union by size — any difference?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both guarantee "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" tree height and "},{"type":"text","text":"O(α(n))","marks":[{"type":"code"}]},{"type":"text","text":" with path compression. Size is more useful when you also need component sizes (e.g. \"size of the largest group\"); rank is a smaller number to store. Never attach arbitrarily — that is what allows "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" chains."}]}]}},"revision":1},{"id":"1984c180-2a59-70d0-9af0-b42cfd11d11b","type":"question","position":"av","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does path compression work and why doesn''t it break the sets?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"During "},{"type":"text","text":"find(x)","marks":[{"type":"code"}]},{"type":"text","text":", every node on the path to the root gets "},{"type":"text","text":"parent[node] = root","marks":[{"type":"code"}]},{"type":"text","text":". Membership is defined by "},{"type":"text","text":"which root you reach","marks":[{"type":"italic"}]},{"type":"text","text":", not by the exact path, so re-pointing nodes at the same root changes nothing about the sets while making future finds shorter."}]}]}},"revision":1},{"id":"320e9901-104d-792f-acd7-e784902e848e","type":"question","position":"aw","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you detect a cycle in an undirected graph with union–find?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Process the edges; for "},{"type":"text","text":"(u, v)","marks":[{"type":"code"}]},{"type":"text","text":" check "},{"type":"text","text":"find(u) == find(v)","marks":[{"type":"code"}]},{"type":"text","text":". Equal → the edge connects two already-connected vertices → cycle. Otherwise "},{"type":"text","text":"union(u, v)","marks":[{"type":"code"}]},{"type":"text","text":". Total "},{"type":"text","text":"O(E · α(V))","marks":[{"type":"code"}]},{"type":"text","text":". It also counts components: "},{"type":"text","text":"V − (number of successful unions)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"fb069e4d-1d57-7323-9577-ceef20021bca","type":"question","position":"ax","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does Kruskal''s algorithm rely on union–find?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kruskal adds the cheapest edge that does not form a cycle. The cycle test on each of "},{"type":"text","text":"E","marks":[{"type":"code"}]},{"type":"text","text":" sorted edges would cost "},{"type":"text","text":"O(V)","marks":[{"type":"code"}]},{"type":"text","text":" with DFS; union–find makes it near constant, giving "},{"type":"text","text":"O(E log E)","marks":[{"type":"code"}]},{"type":"text","text":" total dominated by the sort."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = 'cb7ae394-c66b-754e-a632-58215d9ad546' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
