SELECT 'topic:dsa-advanced/hashing', 'ca052dec-a795-7109-9b0d-864d7de176d6', 'd21dfa90231bd441d7a6e6ea0dcd418c35a5ffa5885fdb3fd7cd47633f6bc199', '8752406e-18c9-766f-bfd8-e41d5041f4f5', TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
