INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, 'd18587f6-230c-7885-b43c-9ec559cc68ce', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('a4564d80-5b7b-7a07-8f5e-cc36621b3761', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A heap gives you the smallest (or largest) element of a changing collection in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":", with "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" insert and remove. Almost every “top k”, “k-way merge” and “running statistic” problem is a heap of the right "},{"type":"text","text":"type","marks":[{"type":"bold"}]},{"type":"text","text":" and the right "},{"type":"text","text":"size","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}}'),
  ('f0988d86-2d40-7f50-ac6d-ca59457aafbc', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary heap","marks":[{"type":"bold"}]},{"type":"text","text":" — a complete binary tree stored in an array where every node is "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" its children ("},{"type":"text","text":"min-heap","marks":[{"type":"bold"}]},{"type":"text","text":") or "},{"type":"text","text":">=","marks":[{"type":"code"}]},{"type":"text","text":" its children ("},{"type":"text","text":"max-heap","marks":[{"type":"bold"}]},{"type":"text","text":"). The root is therefore the minimum (or maximum). A "},{"type":"text","text":"priority queue","marks":[{"type":"italic"}]},{"type":"text","text":" is the abstract interface; a binary heap is its usual implementation."}]}]}}'),
  ('311b701d-bb62-701b-8285-87c346352e64', 'a2', 'code', '{"language":"text","code":"min-heap as a tree              the same heap as an array\n         5                      index:  0   1   2   3   4\n       /   \\                   value:  5   8  10  15  20\n      8     10\n     / \\                       parent(i) = (i - 1) / 2\n   15   20                     children(i) = 2i + 1, 2i + 2","filename":"A heap is just an array with a parent/child index rule — no pointers"}'),
  ('91ea5c63-7f75-7b38-8bf5-75f626632e62', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"How"}]],[[{"type":"text","text":"peek()","marks":[{"type":"code"}]},{"type":"text","text":" — min or max"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"it is "},{"type":"text","text":"a[0]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"push(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"append, then "},{"type":"text","text":"sift up","marks":[{"type":"italic"}]},{"type":"text","text":" while smaller than the parent"}]],[[{"type":"text","text":"pop()","marks":[{"type":"code"}]}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"move the last element to the root, then "},{"type":"text","text":"sift down","marks":[{"type":"italic"}]}]],[[{"type":"text","text":"heapify(array)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"sift down from the last internal node to the root — cheaper than "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" pushes"}]],[[{"type":"text","text":"search for an arbitrary key"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"a heap is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" sorted; only the root is special"}]]]}'),
  ('c9eb9256-2eee-7186-94dd-9a754f621ca8', 'a4', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The heap property says nothing about the order between siblings or between subtrees — "},{"type":"text","text":"a[1..]","marks":[{"type":"code"}]},{"type":"text","text":" is not sorted. Printing the array of a heap or iterating a "},{"type":"text","text":"PriorityQueue","marks":[{"type":"code"}]},{"type":"text","text":" gives an arbitrary-looking order; to get sorted output you must pop repeatedly."}]}]}}'),
  ('34c9b07f-381e-7dd0-baa3-29f72cda6725', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Priority queues in each language"}]}'),
  ('ef2c1af2-d427-7e3a-bf2c-af28aafab6ef', 'a6', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Language"}],[{"type":"text","text":"Type"}],[{"type":"text","text":"Default"}],[{"type":"text","text":"Max-heap"}]],[[{"type":"text","text":"Python"}],[{"type":"text","text":"heapq","marks":[{"type":"code"}]},{"type":"text","text":" functions on a list"}],[{"type":"text","text":"min-heap"}],[{"type":"text","text":"push "},{"type":"text","text":"-x","marks":[{"type":"code"}]},{"type":"text","text":", negate on pop (or "},{"type":"text","text":"(-key, item)","marks":[{"type":"code"}]},{"type":"text","text":" tuples)"}]],[[{"type":"text","text":"C++"}],[{"type":"text","text":"std::priority_queue<T>","marks":[{"type":"code"}]}],[{"type":"text","text":"max","marks":[{"type":"bold"}]},{"type":"text","text":"-heap"}],[{"type":"text","text":"default; min-heap needs "},{"type":"text","text":"priority_queue<T, vector<T>, greater<T>>","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Java"}],[{"type":"text","text":"java.util.PriorityQueue<T>","marks":[{"type":"code"}]}],[{"type":"text","text":"min-heap"}],[{"type":"text","text":"new PriorityQueue<>(Collections.reverseOrder())","marks":[{"type":"code"}]},{"type":"text","text":" or a comparator"}]],[[{"type":"text","text":"JavaScript"}],[{"type":"text","text":"none built in"}],[{"type":"text","text":"—"}],[{"type":"text","text":"write a small "},{"type":"text","text":"Heap","marks":[{"type":"code"}]},{"type":"text","text":" class with a comparator once (below) and reuse it"}]]]}'),
  ('9e3ca49c-014f-77b6-9131-8e0505b73e54', 'a7', 'code', '{"language":"python","code":"import heapq\n\nnums = [5, 15, 10, 20, 8]\n\nmn = []                                  # heapq is a min-heap only\nfor x in nums:\n    heapq.heappush(mn, x)\nprint(\"min-heap:\", *(heapq.heappop(mn) for _ in range(len(nums))))\n\nmx = [-x for x in nums]                  # max-heap: store the negated keys\nheapq.heapify(mx)                        # O(n) build\nprint(\"max-heap:\", *(-heapq.heappop(mx) for _ in range(len(nums))))","filename":"Python"}'),
  ('26b94d20-f267-752a-8265-cc041bd7363b', 'a8', 'code', '{"language":"cpp","code":"#include <functional>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> nums = {5, 15, 10, 20, 8};\n\n    priority_queue<int, vector<int>, greater<int>> mn;     // min-heap needs greater<>\n    for (int x : nums) mn.push(x);\n    cout << \"min-heap:\";\n    while (!mn.empty()) { cout << \" \" << mn.top(); mn.pop(); }\n    cout << \"\\n\";\n\n    priority_queue<int> mx(nums.begin(), nums.end());       // default is a max-heap; O(n) build\n    cout << \"max-heap:\";\n    while (!mx.empty()) { cout << \" \" << mx.top(); mx.pop(); }\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('94287211-085b-7c22-8961-e9a5975c1bbb', 'a9', 'code', '{"language":"java","code":"import java.util.Collections;\nimport java.util.PriorityQueue;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] nums = {5, 15, 10, 20, 8};\n\n        PriorityQueue<Integer> mn = new PriorityQueue<>();        // min-heap by default\n        for (int x : nums) mn.add(x);\n        StringBuilder sb = new StringBuilder(\"min-heap:\");\n        while (!mn.isEmpty()) sb.append('' '').append(mn.poll());\n        System.out.println(sb);\n\n        PriorityQueue<Integer> mx = new PriorityQueue<>(Collections.reverseOrder());   // or (a, b) -> b - a\n        for (int x : nums) mx.add(x);\n        sb = new StringBuilder(\"max-heap:\");\n        while (!mx.isEmpty()) sb.append('' '').append(mx.poll());\n        System.out.println(sb);\n    }\n}","filename":"Java"}'),
  ('febd2cb7-9625-7fff-8b08-e57da5f674fd', 'aA', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }   // cmp(x, y) < 0 → x comes out first\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {                                    // sift up\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {                                     // sift down\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nconst nums = [5, 15, 10, 20, 8];\n\nconst mn = new Heap((a, b) => a - b);                      // min-heap\nfor (const x of nums) mn.push(x);\nconst small = [];\nwhile (mn.size()) small.push(mn.pop());\nconsole.log(\"min-heap:\", small.join(\" \"));\n\nconst mx = new Heap((a, b) => b - a);                      // max-heap: flip the comparator\nfor (const x of nums) mx.push(x);\nconst big = [];\nwhile (mx.size()) big.push(mx.pop());\nconsole.log(\"max-heap:\", big.join(\" \"));","filename":"JavaScript"}'),
  ('b4c2509f-216e-7558-800a-fcc5b57e86bd', 'aB', 'code', '{"language":"text","code":"min-heap: 5 8 10 15 20\nmax-heap: 20 15 10 8 5","filename":"Output"}'),
  ('9e2f0315-1ef7-715e-9486-fe033f9553f4', 'aC', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The JavaScript "},{"type":"text","text":"Heap","marks":[{"type":"code"}]},{"type":"text","text":" class above is reused unchanged in every solution below — comparator "},{"type":"text","text":"(a, b) => a - b","marks":[{"type":"code"}]},{"type":"text","text":" for a min-heap, "},{"type":"text","text":"(a, b) => b - a","marks":[{"type":"code"}]},{"type":"text","text":" for a max-heap, or compare a field of an array/object. Python''s "},{"type":"text","text":"heapq","marks":[{"type":"code"}]},{"type":"text","text":" compares tuples lexicographically, which is how "},{"type":"text","text":"(key, payload)","marks":[{"type":"code"}]},{"type":"text","text":" pairs are ordered in the k-closest and merge problems."}]}]}}'),
  ('ac52e6c4-6928-7c2f-a63e-f5083cbe54a7', 'aD', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python: "},{"type":"text","text":"heapq.heappush(h, -x)","marks":[{"type":"code"}]},{"type":"text","text":" and forgetting to negate on the way out is the classic max-heap slip. Java: "},{"type":"text","text":"(a, b) -> b - a","marks":[{"type":"code"}]},{"type":"text","text":" overflows for values near "},{"type":"text","text":"Integer.MIN_VALUE","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"MAX_VALUE","marks":[{"type":"code"}]},{"type":"text","text":" — use "},{"type":"text","text":"Integer.compare(b, a)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Collections.reverseOrder()","marks":[{"type":"code"}]},{"type":"text","text":". C++: remember the default "},{"type":"text","text":"priority_queue","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"max","marks":[{"type":"bold"}]},{"type":"text","text":"-heap."}]}]}}'),
  ('962ce576-063e-737a-9ae4-45c67986478c', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Sort a k-sorted (nearly sorted) array"}]}'),
  ('63f6b5ae-92fc-7681-b3ab-ca00e9619f0b', 'aF', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [9, 8, 7, 18, 19, 17], k = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"7 8 9 17 18 19","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 9, 8, 7, 4, 70, 60, 50], k = 4","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"4 7 8 9 10 50 60 70","marks":[{"type":"code"}]}]}]}}'),
  ('f2dd188f-e920-77ff-acbc-fae0b5a12c51', 'aG', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every element is at most "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" positions away from its sorted position. A full sort is "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":"; exploiting "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" gives "},{"type":"text","text":"O(n log k)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b9f53c78-c738-75dd-891c-fac9018c8925', 'aH', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The element that belongs at index "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" lies somewhere in "},{"type":"text","text":"arr[i..i+k]","marks":[{"type":"code"}]},{"type":"text","text":". So keep a min-heap of the next "},{"type":"text","text":"k+1","marks":[{"type":"code"}]},{"type":"text","text":" unplaced elements: its minimum is guaranteed to be the next output. Push one element, and whenever the heap holds "},{"type":"text","text":"k+1","marks":[{"type":"code"}]},{"type":"text","text":" items pop its minimum into the result; drain the heap at the end."}]}]}}'),
  ('43acc370-4c88-72db-a63a-0e0dd2002946', 'aI', 'code', '{"language":"python","code":"import heapq\n\ndef sort_k(arr, k):\n    h, res = [], []\n    for x in arr:\n        heapq.heappush(h, x)\n        if len(h) > k:                   # k+1 elements inside → the minimum is final\n            res.append(heapq.heappop(h))\n    while h:                             # drain the last k elements in order\n        res.append(heapq.heappop(h))\n    return res\n\nprint(*sort_k([9, 8, 7, 18, 19, 17], 2))\nprint(*sort_k([10, 9, 8, 7, 4, 70, 60, 50], 4))","filename":"Python"}'),
  ('39f16854-c7fc-7d39-98e7-c43fd5844aab', 'aJ', 'code', '{"language":"cpp","code":"#include <functional>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nvector<int> sortK(const vector<int>& arr, int k) {\n    priority_queue<int, vector<int>, greater<int>> h;     // min-heap\n    vector<int> res;\n    for (int x : arr) {\n        h.push(x);\n        if ((int)h.size() > k) { res.push_back(h.top()); h.pop(); }   // k+1 inside → the minimum is final\n    }\n    while (!h.empty()) { res.push_back(h.top()); h.pop(); }           // drain the last k elements\n    return res;\n}\n\nvoid print(const vector<int>& v) {\n    for (int i = 0; i < (int)v.size(); i++) cout << (i ? \" \" : \"\") << v[i];\n    cout << \"\\n\";\n}\n\nint main() {\n    print(sortK({9, 8, 7, 18, 19, 17}, 2));\n    print(sortK({10, 9, 8, 7, 4, 70, 60, 50}, 4));\n}","filename":"C++"}'),
  ('488c1e1f-c226-75af-8fda-33ba008f82de', 'aK', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.PriorityQueue;\n\npublic class Main {\n    static List<Integer> sortK(int[] arr, int k) {\n        PriorityQueue<Integer> h = new PriorityQueue<>();     // min-heap\n        List<Integer> res = new ArrayList<>();\n        for (int x : arr) {\n            h.add(x);\n            if (h.size() > k) res.add(h.poll());              // k+1 inside → the minimum is final\n        }\n        while (!h.isEmpty()) res.add(h.poll());               // drain the last k elements\n        return res;\n    }\n\n    static String join(List<Integer> xs) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : xs) sb.append(x).append('' '');\n        return sb.toString().trim();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(join(sortK(new int[]{9, 8, 7, 18, 19, 17}, 2)));\n        System.out.println(join(sortK(new int[]{10, 9, 8, 7, 4, 70, 60, 50}, 4)));\n    }\n}","filename":"Java"}'),
  ('112a1d40-5d4b-7056-b0d7-932f1d7c033d', 'aL', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nfunction sortK(arr, k) {\n    const h = new Heap(), res = [];                        // min-heap\n    for (const x of arr) {\n        h.push(x);\n        if (h.size() > k) res.push(h.pop());               // k+1 inside → the minimum is final\n    }\n    while (h.size()) res.push(h.pop());                    // drain the last k elements\n    return res;\n}\n\nconsole.log(sortK([9, 8, 7, 18, 19, 17], 2).join(\" \"));\nconsole.log(sortK([10, 9, 8, 7, 4, 70, 60, 50], 4).join(\" \"));","filename":"JavaScript"}'),
  ('23adf5b5-8dd8-7b60-ae33-102c56abbd87', 'aM', 'code', '{"language":"text","code":"7 8 9 17 18 19\n4 7 8 9 10 50 60 70","filename":"Output"}'),
  ('6ef4eaf8-46d9-73ed-8b25-47f216826abb', 'aN', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log k) · Space O(k)"}]}]}}'),
  ('cc50ae21-134b-741b-851c-3115abfc5a67', 'aO', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The heap must hold "},{"type":"text","text":"k + 1","marks":[{"type":"code"}]},{"type":"text","text":" elements before you trust its minimum, not "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":": with "},{"type":"text","text":"k = 2","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"[9, 8, 7, …]","marks":[{"type":"code"}]},{"type":"text","text":", the "},{"type":"text","text":"7","marks":[{"type":"code"}]},{"type":"text","text":" is only pushed as the third element. Popping after "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" pushes would emit "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"text","text":" first. When "},{"type":"text","text":"k >= n","marks":[{"type":"code"}]},{"type":"text","text":" the method degenerates to heap sort — still correct, just "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4e02a095-fb91-75f3-8625-4060f8261075', 'aP', 'heading', '{"level":1,"content":[{"type":"text","text":"Purchase maximum items with a budget"}]}'),
  ('a49b5904-1fbe-7e70-ab3d-d23842e04b65', 'aQ', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"cost = [1, 12, 5, 111, 200], budget = 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2 (buy 1 and 5)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"cost = [20, 10, 5, 30, 100], budget = 35","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 (buy 5, 10 and 20)","marks":[{"type":"code"}]}]}]}}'),
  ('d1d2f683-7f81-73bc-a420-6f8cf47e9e9e', 'aR', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Greedy: always buy the cheapest remaining item — a more expensive one can never let you afford "},{"type":"text","text":"more","marks":[{"type":"italic"}]},{"type":"text","text":" items. Sorting gives the cheapest items in order in "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]}}'),
  ('78268cae-a7bb-75f3-a919-6626868c5105', 'aS', 'code', '{"language":"python","code":"def max_items_sorted(cost, budget):\n    count = 0\n    for c in sorted(cost):            # cheapest first\n        if c > budget:\n            break\n        budget -= c\n        count += 1\n    return count\n\nprint(max_items_sorted([1, 12, 5, 111, 200], 10))\nprint(max_items_sorted([20, 10, 5, 30, 100], 35))","filename":"Python"}'),
  ('ba271227-1d70-7146-8a49-9941a4e36c27', 'aT', 'code', '{"language":"text","code":"2\n3","filename":"Output"}'),
  ('7e0f6e66-4885-76c9-a340-dab4ce34b4cb', 'aU', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log n) · Space O(1) extra (in-place sort)"}]},{"type":"paragraph","content":[{"type":"text","text":"But you usually stop long before the end — the budget runs out after "},{"type":"text","text":"r","marks":[{"type":"code"}]},{"type":"text","text":" items. A min-heap built in "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" and popped "},{"type":"text","text":"r","marks":[{"type":"code"}]},{"type":"text","text":" times costs "},{"type":"text","text":"O(n + r log n)","marks":[{"type":"code"}]},{"type":"text","text":", which beats a sort when "},{"type":"text","text":"r","marks":[{"type":"code"}]},{"type":"text","text":" is small (a tight budget, a huge catalogue)."}]}]}}'),
  ('36141c31-c9a4-72fa-b374-d47d44c61244', 'aV', 'code', '{"language":"python","code":"import heapq\n\ndef max_items(cost, budget):\n    h = list(cost)\n    heapq.heapify(h)                     # O(n) — cheaper than sorting everything\n    count = 0\n    while h and h[0] <= budget:          # cheapest remaining item is affordable\n        budget -= heapq.heappop(h)\n        count += 1\n    return count\n\nprint(max_items([1, 12, 5, 111, 200], 10))\nprint(max_items([20, 10, 5, 30, 100], 35))","filename":"Python"}'),
  ('09a179b1-e403-7a27-8eb6-8e23a2247a2f', 'aW', 'code', '{"language":"cpp","code":"#include <functional>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint maxItems(const vector<int>& cost, int budget) {\n    priority_queue<int, vector<int>, greater<int>> h(cost.begin(), cost.end());   // O(n) heapify\n    int count = 0;\n    while (!h.empty() && h.top() <= budget) {    // cheapest remaining item is affordable\n        budget -= h.top();\n        h.pop();\n        count++;\n    }\n    return count;\n}\n\nint main() {\n    cout << maxItems({1, 12, 5, 111, 200}, 10) << \"\\n\";\n    cout << maxItems({20, 10, 5, 30, 100}, 35) << \"\\n\";\n}","filename":"C++"}'),
  ('bb9d27e1-1cb6-780f-a64d-404a1ff40054', 'aX', 'code', '{"language":"java","code":"import java.util.PriorityQueue;\n\npublic class Main {\n    static int maxItems(int[] cost, int budget) {\n        PriorityQueue<Integer> h = new PriorityQueue<>();\n        for (int c : cost) h.add(c);                 // n pushes: O(n log n); a Collection ctor heapifies in O(n)\n        int count = 0;\n        while (!h.isEmpty() && h.peek() <= budget) { // cheapest remaining item is affordable\n            budget -= h.poll();\n            count++;\n        }\n        return count;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(maxItems(new int[]{1, 12, 5, 111, 200}, 10));\n        System.out.println(maxItems(new int[]{20, 10, 5, 30, 100}, 35));\n    }\n}","filename":"Java"}'),
  ('f6b74486-cdd2-768e-80e6-c143984c04ce', 'aY', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nfunction maxItems(cost, budget) {\n    const h = new Heap();                            // min-heap\n    for (const c of cost) h.push(c);\n    let count = 0;\n    while (h.size() && h.peek() <= budget) {         // cheapest remaining item is affordable\n        budget -= h.pop();\n        count++;\n    }\n    return count;\n}\n\nconsole.log(maxItems([1, 12, 5, 111, 200], 10));\nconsole.log(maxItems([20, 10, 5, 30, 100], 35));","filename":"JavaScript"}'),
  ('4934a1f0-06ea-79cb-9ee0-b007a4e502cc', 'aZ', 'code', '{"language":"text","code":"2\n3","filename":"Output"}'),
  ('581ccbb1-1f96-7542-a940-4937f6933637', 'aa', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n + r log n) · Space O(n)"}]}]}}'),
  ('67b80962-3678-7ca7-8c4c-7b6a7628ccc7', 'ab', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes'' heap version had two bugs: it iterated "},{"type":"text","text":"for i in cost","marks":[{"type":"code"}]},{"type":"text","text":" while popping from the "},{"type":"text","text":"same","marks":[{"type":"italic"}]},{"type":"text","text":" list ("},{"type":"text","text":"pq = cost","marks":[{"type":"code"}]},{"type":"text","text":" aliases, it does not copy), and the driver called the sorting function instead. Copy the list before "},{"type":"text","text":"heapify","marks":[{"type":"code"}]},{"type":"text","text":", and loop on the heap''s top, not on an index."}]}]}}'),
  ('58160358-862f-7692-a8ba-33d9402956fb', 'ac', 'heading', '{"level":1,"content":[{"type":"text","text":"K largest elements"}]}'),
  ('b1ce3e73-668a-7fe3-9d39-6725b85ce1dd', 'ad', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [5, 15, 10, 20, 8], k = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"15 20","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [3, 9, 1, 7, 5, 8], k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"7 8 9","marks":[{"type":"code"}]}]}]}}'),
  ('04cbc63b-edba-792c-b72e-b22ea1797de6', 'ae', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep a "},{"type":"text","text":"min-heap of size k","marks":[{"type":"bold"}]},{"type":"text","text":" holding the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" largest elements seen so far. Its root is the smallest of those "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" — the "},{"type":"text","text":"threshold","marks":[{"type":"italic"}]},{"type":"text","text":". A new element that is not above the threshold can never be in the answer; one that is replaces the root. The heap is tiny, so each step is "},{"type":"text","text":"O(log k)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('27e22a53-cbb6-75fc-9e22-65115abb8214', 'af', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Build","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Put the first "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" elements into a min-heap."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan the rest","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"x <= heap.top()","marks":[{"type":"code"}]},{"type":"text","text":" ignore it; otherwise pop the top and push "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Collect","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The heap now holds exactly the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" largest. Pop them for ascending order."}]}]}]}]}}'),
  ('e42d11a0-89b4-7d38-a38b-39b4c1d28de8', 'ag', 'code', '{"language":"python","code":"import heapq\n\ndef k_largest(arr, k):\n    h = arr[:k]\n    heapq.heapify(h)                      # min-heap of the k largest seen so far\n    for x in arr[k:]:\n        if x > h[0]:                      # bigger than the current threshold\n            heapq.heapreplace(h, x)       # pop the root and push x in one sift\n    return sorted(h)\n\nprint(*k_largest([5, 15, 10, 20, 8], 2))\nprint(*k_largest([3, 9, 1, 7, 5, 8], 3))","filename":"Python"}'),
  ('dbc5a4b4-dd05-7d79-96fe-a57878eb6b73', 'ah', 'code', '{"language":"cpp","code":"#include <algorithm>\n#include <functional>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nvector<int> kLargest(const vector<int>& arr, int k) {\n    priority_queue<int, vector<int>, greater<int>> h;     // min-heap of the k largest seen so far\n    int n = arr.size();\n    for (int i = 0; i < n; i++) {\n        if (i < k) h.push(arr[i]);\n        else if (arr[i] > h.top()) { h.pop(); h.push(arr[i]); }   // beats the threshold\n    }\n    vector<int> res;\n    while (!h.empty()) { res.push_back(h.top()); h.pop(); }       // popped in ascending order\n    return res;\n}\n\nvoid print(const vector<int>& v) {\n    for (int i = 0; i < (int)v.size(); i++) cout << (i ? \" \" : \"\") << v[i];\n    cout << \"\\n\";\n}\n\nint main() {\n    print(kLargest({5, 15, 10, 20, 8}, 2));\n    print(kLargest({3, 9, 1, 7, 5, 8}, 3));\n}","filename":"C++"}'),
  ('7fdfe885-13bb-71ab-b83b-6efd13624511', 'ai', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.PriorityQueue;\n\npublic class Main {\n    static List<Integer> kLargest(int[] arr, int k) {\n        PriorityQueue<Integer> h = new PriorityQueue<>();     // min-heap of the k largest seen so far\n        for (int i = 0; i < arr.length; i++) {\n            if (i < k) h.add(arr[i]);\n            else if (arr[i] > h.peek()) { h.poll(); h.add(arr[i]); }   // beats the threshold\n        }\n        List<Integer> res = new ArrayList<>();\n        while (!h.isEmpty()) res.add(h.poll());               // polled in ascending order\n        return res;\n    }\n\n    static String join(List<Integer> xs) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : xs) sb.append(x).append('' '');\n        return sb.toString().trim();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(join(kLargest(new int[]{5, 15, 10, 20, 8}, 2)));\n        System.out.println(join(kLargest(new int[]{3, 9, 1, 7, 5, 8}, 3)));\n    }\n}","filename":"Java"}'),
  ('0d647ba8-c27e-73c6-bddb-43cf59ab83ad', 'aj', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nfunction kLargest(arr, k) {\n    const h = new Heap();                                  // min-heap of the k largest seen so far\n    for (let i = 0; i < arr.length; i++) {\n        if (i < k) h.push(arr[i]);\n        else if (arr[i] > h.peek()) { h.pop(); h.push(arr[i]); }   // beats the threshold\n    }\n    const res = [];\n    while (h.size()) res.push(h.pop());                    // popped in ascending order\n    return res;\n}\n\nconsole.log(kLargest([5, 15, 10, 20, 8], 2).join(\" \"));\nconsole.log(kLargest([3, 9, 1, 7, 5, 8], 3).join(\" \"));","filename":"JavaScript"}'),
  ('d72076ef-00cb-7064-a92c-963e3a397272', 'ak', 'code', '{"language":"text","code":"15 20\n7 8 9","filename":"Output"}'),
  ('86a38efd-041d-787f-8bbc-236578fc05f0', 'al', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log k) · Space O(k)"}]},{"type":"paragraph","content":[{"type":"text","text":"The alternative is a max-heap of "},{"type":"text","text":"all","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" elements, popped "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" times. It is simpler and gives the results largest-first, but it needs "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" memory and cannot process a stream:"}]}]}}'),
  ('87d2210c-ac39-7397-841c-ab1beaadeb00', 'am', 'code', '{"language":"python","code":"import heapq\n\ndef k_largest_maxheap(arr, k):\n    h = [-x for x in arr]                   # max-heap via negation\n    heapq.heapify(h)                        # O(n)\n    return [-heapq.heappop(h) for _ in range(k)]   # k pops, O(k log n)\n\nprint(*k_largest_maxheap([5, 15, 10, 20, 8], 2))","filename":"Python"}'),
  ('57f3d5c2-463e-7f9c-b292-5e936b170509', 'an', 'code', '{"language":"text","code":"20 15","filename":"Output"}'),
  ('5ad246de-eecc-7f8a-991f-5c9a28afd534', 'ao', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Approach"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Space"}],[{"type":"text","text":"Works on a stream?"}]],[[{"type":"text","text":"sort, take the last "},{"type":"text","text":"k","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log n)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"no"}]],[[{"type":"text","text":"max-heap of all, pop "},{"type":"text","text":"k","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n + k log n)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"no"}]],[[{"type":"text","text":"min-heap of size ","marks":[{"type":"bold"}]},{"type":"text","text":"k","marks":[{"type":"bold"},{"type":"code"}]}],[{"type":"text","text":"O(n log k)"}],[{"type":"text","text":"O(k)"}],[{"type":"text","text":"yes — the heap is the running answer"}]],[[{"type":"text","text":"quickselect"}],[{"type":"text","text":"O(n) average"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"no (unordered result)"}]]]}'),
  ('6917ce14-520b-7ed9-af28-f1fc0a479d94', 'ap', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a "},{"type":"text","text":"min","marks":[{"type":"bold"}]},{"type":"text","text":"-heap for the k "},{"type":"text","text":"largest","marks":[{"type":"italic"}]},{"type":"text","text":" and a "},{"type":"text","text":"max","marks":[{"type":"bold"}]},{"type":"text","text":"-heap for the k "},{"type":"text","text":"smallest","marks":[{"type":"italic"}]},{"type":"text","text":". The heap type is the opposite of what you are looking for, because the root must be the element you are willing to throw away."}]}]}}'),
  ('4a4a87ce-a82a-798b-8d76-c510705a7a15', 'aq', 'heading', '{"level":1,"content":[{"type":"text","text":"K closest elements to x"}]}'),
  ('6491296e-119d-71fc-8bde-4e1e76e7e429', 'ar', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 15, 7, 3, 4], x = 8, k = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"7 10","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [5, 15, 10, 20, 8], x = 12, k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"8 10 15","marks":[{"type":"code"}]}]}]}}'),
  ('76176f39-9486-78ac-bb72-b743c196307f', 'as', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" elements with the smallest "},{"type":"text","text":"|arr[i] - x|","marks":[{"type":"code"}]},{"type":"text","text":". The naive approach finds the closest element, removes it and repeats "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" times:"}]}]}}'),
  ('4ac60039-7f14-7c63-837d-bf948470e525', 'at', 'code', '{"language":"python","code":"def k_closest_naive(arr, x, k):\n    arr = list(arr)\n    res = []\n    for _ in range(k):                                     # k passes …\n        mi = 0\n        for j in range(1, len(arr)):                       # … each scanning the whole array\n            if abs(arr[j] - x) < abs(arr[mi] - x):\n                mi = j\n        res.append(arr.pop(mi))\n    return sorted(res)\n\nprint(*k_closest_naive([10, 15, 7, 3, 4], 8, 2))","filename":"Python"}'),
  ('32f86e45-b40b-7d78-8f3c-0c36534d137d', 'au', 'code', '{"language":"text","code":"7 10","filename":"Output"}'),
  ('020251e8-e980-7b3f-8bee-6c95e9ca59f5', 'av', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n · k) · Space O(k)"}]}]}}'),
  ('9faa3267-80bf-70dc-97ba-90b962129f22', 'aw', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This is "},{"type":"text","text":"k smallest","marks":[{"type":"italic"}]},{"type":"text","text":" with the key "},{"type":"text","text":"|arr[i] - x|","marks":[{"type":"code"}]},{"type":"text","text":", so flip the previous recipe: a "},{"type":"text","text":"max-heap of size k","marks":[{"type":"bold"}]},{"type":"text","text":" keyed on the distance. The root is the farthest of the current best "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"; a new element closer than it replaces it. Store "},{"type":"text","text":"(distance, value)","marks":[{"type":"code"}]},{"type":"text","text":" pairs so the heap orders by distance but you can still print the value."}]}]}}'),
  ('c22ad621-a59b-7ee1-88a4-1dded37a8c7f', 'ax', 'code', '{"language":"python","code":"import heapq\n\ndef k_closest(arr, x, k):\n    h = []                                        # max-heap on distance: push (-dist, -value)\n    for v in arr:\n        heapq.heappush(h, (-abs(v - x), -v))\n        if len(h) > k:\n            heapq.heappop(h)                      # drop the farthest (on ties: the larger value)\n    return sorted(-v for _, v in h)\n\nprint(*k_closest([10, 15, 7, 3, 4], 8, 2))\nprint(*k_closest([5, 15, 10, 20, 8], 12, 3))","filename":"Python"}'),
  ('d9c2f7f8-662b-702f-8cef-d7c2667a7d5b', 'ay', 'code', '{"language":"cpp","code":"#include <algorithm>\n#include <cstdlib>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nvector<int> kClosest(const vector<int>& arr, int x, int k) {\n    priority_queue<pair<int, int>> h;             // max-heap on (distance, value)\n    for (int v : arr) {\n        h.push({abs(v - x), v});\n        if ((int)h.size() > k) h.pop();           // drop the farthest (on ties: the larger value)\n    }\n    vector<int> res;\n    while (!h.empty()) { res.push_back(h.top().second); h.pop(); }\n    sort(res.begin(), res.end());\n    return res;\n}\n\nvoid print(const vector<int>& v) {\n    for (int i = 0; i < (int)v.size(); i++) cout << (i ? \" \" : \"\") << v[i];\n    cout << \"\\n\";\n}\n\nint main() {\n    print(kClosest({10, 15, 7, 3, 4}, 8, 2));\n    print(kClosest({5, 15, 10, 20, 8}, 12, 3));\n}","filename":"C++"}'),
  ('7685668f-384a-7163-89bc-09fbec03acd0', 'az', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.PriorityQueue;\n\npublic class Main {\n    static List<Integer> kClosest(int[] arr, int x, int k) {\n        // max-heap on distance, then on value: int[]{distance, value}\n        PriorityQueue<int[]> h = new PriorityQueue<>(\n            (a, b) -> a[0] != b[0] ? Integer.compare(b[0], a[0]) : Integer.compare(b[1], a[1]));\n        for (int v : arr) {\n            h.add(new int[]{Math.abs(v - x), v});\n            if (h.size() > k) h.poll();                   // drop the farthest (on ties: the larger value)\n        }\n        List<Integer> res = new ArrayList<>();\n        while (!h.isEmpty()) res.add(h.poll()[1]);\n        Collections.sort(res);\n        return res;\n    }\n\n    static String join(List<Integer> xs) {\n        StringBuilder sb = new StringBuilder();\n        for (int v : xs) sb.append(v).append('' '');\n        return sb.toString().trim();\n    }\n\n    public static void main(String[] args) {\n        System.out.println(join(kClosest(new int[]{10, 15, 7, 3, 4}, 8, 2)));\n        System.out.println(join(kClosest(new int[]{5, 15, 10, 20, 8}, 12, 3)));\n    }\n}","filename":"Java"}'),
  ('98ea2fe6-b8c6-7f82-96fa-7a696b3654c9', 'b00', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nfunction kClosest(arr, x, k) {\n    // max-heap on distance, then on value: [distance, value]\n    const h = new Heap((a, b) => a[0] !== b[0] ? b[0] - a[0] : b[1] - a[1]);\n    for (const v of arr) {\n        h.push([Math.abs(v - x), v]);\n        if (h.size() > k) h.pop();                         // drop the farthest (on ties: the larger value)\n    }\n    const res = [];\n    while (h.size()) res.push(h.pop()[1]);\n    return res.sort((a, b) => a - b);\n}\n\nconsole.log(kClosest([10, 15, 7, 3, 4], 8, 2).join(\" \"));\nconsole.log(kClosest([5, 15, 10, 20, 8], 12, 3).join(\" \"));","filename":"JavaScript"}'),
  ('97e9280a-d43b-7ac0-bf4e-162264c0386c', 'b01', 'code', '{"language":"text","code":"7 10\n8 10 15","filename":"Output"}'),
  ('6a72f75f-4795-70c0-beb1-321b1aa2a6fb', 'b02', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n log k) · Space O(k)"}]}]}}'),
  ('e683d9cb-4793-7ef7-b9b3-9579eaeb0a25', 'b03', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ties matter: two elements at the same distance ("},{"type":"text","text":"7","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"9","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"x = 8","marks":[{"type":"code"}]},{"type":"text","text":") — decide which one wins "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" coding and encode it in the comparator (here: on equal distance the larger value is dropped, so the smaller one is kept). Python''s tuple ordering, C++''s "},{"type":"text","text":"pair","marks":[{"type":"code"}]},{"type":"text","text":" ordering and the explicit Java/JavaScript comparators all implement that same rule. If the array is "},{"type":"text","text":"sorted","marks":[{"type":"bold"}]},{"type":"text","text":", a two-pointer window or binary search solves it in "},{"type":"text","text":"O(log n + k)","marks":[{"type":"code"}]},{"type":"text","text":" with no heap at all."}]}]}}'),
  ('92aa80d9-ffbe-7fa5-8047-42fbe4774a5a', 'b04', 'heading', '{"level":1,"content":[{"type":"text","text":"Merge k sorted arrays"}]}'),
  ('b8bcd551-b576-7f8d-92e0-c87d2ab76f93', 'b05', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arrays = [[10, 20, 30], [5, 15], [1, 9, 11, 18]]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 5 9 10 11 15 18 20 30","marks":[{"type":"code"}]}]}]}}'),
  ('ff0a68a6-3bb3-77fe-8fc5-9e6aa13679c8', 'b06', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"N","marks":[{"type":"code"}]},{"type":"text","text":" is the total number of elements, "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" the number of arrays. Two obvious approaches ignore the fact that the inputs are already sorted:"}]}]}}'),
  ('7ae1c8c2-acf5-7601-95af-6b837f7532ff', 'b07', 'code', '{"language":"python","code":"# 1. concatenate everything and sort: O(N log N) — ignores the existing order\ndef merge_k_sort(arrays):\n    res = []\n    for a in arrays:\n        res.extend(a)\n    return sorted(res)\n\n# 2. merge the arrays one by one into the result: O(N · k) — the result is re-merged k times\ndef merge_two(a, b):\n    res, i, j = [], 0, 0\n    while i < len(a) and j < len(b):\n        if a[i] < b[j]:\n            res.append(a[i]); i += 1\n        else:\n            res.append(b[j]); j += 1\n    return res + a[i:] + b[j:]\n\ndef merge_k_pairwise(arrays):\n    res = list(arrays[0])\n    for a in arrays[1:]:\n        res = merge_two(res, a)\n    return res\n\narrays = [[10, 20, 30], [5, 15], [1, 9, 11, 18]]\nprint(*merge_k_sort(arrays))\nprint(*merge_k_pairwise(arrays))","filename":"Python"}'),
  ('57f67f0b-37a4-7d33-b423-7cd621637601', 'b08', 'code', '{"language":"text","code":"1 5 9 10 11 15 18 20 30\n1 5 9 10 11 15 18 20 30","filename":"Output"}'),
  ('df4b8479-1fe9-7279-8635-81eeaa9ddcfd', 'b09', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At any moment the next output is the smallest among the "},{"type":"text","text":"heads","marks":[{"type":"bold"}]},{"type":"text","text":" of the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" arrays. Keep those "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" heads in a min-heap as "},{"type":"text","text":"(value, array index, element index)","marks":[{"type":"code"}]},{"type":"text","text":". Pop the minimum, append it, and push the next element of the same array. Each of the "},{"type":"text","text":"N","marks":[{"type":"code"}]},{"type":"text","text":" elements enters and leaves a heap of size "},{"type":"text","text":"<= k","marks":[{"type":"code"}]},{"type":"text","text":" once."}]}]}}'),
  ('9b4fdc46-92df-7614-96e0-310146212806', 'b0A', 'code', '{"language":"text","code":"heap of heads          output so far\n{10, 5, 1}       pop 1  → push 9       1\n{10, 5, 9}       pop 5  → push 15      1 5\n{10, 15, 9}      pop 9  → push 11      1 5 9\n{10, 15, 11}     pop 10 → push 20      1 5 9 10\n{20, 15, 11}     pop 11 → push 18      1 5 9 10 11\n...","filename":"The heap never holds more than one element per array"}'),
  ('5bf4bac9-458d-76a7-a51a-729389bdacd9', 'b0B', 'code', '{"language":"python","code":"import heapq\n\ndef merge_k(arrays):\n    h = [(a[0], i, 0) for i, a in enumerate(arrays) if a]   # (value, which array, index in it)\n    heapq.heapify(h)\n    res = []\n    while h:\n        val, ai, j = heapq.heappop(h)\n        res.append(val)\n        if j + 1 < len(arrays[ai]):                          # the same array has more\n            heapq.heappush(h, (arrays[ai][j + 1], ai, j + 1))\n    return res\n\nprint(*merge_k([[10, 20, 30], [5, 15], [1, 9, 11, 18]]))","filename":"Python"}'),
  ('c5f994af-5d2a-765b-8992-421be3a16e21', 'b0C', 'code', '{"language":"cpp","code":"#include <array>\n#include <functional>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nvector<int> mergeK(const vector<vector<int>>& arrays) {\n    using Item = array<int, 3>;                              // {value, which array, index in it}\n    priority_queue<Item, vector<Item>, greater<Item>> h;     // min-heap, compares lexicographically\n    int k = arrays.size();\n    for (int i = 0; i < k; i++)\n        if (!arrays[i].empty()) h.push({arrays[i][0], i, 0});\n    vector<int> res;\n    while (!h.empty()) {\n        Item it = h.top(); h.pop();\n        int val = it[0], ai = it[1], j = it[2];\n        res.push_back(val);\n        if (j + 1 < (int)arrays[ai].size())                  // the same array has more\n            h.push({arrays[ai][j + 1], ai, j + 1});\n    }\n    return res;\n}\n\nint main() {\n    vector<int> res = mergeK({{10, 20, 30}, {5, 15}, {1, 9, 11, 18}});\n    for (int i = 0; i < (int)res.size(); i++) cout << (i ? \" \" : \"\") << res[i];\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('82f18554-9d03-72cd-9657-0abcbab7a41f', 'b0D', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.PriorityQueue;\n\npublic class Main {\n    static List<Integer> mergeK(int[][] arrays) {\n        // int[]{value, which array, index in it}, ordered by value\n        PriorityQueue<int[]> h = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));\n        for (int i = 0; i < arrays.length; i++)\n            if (arrays[i].length > 0) h.add(new int[]{arrays[i][0], i, 0});\n        List<Integer> res = new ArrayList<>();\n        while (!h.isEmpty()) {\n            int[] it = h.poll();\n            int val = it[0], ai = it[1], j = it[2];\n            res.add(val);\n            if (j + 1 < arrays[ai].length)                   // the same array has more\n                h.add(new int[]{arrays[ai][j + 1], ai, j + 1});\n        }\n        return res;\n    }\n\n    public static void main(String[] args) {\n        List<Integer> res = mergeK(new int[][]{{10, 20, 30}, {5, 15}, {1, 9, 11, 18}});\n        StringBuilder sb = new StringBuilder();\n        for (int v : res) sb.append(v).append('' '');\n        System.out.println(sb.toString().trim());\n    }\n}","filename":"Java"}'),
  ('dfdfdda5-3232-7791-a27f-31e9ec2e15fb', 'b0E', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nfunction mergeK(arrays) {\n    const h = new Heap((a, b) => a[0] - b[0]);               // [value, which array, index in it]\n    arrays.forEach((a, i) => { if (a.length) h.push([a[0], i, 0]); });\n    const res = [];\n    while (h.size()) {\n        const [val, ai, j] = h.pop();\n        res.push(val);\n        if (j + 1 < arrays[ai].length)                       // the same array has more\n            h.push([arrays[ai][j + 1], ai, j + 1]);\n    }\n    return res;\n}\n\nconsole.log(mergeK([[10, 20, 30], [5, 15], [1, 9, 11, 18]]).join(\" \"));","filename":"JavaScript"}'),
  ('2edca93c-6116-75fc-90f4-e0fcd1e6957c', 'b0F', 'code', '{"language":"text","code":"1 5 9 10 11 15 18 20 30","filename":"Output"}'),
  ('5ebc32f7-331c-76bc-b6c2-02ed3f038dc9', 'b0G', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(N log k) · Space O(k) for the heap, plus the output"}]}]}}'),
  ('6353e038-50c9-7a3d-ada1-10cf069fcb80', 'b0H', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Approach"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"concatenate + sort"}],[{"type":"text","text":"O(N log N)"}],[{"type":"text","text":"throws away the input order"}]],[[{"type":"text","text":"merge one array at a time"}],[{"type":"text","text":"O(N · k)"}],[{"type":"text","text":"the growing result is re-merged "},{"type":"text","text":"k - 1","marks":[{"type":"code"}]},{"type":"text","text":" times"}]],[[{"type":"text","text":"min-heap of ","marks":[{"type":"bold"}]},{"type":"text","text":"k","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" heads","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(N log k)"}],[{"type":"text","text":"every element passes once through a heap of size "},{"type":"text","text":"k","marks":[{"type":"code"}]}]],[[{"type":"text","text":"divide and conquer (merge pairs)"}],[{"type":"text","text":"O(N log k)"}],[{"type":"text","text":"same bound, no heap, more copying"}]]]}'),
  ('d5ce9f8c-fb5b-7a09-8379-837663bf65dd', 'b0I', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Push the "},{"type":"text","text":"array index and position","marks":[{"type":"bold"}]},{"type":"text","text":", not just the value — otherwise you cannot tell which array to advance. Pushing the whole remaining array into the heap instead of one head makes it "},{"type":"text","text":"O(N log N)","marks":[{"type":"code"}]},{"type":"text","text":" again. The same heap-of-heads pattern merges "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" sorted linked lists, "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" sorted files on disk (external sorting) and "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" sorted streams."}]}]}}'),
  ('d0f69f48-b232-74e4-9e21-b53fccd81f0c', 'b0J', 'heading', '{"level":1,"content":[{"type":"text","text":"Median of a stream"}]}'),
  ('5e4fa920-84a0-7fa5-9e8d-5289dee3b815', 'b0K', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"stream = [25, 7, 10, 15, 20]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"25.0 16.0 10.0 12.5 15.0","marks":[{"type":"code"}]}]}]}}'),
  ('dbe98824-2508-77b3-8978-63864bc23b9e', 'b0L', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After each new number, report the median of everything seen so far. A median needs the "},{"type":"text","text":"middle","marks":[{"type":"italic"}]},{"type":"text","text":" of the data, not its minimum — the trick is to split the data in two halves."}]}]}}'),
  ('bdf9636b-a8c1-7f3a-a50c-45cc59e710fe', 'b0M', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Numbers so far"}],[{"type":"text","text":"Sorted"}],[{"type":"text","text":"Median"}]],[[{"type":"text","text":"25","marks":[{"type":"code"}]}],[{"type":"text","text":"25"}],[{"type":"text","text":"25.0"}]],[[{"type":"text","text":"25 7","marks":[{"type":"code"}]}],[{"type":"text","text":"7 25"}],[{"type":"text","text":"(7 + 25) / 2 = 16.0"}]],[[{"type":"text","text":"25 7 10","marks":[{"type":"code"}]}],[{"type":"text","text":"7 10 25"}],[{"type":"text","text":"10.0"}]],[[{"type":"text","text":"25 7 10 15","marks":[{"type":"code"}]}],[{"type":"text","text":"7 10 15 25"}],[{"type":"text","text":"(10 + 15) / 2 = 12.5"}]],[[{"type":"text","text":"25 7 10 15 20","marks":[{"type":"code"}]}],[{"type":"text","text":"7 10 15 20 25"}],[{"type":"text","text":"15.0"}]]]}'),
  ('e1c6ad7f-11c1-7d9f-808c-44b373fa7e0a', 'b0N', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-sorting after every arrival works but costs "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" per element (or "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" with insertion into a sorted list):"}]}]}}'),
  ('441b2518-aa13-7dd5-82aa-c5c002207220', 'b0O', 'code', '{"language":"python","code":"def medians_naive(stream):\n    seen, out = [], []\n    for x in stream:\n        seen.append(x)\n        seen.sort()                                   # O(n log n) every time\n        n = len(seen)\n        m = seen[n // 2] if n % 2 else (seen[n // 2 - 1] + seen[n // 2]) / 2\n        out.append(f\"{m:.1f}\")\n    return out\n\nprint(*medians_naive([25, 7, 10, 15, 20]))","filename":"Python"}'),
  ('9445b472-7c6b-721a-8da1-c9de1687328c', 'b0P', 'code', '{"language":"text","code":"25.0 16.0 10.0 12.5 15.0","filename":"Output"}'),
  ('b60f59d2-441b-7bf2-9655-e1450d06a533', 'b0Q', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n² log n) total · Space O(n)"}]}]}}'),
  ('6e9f3a9d-107d-7ecb-a92f-cbc0b86700b7', 'b0R', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two heaps.","marks":[{"type":"bold"}]},{"type":"text","text":" Keep the smaller half in a "},{"type":"text","text":"max-heap","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"small","marks":[{"type":"code"}]},{"type":"text","text":" and the larger half in a "},{"type":"text","text":"min-heap","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"large","marks":[{"type":"code"}]},{"type":"text","text":", with "},{"type":"text","text":"|small| - |large|","marks":[{"type":"code"}]},{"type":"text","text":" kept at "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":". The median is then "},{"type":"text","text":"small.top()","marks":[{"type":"code"}]},{"type":"text","text":" (odd count) or the average of the two tops (even count). Every insertion is two or three heap operations."}]}]}}'),
  ('7726e4a0-ace7-74c9-bd23-4a08d6a3edde', 'b0S', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Push ","marks":[{"type":"bold"}]},{"type":"text","text":"x","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" into ","marks":[{"type":"bold"}]},{"type":"text","text":"small","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The max-heap of the lower half."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move ","marks":[{"type":"bold"}]},{"type":"text","text":"small.top()","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" to ","marks":[{"type":"bold"}]},{"type":"text","text":"large","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Guarantees every element of "},{"type":"text","text":"small","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":" every element of "},{"type":"text","text":"large","marks":[{"type":"code"}]},{"type":"text","text":", even if "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" was big."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rebalance","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"large","marks":[{"type":"code"}]},{"type":"text","text":" has more elements than "},{"type":"text","text":"small","marks":[{"type":"code"}]},{"type":"text","text":", move "},{"type":"text","text":"large.top()","marks":[{"type":"code"}]},{"type":"text","text":" back. Now "},{"type":"text","text":"|small| = |large|","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"|small| = |large| + 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read the median","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"small.top()","marks":[{"type":"code"}]},{"type":"text","text":" when "},{"type":"text","text":"small","marks":[{"type":"code"}]},{"type":"text","text":" is bigger, else "},{"type":"text","text":"(small.top() + large.top()) / 2","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('9fc556e9-86e9-709e-8cdf-48a4e6da6716', 'b0T', 'code', '{"language":"text","code":"x = 20 arrives (seen: 25 7 10 15)\n  small (max-heap) = {10, 7}     large (min-heap) = {15, 25}\n\n1. small.push(20)        small = {20, 10, 7}   large = {15, 25}\n2. large.push(small.pop) small = {10, 7}       large = {15, 20, 25}   ← 20 belongs in the upper half\n3. |large| > |small|     small = {15, 10, 7}   large = {20, 25}       ← move 15 back\n4. |small| > |large|     median = small.top() = 15","filename":"One insertion into the two-heap structure"}'),
  ('d288a737-9916-7fb1-a5cc-1b4df5d72c04', 'b0U', 'code', '{"language":"python","code":"import heapq\n\ndef running_medians(stream):\n    small, large = [], []                   # small: max-heap via negation; large: min-heap\n    out = []\n    for x in stream:\n        heapq.heappush(small, -x)\n        heapq.heappush(large, -heapq.heappop(small))      # largest of small moves up\n        if len(large) > len(small):\n            heapq.heappush(small, -heapq.heappop(large))  # rebalance: small keeps the extra one\n        if len(small) > len(large):\n            out.append(f\"{-small[0]:.1f}\")\n        else:\n            out.append(f\"{(-small[0] + large[0]) / 2:.1f}\")\n    return out\n\nprint(*running_medians([25, 7, 10, 15, 20]))","filename":"Python"}'),
  ('31b0f8ba-71fb-75f5-b96a-b57ec7a9defa', 'b0V', 'code', '{"language":"cpp","code":"#include <functional>\n#include <iomanip>\n#include <iostream>\n#include <queue>\n#include <vector>\nusing namespace std;\n\nint main() {\n    vector<int> stream = {25, 7, 10, 15, 20};\n    priority_queue<int> small;                                 // max-heap: lower half\n    priority_queue<int, vector<int>, greater<int>> large;      // min-heap: upper half\n    cout << fixed << setprecision(1);\n    bool firstOut = true;\n    for (int x : stream) {\n        small.push(x);\n        large.push(small.top()); small.pop();                  // largest of small moves up\n        if (large.size() > small.size()) { small.push(large.top()); large.pop(); }   // rebalance\n        double median = small.size() > large.size() ? small.top() : (small.top() + large.top()) / 2.0;\n        cout << (firstOut ? \"\" : \" \") << median;\n        firstOut = false;\n    }\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('882b9ca5-2e0e-75c7-b26d-bda59c692350', 'b0W', 'code', '{"language":"java","code":"import java.util.Collections;\nimport java.util.Locale;\nimport java.util.PriorityQueue;\n\npublic class Main {\n    public static void main(String[] args) {\n        int[] stream = {25, 7, 10, 15, 20};\n        PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder());   // max-heap: lower half\n        PriorityQueue<Integer> large = new PriorityQueue<>();                             // min-heap: upper half\n        StringBuilder sb = new StringBuilder();\n        for (int x : stream) {\n            small.add(x);\n            large.add(small.poll());                                   // largest of small moves up\n            if (large.size() > small.size()) small.add(large.poll());  // rebalance\n            double median = small.size() > large.size() ? small.peek() : (small.peek() + large.peek()) / 2.0;\n            sb.append(String.format(Locale.ROOT, \"%.1f\", median)).append('' '');\n        }\n        System.out.println(sb.toString().trim());\n    }\n}","filename":"Java"}'),
  ('c5ca67d2-50b2-7711-b35b-cb8c6a29411b', 'b0X', 'code', '{"language":"javascript","code":"class Heap {\n    constructor(cmp = (a, b) => a - b) { this.a = []; this.cmp = cmp; }\n    size() { return this.a.length; }\n    peek() { return this.a[0]; }\n    push(x) {\n        const a = this.a;\n        a.push(x);\n        let i = a.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (this.cmp(a[i], a[p]) >= 0) break;\n            [a[i], a[p]] = [a[p], a[i]];\n            i = p;\n        }\n    }\n    pop() {\n        const a = this.a, top = a[0], last = a.pop();\n        if (a.length) {\n            a[0] = last;\n            let i = 0;\n            for (;;) {\n                let m = i;\n                const l = 2 * i + 1, r = l + 1;\n                if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l;\n                if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r;\n                if (m === i) break;\n                [a[i], a[m]] = [a[m], a[i]];\n                i = m;\n            }\n        }\n        return top;\n    }\n}\n\nfunction runningMedians(stream) {\n    const small = new Heap((a, b) => b - a);                  // max-heap: lower half\n    const large = new Heap((a, b) => a - b);                  // min-heap: upper half\n    const out = [];\n    for (const x of stream) {\n        small.push(x);\n        large.push(small.pop());                              // largest of small moves up\n        if (large.size() > small.size()) small.push(large.pop());   // rebalance\n        const median = small.size() > large.size() ? small.peek() : (small.peek() + large.peek()) / 2;\n        out.push(median.toFixed(1));\n    }\n    return out;\n}\n\nconsole.log(runningMedians([25, 7, 10, 15, 20]).join(\" \"));","filename":"JavaScript"}'),
  ('d835c1a9-1984-7521-be85-3642274b42e4', 'b0Y', 'code', '{"language":"text","code":"25.0 16.0 10.0 12.5 15.0","filename":"Output"}'),
  ('77dc4df5-221e-7594-ab22-0f35a84b2e9e', 'b0Z', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(log n) per element · Space O(n)"}]}]}}'),
  ('b28f7983-68c9-7da2-8afc-268233df465c', 'b0a', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"augmented BST","marks":[{"type":"bold"}]},{"type":"text","text":" (each node storing its subtree size, as in the BST topic) also works: insert in "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":", then find the "},{"type":"text","text":"n/2","marks":[{"type":"code"}]},{"type":"text","text":"-th and "},{"type":"text","text":"n/2 + 1","marks":[{"type":"code"}]},{"type":"text","text":"-th smallest in "},{"type":"text","text":"O(h)","marks":[{"type":"code"}]},{"type":"text","text":". It additionally supports deleting elements (a "},{"type":"text","text":"sliding-window","marks":[{"type":"italic"}]},{"type":"text","text":" median), which the two heaps cannot do cheaply. For a pure stream the two heaps are simpler and faster."}]}]}}'),
  ('65947bb9-19c1-7075-9240-3a43d24c8a9b', 'b0b', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pushing "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" straight into whichever heap "},{"type":"text","text":"looks","marks":[{"type":"italic"}]},{"type":"text","text":" right ("},{"type":"text","text":"x < small.top()","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"small","marks":[{"type":"code"}]},{"type":"text","text":") and only then rebalancing is also correct, but it has more branches and an empty-heap edge case. The push-then-move routine above has no special cases. And compute the average in floating point ("},{"type":"text","text":"/ 2.0","marks":[{"type":"code"}]},{"type":"text","text":"): integer division would print "},{"type":"text","text":"12","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"12.5","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('7600dd8f-40e6-7f09-a678-372b88708217', 'b0c', 'heading', '{"level":1,"content":[{"type":"text","text":"Choosing the heap"}]}'),
  ('25fe3f30-b141-7b8d-b02f-7b6385789396', 'b0d', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Problem"}],[{"type":"text","text":"Heap type"}],[{"type":"text","text":"Heap size"}],[{"type":"text","text":"Time"}]],[[{"type":"text","text":"k largest / k-th largest"}],[{"type":"text","text":"min-heap"}],[{"type":"text","text":"k","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log k)"}]],[[{"type":"text","text":"k smallest / k closest"}],[{"type":"text","text":"max-heap (on the key)"}],[{"type":"text","text":"k","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log k)"}]],[[{"type":"text","text":"sort a k-sorted array"}],[{"type":"text","text":"min-heap"}],[{"type":"text","text":"k + 1","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n log k)"}]],[[{"type":"text","text":"merge k sorted arrays"}],[{"type":"text","text":"min-heap of heads"}],[{"type":"text","text":"k","marks":[{"type":"code"}]}],[{"type":"text","text":"O(N log k)"}]],[[{"type":"text","text":"buy cheapest first / schedule by priority"}],[{"type":"text","text":"min-heap of everything"}],[{"type":"text","text":"n","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n + r log n)"}]],[[{"type":"text","text":"running median"}],[{"type":"text","text":"max-heap + min-heap"}],[{"type":"text","text":"n/2","marks":[{"type":"code"}]},{"type":"text","text":" each"}],[{"type":"text","text":"O(log n) per element"}]]]}'),
  ('6874d78a-012b-7feb-a839-a12eea2c19b7', 'b0e', 'callout', '{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ask two questions for every heap problem: "},{"type":"text","text":"what key does the heap order by","marks":[{"type":"italic"}]},{"type":"text","text":" (value, distance, array head) and "},{"type":"text","text":"how large may it grow","marks":[{"type":"italic"}]},{"type":"text","text":" ("},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"k + 1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"). The root is always the element you are prepared to discard."}]}]}}'),
  ('bd70f0fc-4726-706e-b93c-ebe16a7ed6c0', 'b0f', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('1b6cdd60-ad74-76cd-8212-f736bfc2f38a', 'b0g', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is building a heap O(n) when n inserts cost O(n log n)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"heapify","marks":[{"type":"code"}]},{"type":"text","text":" sifts "},{"type":"text","text":"down","marks":[{"type":"bold"}]},{"type":"text","text":" from the last internal node to the root. Most nodes are near the bottom and sift only a step or two; summing "},{"type":"text","text":"height × nodes-at-that-height","marks":[{"type":"code"}]},{"type":"text","text":" over the tree gives "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":". Pushing one at a time sifts "},{"type":"text","text":"up","marks":[{"type":"bold"}]},{"type":"text","text":" from the bottom, where most nodes have "},{"type":"text","text":"log n","marks":[{"type":"code"}]},{"type":"text","text":" ancestors — "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('3646a1f4-7a78-78dc-a758-4ad7106a7ded', 'b0h', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why a min-heap for the k largest elements?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The heap holds the current best "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" and its root is the smallest of them — the only one that can be evicted. A new element either fails to beat that root (ignore it) or replaces it. With a max-heap the root is the best element, which you would never want to evict, so you would have to keep all "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" elements."}]}]}}'),
  ('ab150495-16ef-7121-9f13-e17e16224af1', 'b0i', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Heap or balanced BST for a running median?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two heaps: "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" per element and only the two tops are ever read. A balanced BST augmented with subtree sizes also gives "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" and can additionally delete elements (sliding-window median) and answer any order statistic, at the price of a far bigger implementation — Python and JavaScript have no built-in ordered set to lean on."}]}]}}'),
  ('9f99b97f-8f24-7203-981a-97cf39b667c3', 'b0j', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you get a max-heap in Python, and what is the catch?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"heapq","marks":[{"type":"code"}]},{"type":"text","text":" only implements a min-heap, so push "},{"type":"text","text":"-x","marks":[{"type":"code"}]},{"type":"text","text":" and negate when popping; for records push "},{"type":"text","text":"(-key, item)","marks":[{"type":"code"}]},{"type":"text","text":" tuples. The catch is forgetting the negation on the way out, and for tuples that ties on the key fall through to comparing the payload — make the payload comparable (an index) or wrap it."}]}]}}'),
  ('53dd09cb-f5ec-7ead-bc5f-b069dcf770bb', 'b0k', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does a priority queue preserve insertion order for equal priorities?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — binary heaps are not stable. If FIFO order among equal priorities matters, store a sequence number as a secondary key: "},{"type":"text","text":"(priority, seq, item)","marks":[{"type":"code"}]},{"type":"text","text":". The same trick breaks ties deterministically in the k-closest problem."}]}]}}'),
  ('4f1e58e9-1b59-7053-8ab0-f4e1fdbc89a7', 'b0l', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the time bounds of the heap operations and why is search O(n)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"peek","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"push","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"pop","marks":[{"type":"code"}]},{"type":"text","text":" are "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" (one root-to-leaf path), "},{"type":"text","text":"heapify","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":". A heap only orders parent against children, so an arbitrary key can be anywhere below the root; finding or deleting it needs a linear scan, or an auxiliary index map (the "},{"type":"text","text":"indexed heap","marks":[{"type":"italic"}]},{"type":"text","text":" used by Dijkstra''s decrease-key)."}]}]}}')
) AS c(id, position, type, content)
