SELECT c.id::uuid, 'f1fd716a-1184-7b69-9b31-0626bdc1f6c2', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('edc20c54-5a60-7e9b-8738-04bb48131b35', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Linked-list problems are pointer puzzles: almost every classic one is solved by "},{"type":"text","text":"two pointers moving at different speeds or distances","marks":[{"type":"bold"}]},{"type":"text","text":", by "},{"type":"text","text":"reversing links in place","marks":[{"type":"bold"}]},{"type":"text","text":", or by "},{"type":"text","text":"re-wiring nodes without allocating","marks":[{"type":"bold"}]},{"type":"text","text":". This topic collects the problems interviewers actually ask and the handful of techniques that solve them."}]}]}}'),
  ('b2185a3c-1e88-7dd8-91a1-7f1b2b948595', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Singly linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — a chain of nodes where each node stores a value ("},{"type":"text","text":"data","marks":[{"type":"code"}]},{"type":"text","text":") and a reference to the next node ("},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":"); the last node''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". Only the "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" is kept — every other node is reached by following links, so random access is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" but splicing nodes in and out is "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" once you stand next to them."}]}]}}'),
  ('d7893c24-33fe-72ad-9979-66596b239a7c', 'a2', 'code', '{"language":"text","code":"head\n ↓\n┌────┬───┐   ┌────┬───┐   ┌────┬───┐   ┌────┬───┐\n│ 10 │ ●─┼──▶│ 20 │ ●─┼──▶│ 30 │ ●─┼──▶│ 40 │ ∅ │\n└────┴───┘   └────┴───┘   └────┴───┘   └────┴───┘\n data next","filename":"The list 10 → 20 → 30 → 40 — every solution below works on this shape"}'),
  ('a7830422-8a62-7c21-8603-a9cfed0a8e2f', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Recap: what costs what"}]}'),
  ('2fd35cc5-995f-7db0-bdfe-9d572515c109', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Singly linked list"}],[{"type":"text","text":"Dynamic array"}]],[[{"type":"text","text":"Access "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"-th element"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" — walk from head"}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Insert / delete at head"}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" — shift everything"}]],[[{"type":"text","text":"Insert / delete after a known node"}],[{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" — re-wire two links"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Insert / delete at tail"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" with a tail pointer)"}],[{"type":"text","text":"amortised "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Search"}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" if sorted)"}]],[[{"type":"text","text":"Memory per element"}],[{"type":"text","text":"value + one pointer, scattered"}],[{"type":"text","text":"value only, contiguous and cache-friendly"}]]]}'),
  ('80758294-7303-7592-8ef7-9795dca99dc7', 'a5', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The problems in this topic exploit the one thing a list does better than an array: "},{"type":"text","text":"moving a node costs ","marks":[{"type":"bold"}]},{"type":"text","text":"O(1)","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" and no allocation","marks":[{"type":"bold"}]},{"type":"text","text":". Reversing, merging, swapping pairs and segregating are all done by changing "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" pointers, never by copying values into a new container."}]}]}}'),
  ('d3bbdcb7-a2e2-7075-886c-0e1f177c34d0', 'a6', 'heading', '{"level":1,"content":[{"type":"text","text":"The techniques behind every problem"}]}'),
  ('1c92dfac-af24-7da1-a933-211863c767ab', 'a7', 'callout', '{"variant":"note","title":"Slow and fast pointers","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" moves one node per step, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" two. When "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" reaches the end, "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" is at the middle; if "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" ever catches "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":", there is a loop. Used for: middle, palindrome, loop detection."}]}]}}'),
  ('64c547e4-49cc-7eb2-82a7-5df0d9e10210', 'a8', 'callout', '{"variant":"note","title":"Two pointers a fixed gap apart","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Send "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" ahead by "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" nodes, then move both together; when "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" falls off, "},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" from the end. Used for: nth node from end, intersection (after aligning lengths)."}]}]}}'),
  ('1412004f-a115-7261-b50a-331b152665b9', 'a9', 'callout', '{"variant":"note","title":"Reverse links in place","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three pointers "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" flip each link in one pass. Used for: reverse, reverse in groups of "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":", palindrome (reverse the second half)."}]}]}}'),
  ('f76be5c1-c745-7709-8afa-4b48f1e3cb9d', 'aA', 'callout', '{"variant":"note","title":"Dummy head node","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A throwaway node in front of the list removes every “is this the first node?” special case. Used for: merge, pairwise swap, deleting nodes."}]}]}}'),
  ('cc960869-6f6e-77b8-a73e-696b37dcab74', 'aB', 'callout', '{"variant":"note","title":"Hash the node references","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A set or map keyed by node "},{"type":"text","text":"identity","marks":[{"type":"italic"}]},{"type":"text","text":" (not value) gives a straightforward "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"-space solution — the baseline you beat with pointer tricks. Used for: loop, intersection, clone."}]}]}}'),
  ('859776f9-cae2-7c68-867a-739f3e7c8217', 'aC', 'callout', '{"variant":"note","title":"Re-wire instead of allocate","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread existing nodes into new sublists (even/odd, merged) or interleave copies inside the original list (clone). Used for: segregate, clone with random pointers."}]}]}}'),
  ('e816a4fe-376b-7786-a309-6a4464da1a9c', 'aD', 'heading', '{"level":1,"content":[{"type":"text","text":"Node and helpers used in every solution"}]}'),
  ('fd6a01a3-d01b-7547-9d90-73e665c1dd65', 'aE', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every program below carries the same three pieces: a "},{"type":"text","text":"Node","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"build(values)","marks":[{"type":"code"}]},{"type":"text","text":" that turns an array into a list, and "},{"type":"text","text":"toStr(head)","marks":[{"type":"code"}]},{"type":"text","text":" that prints a list as space-separated values. They are the only boilerplate — the solutions themselves are the functions in between."}]}]}}'),
  ('8e16cf83-6a90-7c87-a0ce-ed1005703a37', 'aF', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):                 # [1, 2, 3] → 1 → 2 → 3\n    head = None\n    for v in reversed(values):     # prepend from the back, so order is kept\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):                  # \"1 2 3\"\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef length(head):\n    n = 0\n    while head:\n        n += 1\n        head = head.next\n    return n\n\nhead = build([10, 20, 30, 40, 50])\nprint(to_str(head))\nprint(\"length:\", length(head))","filename":"Python"}'),
  ('c30464be-5bc4-7267-81ef-cf6ec0d682e3', 'aG', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {            // {1, 2, 3} → 1 → 2 → 3\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {   // prepend from the back\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {                     // \"1 2 3\"\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nint length(Node* head) {\n    int n = 0;\n    for (Node* c = head; c; c = c->next) n++;\n    return n;\n}\n\nint main() {\n    Node* head = build({10, 20, 30, 40, 50});\n    cout << toStr(head) << \"\\n\";\n    cout << \"length: \" << length(head) << \"\\n\";\n}","filename":"C++"}'),
  ('1826b4e6-8c73-712a-878e-1202a01f5621', 'aH', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {                 // {1, 2, 3} → 1 → 2 → 3\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {   // prepend from the back\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {             // \"1 2 3\"\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static int length(Node head) {\n        int n = 0;\n        for (Node c = head; c != null; c = c.next) n++;\n        return n;\n    }\n\n    public static void main(String[] args) {\n        Node head = build(new int[]{10, 20, 30, 40, 50});\n        System.out.println(toStr(head));\n        System.out.println(\"length: \" + length(head));\n    }\n}","filename":"Java"}'),
  ('203c1e2a-b1a0-7faa-8cab-3b7cede63e61', 'aI', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {                       // [1, 2, 3] → 1 → 2 → 3\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {   // prepend from the back\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {                         // \"1 2 3\"\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction length(head) {\n    let n = 0;\n    for (let c = head; c; c = c.next) n++;\n    return n;\n}\n\nconst head = build([10, 20, 30, 40, 50]);\nconsole.log(toStr(head));\nconsole.log(\"length:\", length(head));","filename":"JavaScript"}'),
  ('6ef7f6c0-6560-718b-9bfe-7015218070fa', 'aJ', 'code', '{"language":"text","code":"10 20 30 40 50\nlength: 5","filename":"Output"}'),
  ('5cf312ab-bec3-75d5-8d45-e58c207329f0', 'aK', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"build","marks":[{"type":"code"}]},{"type":"text","text":" prepends from the back of the array so the list comes out in array order without a tail pointer. In C++ the nodes are allocated with "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" and never freed in these short programs — fine for a demo, a leak in real code; a destructor or "},{"type":"text","text":"unique_ptr","marks":[{"type":"code"}]},{"type":"text","text":" chain fixes that."}]}]}}'),
  ('b4c23e9c-360f-7b7a-86db-f9ce8b1c76d3', 'aL', 'heading', '{"level":1,"content":[{"type":"text","text":"Middle of a linked list"}]}'),
  ('f117362b-1bbd-765b-ad33-cf6a1897a3b1', 'aM', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"30 (the second of the two middle nodes)","marks":[{"type":"code"}]}]}]}}'),
  ('f083310f-4319-77d4-998c-04cd49bb6f20', 'aN', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two pointers start at the head. "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" advances one node, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" two. When "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" runs off the end, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" has covered the whole list and "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" exactly half of it — "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" is standing on the middle. One pass, no counting."}]}]}}'),
  ('b416d1fb-00d3-7e63-a3f2-169743664696', 'aO', 'code', '{"language":"text","code":"step 0:   slow            fast\n           ↓               ↓\n          10 → 20 → 30 → 40 → 50\nstep 1:        slow       fast\nstep 2:             slow            fast = ∅ → stop, slow = 30","filename":"fast moves two for every one of slow, so slow ends at the middle"}'),
  ('724bcd20-7027-744b-9fbf-0d95d00f8517', 'aP', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef middle(head):\n    slow = fast = head\n    while fast and fast.next:      # fast moves 2, slow moves 1\n        slow = slow.next\n        fast = fast.next.next\n    return slow\n\nfor values in ([10, 20, 30, 40, 50], [10, 20, 30, 40]):\n    head = build(values)\n    print(to_str(head), \"→ middle\", middle(head).data)","filename":"Python"}'),
  ('bc9294d4-60d7-7139-80da-1f2cee4772eb', 'aQ', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* middle(Node* head) {\n    Node* slow = head;\n    Node* fast = head;\n    while (fast && fast->next) {       // fast moves 2, slow moves 1\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    return slow;\n}\n\nint main() {\n    for (vector<int> values : {vector<int>{10, 20, 30, 40, 50}, vector<int>{10, 20, 30, 40}}) {\n        Node* head = build(values);\n        cout << toStr(head) << \" → middle \" << middle(head)->data << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('9b413bca-1d7b-7e9a-b9e6-657d38d1819c', 'aR', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node middle(Node head) {\n        Node slow = head, fast = head;\n        while (fast != null && fast.next != null) {   // fast moves 2, slow moves 1\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        return slow;\n    }\n\n    public static void main(String[] args) {\n        for (int[] values : new int[][]{{10, 20, 30, 40, 50}, {10, 20, 30, 40}}) {\n            Node head = build(values);\n            System.out.println(toStr(head) + \" → middle \" + middle(head).data);\n        }\n    }\n}","filename":"Java"}'),
  ('f01be7b5-7ead-7a99-86ae-f4c30a17ecc6', 'aS', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction middle(head) {\n    let slow = head, fast = head;\n    while (fast && fast.next) {        // fast moves 2, slow moves 1\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    return slow;\n}\n\nfor (const values of [[10, 20, 30, 40, 50], [10, 20, 30, 40]]) {\n    const head = build(values);\n    console.log(toStr(head), \"→ middle\", middle(head).data);\n}","filename":"JavaScript"}'),
  ('007a9178-2bc0-75e9-9238-246e32d843e6', 'aT', 'code', '{"language":"text","code":"10 20 30 40 50 → middle 30\n10 20 30 40 → middle 30","filename":"Output"}'),
  ('7a110b8b-4b4b-792f-bf10-db1a2a3abe77', 'aU', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('dd0b5342-f11c-7044-a3eb-d863532a6f53', 'aV', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For an even length this returns the "},{"type":"text","text":"second","marks":[{"type":"bold"}]},{"type":"text","text":" middle ("},{"type":"text","text":"30","marks":[{"type":"code"}]},{"type":"text","text":" of "},{"type":"text","text":"10 20 30 40","marks":[{"type":"code"}]},{"type":"text","text":"). To get the first middle instead, loop while "},{"type":"text","text":"fast.next and fast.next.next","marks":[{"type":"code"}]},{"type":"text","text":" — that variant is exactly what the palindrome check below uses, because it wants "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" at the end of the first half."}]}]}}'),
  ('1123fff5-5165-7552-87bd-30bc18936d64', 'aW', 'heading', '{"level":1,"content":[{"type":"text","text":"Nth node from the end"}]}'),
  ('89de2718-ec7b-7ce3-ad20-900787cdfa98', 'aX', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50, n = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50, n = 6","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"none (list is shorter than n)","marks":[{"type":"code"}]}]}]}}'),
  ('9fc72d0b-3aa4-7f55-8549-cdbadcb3f3aa', 'aY', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Move "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" ahead by "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" nodes. Now move "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":" together; the gap between them stays "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":", so when "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" falls off the end, "},{"type":"text","text":"second","marks":[{"type":"code"}]},{"type":"text","text":" is exactly "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" nodes from the end. The naive alternative — count the length, then walk "},{"type":"text","text":"len − n","marks":[{"type":"code"}]},{"type":"text","text":" nodes — also works in "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" but needs two passes."}]}]}}'),
  ('7a4eaa8c-556c-7bdd-bee0-453f7070827f', 'aZ', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef nth_from_end(head, n):\n    first = head\n    for _ in range(n):               # move first n nodes ahead\n        if first is None:\n            return None              # n is larger than the length\n        first = first.next\n    second = head\n    while first:                     # now move both; the gap stays n\n        first = first.next\n        second = second.next\n    return second\n\nhead = build([10, 20, 30, 40, 50])\nfor n in (1, 2, 5, 6):\n    node = nth_from_end(head, n)\n    print(\"n =\", n, \"→\", node.data if node else \"none\")","filename":"Python"}'),
  ('f12cd4d4-6745-7902-8342-5a4a5689932f', 'aa', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nNode* nthFromEnd(Node* head, int n) {\n    Node* first = head;\n    for (int i = 0; i < n; i++) {        // move first n nodes ahead\n        if (!first) return nullptr;      // n is larger than the length\n        first = first->next;\n    }\n    Node* second = head;\n    while (first) {                      // now move both; the gap stays n\n        first = first->next;\n        second = second->next;\n    }\n    return second;\n}\n\nint main() {\n    Node* head = build({10, 20, 30, 40, 50});\n    for (int n : {1, 2, 5, 6}) {\n        Node* node = nthFromEnd(head, n);\n        cout << \"n = \" << n << \" → \" << (node ? to_string(node->data) : \"none\") << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('2687ab27-ad9f-7987-8b9a-73e1f682f965', 'ab', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static Node nthFromEnd(Node head, int n) {\n        Node first = head;\n        for (int i = 0; i < n; i++) {        // move first n nodes ahead\n            if (first == null) return null;  // n is larger than the length\n            first = first.next;\n        }\n        Node second = head;\n        while (first != null) {              // now move both; the gap stays n\n            first = first.next;\n            second = second.next;\n        }\n        return second;\n    }\n\n    public static void main(String[] args) {\n        Node head = build(new int[]{10, 20, 30, 40, 50});\n        for (int n : new int[]{1, 2, 5, 6}) {\n            Node node = nthFromEnd(head, n);\n            System.out.println(\"n = \" + n + \" → \" + (node != null ? String.valueOf(node.data) : \"none\"));\n        }\n    }\n}","filename":"Java"}'),
  ('6c944b78-0198-7015-a615-ad4c7d8b0d3f', 'ac', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction nthFromEnd(head, n) {\n    let first = head;\n    for (let i = 0; i < n; i++) {          // move first n nodes ahead\n        if (!first) return null;           // n is larger than the length\n        first = first.next;\n    }\n    let second = head;\n    while (first) {                        // now move both; the gap stays n\n        first = first.next;\n        second = second.next;\n    }\n    return second;\n}\n\nconst head = build([10, 20, 30, 40, 50]);\nfor (const n of [1, 2, 5, 6]) {\n    const node = nthFromEnd(head, n);\n    console.log(\"n =\", n, \"→\", node ? node.data : \"none\");\n}","filename":"JavaScript"}'),
  ('7dd738fb-fe5f-7662-97d0-ccd183da1d40', 'ad', 'code', '{"language":"text","code":"n = 1 → 50\nn = 2 → 40\nn = 5 → 10\nn = 6 → none","filename":"Output"}'),
  ('3b53c208-cb33-78ff-883d-ac1e4f64e83c', 'ae', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('033b8b37-c81d-70aa-970d-bf0bec1915fd', 'af', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Check "},{"type":"text","text":"first","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"inside","marks":[{"type":"italic"}]},{"type":"text","text":" the first loop. Without that check, "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" larger than the length dereferences "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" — a crash in C++/Java/JavaScript and an "},{"type":"text","text":"AttributeError","marks":[{"type":"code"}]},{"type":"text","text":" in Python. “Delete the nth node from the end” is the same walk with a dummy head so that deleting the first node is not a special case."}]}]}}'),
  ('f6236b9f-9353-797e-8f1c-64608d72d8b0', 'ag', 'heading', '{"level":1,"content":[{"type":"text","text":"Reverse a linked list"}]}'),
  ('7f3f2da8-9223-72f6-b283-bb8c3e5ab802', 'ah', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"50 → 40 → 30 → 20 → 10","marks":[{"type":"code"}]}]}]}}'),
  ('61f405e2-8419-76f0-9050-c641d90c1666', 'ai', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterative:","marks":[{"type":"bold"}]},{"type":"text","text":" walk the list once with three pointers. "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":" is the already-reversed part, "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is the node being flipped, "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" saves the rest so it is not lost when "},{"type":"text","text":"curr.next","marks":[{"type":"code"}]},{"type":"text","text":" is overwritten. "},{"type":"text","text":"Recursive:","marks":[{"type":"bold"}]},{"type":"text","text":" reverse everything after "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":", then make the old second node ("},{"type":"text","text":"head.next","marks":[{"type":"code"}]},{"type":"text","text":") point back to "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" and set "},{"type":"text","text":"head.next = null","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" becomes the tail."}]}]}}'),
  ('130d01d9-3d40-73d4-bc90-5b6ede7dd8ba', 'aj', 'code', '{"language":"text","code":"before:   prev   curr   next\n           ∅  ←  10  →  20 → 30 → 40 → 50\n\nflip:      ∅  ←  10     20 → 30 → 40 → 50      curr.next = prev\n\nadvance:         prev   curr   next\n           ∅  ←  10     20  →  30 → 40 → 50    prev = curr, curr = next","filename":"One step of the iterative reversal — repeat until curr is ∅, then prev is the new head"}'),
  ('3c8492b7-cadd-7cb7-9f42-68dccf5afeac', 'ak', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef reverse_iter(head):\n    prev, curr = None, head\n    while curr:\n        nxt = curr.next              # save the rest of the list\n        curr.next = prev             # flip the link\n        prev, curr = curr, nxt       # advance both pointers\n    return prev                      # prev is the new head\n\ndef reverse_rec(head):\n    if head is None or head.next is None:\n        return head                  # empty or single node: already reversed\n    rest = reverse_rec(head.next)    # reverse everything after head\n    head.next.next = head            # old second node now points back at head\n    head.next = None                 # head becomes the tail\n    return rest\n\nhead = build([10, 20, 30, 40, 50])\nhead = reverse_iter(head)\nprint(\"iterative:\", to_str(head))\nhead = reverse_rec(head)             # reverse it back\nprint(\"recursive:\", to_str(head))","filename":"Python"}'),
  ('4a7650f0-ed02-7fe1-a701-b73b427280df', 'al', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* reverseIter(Node* head) {\n    Node* prev = nullptr;\n    Node* curr = head;\n    while (curr) {\n        Node* next = curr->next;         // save the rest of the list\n        curr->next = prev;               // flip the link\n        prev = curr;                     // advance both pointers\n        curr = next;\n    }\n    return prev;                         // prev is the new head\n}\n\nNode* reverseRec(Node* head) {\n    if (!head || !head->next) return head;   // empty or single node\n    Node* rest = reverseRec(head->next);     // reverse everything after head\n    head->next->next = head;                 // old second node points back at head\n    head->next = nullptr;                    // head becomes the tail\n    return rest;\n}\n\nint main() {\n    Node* head = build({10, 20, 30, 40, 50});\n    head = reverseIter(head);\n    cout << \"iterative: \" << toStr(head) << \"\\n\";\n    head = reverseRec(head);                 // reverse it back\n    cout << \"recursive: \" << toStr(head) << \"\\n\";\n}","filename":"C++"}'),
  ('9edfd079-27fe-72b9-9032-c295a5524272', 'am', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node reverseIter(Node head) {\n        Node prev = null, curr = head;\n        while (curr != null) {\n            Node next = curr.next;           // save the rest of the list\n            curr.next = prev;                // flip the link\n            prev = curr;                     // advance both pointers\n            curr = next;\n        }\n        return prev;                         // prev is the new head\n    }\n\n    static Node reverseRec(Node head) {\n        if (head == null || head.next == null) return head;   // empty or single node\n        Node rest = reverseRec(head.next);   // reverse everything after head\n        head.next.next = head;               // old second node points back at head\n        head.next = null;                    // head becomes the tail\n        return rest;\n    }\n\n    public static void main(String[] args) {\n        Node head = build(new int[]{10, 20, 30, 40, 50});\n        head = reverseIter(head);\n        System.out.println(\"iterative: \" + toStr(head));\n        head = reverseRec(head);             // reverse it back\n        System.out.println(\"recursive: \" + toStr(head));\n    }\n}","filename":"Java"}'),
  ('d9c975fc-f2ab-7f11-98f9-25263e97bb8a', 'an', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction reverseIter(head) {\n    let prev = null, curr = head;\n    while (curr) {\n        const next = curr.next;              // save the rest of the list\n        curr.next = prev;                    // flip the link\n        prev = curr;                         // advance both pointers\n        curr = next;\n    }\n    return prev;                             // prev is the new head\n}\n\nfunction reverseRec(head) {\n    if (!head || !head.next) return head;    // empty or single node\n    const rest = reverseRec(head.next);      // reverse everything after head\n    head.next.next = head;                   // old second node points back at head\n    head.next = null;                        // head becomes the tail\n    return rest;\n}\n\nlet head = build([10, 20, 30, 40, 50]);\nhead = reverseIter(head);\nconsole.log(\"iterative:\", toStr(head));\nhead = reverseRec(head);                     // reverse it back\nconsole.log(\"recursive:\", toStr(head));","filename":"JavaScript"}'),
  ('0e6a06b0-cd35-7f71-bfaf-0cd8ff4ee006', 'ao', 'code', '{"language":"text","code":"iterative: 50 40 30 20 10\nrecursive: 10 20 30 40 50","filename":"Output"}'),
  ('5f2e2db8-753f-77f4-8c08-234ce849f24c', 'ap', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1) iterative · O(n) recursive (call stack)"}]}]}}'),
  ('95fff226-3183-779c-a0a2-9a161f13606e', 'aq', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgetting to save "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" before "},{"type":"text","text":"curr.next = prev","marks":[{"type":"code"}]},{"type":"text","text":" loses the rest of the list. In the recursive version, forgetting "},{"type":"text","text":"head.next = null","marks":[{"type":"code"}]},{"type":"text","text":" leaves a cycle between the last two nodes — the first node still points at the second, which now points back. Prefer the iterative version in production: the recursive one uses one stack frame per node and overflows on long lists (Python at ~1000)."}]}]}}'),
  ('4d1e0214-e264-7627-a841-eb2a4daba30c', 'ar', 'heading', '{"level":1,"content":[{"type":"text","text":"Reverse a linked list in groups of k"}]}'),
  ('1ffae2a0-3c04-743a-ad37-b5dee4d57682', 'as', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50 → 60, k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"30 → 20 → 10 → 60 → 50 → 40","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50, k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"30 → 20 → 10 → 50 → 40","marks":[{"type":"code"}]}]}]}}'),
  ('05143133-3dd4-7c3b-96d8-c06b36edc9ce', 'at', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse the first "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" nodes with the ordinary three-pointer loop. The group''s old first node ("},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":") is now its last node, so its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" must point at the result of reversing the rest — either a recursive call, or the next group in an iterative loop. The last group is reversed even when it holds fewer than "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" nodes (the LeetCode variant leaves a short tail untouched — add a length check if that is required)."}]}]}}'),
  ('6213c842-3f2b-7ae5-b500-71bf6274ef8e', 'au', 'code', '{"language":"text","code":"10 → 20 → 30 │ 40 → 50 → 60          groups of k = 3\n\nreverse group 1:   30 → 20 → 10 → ?          10 was the head, now the tail\nreverse group 2:                60 → 50 → 40\nlink:              30 → 20 → 10 → 60 → 50 → 40","filename":"Each group is reversed on its own; the old head of a group links to the new head of the next"}'),
  ('ba2668f4-f874-7e1c-821e-592b8fb5dc16', 'av', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive","marks":[{"type":"bold"}]},{"type":"text","text":" — the natural way to express “reverse this group, then link to the reversed rest”:"}]}]}}'),
  ('0639bc9c-935c-72cd-8792-4a71c0ca09ac', 'aw', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef reverse_k_rec(head, k):\n    curr, prev = head, None\n    count = 0\n    while curr and count < k:        # reverse the first k nodes\n        nxt = curr.next\n        curr.next = prev\n        prev = curr\n        curr = nxt\n        count += 1\n    if curr:                         # more nodes left: reverse them and link\n        head.next = reverse_k_rec(curr, k)   # head is now the tail of this group\n    return prev                      # prev is the new head of this group\n\nfor values in ([10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 50]):\n    print(to_str(reverse_k_rec(build(values), 3)))","filename":"Python"}'),
  ('470f0749-7e19-7325-9ac8-91c85e865b92', 'ax', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* reverseKRec(Node* head, int k) {\n    Node* curr = head;\n    Node* prev = nullptr;\n    int count = 0;\n    while (curr && count < k) {          // reverse the first k nodes\n        Node* next = curr->next;\n        curr->next = prev;\n        prev = curr;\n        curr = next;\n        count++;\n    }\n    if (curr)                            // more nodes left: reverse them and link\n        head->next = reverseKRec(curr, k);   // head is now the tail of this group\n    return prev;                         // prev is the new head of this group\n}\n\nint main() {\n    for (vector<int> values : {vector<int>{10, 20, 30, 40, 50, 60}, vector<int>{10, 20, 30, 40, 50}})\n        cout << toStr(reverseKRec(build(values), 3)) << \"\\n\";\n}","filename":"C++"}'),
  ('b68f4cf4-551c-7972-8da7-60fe329d1888', 'ay', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node reverseKRec(Node head, int k) {\n        Node curr = head, prev = null;\n        int count = 0;\n        while (curr != null && count < k) {  // reverse the first k nodes\n            Node next = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = next;\n            count++;\n        }\n        if (curr != null)                    // more nodes left: reverse them and link\n            head.next = reverseKRec(curr, k);    // head is now the tail of this group\n        return prev;                         // prev is the new head of this group\n    }\n\n    public static void main(String[] args) {\n        for (int[] values : new int[][]{{10, 20, 30, 40, 50, 60}, {10, 20, 30, 40, 50}})\n            System.out.println(toStr(reverseKRec(build(values), 3)));\n    }\n}","filename":"Java"}'),
  ('282198fa-a995-7026-bb15-abf2f1c013c6', 'az', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction reverseKRec(head, k) {\n    let curr = head, prev = null, count = 0;\n    while (curr && count < k) {              // reverse the first k nodes\n        const next = curr.next;\n        curr.next = prev;\n        prev = curr;\n        curr = next;\n        count++;\n    }\n    if (curr)                                // more nodes left: reverse them and link\n        head.next = reverseKRec(curr, k);    // head is now the tail of this group\n    return prev;                             // prev is the new head of this group\n}\n\nfor (const values of [[10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 50]])\n    console.log(toStr(reverseKRec(build(values), 3)));","filename":"JavaScript"}'),
  ('2de9bcaf-f37c-73bc-a213-83e4a3446a67', 'b00', 'code', '{"language":"text","code":"30 20 10 60 50 40\n30 20 10 50 40","filename":"Output"}'),
  ('62e0f3e5-ca83-74a0-a8ac-0f4a3b8ab6c9', 'b01', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n / k) recursion depth"}]},{"type":"paragraph","content":[{"type":"text","text":"Iterative","marks":[{"type":"bold"}]},{"type":"text","text":" — same work, constant extra space. Remember the first node of each group: after the group is reversed it is the group''s tail, and the "},{"type":"text","text":"previous","marks":[{"type":"italic"}]},{"type":"text","text":" group''s tail must be pointed at the new head of this group."}]}]}}'),
  ('f49b3ad0-617d-77bc-af6b-8416aadabe90', 'b02', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef reverse_k_iter(head, k):\n    curr = head\n    new_head = None\n    prev_tail = None                 # tail of the previous reversed group\n    while curr:\n        group_first = curr           # will become this group''s tail\n        prev = None\n        count = 0\n        while curr and count < k:    # reverse one group\n            nxt = curr.next\n            curr.next = prev\n            prev = curr\n            curr = nxt\n            count += 1\n        if new_head is None:\n            new_head = prev          # first group''s new head is the list''s head\n        else:\n            prev_tail.next = prev    # link previous group to this one\n        prev_tail = group_first\n    return new_head\n\nfor values in ([10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 50]):\n    print(to_str(reverse_k_iter(build(values), 3)))","filename":"Python"}'),
  ('a692668f-d222-7462-84e0-b75df9e800c7', 'b03', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* reverseKIter(Node* head, int k) {\n    Node* curr = head;\n    Node* newHead = nullptr;\n    Node* prevTail = nullptr;            // tail of the previous reversed group\n    while (curr) {\n        Node* groupFirst = curr;         // will become this group''s tail\n        Node* prev = nullptr;\n        int count = 0;\n        while (curr && count < k) {      // reverse one group\n            Node* next = curr->next;\n            curr->next = prev;\n            prev = curr;\n            curr = next;\n            count++;\n        }\n        if (!newHead) newHead = prev;    // first group''s new head is the list''s head\n        else prevTail->next = prev;      // link previous group to this one\n        prevTail = groupFirst;\n    }\n    return newHead;\n}\n\nint main() {\n    for (vector<int> values : {vector<int>{10, 20, 30, 40, 50, 60}, vector<int>{10, 20, 30, 40, 50}})\n        cout << toStr(reverseKIter(build(values), 3)) << \"\\n\";\n}","filename":"C++"}'),
  ('d7a8fdde-895d-72f5-88a6-3adb68ad1914', 'b04', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node reverseKIter(Node head, int k) {\n        Node curr = head, newHead = null;\n        Node prevTail = null;                // tail of the previous reversed group\n        while (curr != null) {\n            Node groupFirst = curr;          // will become this group''s tail\n            Node prev = null;\n            int count = 0;\n            while (curr != null && count < k) {   // reverse one group\n                Node next = curr.next;\n                curr.next = prev;\n                prev = curr;\n                curr = next;\n                count++;\n            }\n            if (newHead == null) newHead = prev;  // first group''s new head is the list''s head\n            else prevTail.next = prev;            // link previous group to this one\n            prevTail = groupFirst;\n        }\n        return newHead;\n    }\n\n    public static void main(String[] args) {\n        for (int[] values : new int[][]{{10, 20, 30, 40, 50, 60}, {10, 20, 30, 40, 50}})\n            System.out.println(toStr(reverseKIter(build(values), 3)));\n    }\n}","filename":"Java"}'),
  ('294475f5-7716-7851-a2d8-71870063aa9d', 'b05', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction reverseKIter(head, k) {\n    let curr = head, newHead = null;\n    let prevTail = null;                     // tail of the previous reversed group\n    while (curr) {\n        const groupFirst = curr;             // will become this group''s tail\n        let prev = null, count = 0;\n        while (curr && count < k) {          // reverse one group\n            const next = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = next;\n            count++;\n        }\n        if (!newHead) newHead = prev;        // first group''s new head is the list''s head\n        else prevTail.next = prev;           // link previous group to this one\n        prevTail = groupFirst;\n    }\n    return newHead;\n}\n\nfor (const values of [[10, 20, 30, 40, 50, 60], [10, 20, 30, 40, 50]])\n    console.log(toStr(reverseKIter(build(values), 3)));","filename":"JavaScript"}'),
  ('b07c56b5-4a5f-7b74-a577-8cb48dcdab63', 'b06', 'code', '{"language":"text","code":"30 20 10 60 50 40\n30 20 10 50 40","filename":"Output"}'),
  ('7e4d6d38-7fc2-7d66-8fce-420cacebe7a3', 'b07', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('96155121-a204-7e5b-8503-db9273cae55a', 'b08', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The two bugs here are both linking bugs: forgetting "},{"type":"text","text":"head.next = …","marks":[{"type":"code"}]},{"type":"text","text":" after the recursive call (groups come back disconnected), or linking "},{"type":"text","text":"prev_tail","marks":[{"type":"code"}]},{"type":"text","text":" to the group''s "},{"type":"text","text":"first","marks":[{"type":"italic"}]},{"type":"text","text":" node instead of its "},{"type":"text","text":"new head","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('73f2b1eb-7ffe-776b-9f18-ca5ab659e977', 'b09', 'heading', '{"level":1,"content":[{"type":"text","text":"Detect a loop — hash set of visited nodes"}]}'),
  ('6cef2598-d3bd-71a2-979d-dd8917e83b5f', 'b0A', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50, and 50 → 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]}]}]}}'),
  ('36c02d8c-3db9-7966-b29c-0b01dbced8e7', 'b0B', 'code', '{"language":"text","code":"10 → 20 → 30 → 40 → 50\n          ↑          │\n          └──────────┘          50.next = 30 — a traversal never ends","filename":"A loop: the last node points back into the list"}'),
  ('bd7aaf42-e2cb-701e-b95f-768988ca1758', 'b0C', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk the list, putting each node''s "},{"type":"text","text":"reference","marks":[{"type":"bold"}]},{"type":"text","text":" (not its value — values may repeat) into a set. The first node already in the set is the loop entry; reaching "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" means no loop. Simple and "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time, but "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" extra memory — the baseline Floyd''s algorithm improves on."}]}]}}'),
  ('ce6d586a-3006-7d97-8534-abb1473fa0e7', 'b0D', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef has_loop_set(head):\n    seen = set()\n    curr = head\n    while curr:\n        if curr in seen:             # visited before → we went round a loop\n            return True\n        seen.add(curr)               # nodes hash by identity, not by value\n        curr = curr.next\n    return False\n\nhead = build([10, 20, 30, 40, 50])\nprint(\"10 → 20 → 30 → 40 → 50:\", \"Yes\" if has_loop_set(head) else \"No\")\ntail = head\nwhile tail.next:\n    tail = tail.next\ntail.next = head.next.next           # 50 → 30 creates the loop\nprint(\"with 50 → 30:\", \"Yes\" if has_loop_set(head) else \"No\")","filename":"Python"}'),
  ('4b7af8bc-6261-7a29-8e57-1e0dae1ef7e9', 'b0E', 'code', '{"language":"text","code":"10 → 20 → 30 → 40 → 50: No\nwith 50 → 30: Yes","filename":"Output"}'),
  ('ea124673-eb25-79ae-9a9c-b9adbfbb950b', 'b0F', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The set must hold "},{"type":"text","text":"references","marks":[{"type":"bold"}]},{"type":"text","text":": in C++ an "},{"type":"text","text":"unordered_set<Node*>","marks":[{"type":"code"}]},{"type":"text","text":" keyed by address, in Java a "},{"type":"text","text":"HashSet<Node>","marks":[{"type":"code"}]},{"type":"text","text":" (identity semantics because "},{"type":"text","text":"Node","marks":[{"type":"code"}]},{"type":"text","text":" does not override "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":"), in JavaScript a "},{"type":"text","text":"Set","marks":[{"type":"code"}]},{"type":"text","text":" of objects. A set of "},{"type":"text","text":"values","marks":[{"type":"italic"}]},{"type":"text","text":" would report a false loop on "},{"type":"text","text":"1 → 2 → 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('6c3212bf-ed6b-7c31-8711-1d36dc6568c2', 'b0G', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n)"}]}]}}'),
  ('c8d268ef-8ab5-761b-b7c1-929491a57acf', 'b0H', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two other "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":"-space tricks you may see: a "},{"type":"text","text":"visited","marks":[{"type":"code"}]},{"type":"text","text":" flag inside each node (needs a field you usually cannot add), or pointing every visited node''s "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" at a sentinel dummy node (destroys the list). Floyd''s algorithm needs neither."}]}]}}'),
  ('fd370d96-cbcc-7ec6-ae36-546626fb2e53', 'b0I', 'heading', '{"level":1,"content":[{"type":"text","text":"Detect a loop — Floyd''s cycle detection"}]}'),
  ('a86dcea1-0986-7f2f-9a1b-2082e6211a27', 'b0J', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50, and 50 → 30","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 → 40 → 50","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]}]}]}}'),
  ('ef68d24f-293e-7574-87de-8ae322adf2c3', 'b0K', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Run "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" (one step) and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" (two steps) from the head. If there is no loop, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" reaches "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". If there is a loop, both pointers eventually circle inside it, and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" gains exactly one node on "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" every step — so it must land on "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" within one lap. Two pointers, no memory."}]}]}}'),
  ('ba41ea37-97ee-761e-99df-60084deb754d', 'b0L', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Initialise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"slow = head","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fast = head","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Advance","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Each step: "},{"type":"text","text":"slow = slow.next","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fast = fast.next.next","marks":[{"type":"code"}]},{"type":"text","text":". Stop with “no loop” when "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"fast.next","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" is the same node as "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":", there is a loop."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why they must meet.","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" enters the loop no later than "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":". Suppose that when "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" enters the loop, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" nodes ahead of it ("},{"type":"text","text":"0 ≤ k < n","marks":[{"type":"code"}]},{"type":"text","text":" for a loop of length "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":") — equivalently, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"n − k","marks":[{"type":"code"}]},{"type":"text","text":" nodes "},{"type":"text","text":"behind","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" going round the circle. Every step "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" moves one and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" moves two, so the gap behind closes by exactly one node per step. After "},{"type":"text","text":"n − k","marks":[{"type":"code"}]},{"type":"text","text":" steps the gap is zero: they stand on the same node. Because the gap shrinks by one (not two), "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" can never jump over "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('cfba3b2a-f3cf-72a2-9151-f1cb516852c2', 'b0M', 'code', '{"language":"text","code":"10 → 20 → 30 → 40 → 50 → (back to 30)        loop length n = 3\n\nstep   slow   fast\n  0     10     10\n  1     20     30\n  2     30     50\n  3     40     40   ← meet","filename":"Trace on the example: slow enters the loop at step 2 with fast one ahead; one more step and they meet"}'),
  ('28acd9c8-c298-7b35-9aaa-d7e27641d903', 'b0N', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef has_loop(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow = slow.next             # one step\n        fast = fast.next.next        # two steps\n        if slow is fast:             # same node (not same value) → loop\n            return True\n    return False                     # fast ran off the end\n\nhead = build([10, 20, 30, 40, 50])\nprint(\"10 → 20 → 30 → 40 → 50:\", \"Yes\" if has_loop(head) else \"No\")\ntail = head\nwhile tail.next:\n    tail = tail.next\ntail.next = head.next.next           # 50 → 30 creates the loop\nprint(\"with 50 → 30:\", \"Yes\" if has_loop(head) else \"No\")","filename":"Python"}'),
  ('15120130-01fa-7e63-bba3-5f7b779c5d45', 'b0O', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nbool hasLoop(Node* head) {\n    Node* slow = head;\n    Node* fast = head;\n    while (fast && fast->next) {\n        slow = slow->next;               // one step\n        fast = fast->next->next;         // two steps\n        if (slow == fast) return true;   // same address → loop\n    }\n    return false;                        // fast ran off the end\n}\n\nint main() {\n    Node* head = build({10, 20, 30, 40, 50});\n    cout << \"10 → 20 → 30 → 40 → 50: \" << (hasLoop(head) ? \"Yes\" : \"No\") << \"\\n\";\n    Node* tail = head;\n    while (tail->next) tail = tail->next;\n    tail->next = head->next->next;       // 50 → 30 creates the loop\n    cout << \"with 50 → 30: \" << (hasLoop(head) ? \"Yes\" : \"No\") << \"\\n\";\n}","filename":"C++"}'),
  ('59f35e1c-04e0-73f6-9558-5f373921fc40', 'b0P', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static boolean hasLoop(Node head) {\n        Node slow = head, fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;                // one step\n            fast = fast.next.next;           // two steps\n            if (slow == fast) return true;   // same reference → loop\n        }\n        return false;                        // fast ran off the end\n    }\n\n    public static void main(String[] args) {\n        Node head = build(new int[]{10, 20, 30, 40, 50});\n        System.out.println(\"10 → 20 → 30 → 40 → 50: \" + (hasLoop(head) ? \"Yes\" : \"No\"));\n        Node tail = head;\n        while (tail.next != null) tail = tail.next;\n        tail.next = head.next.next;          // 50 → 30 creates the loop\n        System.out.println(\"with 50 → 30: \" + (hasLoop(head) ? \"Yes\" : \"No\"));\n    }\n}","filename":"Java"}'),
  ('6410a6a9-983f-7638-b28f-d98829fcffa3', 'b0Q', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction hasLoop(head) {\n    let slow = head, fast = head;\n    while (fast && fast.next) {\n        slow = slow.next;                    // one step\n        fast = fast.next.next;               // two steps\n        if (slow === fast) return true;      // same object → loop\n    }\n    return false;                            // fast ran off the end\n}\n\nconst head = build([10, 20, 30, 40, 50]);\nconsole.log(\"10 → 20 → 30 → 40 → 50:\", hasLoop(head) ? \"Yes\" : \"No\");\nlet tail = head;\nwhile (tail.next) tail = tail.next;\ntail.next = head.next.next;                  // 50 → 30 creates the loop\nconsole.log(\"with 50 → 30:\", hasLoop(head) ? \"Yes\" : \"No\");","filename":"JavaScript"}'),
  ('eb614ba1-2ce3-7132-9bcd-9ec481f5bee7', 'b0R', 'code', '{"language":"text","code":"10 → 20 → 30 → 40 → 50: No\nwith 50 → 30: Yes","filename":"Output"}'),
  ('ab0692ed-bd95-7f06-8b38-5569ded1164e', 'b0S', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('a1a15b9a-39ef-73ca-ba86-eda44a693dbc', 'b0T', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare the "},{"type":"text","text":"nodes","marks":[{"type":"bold"}]},{"type":"text","text":", not their values ("},{"type":"text","text":"slow is fast","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" on references) — a list with repeated values has no loop. And test "},{"type":"text","text":"fast.next","marks":[{"type":"code"}]},{"type":"text","text":" as well as "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" before stepping twice; "},{"type":"text","text":"fast.next.next","marks":[{"type":"code"}]},{"type":"text","text":" on the last node is a "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" dereference."}]}]}}'),
  ('bfba18cc-871b-7998-8fed-627b377024f3', 'b0U', 'heading', '{"level":1,"content":[{"type":"text","text":"Detect and remove a loop"}]}'),
  ('1140a73c-ec0b-76ec-a66b-878b30332b95', 'b0V', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 15 → 5 → 20, and 20 → 15","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 15 → 5 → 20 (loop of length 3 starting at 15 removed)","marks":[{"type":"code"}]}]}]}}'),
  ('7b135afe-6b29-703c-9a43-07429af38904', 'b0W', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Floyd''s meeting point is not the loop''s first node — but it is a fixed distance from it. Move "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" back to "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":", keep "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" at the meeting point, and advance both "},{"type":"text","text":"one step at a time","marks":[{"type":"bold"}]},{"type":"text","text":": they meet exactly at the first node of the loop. Then walk round the loop once more to find the node whose "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is that first node, and set its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('38567a13-08f0-7530-b9af-59193baaff65', 'b0X', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Detect","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run Floyd''s algorithm. If "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" never meet, there is no loop — stop."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Loop length (variation 1)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"From the meeting point, walk round until you are back: the number of steps is the loop length "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"First node of the loop (variation 2)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Put "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" at "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":", leave "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" at the meeting point. Move both one step until they are equal — that node is the loop start."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cut","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"From the loop start, walk until "},{"type":"text","text":"node.next","marks":[{"type":"code"}]},{"type":"text","text":" is the loop start again; that node is the last node of the loop. Set its "},{"type":"text","text":"next = null","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Why moving one pointer back to the head works.","marks":[{"type":"bold"}]},{"type":"text","text":" Let "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" be the distance from "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" to the loop start, "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" the loop length, and "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" the distance from the loop start to the meeting point. When they meet, "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" has walked "},{"type":"text","text":"m + k + x·n","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" twice that, "},{"type":"text","text":"m + k + y·n","marks":[{"type":"code"}]},{"type":"text","text":", for some lap counts "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"y","marks":[{"type":"code"}]},{"type":"text","text":":"}]},{"type":"paragraph","content":[{"type":"text","text":"2(m + k + x·n) = m + k + y·n ⟹ m + k = (y − 2x)·n","marks":[{"type":"code"}]}]},{"type":"paragraph","content":[{"type":"text","text":"So "},{"type":"text","text":"m + k","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"multiple of the loop length","marks":[{"type":"bold"}]},{"type":"text","text":". A pointer that starts at the meeting point (already "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" into the loop) and walks "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" more steps is "},{"type":"text","text":"m + k ≡ 0 (mod n)","marks":[{"type":"code"}]},{"type":"text","text":" into the loop — i.e. back at the loop start. A pointer that starts at "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" and walks "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" steps is also at the loop start. Walking both at the same speed, they coincide for the first time exactly there."}]}]}}'),
  ('31327dd3-6dcf-7028-a0a8-d49ed95dbbb9', 'b0Y', 'code', '{"language":"text","code":"10 → 15 → 5 → 20 → (back to 15)        m = 1, n = 3\n\nFloyd:   slow 10,15,5,20     fast 10,5,15,20  → meet at 20  (k = 2, m + k = 3 = n ✓)\nphase 2: slow = head = 10, fast = 20\n         one step each:  slow → 15, fast → 15   → loop starts at 15\ncut:     from 15 walk to the node whose next is 15: that is 20 → 20.next = ∅","filename":"Trace on the example"}'),
  ('fd123a71-9c90-79bd-8574-6c974e999bb2', 'b0Z', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef detect_and_remove(head):\n    slow = fast = head\n    while fast and fast.next:            # 1. Floyd: find a meeting point\n        slow = slow.next\n        fast = fast.next.next\n        if slow is fast:\n            break\n    else:\n        print(\"no loop\")\n        return\n    length = 1                           # 2. loop length: walk round once\n    p = fast.next\n    while p is not fast:\n        p = p.next\n        length += 1\n    print(\"loop length:\", length)\n    slow = head                          # 3. loop start: same speed from head and meeting point\n    while slow is not fast:\n        slow = slow.next\n        fast = fast.next\n    print(\"loop starts at:\", slow.data)\n    last = slow                          # 4. find the last node of the loop and cut\n    while last.next is not slow:\n        last = last.next\n    last.next = None\n\nhead = build([10, 15, 5, 20])\nhead.next.next.next.next = head.next     # 20 → 15 creates the loop\ndetect_and_remove(head)\nprint(\"after removal:\", to_str(head))\ndetect_and_remove(head)                  # run again: the list is clean now","filename":"Python"}'),
  ('8bdb0c14-1d18-7219-ba35-a939679a0cf6', 'b0a', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nvoid detectAndRemove(Node* head) {\n    Node* slow = head;\n    Node* fast = head;\n    bool met = false;\n    while (fast && fast->next) {             // 1. Floyd: find a meeting point\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) { met = true; break; }\n    }\n    if (!met) { cout << \"no loop\\n\"; return; }\n    int length = 1;                          // 2. loop length: walk round once\n    for (Node* p = fast->next; p != fast; p = p->next) length++;\n    cout << \"loop length: \" << length << \"\\n\";\n    slow = head;                             // 3. loop start: same speed from head and meeting point\n    while (slow != fast) {\n        slow = slow->next;\n        fast = fast->next;\n    }\n    cout << \"loop starts at: \" << slow->data << \"\\n\";\n    Node* last = slow;                       // 4. find the last node of the loop and cut\n    while (last->next != slow) last = last->next;\n    last->next = nullptr;\n}\n\nint main() {\n    Node* head = build({10, 15, 5, 20});\n    head->next->next->next->next = head->next;   // 20 → 15 creates the loop\n    detectAndRemove(head);\n    cout << \"after removal: \" << toStr(head) << \"\\n\";\n    detectAndRemove(head);                   // run again: the list is clean now\n}","filename":"C++"}'),
  ('d1c88420-45f6-785e-9854-c85a97363180', 'b0b', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static void detectAndRemove(Node head) {\n        Node slow = head, fast = head;\n        boolean met = false;\n        while (fast != null && fast.next != null) {   // 1. Floyd: find a meeting point\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) { met = true; break; }\n        }\n        if (!met) { System.out.println(\"no loop\"); return; }\n        int length = 1;                          // 2. loop length: walk round once\n        for (Node p = fast.next; p != fast; p = p.next) length++;\n        System.out.println(\"loop length: \" + length);\n        slow = head;                             // 3. loop start: same speed from head and meeting point\n        while (slow != fast) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n        System.out.println(\"loop starts at: \" + slow.data);\n        Node last = slow;                        // 4. find the last node of the loop and cut\n        while (last.next != slow) last = last.next;\n        last.next = null;\n    }\n\n    public static void main(String[] args) {\n        Node head = build(new int[]{10, 15, 5, 20});\n        head.next.next.next.next = head.next;    // 20 → 15 creates the loop\n        detectAndRemove(head);\n        System.out.println(\"after removal: \" + toStr(head));\n        detectAndRemove(head);                   // run again: the list is clean now\n    }\n}","filename":"Java"}'),
  ('a94067b3-425d-7b76-a2b0-a512b19833f6', 'b0c', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction detectAndRemove(head) {\n    let slow = head, fast = head, met = false;\n    while (fast && fast.next) {                  // 1. Floyd: find a meeting point\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) { met = true; break; }\n    }\n    if (!met) { console.log(\"no loop\"); return; }\n    let length = 1;                              // 2. loop length: walk round once\n    for (let p = fast.next; p !== fast; p = p.next) length++;\n    console.log(\"loop length:\", length);\n    slow = head;                                 // 3. loop start: same speed from head and meeting point\n    while (slow !== fast) {\n        slow = slow.next;\n        fast = fast.next;\n    }\n    console.log(\"loop starts at:\", slow.data);\n    let last = slow;                             // 4. find the last node of the loop and cut\n    while (last.next !== slow) last = last.next;\n    last.next = null;\n}\n\nconst head = build([10, 15, 5, 20]);\nhead.next.next.next.next = head.next;            // 20 → 15 creates the loop\ndetectAndRemove(head);\nconsole.log(\"after removal:\", toStr(head));\ndetectAndRemove(head);                           // run again: the list is clean now","filename":"JavaScript"}'),
  ('5672df8c-c8df-7eae-a4a4-1b66ca91339f', 'b0d', 'code', '{"language":"text","code":"loop length: 3\nloop starts at: 15\nafter removal: 10 15 5 20\nno loop","filename":"Output"}'),
  ('e060a3a2-4723-7a85-841b-1f468392300a', 'b0e', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('fede346b-1ea3-787f-9a5c-8c0fb26dfa2f', 'b0f', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the loop starts at the head itself ("},{"type":"text","text":"m = 0","marks":[{"type":"code"}]},{"type":"text","text":"), the meeting point "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" the loop start, so the phase-2 loop runs zero times — no special case needed. The original notes handled that separately; the version above does not have to because it compares "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" directly rather than "},{"type":"text","text":"slow.next","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"fast.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('86459f41-1222-78e4-a324-a5086f14ef8c', 'b0g', 'heading', '{"level":1,"content":[{"type":"text","text":"Intersection point of two linked lists"}]}'),
  ('a76c3e84-97c5-73b0-8db3-2ce60e7b864d', 'b0h', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"A: 5 → 8 → 7 → 10 → 12 → 15, B: 9 → 10 → 12 → 15 (B''s second node is A''s node 10)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10","marks":[{"type":"code"}]}]}]}}'),
  ('d98ae7cb-e048-74b9-ab43-2a46308a5bc6', 'b0i', 'code', '{"language":"text","code":"A:  5 → 8 → 7 ─┐\n               ├─▶ 10 → 12 → 15 → ∅\nB:        9 ───┘","filename":"Two lists sharing a tail — the intersection is the first shared node, by identity, not by value"}'),
  ('3880f11f-c7f0-7b3a-a261-3da66f7e91be', 'b0j', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Baseline — hash set of nodes.","marks":[{"type":"bold"}]},{"type":"text","text":" Put every node of "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":" in a set, then walk "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":" and return the first node already present. "},{"type":"text","text":"O(m + n)","marks":[{"type":"code"}]},{"type":"text","text":" time, "},{"type":"text","text":"O(m)","marks":[{"type":"code"}]},{"type":"text","text":" space."}]}]}}'),
  ('b74deb82-8e4d-7117-aca7-97785265be0f', 'b0k', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef intersection_set(a, b):\n    seen = set()\n    while a:\n        seen.add(a)                  # node identity, not value\n        a = a.next\n    while b:\n        if b in seen:\n            return b\n        b = b.next\n    return None\n\na = build([5, 8, 7, 10, 12, 15])\nb = Node(9)\nb.next = a.next.next.next            # 9 → 10 → 12 → 15, sharing from 10\nnode = intersection_set(a, b)\nprint(\"intersection:\", node.data if node else \"none\")","filename":"Python"}'),
  ('3f1ba655-fbb2-7f0a-9ab2-2fa893f9113f', 'b0l', 'code', '{"language":"text","code":"intersection: 10","filename":"Output"}'),
  ('13f5821a-ef9d-7cc7-9add-5d5febef3ceb', 'b0m', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient — align the lengths.","marks":[{"type":"bold"}]},{"type":"text","text":" Both lists share their whole tail from the intersection on, so they differ only in the number of nodes "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" it. Count both lengths, advance the longer list''s pointer by the difference, then walk both together; the first time the two pointers are the same node is the intersection (or both reach "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('c5b1da52-954c-79f3-9fa8-528318cb7a9b', 'b0n', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After skipping "},{"type":"text","text":"|len(A) − len(B)|","marks":[{"type":"code"}]},{"type":"text","text":" nodes of the longer list, both pointers are the same distance from the end. From then on they move in lock-step, so they reach the shared tail at the same moment."}]}]}}'),
  ('a0b8a385-4cb2-776a-b08f-e0a133c6554d', 'b0o', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef length(head):\n    n = 0\n    while head:\n        n += 1\n        head = head.next\n    return n\n\ndef intersection(a, b):\n    la, lb = length(a), length(b)\n    while la > lb:                   # advance the longer list by the difference\n        a = a.next\n        la -= 1\n    while lb > la:\n        b = b.next\n        lb -= 1\n    while a is not b:                # same distance from the end: walk together\n        a = a.next\n        b = b.next\n    return a                         # None when both ran off the end\n\na = build([5, 8, 7, 10, 12, 15])\nb = Node(9)\nb.next = a.next.next.next            # 9 → 10 → 12 → 15, sharing from 10\nprint(\"A:\", to_str(a))\nprint(\"B:\", to_str(b))\nnode = intersection(a, b)\nprint(\"intersection:\", node.data if node else \"none\")\nnode = intersection(a, build([1, 2]))\nprint(\"intersection with 1 → 2:\", node.data if node else \"none\")","filename":"Python"}'),
  ('bdd9aef5-c1eb-77ac-a41d-f98eb396c2dd', 'b0p', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nint length(Node* head) {\n    int n = 0;\n    for (Node* c = head; c; c = c->next) n++;\n    return n;\n}\n\nNode* intersection(Node* a, Node* b) {\n    int la = length(a), lb = length(b);\n    while (la > lb) { a = a->next; la--; }   // advance the longer list by the difference\n    while (lb > la) { b = b->next; lb--; }\n    while (a != b) {                         // same distance from the end: walk together\n        a = a->next;\n        b = b->next;\n    }\n    return a;                                // nullptr when both ran off the end\n}\n\nint main() {\n    Node* a = build({5, 8, 7, 10, 12, 15});\n    Node* b = new Node(9);\n    b->next = a->next->next->next;           // 9 → 10 → 12 → 15, sharing from 10\n    cout << \"A: \" << toStr(a) << \"\\n\";\n    cout << \"B: \" << toStr(b) << \"\\n\";\n    Node* node = intersection(a, b);\n    cout << \"intersection: \" << (node ? to_string(node->data) : \"none\") << \"\\n\";\n    node = intersection(a, build({1, 2}));\n    cout << \"intersection with 1 → 2: \" << (node ? to_string(node->data) : \"none\") << \"\\n\";\n}","filename":"C++"}'),
  ('e1c0d417-92a1-7ba6-88e6-e38eaa75b24a', 'b0q', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static int length(Node head) {\n        int n = 0;\n        for (Node c = head; c != null; c = c.next) n++;\n        return n;\n    }\n\n    static Node intersection(Node a, Node b) {\n        int la = length(a), lb = length(b);\n        while (la > lb) { a = a.next; la--; }    // advance the longer list by the difference\n        while (lb > la) { b = b.next; lb--; }\n        while (a != b) {                         // same distance from the end: walk together\n            a = a.next;\n            b = b.next;\n        }\n        return a;                                // null when both ran off the end\n    }\n\n    public static void main(String[] args) {\n        Node a = build(new int[]{5, 8, 7, 10, 12, 15});\n        Node b = new Node(9);\n        b.next = a.next.next.next;               // 9 → 10 → 12 → 15, sharing from 10\n        System.out.println(\"A: \" + toStr(a));\n        System.out.println(\"B: \" + toStr(b));\n        Node node = intersection(a, b);\n        System.out.println(\"intersection: \" + (node != null ? String.valueOf(node.data) : \"none\"));\n        node = intersection(a, build(new int[]{1, 2}));\n        System.out.println(\"intersection with 1 → 2: \" + (node != null ? String.valueOf(node.data) : \"none\"));\n    }\n}","filename":"Java"}'),
  ('00b10510-3b8b-7c9e-86af-17502b4f0033', 'b0r', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction length(head) {\n    let n = 0;\n    for (let c = head; c; c = c.next) n++;\n    return n;\n}\n\nfunction intersection(a, b) {\n    let la = length(a), lb = length(b);\n    while (la > lb) { a = a.next; la--; }        // advance the longer list by the difference\n    while (lb > la) { b = b.next; lb--; }\n    while (a !== b) {                            // same distance from the end: walk together\n        a = a.next;\n        b = b.next;\n    }\n    return a;                                    // null when both ran off the end\n}\n\nconst a = build([5, 8, 7, 10, 12, 15]);\nconst b = new Node(9);\nb.next = a.next.next.next;                       // 9 → 10 → 12 → 15, sharing from 10\nconsole.log(\"A:\", toStr(a));\nconsole.log(\"B:\", toStr(b));\nlet node = intersection(a, b);\nconsole.log(\"intersection:\", node ? node.data : \"none\");\nnode = intersection(a, build([1, 2]));\nconsole.log(\"intersection with 1 → 2:\", node ? node.data : \"none\");","filename":"JavaScript"}'),
  ('f39794a0-c370-7fec-ac02-00990c19589d', 'b0s', 'code', '{"language":"text","code":"A: 5 8 7 10 12 15\nB: 9 10 12 15\nintersection: 10\nintersection with 1 → 2: none","filename":"Output"}'),
  ('340bb189-41a2-71ee-bef2-df56a83f6be6', 'b0t', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(m + n) · Space O(1)"}]}]}}'),
  ('6d68f1a0-99e1-78ea-bea9-e593f5f55486', 'b0u', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No-counting variant:","marks":[{"type":"bold"}]},{"type":"text","text":" walk "},{"type":"text","text":"pa","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"pb","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":". Both travel exactly "},{"type":"text","text":"len(A) + len(B)","marks":[{"type":"code"}]},{"type":"text","text":" nodes, so they reach the intersection together — or both hit "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" after the second list. Same complexity, slightly less code, harder to explain in an interview."}]}]}}'),
  ('be2f2144-6df8-7059-af35-83cd36004a71', 'b0v', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Intersection means the "},{"type":"text","text":"same node object","marks":[{"type":"bold"}]},{"type":"text","text":", not equal values — "},{"type":"text","text":"1 → 2 → 3","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"9 → 3","marks":[{"type":"code"}]},{"type":"text","text":" with two different "},{"type":"text","text":"3","marks":[{"type":"code"}]},{"type":"text","text":" nodes do not intersect. Compare references."}]}]}}'),
  ('bdb44764-d350-788a-b081-e2a5201b14ac', 'b0w', 'heading', '{"level":1,"content":[{"type":"text","text":"Segregate even and odd nodes"}]}'),
  ('c4703311-cd2d-7d14-ae1d-22cc32b5fd3c', 'b0x', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"17 → 15 → 8 → 12 → 5","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"8 → 12 → 17 → 15 → 5 (all even values first, relative order preserved)","marks":[{"type":"code"}]}]}]}}'),
  ('fc810419-2f28-7678-b354-87ba3912d00c', 'b0y', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive — move odd nodes to the end.","marks":[{"type":"bold"}]},{"type":"text","text":" Find the last node, then traverse once more: every odd node is detached and appended after the current last node. Stop after processing the "},{"type":"text","text":"original","marks":[{"type":"italic"}]},{"type":"text","text":" last node, otherwise the nodes you just appended are visited again and the loop never ends."}]}]}}'),
  ('1a905742-12ed-70d7-a241-fd5f63971429', 'b0z', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef segregate_naive(head):\n    if head is None:\n        return None\n    last = head\n    while last.next:\n        last = last.next\n    stop = last                      # original last node: do not go past it\n    dummy = Node(0)\n    dummy.next = head\n    prev, curr = dummy, head\n    while True:\n        nxt = curr.next\n        if curr.data % 2 == 1:       # odd: detach and append after last\n            prev.next = nxt\n            last.next = curr\n            curr.next = None\n            last = curr\n        else:\n            prev = curr\n        if curr is stop:\n            break\n        curr = nxt\n    return dummy.next\n\nprint(to_str(segregate_naive(build([17, 15, 8, 12, 5]))))\nprint(to_str(segregate_naive(build([1, 3, 5]))))","filename":"Python"}'),
  ('13980375-1973-715c-b0a5-675a1e17c3d5', 'b10', 'code', '{"language":"text","code":"8 12 17 15 5\n1 3 5","filename":"Output"}'),
  ('4c68aada-5843-7370-8ab7-d4ba81f89c7d', 'b11', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One traversal — build two sublists and join them.","marks":[{"type":"bold"}]},{"type":"text","text":" Keep the start and end of an "},{"type":"text","text":"even","marks":[{"type":"italic"}]},{"type":"text","text":" sublist and of an "},{"type":"text","text":"odd","marks":[{"type":"italic"}]},{"type":"text","text":" sublist. Every node is appended to the end of its own sublist as it is visited, so each sublist keeps the original relative order. At the end, link the even tail to the odd head and terminate the odd tail."}]}]}}'),
  ('a2730c80-3d41-74b7-b745-b4eac75742e1', 'b12', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nothing is allocated and no node is moved twice: the four pointers "},{"type":"text","text":"even_start","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"even_end","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"odd_start","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"odd_end","marks":[{"type":"code"}]},{"type":"text","text":" just thread the existing nodes into two chains, which are joined once."}]}]}}'),
  ('801a32c1-633e-7a3c-9552-bb9fdc657240', 'b13', 'code', '{"language":"text","code":"input:   17 → 15 → 8 → 12 → 5\n\nevens:   8 → 12                  even_start = 8,  even_end = 12\nodds:    17 → 15 → 5             odd_start = 17,  odd_end = 5\n\njoin:    8 → 12 → 17 → 15 → 5 → ∅    even_end.next = odd_start, odd_end.next = ∅","filename":"Two chains threaded through the same nodes, then joined"}'),
  ('2f406129-0a99-7cae-bf05-ce0007702037', 'b14', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef segregate(head):\n    even_start = even_end = None\n    odd_start = odd_end = None\n    curr = head\n    while curr:\n        if curr.data % 2 == 0:\n            if even_start is None:\n                even_start = even_end = curr\n            else:\n                even_end.next = curr     # append to the even chain\n                even_end = curr\n        else:\n            if odd_start is None:\n                odd_start = odd_end = curr\n            else:\n                odd_end.next = curr      # append to the odd chain\n                odd_end = curr\n        curr = curr.next\n    if even_start is None or odd_start is None:\n        return head                  # all even or all odd: nothing to do\n    even_end.next = odd_start        # join the chains\n    odd_end.next = None              # terminate — or the list gets a cycle\n    return even_start\n\nfor values in ([17, 15, 8, 12, 5], [1, 3, 5], [1, 2, 4]):\n    print(to_str(segregate(build(values))))","filename":"Python"}'),
  ('01f34e96-e799-73e3-aed4-e86d6a83d2e6', 'b15', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* segregate(Node* head) {\n    Node *evenStart = nullptr, *evenEnd = nullptr;\n    Node *oddStart = nullptr, *oddEnd = nullptr;\n    for (Node* curr = head; curr; curr = curr->next) {\n        if (curr->data % 2 == 0) {\n            if (!evenStart) evenStart = evenEnd = curr;\n            else { evenEnd->next = curr; evenEnd = curr; }   // append to the even chain\n        } else {\n            if (!oddStart) oddStart = oddEnd = curr;\n            else { oddEnd->next = curr; oddEnd = curr; }     // append to the odd chain\n        }\n    }\n    if (!evenStart || !oddStart) return head;   // all even or all odd: nothing to do\n    evenEnd->next = oddStart;                    // join the chains\n    oddEnd->next = nullptr;                      // terminate — or the list gets a cycle\n    return evenStart;\n}\n\nint main() {\n    for (vector<int> values : {vector<int>{17, 15, 8, 12, 5}, vector<int>{1, 3, 5}, vector<int>{1, 2, 4}})\n        cout << toStr(segregate(build(values))) << \"\\n\";\n}","filename":"C++"}'),
  ('5f86192c-9086-7ace-be83-d3429bd17f1c', 'b16', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node segregate(Node head) {\n        Node evenStart = null, evenEnd = null, oddStart = null, oddEnd = null;\n        for (Node curr = head; curr != null; curr = curr.next) {\n            if (curr.data % 2 == 0) {\n                if (evenStart == null) evenStart = evenEnd = curr;\n                else { evenEnd.next = curr; evenEnd = curr; }   // append to the even chain\n            } else {\n                if (oddStart == null) oddStart = oddEnd = curr;\n                else { oddEnd.next = curr; oddEnd = curr; }     // append to the odd chain\n            }\n        }\n        if (evenStart == null || oddStart == null) return head;  // all even or all odd\n        evenEnd.next = oddStart;                 // join the chains\n        oddEnd.next = null;                      // terminate — or the list gets a cycle\n        return evenStart;\n    }\n\n    public static void main(String[] args) {\n        for (int[] values : new int[][]{{17, 15, 8, 12, 5}, {1, 3, 5}, {1, 2, 4}})\n            System.out.println(toStr(segregate(build(values))));\n    }\n}","filename":"Java"}'),
  ('142ffcfe-8ca7-7346-8cff-3f25b98563fd', 'b17', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction segregate(head) {\n    let evenStart = null, evenEnd = null, oddStart = null, oddEnd = null;\n    for (let curr = head; curr; curr = curr.next) {\n        if (curr.data % 2 === 0) {\n            if (!evenStart) evenStart = evenEnd = curr;\n            else { evenEnd.next = curr; evenEnd = curr; }       // append to the even chain\n        } else {\n            if (!oddStart) oddStart = oddEnd = curr;\n            else { oddEnd.next = curr; oddEnd = curr; }         // append to the odd chain\n        }\n    }\n    if (!evenStart || !oddStart) return head;    // all even or all odd: nothing to do\n    evenEnd.next = oddStart;                     // join the chains\n    oddEnd.next = null;                          // terminate — or the list gets a cycle\n    return evenStart;\n}\n\nfor (const values of [[17, 15, 8, 12, 5], [1, 3, 5], [1, 2, 4]])\n    console.log(toStr(segregate(build(values))));","filename":"JavaScript"}'),
  ('52c3089e-800e-72e8-bd59-e900dac65709', 'b18', 'code', '{"language":"text","code":"8 12 17 15 5\n1 3 5\n2 4 1","filename":"Output"}'),
  ('f232c9f2-aa19-7b8d-a4f6-00103b513dcc', 'b19', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('60fda42e-72c0-7821-98be-c0713b8a9438', 'b1A', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"odd_end.next = None","marks":[{"type":"code"}]},{"type":"text","text":" is the line everyone forgets. If the last node of the input is even, the odd tail still points at some even node that is now earlier in the list — and the result has a cycle that "},{"type":"text","text":"to_str","marks":[{"type":"code"}]},{"type":"text","text":" would loop on forever. The same two-chain pattern solves “partition a list around a value "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":"” and “odd/even "},{"type":"text","text":"positions","marks":[{"type":"italic"}]},{"type":"text","text":"” (LeetCode 328)."}]}]}}'),
  ('6bca073b-5eff-7824-aa68-42d38d3a2c08', 'b1B', 'heading', '{"level":1,"content":[{"type":"text","text":"Pairwise swap nodes"}]}'),
  ('70de0704-a3e7-760d-9d71-971d745055f9', 'b1C', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 → 2 → 3 → 4","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2 → 1 → 4 → 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 → 2 → 3 → 4 → 5","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2 → 1 → 4 → 3 → 5 (odd one out stays)","marks":[{"type":"code"}]}]}]}}'),
  ('b81e773c-124c-7fb9-b3e4-16a237edc2f6', 'b1D', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Swap the data.","marks":[{"type":"bold"}]},{"type":"text","text":" Walk two nodes at a time and exchange the values of each pair. Trivial — but it only works when swapping values is allowed and cheap. If nodes carry large payloads, or other code holds references to specific nodes (an LRU cache, an iterator), the values must stay with their nodes and the "},{"type":"text","text":"links","marks":[{"type":"italic"}]},{"type":"text","text":" have to be swapped instead."}]}]}}'),
  ('e92de030-5276-7db7-9ea8-798997fcb0e4', 'b1E', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef pairwise_swap_data(head):\n    curr = head\n    while curr and curr.next:        # at least one node ahead\n        curr.data, curr.next.data = curr.next.data, curr.data\n        curr = curr.next.next        # jump over the pair\n    return head\n\nfor values in ([1, 2, 3, 4], [1, 2, 3, 4, 5]):\n    print(to_str(pairwise_swap_data(build(values))))","filename":"Python"}'),
  ('c112c2a9-79af-7633-bf9a-ce02efb6b537', 'b1F', 'code', '{"language":"text","code":"2 1 4 3\n2 1 4 3 5","filename":"Output"}'),
  ('0ff1a225-3b39-7bf8-a13f-0a024d0e9526', 'b1G', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]},{"type":"paragraph","content":[{"type":"text","text":"Swap the links.","marks":[{"type":"bold"}]},{"type":"text","text":" For each pair "},{"type":"text","text":"a → b","marks":[{"type":"code"}]},{"type":"text","text":", make the node "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" the pair point at "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" point at "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" point at whatever followed "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":". A dummy node in front of the head removes the special case for the first pair (whose “node before” would otherwise not exist), and the new head is simply "},{"type":"text","text":"dummy.next","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('d2fe4869-6d4c-7738-a228-47c8b8d77541', 'b1H', 'code', '{"language":"text","code":"prev → a → b → rest            before\n\na.next = b.next   :  prev → a ─────▶ rest\n                              b ──▶ rest\nb.next = a        :  b → a → rest\nprev.next = b     :  prev → b → a → rest\nprev = a          :  ready for the next pair","filename":"Three link changes per pair; prev moves to a, the pair''s new tail"}'),
  ('039e0910-4fc2-7b0a-a885-87ee3ca06a24', 'b1I', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef pairwise_swap(head):\n    dummy = Node(0)                  # sits before the head: no special first pair\n    dummy.next = head\n    prev = dummy\n    while prev.next and prev.next.next:\n        a = prev.next                # first node of the pair\n        b = a.next                   # second node of the pair\n        a.next = b.next              # a now points past the pair\n        b.next = a                   # b points back at a\n        prev.next = b                # the node before the pair points at b\n        prev = a                     # a is the pair''s new tail\n    return dummy.next\n\nfor values in ([1, 2, 3, 4], [1, 2, 3, 4, 5]):\n    print(to_str(pairwise_swap(build(values))))","filename":"Python"}'),
  ('fcb56541-68f2-732e-a06e-14a2e2e2bc34', 'b1J', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* pairwiseSwap(Node* head) {\n    Node dummy(0);                       // sits before the head: no special first pair\n    dummy.next = head;\n    Node* prev = &dummy;\n    while (prev->next && prev->next->next) {\n        Node* a = prev->next;            // first node of the pair\n        Node* b = a->next;               // second node of the pair\n        a->next = b->next;               // a now points past the pair\n        b->next = a;                     // b points back at a\n        prev->next = b;                  // the node before the pair points at b\n        prev = a;                        // a is the pair''s new tail\n    }\n    return dummy.next;\n}\n\nint main() {\n    for (vector<int> values : {vector<int>{1, 2, 3, 4}, vector<int>{1, 2, 3, 4, 5}})\n        cout << toStr(pairwiseSwap(build(values))) << \"\\n\";\n}","filename":"C++"}'),
  ('a7597790-d43c-7268-b620-ffcd71d5bc89', 'b1K', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node pairwiseSwap(Node head) {\n        Node dummy = new Node(0);            // sits before the head: no special first pair\n        dummy.next = head;\n        Node prev = dummy;\n        while (prev.next != null && prev.next.next != null) {\n            Node a = prev.next;              // first node of the pair\n            Node b = a.next;                 // second node of the pair\n            a.next = b.next;                 // a now points past the pair\n            b.next = a;                      // b points back at a\n            prev.next = b;                   // the node before the pair points at b\n            prev = a;                        // a is the pair''s new tail\n        }\n        return dummy.next;\n    }\n\n    public static void main(String[] args) {\n        for (int[] values : new int[][]{{1, 2, 3, 4}, {1, 2, 3, 4, 5}})\n            System.out.println(toStr(pairwiseSwap(build(values))));\n    }\n}","filename":"Java"}'),
  ('7d2be720-8ad6-7419-bceb-91d3d43b7aa8', 'b1L', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction pairwiseSwap(head) {\n    const dummy = new Node(0);               // sits before the head: no special first pair\n    dummy.next = head;\n    let prev = dummy;\n    while (prev.next && prev.next.next) {\n        const a = prev.next;                 // first node of the pair\n        const b = a.next;                    // second node of the pair\n        a.next = b.next;                     // a now points past the pair\n        b.next = a;                          // b points back at a\n        prev.next = b;                       // the node before the pair points at b\n        prev = a;                            // a is the pair''s new tail\n    }\n    return dummy.next;\n}\n\nfor (const values of [[1, 2, 3, 4], [1, 2, 3, 4, 5]])\n    console.log(toStr(pairwiseSwap(build(values))));","filename":"JavaScript"}'),
  ('66d0d0a3-2590-7f79-b26c-fe7bb00553d8', 'b1M', 'code', '{"language":"text","code":"2 1 4 3\n2 1 4 3 5","filename":"Output"}'),
  ('b1e52fbb-0669-74a8-be46-46cc9a8c67e3', 'b1N', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('778722f5-38c6-711e-85f1-5a60f75135a8', 'b1O', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pairwise swap is “reverse in groups of "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":"” with "},{"type":"text","text":"k = 2","marks":[{"type":"code"}]},{"type":"text","text":" and a short tail left alone. The dummy-head trick is worth memorising: it turns every “what if it is the first node?” branch into ordinary code."}]}]}}'),
  ('33f4249b-2d71-78c4-bd82-262c4449d0ae', 'b1P', 'heading', '{"level":1,"content":[{"type":"text","text":"Clone a linked list with random pointers"}]}'),
  ('058c3b13-730d-7549-ab62-4f05e3ca93a3', 'b1Q', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 → 2 → 3 → 4 with random links 1→3, 2→1, 3→4, 4→2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"an independent copy with the same next and random structure","marks":[{"type":"code"}]}]}]}}'),
  ('3ca264e5-2a9e-7c8e-9b95-25e5da07c684', 'b1R', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each node has a second pointer, "},{"type":"text","text":"random","marks":[{"type":"code"}]},{"type":"text","text":", to any node in the list (or "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"). A plain copy that walks "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" cannot set "},{"type":"text","text":"random","marks":[{"type":"code"}]},{"type":"text","text":" on the copies because the target copy may not exist yet — and even when it does, you have to "},{"type":"text","text":"find","marks":[{"type":"italic"}]},{"type":"text","text":" it. Two solutions: a map from original to copy, or a trick that stores the mapping inside the list itself."}]}]}}'),
  ('9b7d0b4f-ea34-7f19-86d5-44620b5c7d60', 'b1S', 'code', '{"language":"text","code":"        ┌─────────────────┐\n        │        ┌────────┼───────┐\n        ▼        │        │       ▼\n1 ───▶ 2 ───▶ 3 ───▶ 4      next (solid)\n│      ▲        │        ▲     random: 1→3, 2→1, 3→4, 4→2\n└──────┼────────┘        │\n       └─────────────────┘","filename":"A list whose random pointers can jump anywhere — forwards, backwards or to itself"}'),
  ('2cafed5a-7858-7d08-ab6a-3346b892e4ce', 'b1T', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Method 1 — dictionary from original to copy.","marks":[{"type":"bold"}]},{"type":"text","text":" Pass 1 creates a copy of every node and records "},{"type":"text","text":"copy_of[original] = copy","marks":[{"type":"code"}]},{"type":"text","text":". Pass 2 sets "},{"type":"text","text":"copy_of[node].next = copy_of[node.next]","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"copy_of[node].random = copy_of[node.random]","marks":[{"type":"code"}]},{"type":"text","text":"; mapping "},{"type":"text","text":"null → null","marks":[{"type":"code"}]},{"type":"text","text":" makes the end of the list and missing randoms fall out for free."}]}]}}'),
  ('3b604d0c-883e-79fe-aa39-f24dac92ced7', 'b1U', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n        self.random = None\n\ndef pairs(head):                     # \"data:random data:random …\"\n    parts = []\n    while head:\n        parts.append(f\"{head.data}:{head.random.data if head.random else ''-''}\")\n        head = head.next\n    return \" \".join(parts)\n\ndef clone(head):\n    copy_of = {None: None}           # original → copy; None maps to None\n    curr = head\n    while curr:                      # pass 1: create the copies\n        copy_of[curr] = Node(curr.data)\n        curr = curr.next\n    curr = head\n    while curr:                      # pass 2: wire next and random via the map\n        copy_of[curr].next = copy_of[curr.next]\n        copy_of[curr].random = copy_of[curr.random]\n        curr = curr.next\n    return copy_of[head]\n\nnodes = [Node(v) for v in (1, 2, 3, 4)]\nfor i in range(3):\n    nodes[i].next = nodes[i + 1]\nfor i, r in enumerate((2, 0, 3, 1)):     # 1→3, 2→1, 3→4, 4→2\n    nodes[i].random = nodes[r]\nhead = nodes[0]\ncopy = clone(head)\nprint(\"original:\", pairs(head))\nprint(\"clone:   \", pairs(copy))\nprint(\"after adding 100 to every original node\")\nfor n in nodes:\n    n.data += 100\nprint(\"original:\", pairs(head))\nprint(\"clone:   \", pairs(copy))      # unchanged: it shares no node with the original","filename":"Python"}'),
  ('d6616a71-70c8-7ee6-b913-9b581524857f', 'b1V', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <unordered_map>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next; Node* random;\n    Node(int d) : data(d), next(nullptr), random(nullptr) {}\n};\n\nstring pairs(Node* head) {                 // \"data:random data:random …\"\n    string s;\n    for (Node* c = head; c; c = c->next)\n        s += to_string(c->data) + \":\" + (c->random ? to_string(c->random->data) : \"-\") + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* clone(Node* head) {\n    unordered_map<Node*, Node*> copyOf;    // original → copy\n    copyOf[nullptr] = nullptr;             // nullptr maps to nullptr\n    for (Node* c = head; c; c = c->next)   // pass 1: create the copies\n        copyOf[c] = new Node(c->data);\n    for (Node* c = head; c; c = c->next) { // pass 2: wire next and random via the map\n        copyOf[c]->next = copyOf[c->next];\n        copyOf[c]->random = copyOf[c->random];\n    }\n    return copyOf[head];\n}\n\nint main() {\n    vector<Node*> nodes;\n    for (int v : {1, 2, 3, 4}) nodes.push_back(new Node(v));\n    for (int i = 0; i < 3; i++) nodes[i]->next = nodes[i + 1];\n    int r[] = {2, 0, 3, 1};                // 1→3, 2→1, 3→4, 4→2\n    for (int i = 0; i < 4; i++) nodes[i]->random = nodes[r[i]];\n    Node* head = nodes[0];\n    Node* copy = clone(head);\n    cout << \"original: \" << pairs(head) << \"\\n\";\n    cout << \"clone:    \" << pairs(copy) << \"\\n\";\n    cout << \"after adding 100 to every original node\\n\";\n    for (Node* n : nodes) n->data += 100;\n    cout << \"original: \" << pairs(head) << \"\\n\";\n    cout << \"clone:    \" << pairs(copy) << \"\\n\";   // unchanged: shares no node with the original\n}","filename":"C++"}'),
  ('a63afc57-c457-77ec-b66a-1696dfb8ed0b', 'b1W', 'code', '{"language":"java","code":"import java.util.HashMap;\nimport java.util.Map;\n\npublic class Main {\n    static class Node {\n        int data; Node next, random;\n        Node(int d) { data = d; }\n    }\n\n    static String pairs(Node head) {         // \"data:random data:random …\"\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next)\n            sb.append(c.data).append('':'').append(c.random != null ? String.valueOf(c.random.data) : \"-\").append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node clone(Node head) {\n        Map<Node, Node> copyOf = new HashMap<>();   // original → copy\n        copyOf.put(null, null);                     // null maps to null\n        for (Node c = head; c != null; c = c.next)  // pass 1: create the copies\n            copyOf.put(c, new Node(c.data));\n        for (Node c = head; c != null; c = c.next) {   // pass 2: wire next and random via the map\n            copyOf.get(c).next = copyOf.get(c.next);\n            copyOf.get(c).random = copyOf.get(c.random);\n        }\n        return copyOf.get(head);\n    }\n\n    public static void main(String[] args) {\n        Node[] nodes = new Node[4];\n        for (int i = 0; i < 4; i++) nodes[i] = new Node(i + 1);\n        for (int i = 0; i < 3; i++) nodes[i].next = nodes[i + 1];\n        int[] r = {2, 0, 3, 1};                  // 1→3, 2→1, 3→4, 4→2\n        for (int i = 0; i < 4; i++) nodes[i].random = nodes[r[i]];\n        Node head = nodes[0];\n        Node copy = clone(head);\n        System.out.println(\"original: \" + pairs(head));\n        System.out.println(\"clone:    \" + pairs(copy));\n        System.out.println(\"after adding 100 to every original node\");\n        for (Node n : nodes) n.data += 100;\n        System.out.println(\"original: \" + pairs(head));\n        System.out.println(\"clone:    \" + pairs(copy));   // unchanged: shares no node with the original\n    }\n}","filename":"Java"}'),
  ('7cd22b08-52c9-72dd-9b78-5bdbd68a6f58', 'b1X', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; this.random = null; }\n}\n\nfunction pairs(head) {                       // \"data:random data:random …\"\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(`${c.data}:${c.random ? c.random.data : \"-\"}`);\n    return parts.join(\" \");\n}\n\nfunction clone(head) {\n    const copyOf = new Map([[null, null]]);  // original → copy; null maps to null\n    for (let c = head; c; c = c.next)        // pass 1: create the copies\n        copyOf.set(c, new Node(c.data));\n    for (let c = head; c; c = c.next) {      // pass 2: wire next and random via the map\n        copyOf.get(c).next = copyOf.get(c.next);\n        copyOf.get(c).random = copyOf.get(c.random);\n    }\n    return copyOf.get(head);\n}\n\nconst nodes = [1, 2, 3, 4].map(v => new Node(v));\nfor (let i = 0; i < 3; i++) nodes[i].next = nodes[i + 1];\n[2, 0, 3, 1].forEach((r, i) => { nodes[i].random = nodes[r]; });   // 1→3, 2→1, 3→4, 4→2\nconst head = nodes[0];\nconst copy = clone(head);\nconsole.log(\"original:\", pairs(head));\nconsole.log(\"clone:   \", pairs(copy));\nconsole.log(\"after adding 100 to every original node\");\nfor (const n of nodes) n.data += 100;\nconsole.log(\"original:\", pairs(head));\nconsole.log(\"clone:   \", pairs(copy));      // unchanged: shares no node with the original","filename":"JavaScript"}'),
  ('0c3fcd47-98f9-7ecc-b73a-81700a5484a6', 'b1Y', 'code', '{"language":"text","code":"original: 1:3 2:1 3:4 4:2\nclone:    1:3 2:1 3:4 4:2\nafter adding 100 to every original node\noriginal: 101:103 102:101 103:104 104:102\nclone:    1:3 2:1 3:4 4:2","filename":"Output"}'),
  ('12ece144-1bb1-7b25-864a-76ae723756b3', 'b1Z', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n) for the map"}]},{"type":"paragraph","content":[{"type":"text","text":"Method 2 — interleave the copies, ","marks":[{"type":"bold"}]},{"type":"text","text":"O(1)","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" extra space.","marks":[{"type":"bold"}]},{"type":"text","text":" Store the mapping "},{"type":"text","text":"in the list","marks":[{"type":"italic"}]},{"type":"text","text":": insert each copy right after its original, so "},{"type":"text","text":"original.next","marks":[{"type":"code"}]},{"type":"text","text":" is always its copy. Then "},{"type":"text","text":"copy.random = original.random.next","marks":[{"type":"code"}]},{"type":"text","text":" finds the right copy in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" without a map. Finally unweave the two lists."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interleave","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For every original node "},{"type":"text","text":"o","marks":[{"type":"code"}]},{"type":"text","text":", create "},{"type":"text","text":"o''","marks":[{"type":"code"}]},{"type":"text","text":" and insert it after "},{"type":"text","text":"o","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"1 → 1'' → 2 → 2'' → 3 → 3'' → 4 → 4''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Set randoms","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"For every original "},{"type":"text","text":"o","marks":[{"type":"code"}]},{"type":"text","text":" (step two at a time): "},{"type":"text","text":"o.next.random = o.random.next","marks":[{"type":"code"}]},{"type":"text","text":" — the copy of "},{"type":"text","text":"o.random","marks":[{"type":"code"}]},{"type":"text","text":" is the node right after it. Skip when "},{"type":"text","text":"o.random","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unweave","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Restore "},{"type":"text","text":"o.next = o.next.next","marks":[{"type":"code"}]},{"type":"text","text":" and set "},{"type":"text","text":"o''.next = o''.next.next","marks":[{"type":"code"}]},{"type":"text","text":", splitting the chain back into the original list and the clone."}]}]}]}]}}'),
  ('cb47fb65-afbe-7fc9-9048-f2ec9253d100', 'b1a', 'code', '{"language":"text","code":"after step 1:   1 → 1'' → 2 → 2'' → 3 → 3'' → 4 → 4''\n\nstep 2 for node 2 (random → 1):  2.next.random = 2.random.next\n                                 2''.random     = 1.next = 1''  ✓\n\nafter step 3:   1 → 2 → 3 → 4          original restored\n                1'' → 2'' → 3'' → 4''      clone, with randoms among the primed nodes","filename":"The copy of any node is always the node right after it — that is the whole trick"}'),
  ('615ec31e-7a9b-74b0-b19c-09c6124b3c9e', 'b1b', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n        self.random = None\n\ndef pairs(head):                     # \"data:random data:random …\"\n    parts = []\n    while head:\n        parts.append(f\"{head.data}:{head.random.data if head.random else ''-''}\")\n        head = head.next\n    return \" \".join(parts)\n\ndef clone(head):\n    if head is None:\n        return None\n    curr = head\n    while curr:                      # 1. insert a copy after every original\n        copy = Node(curr.data)\n        copy.next = curr.next\n        curr.next = copy\n        curr = copy.next\n    curr = head\n    while curr:                      # 2. copy.random = the copy of original.random\n        if curr.random:\n            curr.next.random = curr.random.next\n        curr = curr.next.next\n    clone_head = head.next\n    curr = head\n    while curr:                      # 3. unweave originals and copies\n        copy = curr.next\n        curr.next = copy.next\n        copy.next = copy.next.next if copy.next else None\n        curr = curr.next\n    return clone_head\n\nnodes = [Node(v) for v in (1, 2, 3, 4)]\nfor i in range(3):\n    nodes[i].next = nodes[i + 1]\nfor i, r in enumerate((2, 0, 3, 1)):     # 1→3, 2→1, 3→4, 4→2\n    nodes[i].random = nodes[r]\nhead = nodes[0]\ncopy = clone(head)\nprint(\"original:\", pairs(head))\nprint(\"clone:   \", pairs(copy))\nprint(\"after adding 100 to every original node\")\nfor n in nodes:\n    n.data += 100\nprint(\"original:\", pairs(head))\nprint(\"clone:   \", pairs(copy))","filename":"Python"}'),
  ('4997dacd-7ad0-79c7-8906-6cd03735de64', 'b1c', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next; Node* random;\n    Node(int d) : data(d), next(nullptr), random(nullptr) {}\n};\n\nstring pairs(Node* head) {                 // \"data:random data:random …\"\n    string s;\n    for (Node* c = head; c; c = c->next)\n        s += to_string(c->data) + \":\" + (c->random ? to_string(c->random->data) : \"-\") + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* clone(Node* head) {\n    if (!head) return nullptr;\n    for (Node* curr = head; curr; curr = curr->next->next) {   // 1. insert a copy after every original\n        Node* copy = new Node(curr->data);\n        copy->next = curr->next;\n        curr->next = copy;\n    }\n    for (Node* curr = head; curr; curr = curr->next->next)     // 2. copy->random = copy of original->random\n        if (curr->random) curr->next->random = curr->random->next;\n    Node* cloneHead = head->next;\n    for (Node* curr = head; curr; curr = curr->next) {         // 3. unweave originals and copies\n        Node* copy = curr->next;\n        curr->next = copy->next;\n        copy->next = copy->next ? copy->next->next : nullptr;\n    }\n    return cloneHead;\n}\n\nint main() {\n    vector<Node*> nodes;\n    for (int v : {1, 2, 3, 4}) nodes.push_back(new Node(v));\n    for (int i = 0; i < 3; i++) nodes[i]->next = nodes[i + 1];\n    int r[] = {2, 0, 3, 1};                // 1→3, 2→1, 3→4, 4→2\n    for (int i = 0; i < 4; i++) nodes[i]->random = nodes[r[i]];\n    Node* head = nodes[0];\n    Node* copy = clone(head);\n    cout << \"original: \" << pairs(head) << \"\\n\";\n    cout << \"clone:    \" << pairs(copy) << \"\\n\";\n    cout << \"after adding 100 to every original node\\n\";\n    for (Node* n : nodes) n->data += 100;\n    cout << \"original: \" << pairs(head) << \"\\n\";\n    cout << \"clone:    \" << pairs(copy) << \"\\n\";\n}","filename":"C++"}'),
  ('5ad675c0-8b5b-7afc-a8e8-6748fc60502a', 'b1d', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next, random;\n        Node(int d) { data = d; }\n    }\n\n    static String pairs(Node head) {         // \"data:random data:random …\"\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next)\n            sb.append(c.data).append('':'').append(c.random != null ? String.valueOf(c.random.data) : \"-\").append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node clone(Node head) {\n        if (head == null) return null;\n        for (Node curr = head; curr != null; curr = curr.next.next) {   // 1. insert a copy after every original\n            Node copy = new Node(curr.data);\n            copy.next = curr.next;\n            curr.next = copy;\n        }\n        for (Node curr = head; curr != null; curr = curr.next.next)     // 2. copy.random = copy of original.random\n            if (curr.random != null) curr.next.random = curr.random.next;\n        Node cloneHead = head.next;\n        for (Node curr = head; curr != null; curr = curr.next) {        // 3. unweave originals and copies\n            Node copy = curr.next;\n            curr.next = copy.next;\n            copy.next = copy.next != null ? copy.next.next : null;\n        }\n        return cloneHead;\n    }\n\n    public static void main(String[] args) {\n        Node[] nodes = new Node[4];\n        for (int i = 0; i < 4; i++) nodes[i] = new Node(i + 1);\n        for (int i = 0; i < 3; i++) nodes[i].next = nodes[i + 1];\n        int[] r = {2, 0, 3, 1};                  // 1→3, 2→1, 3→4, 4→2\n        for (int i = 0; i < 4; i++) nodes[i].random = nodes[r[i]];\n        Node head = nodes[0];\n        Node copy = clone(head);\n        System.out.println(\"original: \" + pairs(head));\n        System.out.println(\"clone:    \" + pairs(copy));\n        System.out.println(\"after adding 100 to every original node\");\n        for (Node n : nodes) n.data += 100;\n        System.out.println(\"original: \" + pairs(head));\n        System.out.println(\"clone:    \" + pairs(copy));\n    }\n}","filename":"Java"}'),
  ('0d40f46c-bb22-7bd4-82e1-9de9b675416f', 'b1e', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; this.random = null; }\n}\n\nfunction pairs(head) {                       // \"data:random data:random …\"\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(`${c.data}:${c.random ? c.random.data : \"-\"}`);\n    return parts.join(\" \");\n}\n\nfunction clone(head) {\n    if (!head) return null;\n    for (let curr = head; curr; curr = curr.next.next) {   // 1. insert a copy after every original\n        const copy = new Node(curr.data);\n        copy.next = curr.next;\n        curr.next = copy;\n    }\n    for (let curr = head; curr; curr = curr.next.next)     // 2. copy.random = copy of original.random\n        if (curr.random) curr.next.random = curr.random.next;\n    const cloneHead = head.next;\n    for (let curr = head; curr; curr = curr.next) {        // 3. unweave originals and copies\n        const copy = curr.next;\n        curr.next = copy.next;\n        copy.next = copy.next ? copy.next.next : null;\n    }\n    return cloneHead;\n}\n\nconst nodes = [1, 2, 3, 4].map(v => new Node(v));\nfor (let i = 0; i < 3; i++) nodes[i].next = nodes[i + 1];\n[2, 0, 3, 1].forEach((r, i) => { nodes[i].random = nodes[r]; });   // 1→3, 2→1, 3→4, 4→2\nconst head = nodes[0];\nconst copy = clone(head);\nconsole.log(\"original:\", pairs(head));\nconsole.log(\"clone:   \", pairs(copy));\nconsole.log(\"after adding 100 to every original node\");\nfor (const n of nodes) n.data += 100;\nconsole.log(\"original:\", pairs(head));\nconsole.log(\"clone:   \", pairs(copy));","filename":"JavaScript"}'),
  ('79ffa52f-41ab-71d0-ac95-1bf6b3298bb8', 'b1f', 'code', '{"language":"text","code":"original: 1:3 2:1 3:4 4:2\nclone:    1:3 2:1 3:4 4:2\nafter adding 100 to every original node\noriginal: 101:103 102:101 103:104 104:102\nclone:    1:3 2:1 3:4 4:2","filename":"Output"}'),
  ('a2d33bf8-1912-7d88-8b47-291a56347864', 'b1g', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1) extra (the clone itself is O(n))"}]}]}}'),
  ('95e10a91-da08-771e-adbb-639a8e84d9c8', 'b1h', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original notes wrote "},{"type":"text","text":"curr.next.random = curr.random.next","marks":[{"type":"code"}]},{"type":"text","text":" without checking "},{"type":"text","text":"curr.random","marks":[{"type":"code"}]},{"type":"text","text":" — a "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" random crashes it. Also, step 3 must restore the originals'' "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" pointers; a clone routine that leaves the input list interleaved has corrupted its caller''s data."}]}]}}'),
  ('9aad6e00-bc85-7036-b296-90d3429bf7cf', 'b1i', 'heading', '{"level":1,"content":[{"type":"text","text":"Merge two sorted linked lists"}]}'),
  ('54bb6929-7aa8-7b19-a620-bac337038a83', 'b1j', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 → 20 → 30 and 5 → 25","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 → 10 → 20 → 25 → 30","marks":[{"type":"code"}]}]}]}}'),
  ('82d316b9-796b-7f6c-9bfd-504f4d4e8c6f', 'b1k', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exactly the merge step of merge sort, but without a temporary array: compare the two heads, append the smaller to the result''s tail, advance that list. When one list is exhausted, the whole remainder of the other is already sorted — link it in one step. A dummy head means the result''s tail always exists, so no first-node special case."}]}]}}'),
  ('bd3b4a10-ea40-75a1-a3bf-747316d377c7', 'b1l', 'code', '{"language":"text","code":"a: 10 → 20 → 30        b: 5 → 25\n\ndummy → 5                       take b (5 ≤ 10)\ndummy → 5 → 10                  take a\ndummy → 5 → 10 → 20             take a\ndummy → 5 → 10 → 20 → 25        take b\ndummy → 5 → 10 → 20 → 25 → 30   a has 30 left: link the rest","filename":"Nodes are re-linked, not copied — the two inputs are consumed"}'),
  ('5e8becdf-0c8d-7e38-a967-045eb8e46b69', 'b1m', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef merge(a, b):\n    dummy = Node(0)                  # result tail always exists\n    tail = dummy\n    while a and b:\n        if a.data <= b.data:         # take the smaller head (<= keeps it stable)\n            tail.next = a\n            a = a.next\n        else:\n            tail.next = b\n            b = b.next\n        tail = tail.next\n    tail.next = a if a else b        # the rest of the other list is already sorted\n    return dummy.next\n\nprint(to_str(merge(build([10, 20, 30]), build([5, 25]))))\nprint(to_str(merge(build([1, 3, 5]), build([2, 4, 6]))))\nprint(to_str(merge(build([1, 2, 3]), None)))","filename":"Python"}'),
  ('ccb5d5e6-bdfc-7b8c-838b-13f8a9feca27', 'b1n', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* merge(Node* a, Node* b) {\n    Node dummy(0);                       // result tail always exists\n    Node* tail = &dummy;\n    while (a && b) {\n        if (a->data <= b->data) {        // take the smaller head (<= keeps it stable)\n            tail->next = a;\n            a = a->next;\n        } else {\n            tail->next = b;\n            b = b->next;\n        }\n        tail = tail->next;\n    }\n    tail->next = a ? a : b;              // the rest of the other list is already sorted\n    return dummy.next;\n}\n\nint main() {\n    cout << toStr(merge(build({10, 20, 30}), build({5, 25}))) << \"\\n\";\n    cout << toStr(merge(build({1, 3, 5}), build({2, 4, 6}))) << \"\\n\";\n    cout << toStr(merge(build({1, 2, 3}), nullptr)) << \"\\n\";\n}","filename":"C++"}'),
  ('e7c1ffe0-4a42-7e28-9e58-03ef6fe1d784', 'b1o', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node merge(Node a, Node b) {\n        Node dummy = new Node(0);            // result tail always exists\n        Node tail = dummy;\n        while (a != null && b != null) {\n            if (a.data <= b.data) {          // take the smaller head (<= keeps it stable)\n                tail.next = a;\n                a = a.next;\n            } else {\n                tail.next = b;\n                b = b.next;\n            }\n            tail = tail.next;\n        }\n        tail.next = a != null ? a : b;       // the rest of the other list is already sorted\n        return dummy.next;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(toStr(merge(build(new int[]{10, 20, 30}), build(new int[]{5, 25}))));\n        System.out.println(toStr(merge(build(new int[]{1, 3, 5}), build(new int[]{2, 4, 6}))));\n        System.out.println(toStr(merge(build(new int[]{1, 2, 3}), null)));\n    }\n}","filename":"Java"}'),
  ('976d2f06-2d36-7b22-98c8-1fe2f28df9d8', 'b1p', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction merge(a, b) {\n    const dummy = new Node(0);               // result tail always exists\n    let tail = dummy;\n    while (a && b) {\n        if (a.data <= b.data) {              // take the smaller head (<= keeps it stable)\n            tail.next = a;\n            a = a.next;\n        } else {\n            tail.next = b;\n            b = b.next;\n        }\n        tail = tail.next;\n    }\n    tail.next = a ? a : b;                   // the rest of the other list is already sorted\n    return dummy.next;\n}\n\nconsole.log(toStr(merge(build([10, 20, 30]), build([5, 25]))));\nconsole.log(toStr(merge(build([1, 3, 5]), build([2, 4, 6]))));\nconsole.log(toStr(merge(build([1, 2, 3]), null)));","filename":"JavaScript"}'),
  ('0e1f19bf-39e2-7e1a-b9cb-13664b16fb16', 'b1q', 'code', '{"language":"text","code":"5 10 20 25 30\n1 2 3 4 5 6\n1 2 3","filename":"Output"}'),
  ('9f981b51-df5c-7c26-be21-21224d5dc80a', 'b1r', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(m + n) · Space O(1)"}]},{"type":"paragraph","content":[{"type":"text","text":"The same idea reads naturally as recursion — the head of the merged list is the smaller head, and its "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is the merge of what remains. Elegant, but it uses one stack frame per node, so keep it for short lists:"}]}]}}'),
  ('bac8315a-8e0e-7013-a3dd-3ae2e9b451e0', 'b1s', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef merge_rec(a, b):\n    if a is None:\n        return b\n    if b is None:\n        return a\n    if a.data <= b.data:\n        a.next = merge_rec(a.next, b)    # a is the head, merge the rest behind it\n        return a\n    b.next = merge_rec(a, b.next)\n    return b\n\nprint(to_str(merge_rec(build([10, 20, 30]), build([5, 25]))))","filename":"Python"}'),
  ('d86eb837-725d-73db-a53b-47742b5aa768', 'b1t', 'code', '{"language":"text","code":"5 10 20 25 30","filename":"Output"}'),
  ('65720ffd-3102-7953-95d7-4010b3b22976', 'b1u', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Merge is the building block of "},{"type":"text","text":"merge sort on a linked list","marks":[{"type":"bold"}]},{"type":"text","text":" — the sorting algorithm of choice for lists, because splitting (find the middle with slow/fast) and merging need no random access and no extra array: "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" time, "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" stack. Merging "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" sorted lists uses a min-heap of the "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" current heads."}]}]}}'),
  ('16af58ad-e88b-7235-bfb0-324aa64a2b4b', 'b1v', 'heading', '{"level":1,"content":[{"type":"text","text":"Palindrome linked list"}]}'),
  ('589e338f-3a44-76da-a3b2-1f87a9c25d7d', 'b1w', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 → 2 → 3 → 2 → 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 → 2 → 3 → 4","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"No","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"R → A → D → A → R","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Yes","marks":[{"type":"code"}]}]}]}}'),
  ('4c5e9445-c3c3-7ce4-b0c7-591d503723c1', 'b1x', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Naive — copy the values onto a stack.","marks":[{"type":"bold"}]},{"type":"text","text":" Push every value, then walk the list again popping: pops come out in reverse order, so each pop must equal the current node. "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time but "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" extra space."}]}]}}'),
  ('9b252fb3-6ffe-779e-8a74-bab97eda4eb9', 'b1y', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef is_palindrome_stack(head):\n    stack = []\n    curr = head\n    while curr:\n        stack.append(curr.data)\n        curr = curr.next\n    curr = head\n    while curr:\n        if stack.pop() != curr.data:     # pops come out reversed\n            return False\n        curr = curr.next\n    return True\n\nfor values in ([1, 2, 3, 2, 1], [1, 2, 3, 4]):\n    print(\"Yes\" if is_palindrome_stack(build(values)) else \"No\")","filename":"Python"}'),
  ('c94eddbc-13c3-775e-b2fd-6801829c8752', 'b1z', 'code', '{"language":"text","code":"Yes\nNo","filename":"Output"}'),
  ('be8c6b55-59b2-7c0f-896a-aab32aca0b7c', 'b20', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Efficient — reverse the second half in place.","marks":[{"type":"bold"}]},{"type":"text","text":" Find the end of the first half with slow/fast, reverse the second half, and walk the two halves together comparing values. Then reverse the second half again to restore the list — callers do not expect a read-only query to scramble their data."}]}]}}'),
  ('05acfc4a-94a8-7340-b362-de21c2c258e3', 'b21', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A palindrome reads the same backwards. Reversing just the second half turns “compare position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" with position "},{"type":"text","text":"n − 1 − i","marks":[{"type":"code"}]},{"type":"text","text":"” into a plain forward walk over two lists of (almost) equal length — no index arithmetic, no extra memory."}]}]}}'),
  ('82d6815a-adcf-7021-8f78-26978660c1f8', 'b22', 'code', '{"language":"text","code":"1 → 2 → 3 → 2 → 1          slow stops at 3 (end of first half); second half = 2 → 1\n\nreverse second half:       1 → 2 → 3 → 1 → 2\n                           ↑           ↑\n                           a           b      compare a, b while b exists: 1=1, 2=2 → Yes\nrestore:                   1 → 2 → 3 → 2 → 1","filename":"Odd length: the middle node belongs to the first half and is never compared"}'),
  ('ba33b81f-e937-742b-855f-af4a6f5c5a79', 'b23', 'code', '{"language":"python","code":"class Node:\n    def __init__(self, data):\n        self.data = data\n        self.next = None\n\ndef build(values):\n    head = None\n    for v in reversed(values):\n        node = Node(v)\n        node.next = head\n        head = node\n    return head\n\ndef to_str(head):\n    parts = []\n    while head:\n        parts.append(str(head.data))\n        head = head.next\n    return \" \".join(parts)\n\ndef reverse(head):\n    prev = None\n    while head:\n        nxt = head.next\n        head.next = prev\n        prev = head\n        head = nxt\n    return prev\n\ndef is_palindrome(head):\n    if head is None or head.next is None:\n        return True\n    slow = fast = head\n    while fast.next and fast.next.next:  # slow stops at the end of the first half\n        slow = slow.next\n        fast = fast.next.next\n    second = reverse(slow.next)          # reverse the second half\n    a, b = head, second\n    same = True\n    while b:                             # second half is never longer than the first\n        if a.data != b.data:\n            same = False\n            break\n        a = a.next\n        b = b.next\n    slow.next = reverse(second)          # restore the list\n    return same\n\nfor values in ([1, 2, 3, 2, 1], [1, 2, 3, 4], [1, 2, 2, 1]):\n    head = build(values)\n    print(to_str(head), \"→\", \"Yes\" if is_palindrome(head) else \"No\")\nhead = build([1, 2, 3, 2, 1])\nis_palindrome(head)\nprint(\"list after the check:\", to_str(head))","filename":"Python"}'),
  ('89273f65-f298-7748-97fc-068f972c91df', 'b24', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nstruct Node {\n    int data; Node* next;\n    Node(int d) : data(d), next(nullptr) {}\n};\n\nNode* build(const vector<int>& v) {\n    Node* head = nullptr;\n    for (int i = (int)v.size() - 1; i >= 0; i--) {\n        Node* node = new Node(v[i]);\n        node->next = head;\n        head = node;\n    }\n    return head;\n}\n\nstring toStr(Node* head) {\n    string s;\n    for (Node* c = head; c; c = c->next) s += to_string(c->data) + (c->next ? \" \" : \"\");\n    return s;\n}\n\nNode* reverse(Node* head) {\n    Node* prev = nullptr;\n    while (head) {\n        Node* next = head->next;\n        head->next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nbool isPalindrome(Node* head) {\n    if (!head || !head->next) return true;\n    Node* slow = head;\n    Node* fast = head;\n    while (fast->next && fast->next->next) {   // slow stops at the end of the first half\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    Node* second = reverse(slow->next);        // reverse the second half\n    bool same = true;\n    for (Node *a = head, *b = second; b; a = a->next, b = b->next)   // second half is never longer\n        if (a->data != b->data) { same = false; break; }\n    slow->next = reverse(second);              // restore the list\n    return same;\n}\n\nint main() {\n    for (vector<int> values : {vector<int>{1, 2, 3, 2, 1}, vector<int>{1, 2, 3, 4}, vector<int>{1, 2, 2, 1}}) {\n        Node* head = build(values);\n        cout << toStr(head) << \" → \" << (isPalindrome(head) ? \"Yes\" : \"No\") << \"\\n\";\n    }\n    Node* head = build({1, 2, 3, 2, 1});\n    isPalindrome(head);\n    cout << \"list after the check: \" << toStr(head) << \"\\n\";\n}","filename":"C++"}'),
  ('627c6bbf-ef51-7a9b-9506-804983745aae', 'b25', 'code', '{"language":"java","code":"public class Main {\n    static class Node {\n        int data; Node next;\n        Node(int d) { data = d; }\n    }\n\n    static Node build(int[] v) {\n        Node head = null;\n        for (int i = v.length - 1; i >= 0; i--) {\n            Node node = new Node(v[i]);\n            node.next = head;\n            head = node;\n        }\n        return head;\n    }\n\n    static String toStr(Node head) {\n        StringBuilder sb = new StringBuilder();\n        for (Node c = head; c != null; c = c.next) sb.append(c.data).append(c.next != null ? \" \" : \"\");\n        return sb.toString();\n    }\n\n    static Node reverse(Node head) {\n        Node prev = null;\n        while (head != null) {\n            Node next = head.next;\n            head.next = prev;\n            prev = head;\n            head = next;\n        }\n        return prev;\n    }\n\n    static boolean isPalindrome(Node head) {\n        if (head == null || head.next == null) return true;\n        Node slow = head, fast = head;\n        while (fast.next != null && fast.next.next != null) {   // slow stops at the end of the first half\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        Node second = reverse(slow.next);        // reverse the second half\n        boolean same = true;\n        for (Node a = head, b = second; b != null; a = a.next, b = b.next)   // second half is never longer\n            if (a.data != b.data) { same = false; break; }\n        slow.next = reverse(second);             // restore the list\n        return same;\n    }\n\n    public static void main(String[] args) {\n        for (int[] values : new int[][]{{1, 2, 3, 2, 1}, {1, 2, 3, 4}, {1, 2, 2, 1}}) {\n            Node head = build(values);\n            System.out.println(toStr(head) + \" → \" + (isPalindrome(head) ? \"Yes\" : \"No\"));\n        }\n        Node head = build(new int[]{1, 2, 3, 2, 1});\n        isPalindrome(head);\n        System.out.println(\"list after the check: \" + toStr(head));\n    }\n}","filename":"Java"}'),
  ('2da9e85e-b68c-79b3-8608-4cfbd1d9c469', 'b26', 'code', '{"language":"javascript","code":"class Node {\n    constructor(data) { this.data = data; this.next = null; }\n}\n\nfunction build(values) {\n    let head = null;\n    for (let i = values.length - 1; i >= 0; i--) {\n        const node = new Node(values[i]);\n        node.next = head;\n        head = node;\n    }\n    return head;\n}\n\nfunction toStr(head) {\n    const parts = [];\n    for (let c = head; c; c = c.next) parts.push(c.data);\n    return parts.join(\" \");\n}\n\nfunction reverse(head) {\n    let prev = null;\n    while (head) {\n        const next = head.next;\n        head.next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nfunction isPalindrome(head) {\n    if (!head || !head.next) return true;\n    let slow = head, fast = head;\n    while (fast.next && fast.next.next) {    // slow stops at the end of the first half\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    const second = reverse(slow.next);       // reverse the second half\n    let same = true;\n    for (let a = head, b = second; b; a = a.next, b = b.next)   // second half is never longer\n        if (a.data !== b.data) { same = false; break; }\n    slow.next = reverse(second);             // restore the list\n    return same;\n}\n\nfor (const values of [[1, 2, 3, 2, 1], [1, 2, 3, 4], [1, 2, 2, 1]]) {\n    const head = build(values);\n    console.log(toStr(head), \"→\", isPalindrome(head) ? \"Yes\" : \"No\");\n}\nconst head = build([1, 2, 3, 2, 1]);\nisPalindrome(head);\nconsole.log(\"list after the check:\", toStr(head));","filename":"JavaScript"}'),
  ('f546e9d8-92b1-7467-bb61-53a3077bc9fb', 'b27', 'code', '{"language":"text","code":"1 2 3 2 1 → Yes\n1 2 3 4 → No\n1 2 2 1 → Yes\nlist after the check: 1 2 3 2 1","filename":"Output"}'),
  ('653af30c-4337-7340-80db-f045684faafc', 'b28', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('9bbd3200-dfb1-74ba-97e5-4ae3c1582620', 'b29', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use the "},{"type":"text","text":"fast.next and fast.next.next","marks":[{"type":"code"}]},{"type":"text","text":" loop condition so that "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" lands on the "},{"type":"text","text":"end of the first half","marks":[{"type":"bold"}]},{"type":"text","text":" (the middle node for odd length). With the plain "},{"type":"text","text":"fast and fast.next","marks":[{"type":"code"}]},{"type":"text","text":" condition from the middle-finding problem, "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":" would be one node too far and the halves misaligned. Returning early on a mismatch without restoring the list is the other classic slip — the version above breaks out, restores, then returns."}]}]}}'),
  ('fbf0ef42-d9ae-784b-822b-33fbcf41c5fa', 'b2A', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('90f7eb98-d72f-750f-91ff-3ee91aaa7c82', 'b2B', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does Floyd''s algorithm use speeds 1 and 2 — would 1 and 3 work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any two different speeds work for "},{"type":"text","text":"detection","marks":[{"type":"italic"}]},{"type":"text","text":": once both pointers are in a loop of length "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":", the gap changes by a constant each step and eventually hits a multiple of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":". Speeds 1 and 2 are chosen because the gap shrinks by exactly one per step (guaranteeing a meeting within "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" steps of entering the loop) and because the "},{"type":"text","text":"m + k = multiple of n","marks":[{"type":"code"}]},{"type":"text","text":" identity makes finding the loop "},{"type":"text","text":"start","marks":[{"type":"italic"}]},{"type":"text","text":" a one-liner. With speed 3 the second phase no longer works unchanged."}]}]}}'),
  ('fe140ab5-0977-72f3-b5e1-7b52174e823f', 'b2C', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the start of the loop after detecting it, and why does it work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep one pointer at the meeting point and move the other back to the head; advance both one step at a time — they meet at the loop''s first node. Proof: with "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" = head-to-loop-start, "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" = loop-start-to-meeting-point and "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" = loop length, "},{"type":"text","text":"fast","marks":[{"type":"code"}]},{"type":"text","text":" has travelled twice as far as "},{"type":"text","text":"slow","marks":[{"type":"code"}]},{"type":"text","text":", which gives "},{"type":"text","text":"m + k = (y − 2x)·n","marks":[{"type":"code"}]},{"type":"text","text":", a multiple of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":". So after "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" steps the pointer from the meeting point has gone "},{"type":"text","text":"m + k ≡ 0 (mod n)","marks":[{"type":"code"}]},{"type":"text","text":" into the loop — it is at the loop start, exactly where the pointer from the head has also arrived."}]}]}}'),
  ('2142bf98-5a10-7370-afd7-f77d45b2d3ca', 'b2D', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you detect a loop or find an intersection without Floyd''s algorithm?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash the node references: a set of visited nodes finds a loop (first repeat) or an intersection (first node of "},{"type":"text","text":"B","marks":[{"type":"code"}]},{"type":"text","text":" already seen while walking "},{"type":"text","text":"A","marks":[{"type":"code"}]},{"type":"text","text":") in "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time and "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" space. It is the baseline — mention it first, then improve to "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" space with slow/fast pointers or length alignment."}]}]}}'),
  ('0eb256c7-80ce-7bee-86f0-aa4719b1ac7f', 'b2E', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse a linked list in O(1) space — iterative or recursive?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterative: three pointers ("},{"type":"text","text":"prev","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":") in one pass, "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" extra space. The recursive version is shorter to write but uses "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" stack — one frame per node — and overflows on long lists. Interviewers usually want the iterative version and then ask for the recursive one as a follow-up (or vice versa)."}]}]}}'),
  ('1a87d044-50e6-731f-9587-fd9ed5945843', 'b2F', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the dummy-head trick and when do you use it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Create a throwaway node whose "},{"type":"text","text":"next","marks":[{"type":"code"}]},{"type":"text","text":" is the real head, and work from it. Every operation that might change the head (insert at front, delete the first node, merge, pairwise swap) then has no special case — the first real node is just “the node after dummy”. Return "},{"type":"text","text":"dummy.next","marks":[{"type":"code"}]},{"type":"text","text":" at the end. It costs one allocation and saves a branch and a bug."}]}]}}'),
  ('453635b4-20f4-70eb-bcb7-71e9b299ace0', 'b2G', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clone a list with random pointers in O(1) extra space — how?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Interleave: insert each node''s copy right after it ("},{"type":"text","text":"1 → 1'' → 2 → 2'' …","marks":[{"type":"code"}]},{"type":"text","text":"), so the copy of any node "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"x.next","marks":[{"type":"code"}]},{"type":"text","text":". Set "},{"type":"text","text":"x.next.random = x.random.next","marks":[{"type":"code"}]},{"type":"text","text":" for every original, then unweave the two lists in one more pass. Three passes, "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" time, no map. The hash-map version is the simpler "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"-space baseline."}]}]}}'),
  ('e38fe7b1-2afd-766b-8502-af14c1dd51ca', 'b2H', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which sorting algorithm fits a linked list best, and why not quicksort?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Merge sort: split with slow/fast pointers, merge by re-linking nodes — "},{"type":"text","text":"O(n log n)","marks":[{"type":"code"}]},{"type":"text","text":" with no random access and no extra array. Quicksort and heapsort need "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" index access to partition or sift; on a list every "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" becomes an "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" walk."}]}]}}')
