        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++)
                mat[i][j] = i * cols + j + 1;        // row-major numbering
        for (int[] row : mat) {
            StringBuilder sb = new StringBuilder();
            for (int x : row) sb.append(x).append('' '');
            System.out.println(sb.toString().trim());
        }
    }
}
