FROM (VALUES
  ('e880d40a-c701-7a8a-a37a-c519d2067bbc', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A queue is "},{"type":"text","text":"First In, First Out","marks":[{"type":"bold"}]},{"type":"text","text":"; a deque ("},{"type":"text","text":"double-ended queue","marks":[{"type":"italic"}]},{"type":"text","text":") lets you insert and remove at "},{"type":"text","text":"both","marks":[{"type":"bold"}]},{"type":"text","text":" ends in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":". The advanced problems here use the queue for breadth-first generation and the deque as a "},{"type":"text","text":"sliding window","marks":[{"type":"italic"}]},{"type":"text","text":" that keeps only the candidates that can still matter."}]}]}}'),
  ('65b1e7ac-88ae-7baf-84b0-770938a67ad4', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deque","marks":[{"type":"bold"}]},{"type":"text","text":" — a linear container with "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"pushFront","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"pushBack","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"popFront","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"popBack","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"front","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"back","marks":[{"type":"code"}]},{"type":"text","text":". Restricting it to "},{"type":"text","text":"pushBack","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"popFront","marks":[{"type":"code"}]},{"type":"text","text":" gives a queue; "},{"type":"text","text":"pushBack","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"popBack","marks":[{"type":"code"}]},{"type":"text","text":" gives a stack — one structure covers both."}]}]}}'),
  ('13bae9cd-8a5d-7ced-ba2b-7f8552c7afeb', 'a2', 'code', '{"language":"text","code":"pushFront(x) ──▶ ┌────┬────┬────┬────┬────┐ ◀── pushBack(x)\npopFront()   ◀── │ 20 │ 10 │ 15 │ 30 │ 7  │ ──▶ popBack()\n                 └────┴────┴────┴────┴────┘\n                  front                back","filename":"A deque: both ends are open"}'),
  ('325db45d-0af6-7fae-a23a-53691bb136c4', 'a3', 'heading', '{"level":1,"content":[{"type":"text","text":"Operations and the built-in containers"}]}'),
  ('7aa8d056-62a1-7d45-9e5c-ead51d5d7c51', 'a4', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Python "},{"type":"text","text":"collections.deque","marks":[{"type":"code"}]}],[{"type":"text","text":"C++ "},{"type":"text","text":"std::deque","marks":[{"type":"code"}]}],[{"type":"text","text":"Java "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]}],[{"type":"text","text":"JavaScript"}]],[[{"type":"text","text":"push back"}],[{"type":"text","text":"append(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"push_back(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"addLast(x)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"offer(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"arr.push(x)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"push front"}],[{"type":"text","text":"appendleft(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"push_front(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"addFirst(x)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"push(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"arr.unshift(x)","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"O(n)","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"pop front"}],[{"type":"text","text":"popleft()","marks":[{"type":"code"}]}],[{"type":"text","text":"pop_front()","marks":[{"type":"code"}]},{"type":"text","text":" (+ "},{"type":"text","text":"front()","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"pollFirst()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"poll()","marks":[{"type":"code"}]}],[{"type":"text","text":"arr.shift()","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"O(n)","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"pop back"}],[{"type":"text","text":"pop()","marks":[{"type":"code"}]}],[{"type":"text","text":"pop_back()","marks":[{"type":"code"}]},{"type":"text","text":" (+ "},{"type":"text","text":"back()","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"pollLast()","marks":[{"type":"code"}]}],[{"type":"text","text":"arr.pop()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"peek front / back"}],[{"type":"text","text":"dq[0]","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"dq[-1]","marks":[{"type":"code"}]}],[{"type":"text","text":"front()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"back()","marks":[{"type":"code"}]}],[{"type":"text","text":"peekFirst()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"peekLast()","marks":[{"type":"code"}]}],[{"type":"text","text":"arr[0]","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"arr[arr.length-1]","marks":[{"type":"code"}]}]]]}'),
  ('0bde5e1a-6798-7495-8d21-193d7f836043', 'a5', 'callout', '{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript has no built-in deque. "},{"type":"text","text":"shift()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"unshift()","marks":[{"type":"code"}]},{"type":"text","text":" move every element, so a queue built on them is "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" per operation. For small inputs it does not matter (the first two problems below use it for brevity); for real workloads keep a "},{"type":"text","text":"head index","marks":[{"type":"bold"}]},{"type":"text","text":" into the array ("},{"type":"text","text":"arr[head++]","marks":[{"type":"code"}]},{"type":"text","text":" to dequeue — see the sliding-window solution) or write a small ring-buffer / two-index "},{"type":"text","text":"Deque","marks":[{"type":"code"}]},{"type":"text","text":" class (see the min/max structure)."}]}]}}'),
  ('a2615d66-69a9-78de-9f53-a7869ca819b4', 'a6', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Python''s "},{"type":"text","text":"deque","marks":[{"type":"code"}]},{"type":"text","text":", C++''s "},{"type":"text","text":"std::deque","marks":[{"type":"code"}]},{"type":"text","text":" and Java''s "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" are all "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" at both ends. "},{"type":"text","text":"std::queue","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"std::stack","marks":[{"type":"code"}]},{"type":"text","text":" are thin adapters over "},{"type":"text","text":"std::deque","marks":[{"type":"code"}]},{"type":"text","text":"; Java''s "},{"type":"text","text":"Queue","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Deque","marks":[{"type":"code"}]},{"type":"text","text":" interfaces are both implemented by "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" (prefer it over "},{"type":"text","text":"LinkedList","marks":[{"type":"code"}]},{"type":"text","text":", which allocates a node per element)."}]}]}}'),
  ('befc85b9-9c3e-765b-9847-bd5735fd9391', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Reverse a queue"}]}'),
  ('f3cbd489-cb1a-7071-9430-df70adc3950e', 'a8', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"q = [20, 10, 15, 30] (20 at the front)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"30 15 10 20","marks":[{"type":"code"}]}]}]}}'),
  ('76892db4-6943-7462-a756-a7ef1e54e64b', 'a9', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A stack reverses order. Dequeue everything into a stack, then pop everything back into the queue: the last element out of the queue is the first one pushed back. Only queue operations ("},{"type":"text","text":"enqueue","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dequeue","marks":[{"type":"code"}]},{"type":"text","text":") and a stack are used — the queue is treated as a black box."}]}]}}'),
  ('42e38dba-c8b6-7f1b-a32d-d7412285f1dd', 'aA', 'code', '{"language":"python","code":"from collections import deque\n\ndef reverse_queue(q):\n    st = []\n    while q:\n        st.append(q.popleft())     # drain the queue into a stack\n    while st:\n        q.append(st.pop())         # refill: last out of the queue goes in first\n\nq = deque([20, 10, 15, 30])\nreverse_queue(q)\nprint(*q)","filename":"Python"}'),
  ('27d54f99-6f13-7499-aad4-3fcc7253b4e7', 'aB', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <queue>\n#include <stack>\nusing namespace std;\n\nvoid reverseQueue(queue<int>& q) {\n    stack<int> st;\n    while (!q.empty()) { st.push(q.front()); q.pop(); }   // drain the queue into a stack\n    while (!st.empty()) { q.push(st.top()); st.pop(); }   // refill: last out goes in first\n}\n\nint main() {\n    queue<int> q;\n    for (int x : {20, 10, 15, 30}) q.push(x);\n    reverseQueue(q);\n    while (!q.empty()) { cout << q.front() << \" \"; q.pop(); }\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('6c46506f-842e-7261-9a7d-36f6fa6563a3', 'aC', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\nimport java.util.Queue;\n\npublic class Main {\n    static void reverseQueue(Queue<Integer> q) {\n        Deque<Integer> st = new ArrayDeque<>();\n        while (!q.isEmpty()) st.push(q.poll());   // drain the queue into a stack\n        while (!st.isEmpty()) q.add(st.pop());    // refill: last out goes in first\n    }\n\n    public static void main(String[] args) {\n        Queue<Integer> q = new ArrayDeque<>();\n        for (int x : new int[]{20, 10, 15, 30}) q.add(x);\n        reverseQueue(q);\n        StringBuilder sb = new StringBuilder();\n        while (!q.isEmpty()) sb.append(q.poll()).append('' '');\n        System.out.println(sb.toString().trim());\n    }\n}","filename":"Java"}'),
  ('9ccf3b35-6afc-78e6-bde7-43d129edbb95', 'aD', 'code', '{"language":"javascript","code":"function reverseQueue(q) {\n    const st = [];\n    while (q.length) st.push(q.shift());     // drain the queue into a stack (shift is O(n) in JS)\n    while (st.length) q.push(st.pop());      // refill: last out goes in first\n}\n\nconst q = [20, 10, 15, 30];\nreverseQueue(q);\nconsole.log(q.join(\" \"));","filename":"JavaScript"}'),
  ('f15c3ebd-d2f3-7540-8d2b-d4e60654638a', 'aE', 'code', '{"language":"text","code":"30 15 10 20","filename":"Output"}'),
  ('1ef25bb7-da64-76a1-b9c7-2d2f36ab6914', 'aF', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n) for the stack"}]},{"type":"paragraph","content":[{"type":"text","text":"Recursive version.","marks":[{"type":"bold"}]},{"type":"text","text":" The call stack "},{"type":"text","text":"is","marks":[{"type":"italic"}]},{"type":"text","text":" the stack: dequeue the front, reverse the rest recursively, then enqueue the front at the back. The deepest call enqueues the last element first."}]}]}}'),
  ('2984579b-e5ce-793d-8287-61f6d229ccc2', 'aG', 'code', '{"language":"python","code":"from collections import deque\n\ndef reverse_queue(q):\n    if not q:\n        return\n    front = q.popleft()      # take the front out …\n    reverse_queue(q)         # … reverse the remaining n-1 …\n    q.append(front)          # … and put the old front at the back\n\nq = deque([20, 10, 15, 30])\nreverse_queue(q)\nprint(*q)","filename":"Python"}'),
  ('37e591c7-e0ec-7597-96c8-739f5ff331c4', 'aH', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <queue>\nusing namespace std;\n\nvoid reverseQueue(queue<int>& q) {\n    if (q.empty()) return;\n    int front = q.front(); q.pop();   // take the front out …\n    reverseQueue(q);                  // … reverse the remaining n-1 …\n    q.push(front);                    // … and put the old front at the back\n}\n\nint main() {\n    queue<int> q;\n    for (int x : {20, 10, 15, 30}) q.push(x);\n    reverseQueue(q);\n    while (!q.empty()) { cout << q.front() << \" \"; q.pop(); }\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('e075e6fd-c53a-78ea-b239-0e6c5b88cdc3', 'aI', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Queue;\n\npublic class Main {\n    static void reverseQueue(Queue<Integer> q) {\n        if (q.isEmpty()) return;\n        int front = q.poll();   // take the front out …\n        reverseQueue(q);        // … reverse the remaining n-1 …\n        q.add(front);           // … and put the old front at the back\n    }\n\n    public static void main(String[] args) {\n        Queue<Integer> q = new ArrayDeque<>();\n        for (int x : new int[]{20, 10, 15, 30}) q.add(x);\n        reverseQueue(q);\n        StringBuilder sb = new StringBuilder();\n        while (!q.isEmpty()) sb.append(q.poll()).append('' '');\n        System.out.println(sb.toString().trim());\n    }\n}","filename":"Java"}'),
  ('eb6a1a73-a11a-7315-b78c-618b516ee71b', 'aJ', 'code', '{"language":"javascript","code":"function reverseQueue(q) {\n    if (q.length === 0) return;\n    const front = q.shift();   // take the front out …\n    reverseQueue(q);           // … reverse the remaining n-1 …\n    q.push(front);             // … and put the old front at the back\n}\n\nconst q = [20, 10, 15, 30];\nreverseQueue(q);\nconsole.log(q.join(\" \"));","filename":"JavaScript"}'),
  ('1425d9da-860b-7948-afa6-703f0827fed3', 'aK', 'code', '{"language":"text","code":"30 15 10 20","filename":"Output"}'),
  ('d93ccddb-881b-7e53-ab5d-f37696abeda0', 'aL', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n) call stack"}]}]}}'),
  ('1a7d3418-895e-7fe3-9183-93a171af15a8', 'aM', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The recursive version uses "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" stack frames — Python''s default limit is about 1000, so it is a teaching tool, not a production routine. The iterative version has the same complexity without the depth limit."}]}]}}'),
  ('2dd905da-46d2-7990-bae2-b04f0ccbff7e', 'aN', 'heading', '{"level":1,"content":[{"type":"text","text":"Generate the first n numbers with given digits"}]}'),
  ('68f7767e-8c30-712d-839d-3af3e9703ef9', 'aO', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 10, digits = [5, 6]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5 6 55 56 65 66 555 556 565 566","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 7, digits = [1, 2, 3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1 2 3 11 12 13 21","marks":[{"type":"code"}]}]}]}}'),
  ('e5e9fb22-ac4c-7077-aa02-fb3c4014cca0', 'aP', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Print, in increasing order, the first "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" positive integers whose decimal digits all come from the given set."}]}]}}'),
  ('e0c978a1-5001-7add-a012-d689c5f8055b', 'aQ', 'code', '{"language":"python","code":"def only_digits(num, digits):\n    while num > 0:\n        if num % 10 not in digits:\n            return False\n        num //= 10\n    return True\n\ndef first_n_naive(n, digits):\n    res, num = [], 1\n    while len(res) < n:                 # try 1, 2, 3, … and keep the ones that qualify\n        if only_digits(num, digits):\n            res.append(num)\n        num += 1\n    return res\n\nprint(*first_n_naive(10, [5, 6]))","filename":"Naive — test every natural number; with digits {5, 6} only 2^k of the k-digit numbers qualify, so this gets slow fast"}'),
  ('ded834b5-2b21-76f3-8463-b8253830b87e', 'aR', 'code', '{"language":"text","code":"5 6 55 56 65 66 555 556 565 566","filename":"Output"}'),
  ('c5109302-9420-70be-85aa-c71562a7b8b7', 'aS', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The valid numbers form a "},{"type":"text","text":"tree","marks":[{"type":"bold"}]},{"type":"text","text":": the children of "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" are "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" with each allowed digit appended. A breadth-first traversal of that tree visits the numbers "},{"type":"text","text":"in increasing order","marks":[{"type":"italic"}]},{"type":"text","text":" — all 1-digit numbers, then all 2-digit numbers (smaller prefixes first), and so on. BFS is a queue: start with the single digits, repeatedly dequeue a number, print it, and enqueue its children. Each dequeue produces exactly one answer, so the loop runs "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" times."}]}]}}'),
  ('d4642341-356e-7af6-a0ae-b75e2639a376', 'aT', 'code', '{"language":"text","code":"           (root)\n        /          \\\n       5            6                 ← dequeued 1st, 2nd\n     /   \\        /   \\\n   55     56    65     66             ← 3rd … 6th\n  /  \\   /  \\\n555 556 565 566 …                     ← 7th … 10th","filename":"BFS order of the digit tree is numeric order, because every level is one digit longer and siblings are enqueued smallest-first"}'),
  ('1444e011-4ff1-76f1-92bb-d4401aa9b6db', 'aU', 'code', '{"language":"python","code":"from collections import deque\n\ndef first_n(n, digits):\n    q = deque(str(d) for d in sorted(digits))   # level 1: the single digits, smallest first\n    res = []\n    while len(res) < n:\n        cur = q.popleft()\n        res.append(cur)\n        for d in sorted(digits):\n            q.append(cur + str(d))              # children: one digit longer\n    return res\n\nprint(*first_n(10, [5, 6]))\nprint(*first_n(7, [1, 2, 3]))","filename":"Python"}'),
  ('5bcea129-0251-70a9-a013-57e27dbdee4c', 'aV', 'code', '{"language":"cpp","code":"#include <algorithm>\n#include <iostream>\n#include <queue>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvector<string> firstN(int n, vector<int> digits) {\n    sort(digits.begin(), digits.end());\n    queue<string> q;\n    for (int d : digits) q.push(to_string(d));     // level 1: the single digits, smallest first\n    vector<string> res;\n    while ((int)res.size() < n) {\n        string cur = q.front(); q.pop();\n        res.push_back(cur);\n        for (int d : digits) q.push(cur + to_string(d));   // children: one digit longer\n    }\n    return res;\n}\n\nint main() {\n    for (const string& s : firstN(10, {5, 6})) cout << s << \" \";\n    cout << \"\\n\";\n    for (const string& s : firstN(7, {1, 2, 3})) cout << s << \" \";\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('ae4b9675-7c21-7d8e-866e-5cf008883d5a', 'aW', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.ArrayList;\nimport java.util.Arrays;\nimport java.util.List;\nimport java.util.Queue;\n\npublic class Main {\n    static List<String> firstN(int n, int[] digits) {\n        Arrays.sort(digits);\n        Queue<String> q = new ArrayDeque<>();\n        for (int d : digits) q.add(String.valueOf(d));   // level 1: the single digits, smallest first\n        List<String> res = new ArrayList<>();\n        while (res.size() < n) {\n            String cur = q.poll();\n            res.add(cur);\n            for (int d : digits) q.add(cur + d);          // children: one digit longer\n        }\n        return res;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(String.join(\" \", firstN(10, new int[]{5, 6})));\n        System.out.println(String.join(\" \", firstN(7, new int[]{1, 2, 3})));\n    }\n}","filename":"Java"}'),
  ('8e805f77-80e9-7ad2-9423-588c37bf3b46', 'aX', 'code', '{"language":"javascript","code":"function firstN(n, digits) {\n    digits = [...digits].sort((a, b) => a - b);\n    const q = digits.map(String);                  // level 1: the single digits, smallest first\n    const res = [];\n    while (res.length < n) {\n        const cur = q.shift();\n        res.push(cur);\n        for (const d of digits) q.push(cur + d);   // children: one digit longer\n    }\n    return res;\n}\n\nconsole.log(firstN(10, [5, 6]).join(\" \"));\nconsole.log(firstN(7, [1, 2, 3]).join(\" \"));","filename":"JavaScript"}'),
  ('b4a6c184-2ac0-72bd-8b84-2546ae357c18', 'aY', 'code', '{"language":"text","code":"5 6 55 56 65 66 555 556 565 566\n1 2 3 11 12 13 21","filename":"Output"}'),
  ('1c497429-29a9-70d9-a32c-8db275dad511', 'aZ', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n × k) for k allowed digits · Space O(n × k) queue"}]}]}}'),
  ('72e0ed9f-4b72-728a-a08d-f4ef39f19818', 'aa', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Work with "},{"type":"text","text":"strings","marks":[{"type":"bold"}]},{"type":"text","text":", not integers: appending a digit is string concatenation, and the numbers quickly exceed 64 bits (the 20th number with digits {5, 6} already has 5 digits; the 10 000th has 13). The original notes hard-coded "},{"type":"text","text":"''5''","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"''6''","marks":[{"type":"code"}]},{"type":"text","text":"; the version above takes any digit set and sorts it so BFS order is numeric order."}]}]}}'),
  ('991fa94b-3aa5-7a76-bdea-bc5b31fdec37', 'ab', 'heading', '{"level":1,"content":[{"type":"text","text":"Data structure with min/max operations"}]}'),
  ('08411d58-540e-702e-a9ec-52d4bfdf85ad', 'ac', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Design a structure supporting all of the following in "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"insertMin(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"insertMax(x)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"getMin()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"getMax()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"extractMin()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"extractMax()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('6295f0b8-760c-76d6-9a68-eb9a0acf0b5b', 'ad', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"insertMin(5), insertMax(10), insertMin(3), insertMax(12); getMin, getMax, extractMin, getMin, extractMax, getMax","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3 12 3 5 12 10","marks":[{"type":"code"}]}]}]}}'),
  ('0cd74966-6ca1-7121-82a9-ce28e0e05549', 'ae', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"insertMin(x)","marks":[{"type":"code"}]},{"type":"text","text":" is only ever called with a value that "},{"type":"text","text":"is","marks":[{"type":"bold"}]},{"type":"text","text":" the new minimum, and "},{"type":"text","text":"insertMax(x)","marks":[{"type":"code"}]},{"type":"text","text":" only with the new maximum — that contract is what makes "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" possible (a general priority queue needs "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":"). So keep the elements "},{"type":"text","text":"sorted in a deque","marks":[{"type":"bold"}]},{"type":"text","text":": the minimum lives at the front, the maximum at the back. "},{"type":"text","text":"insertMin","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"pushFront","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"insertMax","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"pushBack","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"getMin","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"getMax","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"front","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"back","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"extractMin","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"extractMax","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"popFront","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"popBack","marks":[{"type":"code"}]},{"type":"text","text":". Every operation is one deque operation."}]}]}}'),
  ('59a7fdc8-33cc-70b2-bead-23a937f71f5f', 'af', 'code', '{"language":"text","code":"insertMin(5)      [5]\ninsertMax(10)     [5, 10]\ninsertMin(3)      [3, 5, 10]          ← front is always the min\ninsertMax(12)     [3, 5, 10, 12]      ← back is always the max\nextractMin() → 3  [5, 10, 12]\nextractMax() → 12 [5, 10]","filename":"The deque stays sorted because insertMin/insertMax only ever add at the correct end"}'),
  ('1c93034f-8ae9-7df0-8d36-8c1dece36c99', 'ag', 'code', '{"language":"python","code":"from collections import deque\n\nclass MinMaxStructure:\n    def __init__(self):\n        self.dq = deque()            # kept sorted: front = min, back = max\n\n    def insert_min(self, x):         # contract: x <= current min\n        self.dq.appendleft(x)\n\n    def insert_max(self, x):         # contract: x >= current max\n        self.dq.append(x)\n\n    def get_min(self):\n        return self.dq[0]\n\n    def get_max(self):\n        return self.dq[-1]\n\n    def extract_min(self):\n        return self.dq.popleft()\n\n    def extract_max(self):\n        return self.dq.pop()\n\ns = MinMaxStructure()\ns.insert_min(5)\ns.insert_max(10)\ns.insert_min(3)\ns.insert_max(12)\nprint(\"getMin:\", s.get_min())\nprint(\"getMax:\", s.get_max())\nprint(\"extractMin:\", s.extract_min())\nprint(\"getMin:\", s.get_min())\nprint(\"extractMax:\", s.extract_max())\nprint(\"getMax:\", s.get_max())","filename":"Python"}'),
  ('924f5205-9644-7ec7-90f3-bdaf12aaf34f', 'ah', 'code', '{"language":"cpp","code":"#include <deque>\n#include <iostream>\nusing namespace std;\n\nclass MinMaxStructure {\n    deque<int> dq;                   // kept sorted: front = min, back = max\npublic:\n    void insertMin(int x) { dq.push_front(x); }   // contract: x <= current min\n    void insertMax(int x) { dq.push_back(x); }    // contract: x >= current max\n    int getMin() const { return dq.front(); }\n    int getMax() const { return dq.back(); }\n    int extractMin() { int x = dq.front(); dq.pop_front(); return x; }\n    int extractMax() { int x = dq.back(); dq.pop_back(); return x; }\n};\n\nint main() {\n    MinMaxStructure s;\n    s.insertMin(5);\n    s.insertMax(10);\n    s.insertMin(3);\n    s.insertMax(12);\n    cout << \"getMin: \" << s.getMin() << \"\\n\";\n    cout << \"getMax: \" << s.getMax() << \"\\n\";\n    cout << \"extractMin: \" << s.extractMin() << \"\\n\";\n    cout << \"getMin: \" << s.getMin() << \"\\n\";\n    cout << \"extractMax: \" << s.extractMax() << \"\\n\";\n    cout << \"getMax: \" << s.getMax() << \"\\n\";\n}","filename":"C++"}'),
  ('197c2b47-547b-7c9f-a0e9-2267571f8cdc', 'ai', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Main {\n    static class MinMaxStructure {\n        Deque<Integer> dq = new ArrayDeque<>();     // kept sorted: front = min, back = max\n        void insertMin(int x) { dq.addFirst(x); }   // contract: x <= current min\n        void insertMax(int x) { dq.addLast(x); }    // contract: x >= current max\n        int getMin() { return dq.peekFirst(); }\n        int getMax() { return dq.peekLast(); }\n        int extractMin() { return dq.pollFirst(); }\n        int extractMax() { return dq.pollLast(); }\n    }\n\n    public static void main(String[] args) {\n        MinMaxStructure s = new MinMaxStructure();\n        s.insertMin(5);\n        s.insertMax(10);\n        s.insertMin(3);\n        s.insertMax(12);\n        System.out.println(\"getMin: \" + s.getMin());\n        System.out.println(\"getMax: \" + s.getMax());\n        System.out.println(\"extractMin: \" + s.extractMin());\n        System.out.println(\"getMin: \" + s.getMin());\n        System.out.println(\"extractMax: \" + s.extractMax());\n        System.out.println(\"getMax: \" + s.getMax());\n    }\n}","filename":"Java"}'),
  ('19ff1662-880a-7a66-8652-f30b902705b1', 'aj', 'code', '{"language":"javascript","code":"class Deque {                        // O(1) at both ends: indices grow outwards from 0\n    constructor() { this.items = {}; this.head = 0; this.tail = 0; }   // tail = one past the last\n    pushFront(x) { this.items[--this.head] = x; }\n    pushBack(x) { this.items[this.tail++] = x; }\n    popFront() { const x = this.items[this.head]; delete this.items[this.head++]; return x; }\n    popBack() { const x = this.items[--this.tail]; delete this.items[this.tail]; return x; }\n    front() { return this.items[this.head]; }\n    back() { return this.items[this.tail - 1]; }\n    get size() { return this.tail - this.head; }\n}\n\nclass MinMaxStructure {\n    constructor() { this.dq = new Deque(); }       // kept sorted: front = min, back = max\n    insertMin(x) { this.dq.pushFront(x); }         // contract: x <= current min\n    insertMax(x) { this.dq.pushBack(x); }          // contract: x >= current max\n    getMin() { return this.dq.front(); }\n    getMax() { return this.dq.back(); }\n    extractMin() { return this.dq.popFront(); }\n    extractMax() { return this.dq.popBack(); }\n}\n\nconst s = new MinMaxStructure();\ns.insertMin(5);\ns.insertMax(10);\ns.insertMin(3);\ns.insertMax(12);\nconsole.log(\"getMin:\", s.getMin());\nconsole.log(\"getMax:\", s.getMax());\nconsole.log(\"extractMin:\", s.extractMin());\nconsole.log(\"getMin:\", s.getMin());\nconsole.log(\"extractMax:\", s.extractMax());\nconsole.log(\"getMax:\", s.getMax());","filename":"JavaScript"}'),
  ('87f82e41-62bd-761a-9163-bb48c64f8e63', 'ak', 'code', '{"language":"text","code":"getMin: 3\ngetMax: 12\nextractMin: 3\ngetMin: 5\nextractMax: 12\ngetMax: 10","filename":"Output"}'),
  ('0d9f03f1-1365-70b3-bbc0-7138a5ba2ac8', 'al', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(1) per operation · Space O(n)"}]}]}}'),
  ('18a57053-0488-7fab-83a3-34fa77c3d97b', 'am', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"State the contract out loud in an interview: this structure is correct "},{"type":"text","text":"only if","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"insertMin","marks":[{"type":"code"}]},{"type":"text","text":" is always given a value no larger than the current minimum and "},{"type":"text","text":"insertMax","marks":[{"type":"code"}]},{"type":"text","text":" a value no smaller than the current maximum (the original notes called it a ''MinMaxStack'' and did not say so). Insert "},{"type":"text","text":"7","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"[3, 5, 10, 12]","marks":[{"type":"code"}]},{"type":"text","text":" through either method and the sorted order — and every later answer — is wrong. For arbitrary inserts you need a min-max heap or two heaps ("},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('c6c9df69-f214-706f-abaf-314de0cea30d', 'an', 'heading', '{"level":1,"content":[{"type":"text","text":"Maximums of all subarrays of size k (sliding window maximum)"}]}'),
  ('24700b85-0095-7e10-b228-8bbe9a1290b6', 'ao', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 8, 5, 12, 15, 7, 6], k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"10 12 15 15 15","marks":[{"type":"code"}]}]}]}}'),
  ('338dface-f869-781b-87ca-8e1f8766e7cf', 'ap', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For every window of "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" consecutive elements, print its maximum. The windows here are "},{"type":"text","text":"[10,8,5]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[8,5,12]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[5,12,15]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[12,15,7]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"[15,7,6]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('fcdef66e-e425-7ca1-b184-0a0a6a5f49d9', 'aq', 'code', '{"language":"python","code":"def window_max_naive(arr, k):\n    res = []\n    for i in range(len(arr) - k + 1):\n        res.append(max(arr[i:i + k]))    # rescan each window\n    return res\n\nprint(*window_max_naive([10, 8, 5, 12, 15, 7, 6], 3))","filename":"Naive — O(n·k): recompute the maximum of every window"}'),
  ('48d6b932-d58b-72f4-bd01-11805ad4cef2', 'ar', 'code', '{"language":"text","code":"10 12 15 15 15","filename":"Output"}'),
  ('16d837f6-f932-73ad-bb07-49a288413923', 'as', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep a deque of "},{"type":"text","text":"indices","marks":[{"type":"bold"}]},{"type":"text","text":" whose values are "},{"type":"text","text":"decreasing","marks":[{"type":"bold"}]},{"type":"text","text":" from front to back — the monotonic-stack idea from the Stack topic, with one extra operation. When "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" arrives, pop from the "},{"type":"text","text":"back","marks":[{"type":"bold"}]},{"type":"text","text":" every index whose value is "},{"type":"text","text":"<= arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" (they can never be a window maximum again: "},{"type":"text","text":"arr[i]","marks":[{"type":"code"}]},{"type":"text","text":" is bigger and will outlive them). Push "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" at the back. Pop from the "},{"type":"text","text":"front","marks":[{"type":"bold"}]},{"type":"text","text":" the index that has slid out of the window ("},{"type":"text","text":"front <= i − k","marks":[{"type":"code"}]},{"type":"text","text":"). The front is now the maximum of the current window. The deque is the set of elements that are still "},{"type":"text","text":"useful","marks":[{"type":"italic"}]},{"type":"text","text":" — each is the maximum of the suffix of the window that starts at it."}]}]}}'),
  ('aef1fc6c-8f5e-7ba8-a7d4-9fa2d652a067', 'at', 'code', '{"language":"text","code":"arr = [10, 8, 5, 12, 15, 7, 6], k = 3        deque holds indices; shown as values\n\ni  arr[i]  pop back while <= arr[i]   push   drop front if out of window   deque (values)   window max\n0   10     –                          0      –                             [10]             (window not full)\n1    8     –                          1      –                             [10, 8]          (window not full)\n2    5     –                          2      –                             [10, 8, 5]       10\n3   12     5, 8, 10                   3      –                             [12]             12\n4   15     12                         4      –                             [15]             15\n5    7     –                          5      –                             [15, 7]          15\n6    6     –                          6      index 4 still inside          [15, 7, 6]       15","filename":"Front of the deque = maximum of the current window; every index enters and leaves at most once"}'),
  ('a6a5d294-5728-70b2-b08d-caec7efd3f37', 'au', 'code', '{"language":"python","code":"from collections import deque\n\ndef window_max(arr, k):\n    dq = deque()                 # indices; arr values decreasing front → back\n    res = []\n    for i in range(len(arr)):\n        while dq and arr[dq[-1]] <= arr[i]:   # smaller-or-equal older elements are useless now\n            dq.pop()\n        dq.append(i)\n        if dq[0] <= i - k:                    # front has slid out of the window\n            dq.popleft()\n        if i >= k - 1:                        # window is full: front is its maximum\n            res.append(arr[dq[0]])\n    return res\n\nprint(*window_max([10, 8, 5, 12, 15, 7, 6], 3))","filename":"Python"}'),
  ('571851d8-4187-7a51-af15-f140e038a1ff', 'av', 'code', '{"language":"cpp","code":"#include <deque>\n#include <iostream>\n#include <vector>\nusing namespace std;\n\nvector<int> windowMax(const vector<int>& arr, int k) {\n    deque<int> dq;               // indices; arr values decreasing front → back\n    vector<int> res;\n    int n = arr.size();\n    for (int i = 0; i < n; i++) {\n        while (!dq.empty() && arr[dq.back()] <= arr[i]) dq.pop_back();   // useless now\n        dq.push_back(i);\n        if (dq.front() <= i - k) dq.pop_front();   // front has slid out of the window\n        if (i >= k - 1) res.push_back(arr[dq.front()]);   // window is full: front is its max\n    }\n    return res;\n}\n\nint main() {\n    for (int x : windowMax({10, 8, 5, 12, 15, 7, 6}, 3)) cout << x << \" \";\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('dbe4e33b-ba3d-741c-97b0-bce998603b1d', 'aw', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Deque;\n\npublic class Main {\n    static int[] windowMax(int[] arr, int k) {\n        Deque<Integer> dq = new ArrayDeque<>();   // indices; arr values decreasing front → back\n        int n = arr.length;\n        int[] res = new int[n - k + 1];\n        for (int i = 0; i < n; i++) {\n            while (!dq.isEmpty() && arr[dq.peekLast()] <= arr[i]) dq.pollLast();   // useless now\n            dq.addLast(i);\n            if (dq.peekFirst() <= i - k) dq.pollFirst();   // front has slid out of the window\n            if (i >= k - 1) res[i - k + 1] = arr[dq.peekFirst()];   // window full: front is its max\n        }\n        return res;\n    }\n\n    public static void main(String[] args) {\n        StringBuilder sb = new StringBuilder();\n        for (int x : windowMax(new int[]{10, 8, 5, 12, 15, 7, 6}, 3)) sb.append(x).append('' '');\n        System.out.println(sb.toString().trim());\n    }\n}","filename":"Java"}'),
  ('5b4836e1-08c5-7946-a6c9-98564dd20908', 'ax', 'code', '{"language":"javascript","code":"function windowMax(arr, k) {\n    const dq = [];               // indices; arr values decreasing front → back\n    let head = 0;                // dq[head] is the front — no O(n) shift()\n    const res = [];\n    for (let i = 0; i < arr.length; i++) {\n        while (dq.length > head && arr[dq[dq.length - 1]] <= arr[i]) dq.pop();   // useless now\n        dq.push(i);\n        if (dq[head] <= i - k) head++;                 // front has slid out of the window\n        if (i >= k - 1) res.push(arr[dq[head]]);       // window is full: front is its maximum\n    }\n    return res;\n}\n\nconsole.log(windowMax([10, 8, 5, 12, 15, 7, 6], 3).join(\" \"));","filename":"JavaScript"}'),
  ('3549973e-e2cb-7b47-b4d9-47bad0ef0730', 'ay', 'code', '{"language":"text","code":"10 12 15 15 15","filename":"Output"}'),
  ('e13b6764-a29f-793d-a505-34313319a4c5', 'az', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) — each index is pushed and popped at most once · Space O(k) for the deque"}]}]}}'),
  ('a8502f48-5a44-7f2f-8deb-923acb15006b', 'b00', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store "},{"type":"text","text":"indices","marks":[{"type":"bold"}]},{"type":"text","text":", not values — you need the index to know when the front has left the window. And pop from the back on "},{"type":"text","text":"<=","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":": an older "},{"type":"text","text":"equal","marks":[{"type":"italic"}]},{"type":"text","text":" element leaves the window earlier than the new one, so keeping it would only make the deque longer. The first "},{"type":"text","text":"k − 1","marks":[{"type":"code"}]},{"type":"text","text":" iterations do not emit anything; the original notes handled that with a separate warm-up loop, the version above folds it into one loop with the "},{"type":"text","text":"i >= k − 1","marks":[{"type":"code"}]},{"type":"text","text":" test."}]}]}}'),
  ('4bf59cb7-5112-79be-85fe-fbdf608744d3', 'b01', 'callout', '{"variant":"note","title":"Variants","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The same deque gives the "},{"type":"text","text":"sliding window minimum","marks":[{"type":"bold"}]},{"type":"text","text":" by flipping the comparison to "},{"type":"text","text":">=","marks":[{"type":"code"}]},{"type":"text","text":". It is also the engine behind "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" solutions for "},{"type":"text","text":"shortest subarray with sum at least k","marks":[{"type":"italic"}]},{"type":"text","text":" and the monotonic-queue optimisation of some DP recurrences."}]}]}}'),
  ('6b58e836-5943-7a79-a735-37b762b27bd3', 'b02', 'heading', '{"level":1,"content":[{"type":"text","text":"First circular tour (petrol pumps)"}]}'),
  ('b79316de-d630-74ab-91c8-ef14a3ce3e34', 'b03', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"petrol = [4, 8, 7, 4], dist = [6, 5, 3, 5] (pumps numbered from 1)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"petrol = [1, 2, 3], dist = [3, 3, 3]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1","marks":[{"type":"code"}]}]}]}}'),
  ('a818467d-9e21-7067-964a-cdc9f5dd7386', 'b04', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" petrol pumps sit on a circle. Pump "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" offers "},{"type":"text","text":"petrol[i]","marks":[{"type":"code"}]},{"type":"text","text":" litres, and "},{"type":"text","text":"dist[i]","marks":[{"type":"code"}]},{"type":"text","text":" litres are burned driving from pump "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" to pump "},{"type":"text","text":"i + 1","marks":[{"type":"code"}]},{"type":"text","text":". Starting with an empty tank, find the first pump from which a truck can complete the full circle, or report that none exists. Here the net gain at each pump is "},{"type":"text","text":"-2, 3, 4, -1","marks":[{"type":"code"}]},{"type":"text","text":"; starting at pump 2 the tank reads "},{"type":"text","text":"3 → 7 → 6 → 4","marks":[{"type":"code"}]},{"type":"text","text":", never negative."}]}]}}'),
  ('4ceea3a6-1f9c-72e2-9618-85055021942c', 'b05', 'code', '{"language":"python","code":"def first_tour_naive(petrol, dist):\n    n = len(petrol)\n    for start in range(n):             # try every start …\n        fuel, i = 0, start\n        while True:                    # … and simulate the whole circle\n            fuel += petrol[i] - dist[i]\n            if fuel < 0:\n                break\n            i = (i + 1) % n\n            if i == start:\n                return start + 1\n    return -1\n\nprint(first_tour_naive([4, 8, 7, 4], [6, 5, 3, 5]))\nprint(first_tour_naive([1, 2, 3], [3, 3, 3]))","filename":"Naive — O(n²): simulate the circle from every start"}'),
  ('71afc362-cb4a-7059-8c00-806b6231717e', 'b06', 'code', '{"language":"text","code":"2\n-1","filename":"Output"}'),
  ('8fb8a157-0523-7604-b9c7-1f3a0568ed8e', 'b07', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Think of the visited pumps as a "},{"type":"text","text":"queue","marks":[{"type":"bold"}]},{"type":"text","text":". If the tank goes negative on reaching pump "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" after starting at "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":", then every start between "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" fails too: the tank was non-negative on arrival at each of them, so starting there with an "},{"type":"text","text":"empty","marks":[{"type":"italic"}]},{"type":"text","text":" tank only makes things worse. Dequeue them all at once — the next candidate start is "},{"type":"text","text":"i + 1","marks":[{"type":"code"}]},{"type":"text","text":". Each pump is enqueued (visited as part of a tour) and dequeued (ruled out) at most once, so one pass suffices. Finally, the candidate that survives to the end is valid only if the "},{"type":"text","text":"total","marks":[{"type":"bold"}]},{"type":"text","text":" surplus (what it gains after its start plus the deficit of the skipped prefix it still has to cross) is "},{"type":"text","text":">= 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('55ef3b52-5527-7e9e-9a30-128b0a23e21f', 'b08', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Scan once","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Keep "},{"type":"text","text":"start = 0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fuel = 0","marks":[{"type":"code"}]},{"type":"text","text":" (fuel since "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":") and "},{"type":"text","text":"deficit = 0","marks":[{"type":"code"}]},{"type":"text","text":" (total shortfall of all ruled-out prefixes)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On a negative tank at pump i","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Everything from "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" is ruled out: "},{"type":"text","text":"deficit += fuel","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"start = i + 1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fuel = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the end","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" completes the circle only if "},{"type":"text","text":"fuel + deficit >= 0","marks":[{"type":"code"}]},{"type":"text","text":" — the surplus it collects from "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"n − 1","marks":[{"type":"code"}]},{"type":"text","text":" must cover the deficit of the wrapped-around prefix. Otherwise no pump works (equivalently, "},{"type":"text","text":"sum(petrol) < sum(dist)","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}}'),
  ('2136bf4f-cb4b-73bf-90b6-a70fbb4ae316', 'b09', 'code', '{"language":"python","code":"def first_tour(petrol, dist):\n    start, fuel, deficit = 0, 0, 0\n    for i in range(len(petrol)):\n        fuel += petrol[i] - dist[i]\n        if fuel < 0:                 # pumps start..i are all ruled out at once\n            deficit += fuel          # remember how short that stretch was\n            start = i + 1\n            fuel = 0\n    return start + 1 if fuel + deficit >= 0 else -1   # 1-based pump number\n\nprint(first_tour([4, 8, 7, 4], [6, 5, 3, 5]))\nprint(first_tour([1, 2, 3], [3, 3, 3]))","filename":"Python"}'),
  ('d25c77d9-13a2-754a-b509-8d31e2261bb1', 'b0A', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint firstTour(const vector<int>& petrol, const vector<int>& dist) {\n    int start = 0, fuel = 0, deficit = 0;\n    int n = petrol.size();\n    for (int i = 0; i < n; i++) {\n        fuel += petrol[i] - dist[i];\n        if (fuel < 0) {              // pumps start..i are all ruled out at once\n            deficit += fuel;         // remember how short that stretch was\n            start = i + 1;\n            fuel = 0;\n        }\n    }\n    return fuel + deficit >= 0 ? start + 1 : -1;   // 1-based pump number\n}\n\nint main() {\n    cout << firstTour({4, 8, 7, 4}, {6, 5, 3, 5}) << \"\\n\";\n    cout << firstTour({1, 2, 3}, {3, 3, 3}) << \"\\n\";\n}","filename":"C++"}'),
  ('b865e3a7-fd47-7463-bbf2-9a5a6d6dd3f3', 'b0B', 'code', '{"language":"java","code":"public class Main {\n    static int firstTour(int[] petrol, int[] dist) {\n        int start = 0, fuel = 0, deficit = 0;\n        for (int i = 0; i < petrol.length; i++) {\n            fuel += petrol[i] - dist[i];\n            if (fuel < 0) {              // pumps start..i are all ruled out at once\n                deficit += fuel;         // remember how short that stretch was\n                start = i + 1;\n                fuel = 0;\n            }\n        }\n        return fuel + deficit >= 0 ? start + 1 : -1;   // 1-based pump number\n    }\n\n    public static void main(String[] args) {\n        System.out.println(firstTour(new int[]{4, 8, 7, 4}, new int[]{6, 5, 3, 5}));\n        System.out.println(firstTour(new int[]{1, 2, 3}, new int[]{3, 3, 3}));\n    }\n}","filename":"Java"}'),
  ('b93c0204-68b3-7f00-8ab9-59bf09002d61', 'b0C', 'code', '{"language":"javascript","code":"function firstTour(petrol, dist) {\n    let start = 0, fuel = 0, deficit = 0;\n    for (let i = 0; i < petrol.length; i++) {\n        fuel += petrol[i] - dist[i];\n        if (fuel < 0) {                  // pumps start..i are all ruled out at once\n            deficit += fuel;             // remember how short that stretch was\n            start = i + 1;\n            fuel = 0;\n        }\n    }\n    return fuel + deficit >= 0 ? start + 1 : -1;   // 1-based pump number\n}\n\nconsole.log(firstTour([4, 8, 7, 4], [6, 5, 3, 5]));\nconsole.log(firstTour([1, 2, 3], [3, 3, 3]));","filename":"JavaScript"}'),
  ('cb05d344-04f0-7aac-9c21-0dc0131154ee', 'b0D', 'code', '{"language":"text","code":"2\n-1","filename":"Output"}'),
  ('a6ab22f6-8fad-7492-969a-afb381cc97f9', 'b0E', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(1)"}]}]}}'),
  ('467ba192-2f57-7365-9d4e-fb737c87a373', 'b0F', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why the final check is enough.","marks":[{"type":"bold"}]},{"type":"text","text":" If "},{"type":"text","text":"sum(petrol) >= sum(dist)","marks":[{"type":"code"}]},{"type":"text","text":" a tour always exists, and the scan above finds the "},{"type":"text","text":"first","marks":[{"type":"italic"}]},{"type":"text","text":" one: every start before "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" was explicitly ruled out, and "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" itself never ran dry on the stretch to the end; wrapping around, it meets the ruled-out prefixes with "},{"type":"text","text":"fuel","marks":[{"type":"code"}]},{"type":"text","text":" in the tank, and "},{"type":"text","text":"fuel + deficit >= 0","marks":[{"type":"code"}]},{"type":"text","text":" says that is enough. The explicit queue version (two indices "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"end","marks":[{"type":"code"}]},{"type":"text","text":" walking around the circle, dequeuing from the front while the tank is negative) is the same argument spelled out with "},{"type":"text","text":"(end + 1) % n","marks":[{"type":"code"}]},{"type":"text","text":" arithmetic."}]}]}}'),
  ('7ece2d36-ad08-7c3a-bf68-90324f38643c', 'b0G', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The answer is the pump "},{"type":"text","text":"number","marks":[{"type":"bold"}]},{"type":"text","text":", and the original notes count from 1 ("},{"type":"text","text":"start + 1","marks":[{"type":"code"}]},{"type":"text","text":"); many online judges count from 0. Say which convention you use. Also do not forget the "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" case — with "},{"type":"text","text":"start","marks":[{"type":"code"}]},{"type":"text","text":" ending at "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" (every pump ruled out) the "},{"type":"text","text":"start + 1","marks":[{"type":"code"}]},{"type":"text","text":" formula would otherwise return a nonsense "},{"type":"text","text":"n + 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('a2cb1ddc-304e-737b-86c7-64b982b1e752', 'b0H', 'heading', '{"level":1,"content":[{"type":"text","text":"Interview Q&A"}]}'),
  ('d169afcd-d6b2-7823-b750-49312e11b81d', 'b0I', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Queue vs deque vs priority queue — when do I use which?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A queue when the order of processing is the order of arrival (BFS, task scheduling). A deque when you also need the other end: sliding windows, work-stealing, palindromes, undo/redo with a bounded history. A priority queue when the next element is determined by a key, not by position — it costs "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":" per operation instead of "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('e2d82ae8-4567-7490-8af9-b464a590128e', 'b0J', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is the sliding window maximum O(n) if there is a while loop inside the for loop?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every index is appended once and removed at most once (from the back by a bigger element, or from the front by sliding out). Total deque operations are at most "},{"type":"text","text":"2n","marks":[{"type":"code"}]},{"type":"text","text":", so the amortised cost per element is constant — the same argument as for the monotonic stack."}]}]}}'),
  ('071e1a03-74f8-708a-b41c-21c5fb378173', 'b0K', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you implement a deque yourself?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A circular array with "},{"type":"text","text":"head","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"tail","marks":[{"type":"code"}]},{"type":"text","text":" indices (and either a "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" counter or one wasted slot to tell full from empty) gives "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":" at both ends with cache-friendly storage; grow by doubling when full. A doubly linked list also works but spends a node per element. "},{"type":"text","text":"collections.deque","marks":[{"type":"code"}]},{"type":"text","text":" uses blocks of 64 pointers in a doubly linked list of blocks; "},{"type":"text","text":"ArrayDeque","marks":[{"type":"code"}]},{"type":"text","text":" is a circular array."}]}]}}'),
  ('2b81ff45-f48b-7c90-91ae-d1a84f3e7d01', 'b0L', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How would you generate the numbers in the digit problem without a queue?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Treat the index as a counter in base "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" (the number of digits) with a bijective numeration: the "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":"-th number''s digits are the base-"},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" representation of "},{"type":"text","text":"m","marks":[{"type":"code"}]},{"type":"text","text":" with digits mapped through the sorted digit set. That is "},{"type":"text","text":"O(log m)","marks":[{"type":"code"}]},{"type":"text","text":" per number and needs no memory — but the BFS version is the one interviewers expect first, because it generalises to any ''generate in order by extending'' problem."}]}]}}'),
  ('62aeffc8-791f-79d7-b9eb-f8664c8e013d', 'b0M', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does the petrol-pump argument rule out all pumps between the start and the failure point?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suppose the tour from "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" first goes negative on arriving at "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":". For any "},{"type":"text","text":"s < t <= i","marks":[{"type":"code"}]},{"type":"text","text":", the tank on arrival at "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" (from "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":") was non-negative, so starting at "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" with an empty tank gives at every later pump at most the fuel the "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":"-tour had there — and that went negative at "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":". So "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" fails too, and the next possible start is "},{"type":"text","text":"i + 1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}')
