INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '86075263-b1f7-7f37-8dd6-69236a901158', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('120e4fb5-c709-7b78-86b8-8be00d27e827', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursion solves a problem by calling itself on a "},{"type":"text","text":"smaller instance","marks":[{"type":"bold"}]},{"type":"text","text":" and trusting that call''s answer. The problems here — rope cutting, subsets, Tower of Hanoi, Josephus, subset sum and permutations — are the templates for backtracking and dynamic programming later in the course."}]}]}}'),
  ('8901f2dc-e57b-7780-bda4-de6ce29e29f1', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursion","marks":[{"type":"bold"}]},{"type":"text","text":" — a function that calls itself with an input strictly closer to a "},{"type":"text","text":"base case","marks":[{"type":"bold"}]},{"type":"text","text":", which is answered directly. Each active call lives in its own stack frame, so the maximum depth of the recursion is also the auxiliary space."}]}]}}'),
  ('c2b1a8bd-d995-7ddc-8200-aac374c7bdab', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"How a recursive call runs"}]}'),
  ('c8256885-2c2d-731f-bf4a-90956aa2d89e', 'a3', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every call pushes a frame (parameters, locals, return address) on the "},{"type":"text","text":"call stack","marks":[{"type":"bold"}]},{"type":"text","text":"; the frame is popped when the call returns. Work written "},{"type":"text","text":"before","marks":[{"type":"italic"}]},{"type":"text","text":" the recursive call happens on the way "},{"type":"text","text":"down","marks":[{"type":"bold"}]},{"type":"text","text":", work "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" it happens on the way "},{"type":"text","text":"up","marks":[{"type":"bold"}]},{"type":"text","text":" — the trace below shows both."}]}]}}'),
  ('2eac15e3-c5e0-7b1f-8919-158452de1b9e', 'a4', 'code', '{"language":"python","code":"def trace(n):\n    if n == 0:                    # base case: answered without another call\n        print(\"base case reached\")\n        return\n    print(\"enter\", n)             # on the way down\n    trace(n - 1)                  # smaller instance\n    print(\"exit\", n)              # on the way up, after the sub-call finished\n\ntrace(3)","filename":"Python"}'),
  ('5e209d80-0122-74c8-b5d1-788122f44009', 'a5', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nvoid trace(int n) {\n    if (n == 0) {                 // base case: answered without another call\n        cout << \"base case reached\\n\";\n        return;\n    }\n    cout << \"enter \" << n << \"\\n\";    // on the way down\n    trace(n - 1);                     // smaller instance\n    cout << \"exit \" << n << \"\\n\";     // on the way up, after the sub-call finished\n}\n\nint main() { trace(3); }","filename":"C++"}'),
  ('050af378-cb77-73d9-a967-86579594bc0a', 'a6', 'code', '{"language":"java","code":"public class Main {\n    static void trace(int n) {\n        if (n == 0) {             // base case: answered without another call\n            System.out.println(\"base case reached\");\n            return;\n        }\n        System.out.println(\"enter \" + n);   // on the way down\n        trace(n - 1);                       // smaller instance\n        System.out.println(\"exit \" + n);    // on the way up, after the sub-call finished\n    }\n\n    public static void main(String[] args) { trace(3); }\n}","filename":"Java"}'),
  ('f4a9bf03-dadb-750d-b9fc-b1a0a6f7c4bd', 'a7', 'code', '{"language":"javascript","code":"function trace(n) {\n    if (n === 0) {                // base case: answered without another call\n        console.log(\"base case reached\");\n        return;\n    }\n    console.log(\"enter\", n);      // on the way down\n    trace(n - 1);                 // smaller instance\n    console.log(\"exit\", n);       // on the way up, after the sub-call finished\n}\n\ntrace(3);","filename":"JavaScript"}'),
  ('3f021fb5-d40a-7d3a-9f80-cd03eea9a095', 'a8', 'code', '{"language":"text","code":"enter 3\nenter 2\nenter 1\nbase case reached\nexit 1\nexit 2\nexit 3","filename":"Output"}'),
  ('318c0fea-5c3e-7a9a-a863-fed2481ffbd8', 'a9', 'code', '{"language":"text","code":"trace(3)                         call stack (top is the running call)\n └ trace(2)                      ┌──────────┐\n    └ trace(1)                   │ trace(0) │ ← base case, 4 frames deep\n       └ trace(0)  base case     │ trace(1) │\n                                 │ trace(2) │\n                                 │ trace(3) │\n                                 └──────────┘","filename":"Depth 4 = O(n) auxiliary space, even though the function declares no arrays"}'),
  ('3d5df15e-dec1-7fcf-985b-8919e5c5ff4d', 'aA', 'callout', '{"variant":"note","title":"Base case first","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without it the recursion never stops: Python raises "},{"type":"text","text":"RecursionError","marks":[{"type":"code"}]},{"type":"text","text":" at ~1000 frames, C++/Java crash with a stack overflow."}]}]}}'),
  ('8d4de218-557e-713d-aba0-c0ff0e2e8880', 'aB', 'callout', '{"variant":"note","title":"Make progress","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every call must move strictly towards the base case ("},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"i+1","marks":[{"type":"code"}]},{"type":"text","text":", a shorter string)."}]}]}}'),
  ('190f0725-fedc-70d1-96c9-5b3c21e9d49e', 'aC', 'callout', '{"variant":"note","title":"Trust the sub-call","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Assume "},{"type":"text","text":"f(n-1)","marks":[{"type":"code"}]},{"type":"text","text":" is correct and only write how to build "},{"type":"text","text":"f(n)","marks":[{"type":"code"}]},{"type":"text","text":" from it — the "},{"type":"text","text":"recursive leap of faith","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('5cac14c4-ac5a-7e41-8d05-e92af461836b', 'aD', 'callout', '{"variant":"note","title":"Count the tree","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time ≈ number of nodes in the recursion tree (branching^depth); space = its height."}]}]}}'),
  ('b7d8ccbc-5bed-731b-809c-df549fe4e773', 'aE', 'heading', '{"level":1,"content":[{"type":"text","text":"Rope cutting problem"}]}'),
  ('fdbea1bf-c97e-71a2-9a71-98af0fea0f8d', 'aF', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 5, a = 2, b = 5, c = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"5","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 23, a = 12, b = 9, c = 11","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 5, a = 4, b = 2, c = 6","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"-1","marks":[{"type":"code"}]}]}]}}'),
  ('965ba1cd-ea93-7e04-bb6f-d640b06c2b03', 'aG', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cut a rope of length "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" into the "},{"type":"text","text":"maximum number of pieces","marks":[{"type":"bold"}]},{"type":"text","text":", each of length "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":"; return "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":" if no exact division exists. For "},{"type":"text","text":"n = 23","marks":[{"type":"code"}]},{"type":"text","text":" the best is "},{"type":"text","text":"12 + 11","marks":[{"type":"code"}]},{"type":"text","text":" (2 pieces); for "},{"type":"text","text":"n = 5","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"c = 1","marks":[{"type":"code"}]},{"type":"text","text":" it is five unit pieces."}]}]}}'),
  ('3f15e70b-7e83-7daf-987c-01ebe5a9cd72', 'aH', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The first cut is "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"c","marks":[{"type":"code"}]},{"type":"text","text":". Whichever it is, the rest of the rope is a smaller rope with the same question — so "},{"type":"text","text":"maxPieces(n) = 1 + max(maxPieces(n-a), maxPieces(n-b), maxPieces(n-c))","marks":[{"type":"code"}]},{"type":"text","text":". A rope of length "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" needs "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" more cuts (base case); a negative length means that cut overshoots and is reported as "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":", which the "},{"type":"text","text":"max","marks":[{"type":"code"}]},{"type":"text","text":" discards unless all three branches fail."}]}]}}'),
  ('3bca7705-9436-7622-83ae-dad695ef9d2c', 'aI', 'code', '{"language":"text","code":"maxPieces(5)  a=2 b=5 c=1\n├── maxPieces(3)   (cut 2)\n│   ├── maxPieces(1)  → ├ (-1) → -1   ├ (-4) → -1   ├ (0) → 0     ⇒ 1\n│   ├── maxPieces(-2) → -1\n│   └── maxPieces(2)  → … ⇒ 2\n│                                          ⇒ 1 + max(1, -1, 2) = 3\n├── maxPieces(0)   (cut 5)  → 0            ⇒ 0 + 1 = 1\n└── maxPieces(4)   (cut 1)  → … ⇒ 4        ⇒ 5\n                                           answer = max(3, 1, 5) = 5","filename":"Three branches per node; a negative length is a dead branch (-1)"}'),
  ('c1dee9a5-0286-77a5-873b-ed77751efdea', 'aJ', 'code', '{"language":"python","code":"def max_pieces(n, a, b, c):\n    if n == 0:\n        return 0                      # nothing left to cut: 0 more pieces\n    if n < 0:\n        return -1                     # this cut overshot the rope: invalid\n    res = max(max_pieces(n - a, a, b, c),\n              max_pieces(n - b, a, b, c),\n              max_pieces(n - c, a, b, c))\n    if res == -1:\n        return -1                     # none of the three cuts can finish the rope\n    return res + 1                    # +1 for the piece cut here\n\nfor n, a, b, c in ((5, 2, 5, 1), (23, 12, 9, 11), (5, 4, 2, 6)):\n    print(f\"n={n} a={a} b={b} c={c} ->\", max_pieces(n, a, b, c))","filename":"Python"}'),
  ('0e36357c-86b0-74eb-8b25-c2c17a60c733', 'aK', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint maxPieces(int n, int a, int b, int c) {\n    if (n == 0) return 0;                 // nothing left to cut: 0 more pieces\n    if (n < 0) return -1;                 // this cut overshot the rope: invalid\n    int res = max({maxPieces(n - a, a, b, c),\n                   maxPieces(n - b, a, b, c),\n                   maxPieces(n - c, a, b, c)});\n    if (res == -1) return -1;             // none of the three cuts can finish the rope\n    return res + 1;                       // +1 for the piece cut here\n}\n\nint main() {\n    int tests[3][4] = {{5, 2, 5, 1}, {23, 12, 9, 11}, {5, 4, 2, 6}};\n    for (auto& t : tests)\n        cout << \"n=\" << t[0] << \" a=\" << t[1] << \" b=\" << t[2] << \" c=\" << t[3]\n             << \" -> \" << maxPieces(t[0], t[1], t[2], t[3]) << \"\\n\";\n}","filename":"C++"}'),
  ('55d6bd66-25ce-78b3-adba-139cdc647ca6', 'aL', 'code', '{"language":"java","code":"public class Main {\n    static int maxPieces(int n, int a, int b, int c) {\n        if (n == 0) return 0;             // nothing left to cut: 0 more pieces\n        if (n < 0) return -1;             // this cut overshot the rope: invalid\n        int res = Math.max(maxPieces(n - a, a, b, c),\n                  Math.max(maxPieces(n - b, a, b, c), maxPieces(n - c, a, b, c)));\n        if (res == -1) return -1;         // none of the three cuts can finish the rope\n        return res + 1;                   // +1 for the piece cut here\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{5, 2, 5, 1}, {23, 12, 9, 11}, {5, 4, 2, 6}};\n        for (int[] t : tests)\n            System.out.println(\"n=\" + t[0] + \" a=\" + t[1] + \" b=\" + t[2] + \" c=\" + t[3]\n                               + \" -> \" + maxPieces(t[0], t[1], t[2], t[3]));\n    }\n}","filename":"Java"}'),
  ('b21c5545-4e97-7330-861f-cba59a92cb07', 'aM', 'code', '{"language":"javascript","code":"function maxPieces(n, a, b, c) {\n    if (n === 0) return 0;                // nothing left to cut: 0 more pieces\n    if (n < 0) return -1;                 // this cut overshot the rope: invalid\n    const res = Math.max(maxPieces(n - a, a, b, c),\n                         maxPieces(n - b, a, b, c),\n                         maxPieces(n - c, a, b, c));\n    if (res === -1) return -1;            // none of the three cuts can finish the rope\n    return res + 1;                       // +1 for the piece cut here\n}\n\nfor (const [n, a, b, c] of [[5, 2, 5, 1], [23, 12, 9, 11], [5, 4, 2, 6]])\n    console.log(`n=${n} a=${a} b=${b} c=${c} ->`, maxPieces(n, a, b, c));","filename":"JavaScript"}'),
  ('866f3e65-bd62-779d-a9e7-b70fc962b8a9', 'aN', 'code', '{"language":"text","code":"n=5 a=2 b=5 c=1 -> 5\nn=23 a=12 b=9 c=11 -> 2\nn=5 a=4 b=2 c=6 -> -1","filename":"Output"}'),
  ('2b24d708-ebdb-7c99-bddc-04b3b89b3973', 'aO', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(3^n) · Space O(n) recursion depth"}]}]}}'),
  ('1cb31415-640f-70e3-acd7-c51075eadd23', 'aP', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returning "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" for a negative length (instead of "},{"type":"text","text":"-1","marks":[{"type":"code"}]},{"type":"text","text":") silently counts an impossible cut as valid and over-reports the answer. Also note the massive overlap in the tree — "},{"type":"text","text":"maxPieces(2)","marks":[{"type":"code"}]},{"type":"text","text":" is computed many times. Memoising on "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" turns this into the "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" dynamic-programming solution in the DP topic."}]}]}}'),
  ('2f7bbc41-6fac-79ac-b36f-6147135475fe', 'aQ', 'heading', '{"level":1,"content":[{"type":"text","text":"Subsets of a string"}]}'),
  ('395ddfe4-b407-73e5-9f00-d9ce356db3fc', 'aR', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"AB\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"\"\" B A AB","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"ABC\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"\"\" C B BC A AC AB ABC","marks":[{"type":"code"}]}]}]}}'),
  ('a121d7b2-25a1-756f-a077-211af6d1c611', 'aS', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Generate all "},{"type":"text","text":"2^n","marks":[{"type":"code"}]},{"type":"text","text":" subsets (subsequences keeping the original order) of a string of distinct characters."}]}]}}'),
  ('a081071d-330f-775d-8ac5-43689470c2f8', 'aT', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk the string one index at a time. For "},{"type":"text","text":"s[i]","marks":[{"type":"code"}]},{"type":"text","text":" there are exactly two choices — "},{"type":"text","text":"leave it out","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"put it in","marks":[{"type":"bold"}]},{"type":"text","text":" — and the rest of the string is the same problem. When the index reaches the end, the accumulated "},{"type":"text","text":"curr","marks":[{"type":"code"}]},{"type":"text","text":" is one finished subset. Two choices at each of "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" levels gives "},{"type":"text","text":"2^n","marks":[{"type":"code"}]},{"type":"text","text":" leaves."}]}]}}'),
  ('9dd72f09-bdb3-767f-968f-77bd2b356bef', 'aU', 'code', '{"language":"text","code":"sub(\"\", 0)                                       s = \"ABC\"\n├── exclude A → sub(\"\", 1)\n│   ├── exclude B → sub(\"\", 2)\n│   │   ├── exclude C → \"\"      ✔\n│   │   └── include C → \"C\"     ✔\n│   └── include B → sub(\"B\", 2)\n│       ├── \"B\"  ✔     └── \"BC\" ✔\n└── include A → sub(\"A\", 1)\n    ├── sub(\"A\", 2)  → \"A\" ✔, \"AC\" ✔\n    └── sub(\"AB\", 2) → \"AB\" ✔, \"ABC\" ✔","filename":"Depth n, 2^n leaves — one per subset. Exclude first, so the empty string is printed first"}'),
  ('3e9c4939-fb14-7f46-888e-44bc9688aa03', 'aV', 'code', '{"language":"python","code":"def subsets(s, curr, i, out):\n    if i == len(s):\n        out.append(curr if curr else ''\"\"'')    # a finished subset\n        return\n    subsets(s, curr, i + 1, out)              # exclude s[i]\n    subsets(s, curr + s[i], i + 1, out)       # include s[i]\n\nfor s in (\"AB\", \"ABC\"):\n    out = []\n    subsets(s, \"\", 0, out)\n    print(s, \"->\", \" \".join(out), f\"({len(out)} subsets)\")","filename":"Python"}'),
  ('6aac78a0-ce02-7847-9391-557e6b4803ef', 'aW', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid subsets(const string& s, string curr, int i, vector<string>& out) {\n    if (i == (int)s.size()) {\n        out.push_back(curr.empty() ? \"\\\"\\\"\" : curr);   // a finished subset\n        return;\n    }\n    subsets(s, curr, i + 1, out);             // exclude s[i]\n    subsets(s, curr + s[i], i + 1, out);      // include s[i]\n}\n\nint main() {\n    for (string s : {\"AB\", \"ABC\"}) {\n        vector<string> out;\n        subsets(s, \"\", 0, out);\n        cout << s << \" ->\";\n        for (const string& x : out) cout << \" \" << x;\n        cout << \" (\" << out.size() << \" subsets)\\n\";\n    }\n}","filename":"C++"}'),
  ('b9ddf709-2068-7350-9d30-a5ebf64b2865', 'aX', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static void subsets(String s, String curr, int i, List<String> out) {\n        if (i == s.length()) {\n            out.add(curr.isEmpty() ? \"\\\"\\\"\" : curr);  // a finished subset\n            return;\n        }\n        subsets(s, curr, i + 1, out);                 // exclude s[i]\n        subsets(s, curr + s.charAt(i), i + 1, out);   // include s[i]\n    }\n\n    public static void main(String[] args) {\n        for (String s : new String[]{\"AB\", \"ABC\"}) {\n            List<String> out = new ArrayList<>();\n            subsets(s, \"\", 0, out);\n            System.out.println(s + \" -> \" + String.join(\" \", out) + \" (\" + out.size() + \" subsets)\");\n        }\n    }\n}","filename":"Java"}'),
  ('61c3ab54-560d-7439-b8e1-db132c3152bd', 'aY', 'code', '{"language":"javascript","code":"function subsets(s, curr, i, out) {\n    if (i === s.length) {\n        out.push(curr === \"\" ? ''\"\"'' : curr);  // a finished subset\n        return;\n    }\n    subsets(s, curr, i + 1, out);             // exclude s[i]\n    subsets(s, curr + s[i], i + 1, out);      // include s[i]\n}\n\nfor (const s of [\"AB\", \"ABC\"]) {\n    const out = [];\n    subsets(s, \"\", 0, out);\n    console.log(s, \"->\", out.join(\" \"), `(${out.length} subsets)`);\n}","filename":"JavaScript"}'),
  ('5f84f6be-b1d4-791d-9aea-b4ea63cdeee9', 'aZ', 'code', '{"language":"text","code":"AB -> \"\" B A AB (4 subsets)\nABC -> \"\" C B BC A AC AB ABC (8 subsets)","filename":"Output"}'),
  ('f888a3ca-a801-7526-a9c0-69ad67f2b63a', 'aa', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(2^n · n) · Space O(n) recursion depth (plus the output)"}]}]}}'),
  ('c644a666-5634-75d0-8664-5533bb87ae9a', 'ab', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Swapping the two recursive calls (include first) lists "},{"type":"text","text":"ABC AB AC A BC B C \"\"","marks":[{"type":"code"}]},{"type":"text","text":" instead — the set of subsets is the same, only the order changes. The iterative bitmask version of this problem is in Bit Magic → "},{"type":"text","text":"Power set using bitmasks","marks":[{"type":"italic"}]},{"type":"text","text":". With repeated characters this prints duplicate subsets; sort the string and skip equal neighbours to avoid that."}]}]}}'),
  ('14e2ca47-74ab-75f1-bebc-73d594c98c96', 'ac', 'heading', '{"level":1,"content":[{"type":"text","text":"Tower of Hanoi"}]}'),
  ('6ea8c425-e92a-7545-9afa-2329a5936bb5', 'ad', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 1","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Move disc 1 from A to C","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"Move disc 1 from A to B / Move disc 2 from A to C / Move disc 1 from B to C","marks":[{"type":"code"}]}]}]}}'),
  ('a717385b-1789-7574-8fa9-bb9466a6c61a', 'ae', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Move "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" discs from peg "},{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":" (source) to peg "},{"type":"text","text":"C","marks":[{"type":"bold"}]},{"type":"text","text":" (destination) using peg "},{"type":"text","text":"B","marks":[{"type":"bold"}]},{"type":"text","text":" (auxiliary), under three rules:"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only "},{"type":"text","text":"one disc","marks":[{"type":"bold"}]},{"type":"text","text":" moves at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"larger disc may never sit on a smaller","marks":[{"type":"bold"}]},{"type":"text","text":" one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the "},{"type":"text","text":"top disc","marks":[{"type":"bold"}]},{"type":"text","text":" of a peg can be moved."}]}]}]}]}}'),
  ('2cdc262e-51e5-788c-9342-442c715729b1', 'af', 'code', '{"language":"text","code":"    A          B          C                 A          B          C\n    |          |          |                 |          |          |\n   ═╪═         |          |      →          |          |         ═╪═\n  ══╪══        |          |                 |          |        ══╪══\n ═══╪═══       |          |                 |          |       ═══╪═══\n────┴──────────┴──────────┴──          ────┴──────────┴──────────┴──","filename":"n = 3: the whole tower must end on C in the same order"}'),
  ('18210495-01a2-7788-b6d5-e85f99f79f07', 'ag', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To move "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" discs A → C, the biggest disc "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" can only move when the other "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" discs are out of the way on B. So: move "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" discs A → B (using C as spare), move disc "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" A → C, then move the "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" discs B → C (using A as spare). The recursion is the same problem with the pegs "},{"type":"text","text":"relabelled","marks":[{"type":"bold"}]},{"type":"text","text":" — that is why the function takes the three pegs as parameters."}]}]}}'),
  ('0ec6ae47-2a77-7c5e-8468-c31b7dad4319', 'ah', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"TOH(n-1, A, C, B)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Park the top "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" discs on the auxiliary peg B, using C as the spare."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Move disc ","marks":[{"type":"bold"}]},{"type":"text","text":"n","marks":[{"type":"code"},{"type":"bold"}]},{"type":"text","text":" from A to C","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The largest disc makes its single move onto the empty destination."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"TOH(n-1, B, A, C)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Bring the "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" discs from B onto C, using A as the spare."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"moves(n) = 2 · moves(n−1) + 1 = 2^n − 1 (3 discs → 7, 10 discs → 1023, 64 discs → 1.8 × 10^19)","marks":[{"type":"code"}]}]}]}}'),
  ('4db69148-55dc-7f8a-a5c2-63c33977b544', 'ai', 'code', '{"language":"python","code":"def toh(n, src, aux, dst):\n    if n == 0:\n        return 0                              # no discs: no moves\n    moves = toh(n - 1, src, dst, aux)         # park n-1 discs on the auxiliary peg\n    print(f\"Move disc {n} from {src} to {dst}\")\n    moves += 1 + toh(n - 1, aux, src, dst)    # bring them onto the destination\n    return moves\n\nfor n in (2, 3):\n    print(\"n =\", n)\n    print(\"moves:\", toh(n, \"A\", \"B\", \"C\"))","filename":"Python"}'),
  ('22ff7143-d137-765f-9c11-aee2b8f7955a', 'aj', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nint toh(int n, char src, char aux, char dst) {\n    if (n == 0) return 0;                         // no discs: no moves\n    int moves = toh(n - 1, src, dst, aux);        // park n-1 discs on the auxiliary peg\n    cout << \"Move disc \" << n << \" from \" << src << \" to \" << dst << \"\\n\";\n    moves += 1 + toh(n - 1, aux, src, dst);       // bring them onto the destination\n    return moves;\n}\n\nint main() {\n    for (int n : {2, 3}) {\n        cout << \"n = \" << n << \"\\n\";\n        int moves = toh(n, ''A'', ''B'', ''C'');      // run first: the moves print inside\n        cout << \"moves: \" << moves << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('d78f0c23-977d-7be3-89ec-2ef88ff729cf', 'ak', 'code', '{"language":"java","code":"public class Main {\n    static int toh(int n, char src, char aux, char dst) {\n        if (n == 0) return 0;                     // no discs: no moves\n        int moves = toh(n - 1, src, dst, aux);    // park n-1 discs on the auxiliary peg\n        System.out.println(\"Move disc \" + n + \" from \" + src + \" to \" + dst);\n        moves += 1 + toh(n - 1, aux, src, dst);   // bring them onto the destination\n        return moves;\n    }\n\n    public static void main(String[] args) {\n        for (int n : new int[]{2, 3}) {\n            System.out.println(\"n = \" + n);\n            System.out.println(\"moves: \" + toh(n, ''A'', ''B'', ''C''));\n        }\n    }\n}","filename":"Java"}'),
  ('21663be3-0e1b-7b77-aa9e-cf625388aa38', 'al', 'code', '{"language":"javascript","code":"function toh(n, src, aux, dst) {\n    if (n === 0) return 0;                        // no discs: no moves\n    let moves = toh(n - 1, src, dst, aux);        // park n-1 discs on the auxiliary peg\n    console.log(`Move disc ${n} from ${src} to ${dst}`);\n    moves += 1 + toh(n - 1, aux, src, dst);       // bring them onto the destination\n    return moves;\n}\n\nfor (const n of [2, 3]) {\n    console.log(\"n =\", n);\n    console.log(\"moves:\", toh(n, \"A\", \"B\", \"C\"));\n}","filename":"JavaScript"}'),
  ('0031b5c5-ea03-733d-b0c6-d79b83de05fc', 'am', 'code', '{"language":"text","code":"n = 2\nMove disc 1 from A to B\nMove disc 2 from A to C\nMove disc 1 from B to C\nmoves: 3\nn = 3\nMove disc 1 from A to C\nMove disc 2 from A to B\nMove disc 1 from C to B\nMove disc 3 from A to C\nMove disc 1 from B to A\nMove disc 2 from B to C\nMove disc 1 from A to C\nmoves: 7","filename":"Output"}'),
  ('5e207734-d202-7d7e-b981-8502cf4888d6', 'an', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(2^n) moves · Space O(n) recursion depth"}]}]}}'),
  ('6c0f2418-a3a5-7667-8da6-a84ac9bab1b8', 'ao', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The classic slip is the "},{"type":"text","text":"peg order","marks":[{"type":"bold"}]},{"type":"text","text":" in the two recursive calls. With the signature "},{"type":"text","text":"TOH(n, source, auxiliary, destination)","marks":[{"type":"code"}]},{"type":"text","text":" the first call is "},{"type":"text","text":"TOH(n-1, A, C, B)","marks":[{"type":"code"}]},{"type":"text","text":" (destination becomes the spare) and the second is "},{"type":"text","text":"TOH(n-1, B, A, C)","marks":[{"type":"code"}]},{"type":"text","text":" (source becomes the spare). Using "},{"type":"text","text":"n == 1","marks":[{"type":"code"}]},{"type":"text","text":" as the base case also works; "},{"type":"text","text":"n == 0","marks":[{"type":"code"}]},{"type":"text","text":" avoids a special-cased print."}]}]}}'),
  ('8b19ebd0-3085-74e5-8ac1-2f64ef422b5d', 'ap', 'heading', '{"level":1,"content":[{"type":"text","text":"Josephus problem (elimination game)"}]}'),
  ('877e365d-6d24-7f6c-bfa0-dabfb96daf3f', 'aq', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 7, k = 3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"3","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n = 8, k = 2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"0","marks":[{"type":"code"}]}]}]}}'),
  ('6d66b803-b3ad-78d2-8cc6-6c58d5cd954f', 'ar', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" people stand in a circle numbered "},{"type":"text","text":"0 … n-1","marks":[{"type":"code"}]},{"type":"text","text":". Starting at "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":", every "},{"type":"text","text":"kth","marks":[{"type":"bold"}]},{"type":"text","text":" person is eliminated and the count restarts from the next person. Which position survives?"}]}]}}'),
  ('33b2768b-6976-77b8-99dd-c9111366b9a0', 'as', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After the first elimination ("},{"type":"text","text":"k-1","marks":[{"type":"code"}]},{"type":"text","text":" is removed), the circle has "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" people and the count restarts at position "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":". If we "},{"type":"text","text":"renumber","marks":[{"type":"bold"}]},{"type":"text","text":" so that position "},{"type":"text","text":"k","marks":[{"type":"code"}]},{"type":"text","text":" becomes "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":", the remaining game is exactly "},{"type":"text","text":"josephus(n-1, k)","marks":[{"type":"code"}]},{"type":"text","text":". Its survivor "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" in the renumbered circle sits at "},{"type":"text","text":"(j + k) % n","marks":[{"type":"code"}]},{"type":"text","text":" in the original one — hence "},{"type":"text","text":"jos(n, k) = (jos(n-1, k) + k) % n","marks":[{"type":"code"}]},{"type":"text","text":", with "},{"type":"text","text":"jos(1, k) = 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('6b06fcb9-9a8f-7c67-a385-8640cf2eaef8', 'at', 'code', '{"language":"text","code":"jos(1,3) = 0\njos(2,3) = (0 + 3) % 2 = 1\njos(3,3) = (1 + 3) % 3 = 1\njos(4,3) = (1 + 3) % 4 = 0\njos(5,3) = (0 + 3) % 5 = 3\njos(6,3) = (3 + 3) % 6 = 0\njos(7,3) = (0 + 3) % 7 = 3     ← survivor for n = 7, k = 3","filename":"Unwinding the recursion from the base case up"}'),
  ('b3aadef4-dcbb-7cf9-b81d-e787b8207af6', 'au', 'code', '{"language":"python","code":"def josephus(n, k):\n    if n == 1:\n        return 0                          # one person left: position 0 survives\n    return (josephus(n - 1, k) + k) % n   # shift the smaller game''s answer back by k\n\nfor n, k in ((7, 3), (8, 2), (5, 2)):\n    print(f\"n={n} k={k} ->\", josephus(n, k))","filename":"Python"}'),
  ('8c46edfd-1aab-7d4c-8790-ef4f1fe5d848', 'av', 'code', '{"language":"cpp","code":"#include <iostream>\nusing namespace std;\n\nint josephus(int n, int k) {\n    if (n == 1) return 0;                     // one person left: position 0 survives\n    return (josephus(n - 1, k) + k) % n;      // shift the smaller game''s answer back by k\n}\n\nint main() {\n    int tests[3][2] = {{7, 3}, {8, 2}, {5, 2}};\n    for (auto& t : tests)\n        cout << \"n=\" << t[0] << \" k=\" << t[1] << \" -> \" << josephus(t[0], t[1]) << \"\\n\";\n}","filename":"C++"}'),
  ('987071a5-41c5-78f2-b531-fef69b99e7ae', 'aw', 'code', '{"language":"java","code":"public class Main {\n    static int josephus(int n, int k) {\n        if (n == 1) return 0;                 // one person left: position 0 survives\n        return (josephus(n - 1, k) + k) % n;  // shift the smaller game''s answer back by k\n    }\n\n    public static void main(String[] args) {\n        int[][] tests = {{7, 3}, {8, 2}, {5, 2}};\n        for (int[] t : tests)\n            System.out.println(\"n=\" + t[0] + \" k=\" + t[1] + \" -> \" + josephus(t[0], t[1]));\n    }\n}","filename":"Java"}'),
  ('2648c437-c167-7e89-b3c5-b7962902c752', 'ax', 'code', '{"language":"javascript","code":"function josephus(n, k) {\n    if (n === 1) return 0;                    // one person left: position 0 survives\n    return (josephus(n - 1, k) + k) % n;      // shift the smaller game''s answer back by k\n}\n\nfor (const [n, k] of [[7, 3], [8, 2], [5, 2]])\n    console.log(`n=${n} k=${k} ->`, josephus(n, k));","filename":"JavaScript"}'),
  ('c3d562c1-2665-7e33-91ac-ea3be2c955de', 'ay', 'code', '{"language":"text","code":"n=7 k=3 -> 3\nn=8 k=2 -> 0\nn=5 k=2 -> 2","filename":"Output"}'),
  ('bb76dde5-da5d-74bd-933b-0b46e5e89a64', 'az', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) · Space O(n) recursion depth — or O(1) with a loop"}]},{"type":"paragraph","content":[{"type":"text","text":"To "},{"type":"text","text":"see","marks":[{"type":"bold"}]},{"type":"text","text":" the eliminations, simulate the circle with a list: the next victim is "},{"type":"text","text":"(idx + k - 1) % size","marks":[{"type":"code"}]},{"type":"text","text":" and the count resumes at that index."}]}]}}'),
  ('4a175448-0c31-781e-9cd9-f430b2bf1317', 'b00', 'code', '{"language":"python","code":"def simulate(n, k):\n    people = list(range(n))\n    idx = 0\n    while len(people) > 1:\n        idx = (idx + k - 1) % len(people)     # count k people from idx, wrapping around\n        removed = people.pop(idx)             # the next person now sits at idx\n        print(\"remove\", removed, \"-> left:\", \" \".join(map(str, people)))\n    print(\"survivor:\", people[0])\n\nsimulate(7, 3)","filename":"Python"}'),
  ('f5598310-28c6-7a2b-b696-7fedf167e416', 'b01', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid simulate(int n, int k) {\n    vector<int> people;\n    for (int i = 0; i < n; i++) people.push_back(i);\n    int idx = 0;\n    while (people.size() > 1) {\n        int size = people.size();\n        idx = (idx + k - 1) % size;               // count k people from idx, wrapping around\n        int removed = people[idx];\n        people.erase(people.begin() + idx);       // the next person now sits at idx\n        cout << \"remove \" << removed << \" -> left:\";\n        for (int x : people) cout << \" \" << x;\n        cout << \"\\n\";\n    }\n    cout << \"survivor: \" << people[0] << \"\\n\";\n}\n\nint main() { simulate(7, 3); }","filename":"C++"}'),
  ('21da9ee0-6a84-7f7b-94fc-ceb23ff01795', 'b02', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static void simulate(int n, int k) {\n        List<Integer> people = new ArrayList<>();\n        for (int i = 0; i < n; i++) people.add(i);\n        int idx = 0;\n        while (people.size() > 1) {\n            idx = (idx + k - 1) % people.size();  // count k people from idx, wrapping around\n            int removed = people.remove(idx);     // the next person now sits at idx\n            StringBuilder sb = new StringBuilder();\n            for (int x : people) sb.append('' '').append(x);\n            System.out.println(\"remove \" + removed + \" -> left:\" + sb);\n        }\n        System.out.println(\"survivor: \" + people.get(0));\n    }\n\n    public static void main(String[] args) { simulate(7, 3); }\n}","filename":"Java"}'),
  ('43ec8302-9f52-708f-9434-c1a5e56d0f3f', 'b03', 'code', '{"language":"javascript","code":"function simulate(n, k) {\n    const people = Array.from({ length: n }, (_, i) => i);\n    let idx = 0;\n    while (people.length > 1) {\n        idx = (idx + k - 1) % people.length;      // count k people from idx, wrapping around\n        const [removed] = people.splice(idx, 1);  // the next person now sits at idx\n        console.log(\"remove\", removed, \"-> left:\", people.join(\" \"));\n    }\n    console.log(\"survivor:\", people[0]);\n}\n\nsimulate(7, 3);","filename":"JavaScript"}'),
  ('9209d5b3-9b80-75c0-9ee7-18e4a5c451e0', 'b04', 'code', '{"language":"text","code":"remove 2 -> left: 0 1 3 4 5 6\nremove 5 -> left: 0 1 3 4 6\nremove 1 -> left: 0 3 4 6\nremove 6 -> left: 0 3 4\nremove 4 -> left: 0 3\nremove 0 -> left: 3\nsurvivor: 3","filename":"Output"}'),
  ('32d2e8bf-b00b-7229-b310-2ece5525a9b4', 'b05', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n²) with list deletion, O(n · k) with a linked circle · Space O(n)"}]}]}}'),
  ('0460159f-6214-7c8f-8319-ef7ebc39bc7b', 'b06', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mixing up "},{"type":"text","text":"0-based and 1-based","marks":[{"type":"bold"}]},{"type":"text","text":" numbering. The formula above returns a 0-based position; if the people are numbered "},{"type":"text","text":"1 … n","marks":[{"type":"code"}]},{"type":"text","text":" the survivor is "},{"type":"text","text":"jos(n, k) + 1","marks":[{"type":"code"}]},{"type":"text","text":" (for "},{"type":"text","text":"n = 7, k = 3","marks":[{"type":"code"}]},{"type":"text","text":" that is "},{"type":"text","text":"4","marks":[{"type":"code"}]},{"type":"text","text":"). Also "},{"type":"text","text":"people.remove(idx)","marks":[{"type":"code"}]},{"type":"text","text":" in Java must receive an "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", not an "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":" — "},{"type":"text","text":"remove(Integer)","marks":[{"type":"code"}]},{"type":"text","text":" removes by "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}}'),
  ('3bd00f3f-8774-7c88-b3ee-bb00cd6b4c57', 'b07', 'heading', '{"level":1,"content":[{"type":"text","text":"Subset sum (count the subsets)"}]}'),
  ('57a1d86f-43fe-79d1-824f-e488e8c7e2fe', 'b08', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 5, 2, 3, 6], sum = 8","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 20, 15], sum = 0","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"1","marks":[{"type":"code"}]}]}]}}'),
  ('6ca198ff-914f-769d-b2ec-de81c2ce2c66', 'b09', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Count the subsets of "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":" whose elements add up to "},{"type":"text","text":"sum","marks":[{"type":"code"}]},{"type":"text","text":". For "},{"type":"text","text":"{10, 5, 2, 3, 6}","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"8","marks":[{"type":"code"}]},{"type":"text","text":" there are two: "},{"type":"text","text":"{5, 3}","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"{2, 6}","marks":[{"type":"code"}]},{"type":"text","text":". For "},{"type":"text","text":"sum = 0","marks":[{"type":"code"}]},{"type":"text","text":" the empty subset always counts, so the answer is at least "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('46e1527c-680c-74d7-a876-bba10dd45e53', 'b0A', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Look at the "},{"type":"text","text":"last","marks":[{"type":"bold"}]},{"type":"text","text":" element "},{"type":"text","text":"arr[n-1]","marks":[{"type":"code"}]},{"type":"text","text":". Either it is left out — count the subsets of the first "},{"type":"text","text":"n-1","marks":[{"type":"code"}]},{"type":"text","text":" elements that reach "},{"type":"text","text":"sum","marks":[{"type":"code"}]},{"type":"text","text":" — or it is taken — count those that reach "},{"type":"text","text":"sum - arr[n-1]","marks":[{"type":"code"}]},{"type":"text","text":". Add the two. With no elements left ("},{"type":"text","text":"n == 0","marks":[{"type":"code"}]},{"type":"text","text":") there is exactly one subset, the empty one, and it works only if the remaining "},{"type":"text","text":"sum","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('c1149c03-cfde-7ed4-8764-ddd2aed60bb9', 'b0B', 'code', '{"language":"text","code":"count(n=3, sum=3)   arr = {1, 2, 3}\n├── exclude 3 → count(2, 3)\n│   ├── exclude 2 → count(1, 3) → count(0,3)=0, count(0,2)=0          ⇒ 0\n│   └── include 2 → count(1, 1) → count(0,1)=0, count(0,0)=1  {1,2}  ⇒ 1\n└── include 3 → count(2, 0)\n    ├── exclude 2 → count(1, 0) → count(0,0)=1  {3}, count(0,-1)=0   ⇒ 1\n    └── include 2 → count(1,-2) → 0                                   ⇒ 0\n                                                               total = 2","filename":"Each leaf with sum 0 is one valid subset"}'),
  ('016194bd-1f50-7107-a3ea-c3a8ae764c5a', 'b0C', 'code', '{"language":"python","code":"def count_subsets(arr, n, target):\n    if n == 0:\n        return 1 if target == 0 else 0            # empty subset: valid only if nothing is left to reach\n    return (count_subsets(arr, n - 1, target)                 # exclude arr[n-1]\n            + count_subsets(arr, n - 1, target - arr[n - 1]))  # include arr[n-1]\n\nfor arr, target in (([10, 5, 2, 3, 6], 8), ([10, 20, 15], 0), ([1, 2, 3], 3)):\n    print(\" \".join(map(str, arr)), \"| sum\", target, \"->\", count_subsets(arr, len(arr), target))","filename":"Python"}'),
  ('dfc33e40-b448-7c7e-bf4d-bd8d42ea0dae', 'b0D', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint countSubsets(const vector<int>& arr, int n, int target) {\n    if (n == 0) return target == 0 ? 1 : 0;       // empty subset: valid only if nothing is left to reach\n    return countSubsets(arr, n - 1, target)                   // exclude arr[n-1]\n         + countSubsets(arr, n - 1, target - arr[n - 1]);     // include arr[n-1]\n}\n\nint main() {\n    vector<pair<vector<int>, int>> tests = {{{10, 5, 2, 3, 6}, 8}, {{10, 20, 15}, 0}, {{1, 2, 3}, 3}};\n    for (auto& [arr, target] : tests) {\n        for (int x : arr) cout << x << \" \";\n        cout << \"| sum \" << target << \" -> \" << countSubsets(arr, arr.size(), target) << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('1fbd2162-e21a-74bb-9eda-1d38d5c08898', 'b0E', 'code', '{"language":"java","code":"public class Main {\n    static int countSubsets(int[] arr, int n, int target) {\n        if (n == 0) return target == 0 ? 1 : 0;   // empty subset: valid only if nothing is left to reach\n        return countSubsets(arr, n - 1, target)               // exclude arr[n-1]\n             + countSubsets(arr, n - 1, target - arr[n - 1]); // include arr[n-1]\n    }\n\n    public static void main(String[] args) {\n        int[][] arrays = {{10, 5, 2, 3, 6}, {10, 20, 15}, {1, 2, 3}};\n        int[] targets = {8, 0, 3};\n        for (int t = 0; t < arrays.length; t++) {\n            StringBuilder sb = new StringBuilder();\n            for (int x : arrays[t]) sb.append(x).append('' '');\n            System.out.println(sb + \"| sum \" + targets[t] + \" -> \"\n                               + countSubsets(arrays[t], arrays[t].length, targets[t]));\n        }\n    }\n}","filename":"Java"}'),
  ('b9b9265d-d298-7c38-b405-a877da4ffd26', 'b0F', 'code', '{"language":"javascript","code":"function countSubsets(arr, n, target) {\n    if (n === 0) return target === 0 ? 1 : 0;     // empty subset: valid only if nothing is left to reach\n    return countSubsets(arr, n - 1, target)                   // exclude arr[n-1]\n         + countSubsets(arr, n - 1, target - arr[n - 1]);     // include arr[n-1]\n}\n\nfor (const [arr, target] of [[[10, 5, 2, 3, 6], 8], [[10, 20, 15], 0], [[1, 2, 3], 3]])\n    console.log(arr.join(\" \"), \"| sum\", target, \"->\", countSubsets(arr, arr.length, target));","filename":"JavaScript"}'),
  ('1ad3476a-ec9c-7ef1-aee2-07d56c9bee19', 'b0G', 'code', '{"language":"text","code":"10 5 2 3 6 | sum 8 -> 2\n10 20 15 | sum 0 -> 1\n1 2 3 | sum 3 -> 2","filename":"Output"}'),
  ('10a37044-d2bc-7819-a00a-200a0a59f369', 'b0H', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(2^n) · Space O(n) recursion depth"}]}]}}'),
  ('63f6e1d6-c472-7efd-86a5-dfe628e17eda', 'b0I', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pruning "},{"type":"text","text":"target < 0","marks":[{"type":"code"}]},{"type":"text","text":" (return "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" early) is safe only when all elements are non-negative. The same recurrence, memoised on "},{"type":"text","text":"(n, target)","marks":[{"type":"code"}]},{"type":"text","text":", is the "},{"type":"text","text":"O(n · sum)","marks":[{"type":"code"}]},{"type":"text","text":" subset-sum DP; replacing "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"or","marks":[{"type":"code"}]},{"type":"text","text":" answers the "},{"type":"text","text":"decision","marks":[{"type":"italic"}]},{"type":"text","text":" version (does any subset reach the sum?)."}]}]}}'),
  ('a7f33db7-d2f9-7a26-86bf-1a200edc34ef', 'b0J', 'heading', '{"level":1,"content":[{"type":"text","text":"Print all permutations of a string"}]}'),
  ('09e4df83-fb4d-77fe-b7f4-4478186b6897', 'b0K', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"AB\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"AB BA","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"s = \"ABC\"","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"ABC ACB BAC BCA CBA CAB","marks":[{"type":"code"}]}]}]}}'),
  ('fbf2eff0-b218-7e08-a155-59c6d078d434', 'b0L', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Print every arrangement of the characters of "},{"type":"text","text":"s","marks":[{"type":"code"}]},{"type":"text","text":" — there are "},{"type":"text","text":"n!","marks":[{"type":"code"}]},{"type":"text","text":" of them for "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" distinct characters."}]}]}}'),
  ('14862f2d-dfbf-778b-ac46-84a37c1104c2', 'b0M', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Fix position "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" by trying "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" character from "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" to the end in that slot (swap it in), recursively permute the rest "},{"type":"text","text":"i+1 … n-1","marks":[{"type":"code"}]},{"type":"text","text":", then "},{"type":"text","text":"swap it back","marks":[{"type":"bold"}]},{"type":"text","text":" so the next candidate starts from the original arrangement. The swap-back is what makes this "},{"type":"text","text":"backtracking","marks":[{"type":"italic"}]},{"type":"text","text":": the shared array is restored after every choice."}]}]}}'),
  ('58a30578-2e54-7c45-9416-db5d1f337b63', 'b0N', 'code', '{"language":"text","code":"permute(ABC, i=0)\n├── swap(0,0) → A|BC  permute(i=1)\n│                ├── swap(1,1) → AB|C → ABC ✔\n│                └── swap(1,2) → AC|B → ACB ✔   (swap back → ABC)\n├── swap(0,1) → B|AC  permute(i=1)\n│                ├── BAC ✔\n│                └── BCA ✔                       (swap back → ABC)\n└── swap(0,2) → C|BA  permute(i=1)\n                 ├── CBA ✔\n                 └── CAB ✔                       (swap back → ABC)","filename":"n choices at level 0, n−1 at level 1, … → n! leaves. Note the order is not alphabetical"}'),
  ('2ff4b1ad-1c64-7b3f-8344-c99f07b45b92', 'b0O', 'code', '{"language":"python","code":"def permute(chars, i, out):\n    n = len(chars)\n    if i == n - 1:\n        out.append(\"\".join(chars))            # every position fixed: one permutation\n        return\n    for j in range(i, n):\n        chars[i], chars[j] = chars[j], chars[i]   # choose chars[j] for position i\n        permute(chars, i + 1, out)\n        chars[i], chars[j] = chars[j], chars[i]   # backtrack: undo the swap\n\nfor s in (\"AB\", \"ABC\"):\n    out = []\n    permute(list(s), 0, out)\n    print(s, \"->\", \" \".join(out))","filename":"Python"}'),
  ('e0e632ff-f00e-7bbf-8d71-906415da79ea', 'b0P', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <string>\n#include <vector>\n#include <utility>\nusing namespace std;\n\nvoid permute(string& s, int i, vector<string>& out) {\n    int n = s.size();\n    if (i == n - 1) {\n        out.push_back(s);                     // every position fixed: one permutation\n        return;\n    }\n    for (int j = i; j < n; j++) {\n        swap(s[i], s[j]);                     // choose s[j] for position i\n        permute(s, i + 1, out);\n        swap(s[i], s[j]);                     // backtrack: undo the swap\n    }\n}\n\nint main() {\n    for (string s : {\"AB\", \"ABC\"}) {\n        vector<string> out;\n        string work = s;\n        permute(work, 0, out);\n        cout << s << \" ->\";\n        for (const string& p : out) cout << \" \" << p;\n        cout << \"\\n\";\n    }\n}","filename":"C++"}'),
  ('e24252d4-bc49-72ae-ab60-a670abe4fa15', 'b0Q', 'code', '{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\npublic class Main {\n    static void permute(char[] s, int i, List<String> out) {\n        int n = s.length;\n        if (i == n - 1) {\n            out.add(new String(s));           // every position fixed: one permutation\n            return;\n        }\n        for (int j = i; j < n; j++) {\n            char t = s[i]; s[i] = s[j]; s[j] = t;   // choose s[j] for position i\n            permute(s, i + 1, out);\n            t = s[i]; s[i] = s[j]; s[j] = t;        // backtrack: undo the swap\n        }\n    }\n\n    public static void main(String[] args) {\n        for (String s : new String[]{\"AB\", \"ABC\"}) {\n            List<String> out = new ArrayList<>();\n            permute(s.toCharArray(), 0, out);\n            System.out.println(s + \" -> \" + String.join(\" \", out));\n        }\n    }\n}","filename":"Java"}'),
  ('5639c844-bc39-7ceb-bd36-b2e5aefa32af', 'b0R', 'code', '{"language":"javascript","code":"function permute(chars, i, out) {\n    const n = chars.length;\n    if (i === n - 1) {\n        out.push(chars.join(\"\"));             // every position fixed: one permutation\n        return;\n    }\n    for (let j = i; j < n; j++) {\n        [chars[i], chars[j]] = [chars[j], chars[i]];   // choose chars[j] for position i\n        permute(chars, i + 1, out);\n        [chars[i], chars[j]] = [chars[j], chars[i]];   // backtrack: undo the swap\n    }\n}\n\nfor (const s of [\"AB\", \"ABC\"]) {\n    const out = [];\n    permute([...s], 0, out);\n    console.log(s, \"->\", out.join(\" \"));\n}","filename":"JavaScript"}'),
  ('bf2e1433-b280-7edd-9b55-f98093d18743', 'b0S', 'code', '{"language":"text","code":"AB -> AB BA\nABC -> ABC ACB BAC BCA CBA CAB","filename":"Output"}'),
  ('e08d77b8-2140-741f-8c7b-bd33121e0869', 'b0T', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n! · n) · Space O(n) recursion depth, swapping in place"}]}]}}'),
  ('ef83dae3-b816-709c-962e-947113edf5dc', 'b0U', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Forgetting the "},{"type":"text","text":"second swap","marks":[{"type":"bold"}]},{"type":"text","text":" corrupts the array for the next "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" and produces duplicates and missing permutations. The in-place swap uses no extra array, but the auxiliary space is still "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" because of the recursion depth — not "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":". With repeated characters ("},{"type":"text","text":"\"AAB\"","marks":[{"type":"code"}]},{"type":"text","text":") this prints duplicates; skip a "},{"type":"text","text":"j","marks":[{"type":"code"}]},{"type":"text","text":" whose character was already tried at this position, or use a frequency map."}]}]}}'),
  ('1b06fb6c-6973-7fee-8ca1-06cad8665e63', 'b0V', 'heading', '{"level":1,"content":[{"type":"text","text":"Recursion trees at a glance"}]}'),
  ('c38fd7b5-9916-7af8-8cfb-2e3700305828', 'b0W', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cost of a recursive solution is read off its tree: "},{"type":"text","text":"time","marks":[{"type":"bold"}]},{"type":"text","text":" is roughly the number of nodes (branching factor to the power of the depth), "},{"type":"text","text":"auxiliary space","marks":[{"type":"bold"}]},{"type":"text","text":" is the height. Overlapping subproblems (the same node appearing many times) are the signal to memoise."}]}]}}'),
  ('b15a0100-1bf1-75d8-91cf-3d5168126e95', 'b0X', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Problem"}],[{"type":"text","text":"Branching"}],[{"type":"text","text":"Depth"}],[{"type":"text","text":"Time"}],[{"type":"text","text":"Aux space"}],[{"type":"text","text":"Overlap?"}]],[[{"type":"text","text":"Rope cutting"}],[{"type":"text","text":"3"}],[{"type":"text","text":"n / min(a,b,c)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(3^n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"yes → DP "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Subsets of a string"}],[{"type":"text","text":"2"}],[{"type":"text","text":"n","marks":[{"type":"code"}]}],[{"type":"text","text":"O(2^n · n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"no — every leaf is a distinct answer"}]],[[{"type":"text","text":"Tower of Hanoi"}],[{"type":"text","text":"2"}],[{"type":"text","text":"n","marks":[{"type":"code"}]}],[{"type":"text","text":"O(2^n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"no — every move is output"}]],[[{"type":"text","text":"Josephus"}],[{"type":"text","text":"1"}],[{"type":"text","text":"n","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" (loop: "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"Subset sum count"}],[{"type":"text","text":"2"}],[{"type":"text","text":"n","marks":[{"type":"code"}]}],[{"type":"text","text":"O(2^n)","marks":[{"type":"code"}]}],[{"type":"text","text":"O(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"yes → DP "},{"type":"text","text":"O(n · sum)","marks":[{"type":"code"}]}]],