SELECT c.id::uuid, '4f9f381d-db17-7133-9a73-781add10400e', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('4cc1e028-fb6d-7077-94ba-f2373e75f0a0', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A segment tree answers "},{"type":"text","text":"range queries","marks":[{"type":"bold"}]},{"type":"text","text":" (sum, min, max, …) over an array and "},{"type":"text","text":"updates","marks":[{"type":"bold"}]},{"type":"text","text":" single elements, both in "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":". It is the structure to use when both operations are frequent, because a plain array makes queries slow and a prefix-sum array makes updates slow."}]}]}}'),
  ('5222d5e0-ef70-7135-8697-310269a6b8bf', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Segment tree","marks":[{"type":"bold"}]},{"type":"text","text":" — a binary tree over a fixed-size array in which every node stores an aggregate (e.g. the sum) of one contiguous segment: the root covers the whole array, each child covers one half of its parent''s segment, and the leaves are the individual elements."}]}]}}'),
  ('20091874-4722-7a78-bfae-6f775477533d', 'a2', 'code', '{"language":"text","code":"arr = [10, 20, 30, 40]            index:  0   1   2   3\n\n                [0..3] = 100                 tree[0]\n               /            \\\n      [0..1] = 30          [2..3] = 70        tree[1]  tree[2]\n      /       \\            /       \\\n[0]=10     [1]=20    [2]=30     [3]=40        tree[3] tree[4] tree[5] tree[6]\n\ntree array:  100  30  70  10  20  30  40\n              0    1   2   3   4   5   6        children of i are 2i+1 and 2i+2","filename":"Segment tree of sums over [10, 20, 30, 40], stored in an array like a heap"}'),
  ('5caa9d8a-ffa2-7fa1-b9dc-52dcb7e0d3df', 'a3', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 20, 30, 40, 50]; getSum(0, 2); getSum(1, 3); update(1, 60); getSum(0, 2)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"60, 90, then 100","marks":[{"type":"code"}]}]}]}}'),
  ('c985401c-0465-7c96-ac69-ef746156dc41', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Why not a plain array or prefix sums?"}]}'),
  ('5b922beb-614a-7c35-b923-d3b075636930', 'a5', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suppose "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" operations arrive, of which a quarter are range-sum queries and three quarters are updates. With a plain array queries cost "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" and updates "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":", so the average is "},{"type":"text","text":"(x/4 · O(n) + 3x/4 · O(1)) / x = O(n)","marks":[{"type":"code"}]},{"type":"text","text":". With a prefix-sum array it is the reverse — queries "},{"type":"text","text":"O(1)","marks":[{"type":"code"}]},{"type":"text","text":", updates "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":" — and the average is again "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":". A segment tree makes "},{"type":"text","text":"both","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"O(log n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('5d927486-33d2-7e29-8516-8c8204fb741e', 'a6', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Structure"}],[{"type":"text","text":"Range sum"}],[{"type":"text","text":"Point update"}],[{"type":"text","text":"Preprocessing"}],[{"type":"text","text":"Space"}]],[[{"type":"text","text":"Plain array"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"—"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"Prefix-sum array"}],[{"type":"text","text":"O(1)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n)"}]],[[{"type":"text","text":"Segment tree","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(log n)","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(log n)","marks":[{"type":"bold"}]}],[{"type":"text","text":"O(n)"}],[{"type":"text","text":"O(n) (≈ 4n slots)"}]],[[{"type":"text","text":"Binary indexed tree"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(log n)"}],[{"type":"text","text":"O(n log n) (O(n) possible)"}],[{"type":"text","text":"O(n) (n + 1 slots)"}]]]}'),
  ('cd8d13fe-1335-744b-b2ad-f8e4afd4d266', 'a7', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Segment trees work for any "},{"type":"text","text":"associative","marks":[{"type":"bold"}]},{"type":"text","text":" aggregate: sum, min, max, gcd, XOR, number of zeros, … Replace the "},{"type":"text","text":"+","marks":[{"type":"code"}]},{"type":"text","text":" in the three functions below and nothing else changes. They also extend to range updates with lazy propagation — the binary indexed tree does not handle min/max."}]}]}}'),
  ('eb8b078a-e79a-7db3-bb50-48df8d194fa1', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Size of the tree array"}]}'),
  ('9b2092d0-1a92-742f-8b8e-0063f00dde69', 'a9', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Children of node "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" live at "},{"type":"text","text":"2i + 1","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"2i + 2","marks":[{"type":"code"}]},{"type":"text","text":", so the tree is stored in a plain array with no pointers. How large must it be?"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" is a power of two the tree is perfect: "},{"type":"text","text":"2n − 1","marks":[{"type":"code"}]},{"type":"text","text":" nodes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Otherwise let "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":" be the smallest power of two "},{"type":"text","text":"greater than","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":"; the tree needs at most "},{"type":"text","text":"2x − 1","marks":[{"type":"code"}]},{"type":"text","text":" slots (some stay unused)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In practice allocate "},{"type":"text","text":"4n","marks":[{"type":"code"}]},{"type":"text","text":" — it is always enough ("},{"type":"text","text":"2x − 1 < 4n","marks":[{"type":"code"}]},{"type":"text","text":") and saves computing "},{"type":"text","text":"x","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"size = 2 · 2^⌈log₂ n⌉ − 1 (≤ 4n)","marks":[{"type":"code"}]}]}]}}'),
  ('75372bc2-24ca-7f5d-b594-130708c14abe', 'aA', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"n = 5","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"x = 8","marks":[{"type":"code"}]},{"type":"text","text":" → at most "},{"type":"text","text":"15","marks":[{"type":"code"}]},{"type":"text","text":" slots; "},{"type":"text","text":"n = 4","marks":[{"type":"code"}]},{"type":"text","text":" → exactly "},{"type":"text","text":"7","marks":[{"type":"code"}]},{"type":"text","text":" slots, all used."}]}]}}'),
  ('49b8907a-20ee-7579-9a2a-f4db1dd9c7ed', 'aB', 'heading', '{"level":1,"content":[{"type":"text","text":"Constructing the segment tree"}]}'),
  ('fc81b305-e3ee-7b1c-ab2a-378dd0af0ea8', 'aC', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 20, 30, 40]","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"tree = [100, 30, 70, 10, 20, 30, 40]","marks":[{"type":"code"}]}]}]}}'),
  ('7ea3f4fd-a724-7ee3-a9bd-8aac24773d40', 'aD', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Build recursively: if the segment is a single element store it; otherwise build the left half and the right half, then store their sum. Every node is written exactly once — "},{"type":"text","text":"O(n)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('439b63dd-6a3a-7820-80fc-f2941b8a9145', 'aE', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"build(ss, se, si)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"ss","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"se","marks":[{"type":"code"}]},{"type":"text","text":" = segment start/end in "},{"type":"text","text":"arr","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"si","marks":[{"type":"code"}]},{"type":"text","text":" = index of this node in "},{"type":"text","text":"tree","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Leaf","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"ss == se","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"tree[si] = arr[ss]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Internal node","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"mid = (ss + se) / 2","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"tree[si] = build(ss, mid, 2si+1) + build(mid+1, se, 2si+2)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}}'),
  ('241269c1-00cb-7565-aa28-8d4565ae1dc2', 'aF', 'code', '{"language":"python","code":"def build(arr, tree, ss, se, si):\n    if ss == se:                                        # leaf: a single element\n        tree[si] = arr[ss]\n        return tree[si]\n    mid = (ss + se) // 2\n    tree[si] = build(arr, tree, ss, mid, 2 * si + 1) + build(arr, tree, mid + 1, se, 2 * si + 2)\n    return tree[si]                                     # parent = left sum + right sum\n\ndef tree_size(n):\n    x = 1\n    while x < n:                                        # smallest power of two ≥ n\n        x *= 2\n    return 2 * x - 1\n\narr = [10, 20, 30, 40]\ntree = [0] * tree_size(len(arr))\nbuild(arr, tree, 0, len(arr) - 1, 0)\nprint(\"tree:\", \" \".join(map(str, tree)))","filename":"Python"}'),
  ('ec8f2a84-0af6-701b-9104-c4d52a7f287a', 'aG', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint build(const vector<int>& arr, vector<int>& tree, int ss, int se, int si) {\n    if (ss == se) return tree[si] = arr[ss];            // leaf: a single element\n    int mid = (ss + se) / 2;\n    return tree[si] = build(arr, tree, ss, mid, 2 * si + 1)\n                    + build(arr, tree, mid + 1, se, 2 * si + 2);   // parent = left sum + right sum\n}\n\nint treeSize(int n) {\n    int x = 1;\n    while (x < n) x *= 2;                                // smallest power of two ≥ n\n    return 2 * x - 1;\n}\n\nint main() {\n    vector<int> arr = {10, 20, 30, 40};\n    int n = arr.size();\n    vector<int> tree(treeSize(n), 0);\n    build(arr, tree, 0, n - 1, 0);\n    cout << \"tree:\";\n    for (int v : tree) cout << \" \" << v;\n    cout << \"\\n\";\n}","filename":"C++"}'),
  ('97032dc9-9076-7118-bade-47d03f7c4db6', 'aH', 'code', '{"language":"java","code":"public class Main {\n    static int build(int[] arr, int[] tree, int ss, int se, int si) {\n        if (ss == se) return tree[si] = arr[ss];        // leaf: a single element\n        int mid = (ss + se) / 2;\n        return tree[si] = build(arr, tree, ss, mid, 2 * si + 1)\n                        + build(arr, tree, mid + 1, se, 2 * si + 2);   // parent = left sum + right sum\n    }\n\n    static int treeSize(int n) {\n        int x = 1;\n        while (x < n) x *= 2;                            // smallest power of two ≥ n\n        return 2 * x - 1;\n    }\n\n    public static void main(String[] args) {\n        int[] arr = {10, 20, 30, 40};\n        int[] tree = new int[treeSize(arr.length)];\n        build(arr, tree, 0, arr.length - 1, 0);\n        StringBuilder sb = new StringBuilder(\"tree:\");\n        for (int v : tree) sb.append('' '').append(v);\n        System.out.println(sb);\n    }\n}","filename":"Java"}'),
  ('5a16fb80-a00e-7170-9436-037de9d74fa9', 'aI', 'code', '{"language":"javascript","code":"function build(arr, tree, ss, se, si) {\n    if (ss === se) return (tree[si] = arr[ss]);         // leaf: a single element\n    const mid = Math.floor((ss + se) / 2);\n    return (tree[si] = build(arr, tree, ss, mid, 2 * si + 1)\n                     + build(arr, tree, mid + 1, se, 2 * si + 2));   // parent = left sum + right sum\n}\n\nfunction treeSize(n) {\n    let x = 1;\n    while (x < n) x *= 2;                                // smallest power of two ≥ n\n    return 2 * x - 1;\n}\n\nconst arr = [10, 20, 30, 40];\nconst tree = new Array(treeSize(arr.length)).fill(0);\nbuild(arr, tree, 0, arr.length - 1, 0);\nconsole.log(\"tree:\", tree.join(\" \"));","filename":"JavaScript"}'),
  ('0ce71537-b242-707f-9604-13bcb1bf0c86', 'aJ', 'code', '{"language":"text","code":"tree: 100 30 70 10 20 30 40","filename":"Output"}'),
  ('2a04ad37-8be0-7d16-b61b-8ea7280d5164', 'aK', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(n) — each of the ≈ 2n nodes is computed once · Space O(n)"}]}]}}'),
  ('7e97b099-b8fa-7693-b5ae-0fa0a6e412c0', 'aL', 'heading', '{"level":1,"content":[{"type":"text","text":"Range query"}]}'),
  ('44809910-6426-71f0-a0d7-b2d5075b0ba9', 'aM', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 20, 30, 40]; getSum(0, 2)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"60","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"getSum(1, 3)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"90","marks":[{"type":"code"}]}]}]}}'),
  ('a18fd202-cf28-7077-894e-f1843c1f94c6', 'aN', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Walk down from the root. A node''s segment relates to the query range "},{"type":"text","text":"[qs, qe]","marks":[{"type":"code"}]},{"type":"text","text":" in one of three ways: "},{"type":"text","text":"completely inside","marks":[{"type":"bold"}]},{"type":"text","text":" → return its stored sum without going deeper; "},{"type":"text","text":"completely outside","marks":[{"type":"bold"}]},{"type":"text","text":" → contribute "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"partially overlapping","marks":[{"type":"bold"}]},{"type":"text","text":" → recurse into both children and add."}]}]}}'),
  ('57e3681f-b13d-7a66-ab97-4fbdf5c3d460', 'aO', 'code', '{"language":"text","code":"getSum(1, 2) on [10, 20, 30, 40]\n\n         [0..3]  partial overlap → recurse\n        /      \\\n  [0..1] partial  [2..3] partial\n  /    \\          /    \\\n[0]    [1]      [2]    [3]\noutside inside  inside outside\n  0     20       30      0        → 20 + 30 = 50","filename":"The three cases — at most two nodes per level are partially overlapped, so the query touches O(log n) nodes"}'),
  ('9841bbed-4237-7ff9-9c3c-5f36ccf21e53', 'aP', 'code', '{"language":"python","code":"def build(arr, tree, ss, se, si):\n    if ss == se:\n        tree[si] = arr[ss]\n        return tree[si]\n    mid = (ss + se) // 2\n    tree[si] = build(arr, tree, ss, mid, 2 * si + 1) + build(arr, tree, mid + 1, se, 2 * si + 2)\n    return tree[si]\n\ndef get_sum_rec(tree, qs, qe, ss, se, si):\n    if qe < ss or qs > se:                              # segment completely outside the query\n        return 0\n    if qs <= ss and se <= qe:                           # segment completely inside the query\n        return tree[si]\n    mid = (ss + se) // 2                                # partial overlap: ask both children\n    return get_sum_rec(tree, qs, qe, ss, mid, 2 * si + 1) + get_sum_rec(tree, qs, qe, mid + 1, se, 2 * si + 2)\n\ndef get_sum(tree, n, qs, qe):\n    if qs < 0 or qe > n - 1 or qs > qe:\n        raise ValueError(\"invalid range\")\n    return get_sum_rec(tree, qs, qe, 0, n - 1, 0)\n\narr = [10, 20, 30, 40]\nn = len(arr)\nx = 1\nwhile x < n:\n    x *= 2\ntree = [0] * (2 * x - 1)\nbuild(arr, tree, 0, n - 1, 0)\nprint(\"tree:\", \" \".join(map(str, tree)))\nfor qs, qe in [(0, 2), (1, 3), (2, 2)]:\n    print(f\"sum({qs}, {qe}):\", get_sum(tree, n, qs, qe))","filename":"Python"}'),
  ('83a334b5-aaf6-7140-8df0-ccf5bf7be53c', 'aQ', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\n#include <stdexcept>\nusing namespace std;\n\nint build(const vector<int>& arr, vector<int>& tree, int ss, int se, int si) {\n    if (ss == se) return tree[si] = arr[ss];\n    int mid = (ss + se) / 2;\n    return tree[si] = build(arr, tree, ss, mid, 2 * si + 1) + build(arr, tree, mid + 1, se, 2 * si + 2);\n}\n\nint getSumRec(const vector<int>& tree, int qs, int qe, int ss, int se, int si) {\n    if (qe < ss || qs > se) return 0;                   // segment completely outside the query\n    if (qs <= ss && se <= qe) return tree[si];          // segment completely inside the query\n    int mid = (ss + se) / 2;                             // partial overlap: ask both children\n    return getSumRec(tree, qs, qe, ss, mid, 2 * si + 1) + getSumRec(tree, qs, qe, mid + 1, se, 2 * si + 2);\n}\n\nint getSum(const vector<int>& tree, int n, int qs, int qe) {\n    if (qs < 0 || qe > n - 1 || qs > qe) throw invalid_argument(\"invalid range\");\n    return getSumRec(tree, qs, qe, 0, n - 1, 0);\n}\n\nint main() {\n    vector<int> arr = {10, 20, 30, 40};\n    int n = arr.size(), x = 1;\n    while (x < n) x *= 2;\n    vector<int> tree(2 * x - 1, 0);\n    build(arr, tree, 0, n - 1, 0);\n    cout << \"tree:\";\n    for (int v : tree) cout << \" \" << v;\n    cout << \"\\n\";\n    int queries[3][2] = {{0, 2}, {1, 3}, {2, 2}};\n    for (auto& q : queries) cout << \"sum(\" << q[0] << \", \" << q[1] << \"): \" << getSum(tree, n, q[0], q[1]) << \"\\n\";\n}","filename":"C++"}'),
  ('4288128a-1633-7051-b9fc-cd540e4a6c1d', 'aR', 'code', '{"language":"java","code":"public class Main {\n    static int build(int[] arr, int[] tree, int ss, int se, int si) {\n        if (ss == se) return tree[si] = arr[ss];\n        int mid = (ss + se) / 2;\n        return tree[si] = build(arr, tree, ss, mid, 2 * si + 1) + build(arr, tree, mid + 1, se, 2 * si + 2);\n    }\n\n    static int getSumRec(int[] tree, int qs, int qe, int ss, int se, int si) {\n        if (qe < ss || qs > se) return 0;               // segment completely outside the query\n        if (qs <= ss && se <= qe) return tree[si];      // segment completely inside the query\n        int mid = (ss + se) / 2;                         // partial overlap: ask both children\n        return getSumRec(tree, qs, qe, ss, mid, 2 * si + 1) + getSumRec(tree, qs, qe, mid + 1, se, 2 * si + 2);\n    }\n\n    static int getSum(int[] tree, int n, int qs, int qe) {\n        if (qs < 0 || qe > n - 1 || qs > qe) throw new IllegalArgumentException(\"invalid range\");\n        return getSumRec(tree, qs, qe, 0, n - 1, 0);\n    }\n\n    public static void main(String[] args) {\n        int[] arr = {10, 20, 30, 40};\n        int n = arr.length, x = 1;\n        while (x < n) x *= 2;\n        int[] tree = new int[2 * x - 1];\n        build(arr, tree, 0, n - 1, 0);\n        StringBuilder sb = new StringBuilder(\"tree:\");\n        for (int v : tree) sb.append('' '').append(v);\n        System.out.println(sb);\n        int[][] queries = {{0, 2}, {1, 3}, {2, 2}};\n        for (int[] q : queries) System.out.println(\"sum(\" + q[0] + \", \" + q[1] + \"): \" + getSum(tree, n, q[0], q[1]));\n    }\n}","filename":"Java"}'),
  ('2c89c21a-d6f7-701f-9f44-057ecfdca566', 'aS', 'code', '{"language":"javascript","code":"function build(arr, tree, ss, se, si) {\n    if (ss === se) return (tree[si] = arr[ss]);\n    const mid = Math.floor((ss + se) / 2);\n    return (tree[si] = build(arr, tree, ss, mid, 2 * si + 1) + build(arr, tree, mid + 1, se, 2 * si + 2));\n}\n\nfunction getSumRec(tree, qs, qe, ss, se, si) {\n    if (qe < ss || qs > se) return 0;                   // segment completely outside the query\n    if (qs <= ss && se <= qe) return tree[si];          // segment completely inside the query\n    const mid = Math.floor((ss + se) / 2);               // partial overlap: ask both children\n    return getSumRec(tree, qs, qe, ss, mid, 2 * si + 1) + getSumRec(tree, qs, qe, mid + 1, se, 2 * si + 2);\n}\n\nfunction getSum(tree, n, qs, qe) {\n    if (qs < 0 || qe > n - 1 || qs > qe) throw new Error(\"invalid range\");\n    return getSumRec(tree, qs, qe, 0, n - 1, 0);\n}\n\nconst arr = [10, 20, 30, 40];\nconst n = arr.length;\nlet x = 1;\nwhile (x < n) x *= 2;\nconst tree = new Array(2 * x - 1).fill(0);\nbuild(arr, tree, 0, n - 1, 0);\nconsole.log(\"tree:\", tree.join(\" \"));\nfor (const [qs, qe] of [[0, 2], [1, 3], [2, 2]]) console.log(`sum(${qs}, ${qe}):`, getSum(tree, n, qs, qe));","filename":"JavaScript"}'),
  ('6ff51c36-1101-7cb4-af47-4c87b0101a6f', 'aT', 'code', '{"language":"text","code":"tree: 100 30 70 10 20 30 40\nsum(0, 2): 60\nsum(1, 3): 90\nsum(2, 2): 30","filename":"Output"}'),
  ('2c2538ae-b3a1-74ff-86b4-200c573e2c49', 'aU', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Time O(log n) per query · Space O(log n) recursion depth"}]}]}}'),
  ('e5c01e52-6c4c-7d03-96e5-4f4264104df5', 'aV', 'callout', '{"variant":"warning","title":"Pitfall","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The order of the two base cases matters: test "},{"type":"text","text":"completely outside","marks":[{"type":"italic"}]},{"type":"text","text":" before "},{"type":"text","text":"completely inside","marks":[{"type":"italic"}]},{"type":"text","text":". For a single-element segment both "},{"type":"text","text":"qe < ss","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"qs <= ss && se <= qe","marks":[{"type":"code"}]},{"type":"text","text":" can be evaluated — the outside test must win when the leaf is not in the range."}]}]}}'),
  ('adc610a1-dcff-7e6b-ad59-d30454bafc48', 'aW', 'heading', '{"level":1,"content":[{"type":"text","text":"Point update"}]}'),
  ('93559554-b5d7-7650-97c4-f781e32a9223', 'aX', 'callout', '{"variant":"tip","title":"Example","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Input:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"arr = [10, 20, 30, 40]; update(1, 60); getSum(0, 2)","marks":[{"type":"code"}]},{"type":"hardBreak"},{"type":"text","text":"Output:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"100 (the tree becomes 140 70 70 10 60 30 40)","marks":[{"type":"code"}]}]}]}}'),
  ('e7d7c85a-361a-7d40-989b-f2b9fae2cacd', 'aY', 'callout', '{"variant":"note","title":"Idea","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the nodes whose segment "},{"type":"text","text":"contains index ","marks":[{"type":"bold"}]},{"type":"text","text":"i","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" — one per level, root to leaf — are affected. Compute "},{"type":"text","text":"diff = newValue − arr[i]","marks":[{"type":"code"}]},{"type":"text","text":", then walk down from the root adding "},{"type":"text","text":"diff","marks":[{"type":"code"}]},{"type":"text","text":" to every node on the path to leaf "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" and ignoring the subtrees that do not contain "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('2f1f53b7-ca19-734e-83c0-30c1de4e0f51', 'aZ', 'text', '{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Compute the difference","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"diff = new_val − arr[i]","marks":[{"type":"code"}]},{"type":"text","text":"; also store "},{"type":"text","text":"arr[i] = new_val","marks":[{"type":"code"}]},{"type":"text","text":" so later updates compute the right difference."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"update(ss, se, i, si, diff)","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" is outside "},{"type":"text","text":"[ss, se]","marks":[{"type":"code"}]},{"type":"text","text":" → return (this subtree is untouched)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add and descend","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"tree[si] += diff","marks":[{"type":"code"}]},{"type":"text","text":"; if the segment has more than one element, recurse into both children (only the one containing "},{"type":"text","text":"i","marks":[{"type":"code"}]},{"type":"text","text":" does any work)."}]}]}]}]}}'),
  ('5b79bfe2-d2b2-77fb-a155-e77e327eff52', 'aa', 'code', '{"language":"text","code":"update(1, 60) on [10, 20, 30, 40]: diff = 60 − 20 = +40\n\n         [0..3] 100 → 140            ← contains index 1: += 40\n        /            \\\n  [0..1] 30 → 70      [2..3] 70       ← index 1 not in [2..3]: skip\n  /       \\\n[0] 10    [1] 20 → 60                 ← the leaf itself","filename":"Exactly one node per level changes"}'),
  ('e3f74e96-55ef-73ce-86ae-bfe0d4577b13', 'ab', 'code', '{"language":"python","code":"class SegmentTree:\n    def __init__(self, arr):\n        self.arr = arr[:]\n        self.n = len(arr)\n        x = 1\n        while x < self.n:\n            x *= 2\n        self.tree = [0] * (2 * x - 1)\n        self._build(0, self.n - 1, 0)\n\n    def _build(self, ss, se, si):\n        if ss == se:\n            self.tree[si] = self.arr[ss]\n            return self.tree[si]\n        mid = (ss + se) // 2\n        self.tree[si] = self._build(ss, mid, 2 * si + 1) + self._build(mid + 1, se, 2 * si + 2)\n        return self.tree[si]\n\n    def get_sum(self, qs, qe, ss=0, se=None, si=0):\n        if se is None:\n            se = self.n - 1\n        if qe < ss or qs > se:\n            return 0\n        if qs <= ss and se <= qe:\n            return self.tree[si]\n        mid = (ss + se) // 2\n        return self.get_sum(qs, qe, ss, mid, 2 * si + 1) + self.get_sum(qs, qe, mid + 1, se, 2 * si + 2)\n\n    def update(self, i, new_val):\n        diff = new_val - self.arr[i]                    # how much every ancestor must change\n        self.arr[i] = new_val\n        self._update(0, self.n - 1, i, 0, diff)\n\n    def _update(self, ss, se, i, si, diff):\n        if i < ss or i > se:                            # index not in this segment\n            return\n        self.tree[si] += diff                           # this node''s segment contains i\n        if ss < se:\n            mid = (ss + se) // 2\n            self._update(ss, mid, i, 2 * si + 1, diff)\n            self._update(mid + 1, se, i, 2 * si + 2, diff)\n\nst = SegmentTree([10, 20, 30, 40])\nprint(\"tree:\", \" \".join(map(str, st.tree)))\nprint(\"sum(0, 2):\", st.get_sum(0, 2))\nprint(\"update(1, 60)\")\nst.update(1, 60)\nprint(\"tree:\", \" \".join(map(str, st.tree)))\nprint(\"sum(0, 2):\", st.get_sum(0, 2))\nprint(\"sum(1, 3):\", st.get_sum(1, 3))","filename":"Python"}'),
  ('248ccb32-d60e-706f-a4ce-71e35b1a345e', 'ac', 'code', '{"language":"cpp","code":"#include <iostream>\n#include <vector>\nusing namespace std;\n\nclass SegmentTree {\n    vector<int> arr, tree;\n    int n;\n    int build(int ss, int se, int si) {\n        if (ss == se) return tree[si] = arr[ss];\n        int mid = (ss + se) / 2;\n        return tree[si] = build(ss, mid, 2 * si + 1) + build(mid + 1, se, 2 * si + 2);\n    }\n    int getSum(int qs, int qe, int ss, int se, int si) const {\n        if (qe < ss || qs > se) return 0;\n        if (qs <= ss && se <= qe) return tree[si];\n        int mid = (ss + se) / 2;\n        return getSum(qs, qe, ss, mid, 2 * si + 1) + getSum(qs, qe, mid + 1, se, 2 * si + 2);\n    }\n    void update(int ss, int se, int i, int si, int diff) {\n        if (i < ss || i > se) return;                   // index not in this segment\n        tree[si] += diff;                               // this node''s segment contains i\n        if (ss < se) {\n            int mid = (ss + se) / 2;\n            update(ss, mid, i, 2 * si + 1, diff);\n            update(mid + 1, se, i, 2 * si + 2, diff);\n        }\n    }\npublic:\n    SegmentTree(const vector<int>& a) : arr(a), n(a.size()) {\n        int x = 1;\n        while (x < n) x *= 2;\n        tree.assign(2 * x - 1, 0);\n        build(0, n - 1, 0);\n    }\n    int getSum(int qs, int qe) const { return getSum(qs, qe, 0, n - 1, 0); }\n    void update(int i, int newVal) {\n        int diff = newVal - arr[i];                     // how much every ancestor must change\n        arr[i] = newVal;\n        update(0, n - 1, i, 0, diff);\n    }\n    void print() const { cout << \"tree:\"; for (int v : tree) cout << \" \" << v; cout << \"\\n\"; }\n};\n\nint main() {\n    SegmentTree st({10, 20, 30, 40});\n    st.print();\n    cout << \"sum(0, 2): \" << st.getSum(0, 2) << \"\\n\";\n    cout << \"update(1, 60)\\n\";\n    st.update(1, 60);\n    st.print();\n    cout << \"sum(0, 2): \" << st.getSum(0, 2) << \"\\n\";\n    cout << \"sum(1, 3): \" << st.getSum(1, 3) << \"\\n\";\n}","filename":"C++"}'),
  ('14d925b9-77f2-7a6c-9a8e-ede785b46fdb', 'ad', 'code', '{"language":"java","code":"public class Main {\n    static class SegmentTree {\n        int[] arr, tree;\n        int n;\n        SegmentTree(int[] a) {\n            arr = a.clone(); n = a.length;\n            int x = 1;\n            while (x < n) x *= 2;\n            tree = new int[2 * x - 1];\n            build(0, n - 1, 0);\n        }\n        int build(int ss, int se, int si) {\n            if (ss == se) return tree[si] = arr[ss];\n            int mid = (ss + se) / 2;\n            return tree[si] = build(ss, mid, 2 * si + 1) + build(mid + 1, se, 2 * si + 2);\n        }\n        int getSum(int qs, int qe) { return getSum(qs, qe, 0, n - 1, 0); }\n        int getSum(int qs, int qe, int ss, int se, int si) {\n            if (qe < ss || qs > se) return 0;\n            if (qs <= ss && se <= qe) return tree[si];\n            int mid = (ss + se) / 2;\n            return getSum(qs, qe, ss, mid, 2 * si + 1) + getSum(qs, qe, mid + 1, se, 2 * si + 2);\n        }\n        void update(int i, int newVal) {\n            int diff = newVal - arr[i];                 // how much every ancestor must change\n            arr[i] = newVal;\n            update(0, n - 1, i, 0, diff);\n        }\n        void update(int ss, int se, int i, int si, int diff) {\n            if (i < ss || i > se) return;               // index not in this segment\n            tree[si] += diff;                           // this node''s segment contains i\n            if (ss < se) {\n                int mid = (ss + se) / 2;\n                update(ss, mid, i, 2 * si + 1, diff);\n                update(mid + 1, se, i, 2 * si + 2, diff);\n            }\n        }\n        String dump() { StringBuilder sb = new StringBuilder(\"tree:\"); for (int v : tree) sb.append('' '').append(v); return sb.toString(); }\n    }\n\n    public static void main(String[] args) {\n        SegmentTree st = new SegmentTree(new int[]{10, 20, 30, 40});\n        System.out.println(st.dump());\n        System.out.println(\"sum(0, 2): \" + st.getSum(0, 2));\n        System.out.println(\"update(1, 60)\");\n        st.update(1, 60);\n        System.out.println(st.dump());\n        System.out.println(\"sum(0, 2): \" + st.getSum(0, 2));\n        System.out.println(\"sum(1, 3): \" + st.getSum(1, 3));\n    }\n}","filename":"Java"}'),
  ('cfd933b3-7cfa-7fea-9cfb-d6b70674b037', 'ae', 'code', '{"language":"javascript","code":"class SegmentTree {\n    constructor(a) {\n        this.arr = [...a]; this.n = a.length;\n        let x = 1;\n        while (x < this.n) x *= 2;\n        this.tree = new Array(2 * x - 1).fill(0);\n        this.build(0, this.n - 1, 0);\n    }\n    build(ss, se, si) {\n        if (ss === se) return (this.tree[si] = this.arr[ss]);\n        const mid = Math.floor((ss + se) / 2);\n        return (this.tree[si] = this.build(ss, mid, 2 * si + 1) + this.build(mid + 1, se, 2 * si + 2));\n    }\n    getSum(qs, qe, ss = 0, se = this.n - 1, si = 0) {\n        if (qe < ss || qs > se) return 0;\n        if (qs <= ss && se <= qe) return this.tree[si];\n        const mid = Math.floor((ss + se) / 2);\n        return this.getSum(qs, qe, ss, mid, 2 * si + 1) + this.getSum(qs, qe, mid + 1, se, 2 * si + 2);\n    }\n    update(i, newVal) {\n        const diff = newVal - this.arr[i];              // how much every ancestor must change\n        this.arr[i] = newVal;\n        this.updateRec(0, this.n - 1, i, 0, diff);\n    }\n    updateRec(ss, se, i, si, diff) {\n        if (i < ss || i > se) return;                   // index not in this segment\n        this.tree[si] += diff;                          // this node''s segment contains i\n        if (ss < se) {\n            const mid = Math.floor((ss + se) / 2);\n            this.updateRec(ss, mid, i, 2 * si + 1, diff);\n            this.updateRec(mid + 1, se, i, 2 * si + 2, diff);\n        }\n    }\n}\n\nconst st = new SegmentTree([10, 20, 30, 40]);\nconsole.log(\"tree:\", st.tree.join(\" \"));\nconsole.log(\"sum(0, 2):\", st.getSum(0, 2));\nconsole.log(\"update(1, 60)\");\nst.update(1, 60);\nconsole.log(\"tree:\", st.tree.join(\" \"));\nconsole.log(\"sum(0, 2):\", st.getSum(0, 2));\nconsole.log(\"sum(1, 3):\", st.getSum(1, 3));","filename":"JavaScript"}'),
